  UNIQUE INDEX `agents_email_unique`(`email`) USING BTREE,
  UNIQUE INDEX `agents_full_mobile_unique`(`full_mobile`) USING BTREE,
  INDEX `agents_mobile_index`(`mobile`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

