-- ----------------------------
-- Table structure for frontend_header_section_faqs
-- ----------------------------
DROP TABLE IF EXISTS `frontend_header_section_faqs`;
CREATE TABLE `frontend_header_section_faqs`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `parent_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `type` enum('personal','business','enterprise','company') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `value` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `last_edit_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp(0) NULL DEFAULT NULL,
  `updated_at` timestamp(0) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `frontend_header_section_faqs_parent_id_foreign`(`parent_id`) USING BTREE,
  INDEX `frontend_header_section_faqs_last_edit_by_foreign`(`last_edit_by`) USING BTREE,
  CONSTRAINT `frontend_header_section_faqs_last_edit_by_foreign` FOREIGN KEY (`last_edit_by`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `frontend_header_section_faqs_parent_id_foreign` FOREIGN KEY (`parent_id`) REFERENCES `frontend_header_sections` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 33 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of frontend_header_section_faqs
-- ----------------------------
INSERT INTO `frontend_header_section_faqs` VALUES (1, 1, 'personal', '{\"language\":{\"en\":{\"heading\":\"How can I receive money through QRPay Pro?\",\"sub_heading\":\"Simply share your QRPay Pro ID, email, or phone number with the sender, and they can transfer funds directly to your  account.\"},\"ar\":{\"heading\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0633\\u062a\\u0644\\u0627\\u0645 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 QRPay Pro\\u061f\",\"sub_heading\":\"\\u0645\\u0627 \\u0639\\u0644\\u064a\\u0643 \\u0633\\u0648\\u0649 \\u0645\\u0634\\u0627\\u0631\\u0643\\u0629 \\u0645\\u0639\\u0631\\u0641 QRPay Pro \\u0623\\u0648 \\u0627\\u0644\\u0628\\u0631\\u064a\\u062f \\u0627\\u0644\\u0625\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a \\u0623\\u0648 \\u0631\\u0642\\u0645 \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u0645\\u0639 \\u0627\\u0644\\u0645\\u0631\\u0633\\u0644\\u060c \\u0648\\u064a\\u0645\\u0643\\u0646\\u0647 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0643.\"},\"es\":{\"heading\":\"\\u00bfC\\u00f3mo puedo recibir dinero a trav\\u00e9s de QRPay Pro?\",\"sub_heading\":\"Simplemente comparta su ID de QRPay Pro, correo electr\\u00f3nico o n\\u00famero de tel\\u00e9fono con el remitente, y \\u00e9l podr\\u00e1 transferir fondos directamente a su cuenta.\"},\"fr\":{\"heading\":\"Comment puis-je recevoir de l\'argent via QRPay Pro\\u00a0?\",\"sub_heading\":\"Partagez simplement votre identifiant QRPay Pro, votre adresse e-mail ou votre num\\u00e9ro de t\\u00e9l\\u00e9phone avec l\'exp\\u00e9diteur, et il pourra transf\\u00e9rer des fonds directement sur votre compte.\"},\"hi\":{\"heading\":\"\\u092e\\u0948\\u0902 QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0902?\",\"sub_heading\":\"\\u092c\\u0938 \\u092a\\u094d\\u0930\\u0947\\u0937\\u0915 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0905\\u092a\\u0928\\u0940 QRPay \\u092a\\u094d\\u0930\\u094b \\u0906\\u0908\\u0921\\u0940, \\u0908\\u092e\\u0947\\u0932 \\u092f\\u093e \\u092b\\u094b\\u0928 \\u0928\\u0902\\u092c\\u0930 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930\\u0947\\u0902, \\u0914\\u0930 \\u0935\\u0947 \\u0938\\u0940\\u0927\\u0947 \\u0906\\u092a\\u0915\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u093f\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"items\":{\"6722fdf3dd60c\":{\"language\":{\"en\":{\"question\":\"Which currencies can I exchange with QRPay Pro?\",\"answer\":\"QRPay Pro supports a variety of major currencies, allowing you to exchange between them with ease. For a full list of supported currencies, check your account settings or visit the Exchange Money page in the app.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0647\\u064a \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0633\\u062a\\u0628\\u062f\\u0627\\u0644\\u0647\\u0627 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\\u061f\",\"answer\":\"\\u064a\\u062f\\u0639\\u0645 QRPay Pro \\u0645\\u062c\\u0645\\u0648\\u0639\\u0629 \\u0645\\u062a\\u0646\\u0648\\u0639\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0631\\u0626\\u064a\\u0633\\u064a\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0645\\u062d \\u0644\\u0643 \\u0628\\u0627\\u0644\\u062a\\u0628\\u0627\\u062f\\u0644 \\u0628\\u064a\\u0646\\u0647\\u0627 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629. \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0642\\u0627\\u0626\\u0645\\u0629 \\u0643\\u0627\\u0645\\u0644\\u0629 \\u0628\\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u062f\\u0639\\u0648\\u0645\\u0629\\u060c \\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0623\\u0648 \\u0642\\u0645 \\u0628\\u0632\\u064a\\u0627\\u0631\\u0629 \\u0635\\u0641\\u062d\\u0629 Exchange Money \\u0641\\u064a \\u0627\\u0644\\u062a\\u0637\\u0628\\u064a\\u0642.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 monedas puedo cambiar con QRPay Pro?\",\"answer\":\"QRPay Pro admite una variedad de monedas importantes, lo que le permite intercambiarlas con facilidad. Para obtener una lista completa de las monedas admitidas, verifique la configuraci\\u00f3n de su cuenta o visite la p\\u00e1gina Exchange Money en la aplicaci\\u00f3n.\"},\"fr\":{\"question\":\"Quelles devises puis-je \\u00e9changer avec QRPay Pro ?\",\"answer\":\"QRPay Pro prend en charge une vari\\u00e9t\\u00e9 de devises principales, vous permettant d\'\\u00e9changer facilement entre elles. Pour une liste compl\\u00e8te des devises prises en charge, v\\u00e9rifiez les param\\u00e8tres de votre compte ou visitez la page Exchange Money de l\'application.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0915\\u093f\\u0928 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u093e \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0902?\",\"answer\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0906\\u092a \\u0909\\u0928\\u0915\\u0947 \\u092c\\u0940\\u091a \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0938\\u092e\\u0930\\u094d\\u0925\\u093f\\u0924 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u0940 \\u092a\\u0942\\u0930\\u0940 \\u0938\\u0942\\u091a\\u0940 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u0905\\u092a\\u0928\\u0940 \\u0916\\u093e\\u0924\\u093e \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917 \\u091c\\u093e\\u0902\\u091a\\u0947\\u0902 \\u092f\\u093e \\u0910\\u092a \\u092e\\u0947\\u0902 \\u090f\\u0915\\u094d\\u0938\\u091a\\u0947\\u0902\\u091c \\u092e\\u0928\\u0940 \\u092a\\u0947\\u091c \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0902\\u0964\"}},\"id\":\"6722fdf3dd60c\"},\"6722fe0991db1\":{\"language\":{\"en\":{\"question\":\"How long does a currency exchange transaction take?\",\"answer\":\"Currency exchanges are processed instantly. Once you confirm the transaction, your new balance will be available in your account within moments.\"},\"ar\":{\"question\":\"\\u0643\\u0645 \\u0645\\u0646 \\u0627\\u0644\\u0648\\u0642\\u062a \\u062a\\u0633\\u062a\\u063a\\u0631\\u0642 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0629 \\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a\\u061f\",\"answer\":\"\\u062a\\u062a\\u0645 \\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631. \\u0628\\u0645\\u062c\\u0631\\u062f \\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629\\u060c \\u0633\\u064a\\u0643\\u0648\\u0646 \\u0631\\u0635\\u064a\\u062f\\u0643 \\u0627\\u0644\\u062c\\u062f\\u064a\\u062f \\u0645\\u062a\\u0627\\u062d\\u064b\\u0627 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628\\u0643 \\u062e\\u0644\\u0627\\u0644 \\u0644\\u062d\\u0638\\u0627\\u062a.\"},\"es\":{\"question\":\"\\u00bfCu\\u00e1nto tiempo lleva una transacci\\u00f3n de cambio de moneda?\",\"answer\":\"Los cambios de moneda se procesan al instante. Una vez que confirme la transacci\\u00f3n, su nuevo saldo estar\\u00e1 disponible en su cuenta en unos momentos.\"},\"fr\":{\"question\":\"Combien de temps dure une op\\u00e9ration de change ?\",\"answer\":\"Les \\u00e9changes de devises sont trait\\u00e9s instantan\\u00e9ment. Une fois la transaction confirm\\u00e9e, votre nouveau solde sera disponible sur votre compte en quelques instants.\"},\"hi\":{\"question\":\"\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u092e\\u0947\\u0902 \\u0915\\u093f\\u0924\\u0928\\u093e \\u0938\\u092e\\u092f \\u0932\\u0917\\u0924\\u093e \\u0939\\u0948?\",\"answer\":\"\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0924\\u0941\\u0930\\u0902\\u0924 \\u0938\\u0902\\u0938\\u093e\\u0927\\u093f\\u0924 \\u0939\\u094b\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u090f\\u0915 \\u092c\\u093e\\u0930 \\u091c\\u092c \\u0906\\u092a \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930 \\u0926\\u0947\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0924\\u094b \\u0915\\u0941\\u091b \\u0939\\u0940 \\u0915\\u094d\\u0937\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u0906\\u092a\\u0915\\u093e \\u0928\\u092f\\u093e \\u092c\\u0948\\u0932\\u0947\\u0902\\u0938 \\u0906\\u092a\\u0915\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0939\\u094b \\u091c\\u093e\\u090f\\u0917\\u093e\\u0964\"}},\"id\":\"6722fe0991db1\"},\"6722fe1edb933\":{\"language\":{\"en\":{\"question\":\"Are there any fees for exchanging currencies?\",\"answer\":\"Yes, a small transaction fee may apply for currency exchanges. QRPay Pro offers competitive rates, and you\\u2019ll see any applicable fees and the exact conversion rate before you confirm the exchange.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0639\\u0644\\u0649 \\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u0642\\u062f \\u064a\\u062a\\u0645 \\u062a\\u0637\\u0628\\u064a\\u0642 \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0629 \\u0635\\u063a\\u064a\\u0631\\u0629 \\u0639\\u0644\\u0649 \\u062a\\u0628\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a. \\u064a\\u0642\\u062f\\u0645 QRPay Pro \\u0623\\u0633\\u0639\\u0627\\u0631\\u064b\\u0627 \\u062a\\u0646\\u0627\\u0641\\u0633\\u064a\\u0629\\u060c \\u0648\\u0633\\u062a\\u0631\\u0649 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0637\\u0628\\u0642\\u0629 \\u0648\\u0645\\u0639\\u062f\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u062f\\u0642\\u064a\\u0642 \\u0642\\u0628\\u0644 \\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u062a\\u0628\\u0627\\u062f\\u0644.\"},\"es\":{\"question\":\"\\u00bfHay alguna tarifa por cambiar divisas?\",\"answer\":\"S\\u00ed, es posible que se aplique una peque\\u00f1a tarifa de transacci\\u00f3n para los cambios de moneda. QRPay Pro ofrece tarifas competitivas y ver\\u00e1 las tarifas aplicables y la tasa de conversi\\u00f3n exacta antes de confirmar el cambio.\"},\"fr\":{\"question\":\"Y a-t-il des frais pour \\u00e9changer des devises ?\",\"answer\":\"Oui, des frais de transaction minimes peuvent s\'appliquer pour les \\u00e9changes de devises. QRPay Pro propose des tarifs comp\\u00e9titifs et vous verrez tous les frais applicables ainsi que le taux de conversion exact avant de confirmer l\'\\u00e9change.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u094b\\u0908 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0939\\u0948?\",\"answer\":\"\\u0939\\u093e\\u0902, \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0915\\u0947 \\u0932\\u093f\\u090f \\u090f\\u0915 \\u091b\\u094b\\u091f\\u093e \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0932\\u093e\\u0917\\u0942 \\u0939\\u094b \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u094d\\u0930\\u0924\\u093f\\u0938\\u094d\\u092a\\u0930\\u094d\\u0927\\u0940 \\u0926\\u0930\\u0947\\u0902 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948, \\u0914\\u0930 \\u090f\\u0915\\u094d\\u0938\\u091a\\u0947\\u0902\\u091c \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u0906\\u092a\\u0915\\u094b \\u0915\\u094b\\u0908 \\u092d\\u0940 \\u0932\\u093e\\u0917\\u0942 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0914\\u0930 \\u0938\\u091f\\u0940\\u0915 \\u0930\\u0942\\u092a\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0926\\u0930 \\u0926\\u093f\\u0916\\u093e\\u0908 \\u0926\\u0947\\u0917\\u0940\\u0964\"}},\"id\":\"6722fe1edb933\"},\"6722fe33662d2\":{\"language\":{\"en\":{\"question\":\"How do I know the exchange rate is accurate?\",\"answer\":\"QRPay Pro uses real-time exchange rates provided by trusted financial institutions. The rate you see at the time of transaction is the rate applied to your currency conversion, ensuring transparency and accuracy.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u0623\\u0639\\u0631\\u0641 \\u0623\\u0646 \\u0633\\u0639\\u0631 \\u0627\\u0644\\u0635\\u0631\\u0641 \\u062f\\u0642\\u064a\\u0642\\u061f\",\"answer\":\"\\u064a\\u0633\\u062a\\u062e\\u062f\\u0645 QRPay Pro \\u0623\\u0633\\u0639\\u0627\\u0631 \\u0627\\u0644\\u0635\\u0631\\u0641 \\u0641\\u064a \\u0627\\u0644\\u0648\\u0642\\u062a \\u0627\\u0644\\u062d\\u0642\\u064a\\u0642\\u064a \\u0627\\u0644\\u062a\\u064a \\u062a\\u0642\\u062f\\u0645\\u0647\\u0627 \\u0627\\u0644\\u0645\\u0624\\u0633\\u0633\\u0627\\u062a \\u0627\\u0644\\u0645\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0648\\u062b\\u0648\\u0642\\u0629. \\u0627\\u0644\\u0633\\u0639\\u0631 \\u0627\\u0644\\u0630\\u064a \\u062a\\u0631\\u0627\\u0647 \\u0641\\u064a \\u0648\\u0642\\u062a \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629 \\u0647\\u0648 \\u0627\\u0644\\u0633\\u0639\\u0631 \\u0627\\u0644\\u0645\\u0637\\u0628\\u0642 \\u0639\\u0644\\u0649 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0636\\u0645\\u0646 \\u0627\\u0644\\u0634\\u0641\\u0627\\u0641\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062f\\u0642\\u0629.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo s\\u00e9 que el tipo de cambio es exacto?\",\"answer\":\"QRPay Pro utiliza tipos de cambio en tiempo real proporcionados por instituciones financieras confiables. La tasa que ve en el momento de la transacci\\u00f3n es la tasa aplicada a su conversi\\u00f3n de moneda, lo que garantiza transparencia y precisi\\u00f3n.\"},\"fr\":{\"question\":\"Comment puis-je savoir si le taux de change est exact ?\",\"answer\":\"QRPay Pro utilise les taux de change en temps r\\u00e9el fournis par des institutions financi\\u00e8res de confiance. Le taux que vous voyez au moment de la transaction est le taux appliqu\\u00e9 \\u00e0 votre conversion de devise, garantissant transparence et pr\\u00e9cision.\"},\"hi\":{\"question\":\"\\u092e\\u0941\\u091d\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u092a\\u0924\\u093e \\u091a\\u0932\\u0947\\u0917\\u093e \\u0915\\u093f \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0926\\u0930 \\u0938\\u091f\\u0940\\u0915 \\u0939\\u0948?\",\"answer\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0935\\u093f\\u0936\\u094d\\u0935\\u0938\\u0928\\u0940\\u092f \\u0935\\u093f\\u0924\\u094d\\u0924\\u0940\\u092f \\u0938\\u0902\\u0938\\u094d\\u0925\\u093e\\u0928\\u094b\\u0902 \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0940 \\u0917\\u0908 \\u0935\\u093e\\u0938\\u094d\\u0924\\u0935\\u093f\\u0915 \\u0938\\u092e\\u092f \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0926\\u0930\\u094b\\u0902 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0932\\u0947\\u0928-\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0938\\u092e\\u092f \\u0906\\u092a \\u091c\\u094b \\u0926\\u0930 \\u0926\\u0947\\u0916\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0935\\u0939 \\u0906\\u092a\\u0915\\u0940 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0930\\u0942\\u092a\\u093e\\u0902\\u0924\\u0930\\u0923 \\u092a\\u0930 \\u0932\\u093e\\u0917\\u0942 \\u0926\\u0930 \\u0939\\u0948, \\u091c\\u094b \\u092a\\u093e\\u0930\\u0926\\u0930\\u094d\\u0936\\u093f\\u0924\\u093e \\u0914\\u0930 \\u0938\\u091f\\u0940\\u0915\\u0924\\u093e \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0924\\u0940 \\u0939\\u0948\\u0964\"}},\"id\":\"6722fe33662d2\"}}}', 1, 1, '2024-10-31 09:45:14', '2024-11-06 19:10:19');
INSERT INTO `frontend_header_section_faqs` VALUES (2, 5, 'personal', '{\"language\":{\"en\":{\"heading\":\"Currency Exchange Made Easy\",\"sub_heading\":\"Get quick answers to your questions about converting currencies in your QRPay Pro account.\"},\"ar\":{\"heading\":\"\\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0623\\u0635\\u0628\\u062d \\u0633\\u0647\\u0644\\u0627\",\"sub_heading\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0633\\u0631\\u064a\\u0639\\u0629 \\u0644\\u0623\\u0633\\u0626\\u0644\\u062a\\u0643 \\u062d\\u0648\\u0644 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643.\"},\"es\":{\"heading\":\"Cambio de moneda f\\u00e1cil\",\"sub_heading\":\"Obtenga respuestas r\\u00e1pidas a sus preguntas sobre la conversi\\u00f3n de monedas en su cuenta QRPay Pro.\"},\"fr\":{\"heading\":\"Cambio de moneda f\\u00e1cil\",\"sub_heading\":\"Obtenez des r\\u00e9ponses rapides \\u00e0 vos questions sur la conversion de devises dans votre compte QRPay Pro.\"},\"hi\":{\"heading\":\"\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0915\\u094b \\u0906\\u0938\\u093e\\u0928 \\u092c\\u0928\\u093e\\u092f\\u093e \\u0917\\u092f\\u093e\",\"sub_heading\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u094b \\u092a\\u0930\\u093f\\u0935\\u0930\\u094d\\u0924\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0924\\u094d\\u0935\\u0930\\u093f\\u0924 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"67247b1515299\":{\"language\":{\"en\":{\"question\":\"Which currencies can I exchange with QRPay Pro?\",\"answer\":\"QRPay Pro supports a variety of major currencies, allowing you to exchange between them with ease. For a full list of supported currencies, check your account settings or visit the Exchange Money page in the app.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0647\\u064a \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0633\\u062a\\u0628\\u062f\\u0627\\u0644\\u0647\\u0627 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\\u061f\",\"answer\":\"\\u064a\\u062f\\u0639\\u0645 QRPay Pro \\u0645\\u062c\\u0645\\u0648\\u0639\\u0629 \\u0645\\u062a\\u0646\\u0648\\u0639\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0631\\u0626\\u064a\\u0633\\u064a\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0645\\u062d \\u0644\\u0643 \\u0628\\u0627\\u0644\\u062a\\u0628\\u0627\\u062f\\u0644 \\u0628\\u064a\\u0646\\u0647\\u0627 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629. \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0642\\u0627\\u0626\\u0645\\u0629 \\u0643\\u0627\\u0645\\u0644\\u0629 \\u0628\\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u062f\\u0639\\u0648\\u0645\\u0629\\u060c \\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0623\\u0648 \\u0642\\u0645 \\u0628\\u0632\\u064a\\u0627\\u0631\\u0629 \\u0635\\u0641\\u062d\\u0629 Exchange Money \\u0641\\u064a \\u0627\\u0644\\u062a\\u0637\\u0628\\u064a\\u0642.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 monedas puedo cambiar con QRPay Pro?\",\"answer\":\"QRPay Pro admite una variedad de monedas importantes, lo que le permite intercambiarlas con facilidad. Para obtener una lista completa de las monedas admitidas, verifique la configuraci\\u00f3n de su cuenta o visite la p\\u00e1gina Exchange Money en la aplicaci\\u00f3n.\"},\"fr\":{\"question\":\"\\u00bfQu\\u00e9 monedas puedo cambiar con QRPay Pro?\",\"answer\":\"QRPay Pro prend en charge une vari\\u00e9t\\u00e9 de devises principales, vous permettant d\'\\u00e9changer facilement entre elles. Pour une liste compl\\u00e8te des devises prises en charge, v\\u00e9rifiez les param\\u00e8tres de votre compte ou visitez la page Exchange Money de l\'application.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0915\\u093f\\u0928 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u093e \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0902?\",\"answer\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0906\\u092a \\u0909\\u0928\\u0915\\u0947 \\u092c\\u0940\\u091a \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0938\\u092e\\u0930\\u094d\\u0925\\u093f\\u0924 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u0940 \\u092a\\u0942\\u0930\\u0940 \\u0938\\u0942\\u091a\\u0940 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u0905\\u092a\\u0928\\u0940 \\u0916\\u093e\\u0924\\u093e \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917 \\u091c\\u093e\\u0902\\u091a\\u0947\\u0902 \\u092f\\u093e \\u0910\\u092a \\u092e\\u0947\\u0902 \\u090f\\u0915\\u094d\\u0938\\u091a\\u0947\\u0902\\u091c \\u092e\\u0928\\u0940 \\u092a\\u0947\\u091c \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0902\\u0964\"}},\"id\":\"67247b1515299\"},\"67247b1fbbc53\":{\"language\":{\"en\":{\"question\":\"How long does a currency exchange transaction take?\",\"answer\":\"Currency exchanges are processed instantly. Once you confirm the transaction, your new balance will be available in your account within moments.\"},\"ar\":{\"question\":\"\\u0643\\u0645 \\u0645\\u0646 \\u0627\\u0644\\u0648\\u0642\\u062a \\u062a\\u0633\\u062a\\u063a\\u0631\\u0642 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0629 \\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a\\u061f\",\"answer\":\"\\u062a\\u062a\\u0645 \\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631. \\u0628\\u0645\\u062c\\u0631\\u062f \\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629\\u060c \\u0633\\u064a\\u0643\\u0648\\u0646 \\u0631\\u0635\\u064a\\u062f\\u0643 \\u0627\\u0644\\u062c\\u062f\\u064a\\u062f \\u0645\\u062a\\u0627\\u062d\\u064b\\u0627 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628\\u0643 \\u062e\\u0644\\u0627\\u0644 \\u0644\\u062d\\u0638\\u0627\\u062a.\"},\"es\":{\"question\":\"\\u00bfCu\\u00e1nto tiempo lleva una transacci\\u00f3n de cambio de moneda?\",\"answer\":\"Los cambios de moneda se procesan al instante. Una vez que confirme la transacci\\u00f3n, su nuevo saldo estar\\u00e1 disponible en su cuenta en unos momentos.\"},\"fr\":{\"question\":\"\\u00bfCu\\u00e1nto tiempo lleva una transacci\\u00f3n de cambio de moneda?\",\"answer\":\"Les \\u00e9changes de devises sont trait\\u00e9s instantan\\u00e9ment. Une fois la transaction confirm\\u00e9e, votre nouveau solde sera disponible sur votre compte en quelques instants.\"},\"hi\":{\"question\":\"\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u092e\\u0947\\u0902 \\u0915\\u093f\\u0924\\u0928\\u093e \\u0938\\u092e\\u092f \\u0932\\u0917\\u0924\\u093e \\u0939\\u0948?\",\"answer\":\"\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0924\\u0941\\u0930\\u0902\\u0924 \\u0938\\u0902\\u0938\\u093e\\u0927\\u093f\\u0924 \\u0939\\u094b\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u090f\\u0915 \\u092c\\u093e\\u0930 \\u091c\\u092c \\u0906\\u092a \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930 \\u0926\\u0947\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0924\\u094b \\u0915\\u0941\\u091b \\u0939\\u0940 \\u0915\\u094d\\u0937\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u0906\\u092a\\u0915\\u093e \\u0928\\u092f\\u093e \\u092c\\u0948\\u0932\\u0947\\u0902\\u0938 \\u0906\\u092a\\u0915\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0939\\u094b \\u091c\\u093e\\u090f\\u0917\\u093e\\u0964\"}},\"id\":\"67247b1fbbc53\"},\"67247b2c5e4fa\":{\"language\":{\"en\":{\"question\":\"Are there any fees for exchanging currencies?\",\"answer\":\"Yes, a small transaction fee may apply for currency exchanges. QRPay Pro offers competitive rates, and you\\u2019ll see any applicable fees and the exact conversion rate before you confirm the exchange.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0639\\u0644\\u0649 \\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u0642\\u062f \\u064a\\u062a\\u0645 \\u062a\\u0637\\u0628\\u064a\\u0642 \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0629 \\u0635\\u063a\\u064a\\u0631\\u0629 \\u0639\\u0644\\u0649 \\u062a\\u0628\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a. \\u064a\\u0642\\u062f\\u0645 QRPay Pro \\u0623\\u0633\\u0639\\u0627\\u0631\\u064b\\u0627 \\u062a\\u0646\\u0627\\u0641\\u0633\\u064a\\u0629\\u060c \\u0648\\u0633\\u062a\\u0631\\u0649 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0637\\u0628\\u0642\\u0629 \\u0648\\u0645\\u0639\\u062f\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u062f\\u0642\\u064a\\u0642 \\u0642\\u0628\\u0644 \\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u062a\\u0628\\u0627\\u062f\\u0644.\"},\"es\":{\"question\":\"\\u00bfHay alguna tarifa por cambiar divisas?\",\"answer\":\"S\\u00ed, es posible que se aplique una peque\\u00f1a tarifa de transacci\\u00f3n para los cambios de moneda. QRPay Pro ofrece tarifas competitivas y ver\\u00e1 las tarifas aplicables y la tasa de conversi\\u00f3n exacta antes de confirmar el cambio.\"},\"fr\":{\"question\":\"\\u00bfHay alguna tarifa por cambiar divisas?\",\"answer\":\"Oui, des frais de transaction minimes peuvent s\'appliquer pour les \\u00e9changes de devises. QRPay Pro propose des tarifs comp\\u00e9titifs et vous verrez tous les frais applicables ainsi que le taux de conversion exact avant de confirmer l\'\\u00e9change.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u094b\\u0908 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0939\\u0948?\",\"answer\":\"\\u0939\\u093e\\u0902, \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0915\\u0947 \\u0932\\u093f\\u090f \\u090f\\u0915 \\u091b\\u094b\\u091f\\u093e \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0932\\u093e\\u0917\\u0942 \\u0939\\u094b \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u094d\\u0930\\u0924\\u093f\\u0938\\u094d\\u092a\\u0930\\u094d\\u0927\\u0940 \\u0926\\u0930\\u0947\\u0902 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948, \\u0914\\u0930 \\u090f\\u0915\\u094d\\u0938\\u091a\\u0947\\u0902\\u091c \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u0906\\u092a\\u0915\\u094b \\u0915\\u094b\\u0908 \\u092d\\u0940 \\u0932\\u093e\\u0917\\u0942 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0914\\u0930 \\u0938\\u091f\\u0940\\u0915 \\u0930\\u0942\\u092a\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0926\\u0930 \\u0926\\u093f\\u0916\\u093e\\u0908 \\u0926\\u0947\\u0917\\u0940\\u0964\"}},\"id\":\"67247b2c5e4fa\"},\"67247b37b689e\":{\"language\":{\"en\":{\"question\":\"How do I know the exchange rate is accurate?\",\"answer\":\"QRPay Pro uses real-time exchange rates provided by trusted financial institutions. The rate you see at the time of transaction is the rate applied to your currency conversion, ensuring transparency and accuracy.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u0623\\u0639\\u0631\\u0641 \\u0623\\u0646 \\u0633\\u0639\\u0631 \\u0627\\u0644\\u0635\\u0631\\u0641 \\u062f\\u0642\\u064a\\u0642\\u061f\",\"answer\":\"\\u064a\\u0633\\u062a\\u062e\\u062f\\u0645 QRPay Pro \\u0623\\u0633\\u0639\\u0627\\u0631 \\u0627\\u0644\\u0635\\u0631\\u0641 \\u0641\\u064a \\u0627\\u0644\\u0648\\u0642\\u062a \\u0627\\u0644\\u062d\\u0642\\u064a\\u0642\\u064a \\u0627\\u0644\\u062a\\u064a \\u062a\\u0642\\u062f\\u0645\\u0647\\u0627 \\u0627\\u0644\\u0645\\u0624\\u0633\\u0633\\u0627\\u062a \\u0627\\u0644\\u0645\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0648\\u062b\\u0648\\u0642\\u0629. \\u0627\\u0644\\u0633\\u0639\\u0631 \\u0627\\u0644\\u0630\\u064a \\u062a\\u0631\\u0627\\u0647 \\u0641\\u064a \\u0648\\u0642\\u062a \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629 \\u0647\\u0648 \\u0627\\u0644\\u0633\\u0639\\u0631 \\u0627\\u0644\\u0645\\u0637\\u0628\\u0642 \\u0639\\u0644\\u0649 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0636\\u0645\\u0646 \\u0627\\u0644\\u0634\\u0641\\u0627\\u0641\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062f\\u0642\\u0629.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo s\\u00e9 que el tipo de cambio es exacto?\",\"answer\":\"QRPay Pro utiliza tipos de cambio en tiempo real proporcionados por instituciones financieras confiables. La tasa que ve en el momento de la transacci\\u00f3n es la tasa aplicada a su conversi\\u00f3n de moneda, lo que garantiza transparencia y precisi\\u00f3n.\"},\"fr\":{\"question\":\"\\u00bfC\\u00f3mo s\\u00e9 que el tipo de cambio es exacto?\",\"answer\":\"QRPay Pro utilise les taux de change en temps r\\u00e9el fournis par des institutions financi\\u00e8res de confiance. Le taux que vous voyez au moment de la transaction est le taux appliqu\\u00e9 \\u00e0 votre conversion de devise, garantissant transparence et pr\\u00e9cision.\"},\"hi\":{\"question\":\"\\u092e\\u0941\\u091d\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u092a\\u0924\\u093e \\u091a\\u0932\\u0947\\u0917\\u093e \\u0915\\u093f \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0926\\u0930 \\u0938\\u091f\\u0940\\u0915 \\u0939\\u0948?\",\"answer\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0935\\u093f\\u0936\\u094d\\u0935\\u0938\\u0928\\u0940\\u092f \\u0935\\u093f\\u0924\\u094d\\u0924\\u0940\\u092f \\u0938\\u0902\\u0938\\u094d\\u0925\\u093e\\u0928\\u094b\\u0902 \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0940 \\u0917\\u0908 \\u0935\\u093e\\u0938\\u094d\\u0924\\u0935\\u093f\\u0915 \\u0938\\u092e\\u092f \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0926\\u0930\\u094b\\u0902 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0932\\u0947\\u0928-\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0938\\u092e\\u092f \\u0906\\u092a \\u091c\\u094b \\u0926\\u0930 \\u0926\\u0947\\u0916\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0935\\u0939 \\u0906\\u092a\\u0915\\u0940 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0930\\u0942\\u092a\\u093e\\u0902\\u0924\\u0930\\u0923 \\u092a\\u0930 \\u0932\\u093e\\u0917\\u0942 \\u0926\\u0930 \\u0939\\u0948, \\u091c\\u094b \\u092a\\u093e\\u0930\\u0926\\u0930\\u094d\\u0936\\u093f\\u0924\\u093e \\u0914\\u0930 \\u0938\\u091f\\u0940\\u0915\\u0924\\u093e \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0924\\u0940 \\u0939\\u0948\\u0964\"}},\"id\":\"67247b37b689e\"}}}', 1, 1, '2024-11-01 12:53:58', '2024-11-06 19:18:30');
INSERT INTO `frontend_header_section_faqs` VALUES (6, 6, 'personal', '{\"language\":{\"en\":{\"heading\":\"Sending Money with QRPay Pro: Your Questions Answered\",\"sub_heading\":\"Learn everything you need to know to transfer funds effortlessly and securely.\"},\"ar\":{\"heading\":\"\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro: \\u0627\\u0644\\u0625\\u062c\\u0627\\u0628\\u0629 \\u0639\\u0644\\u0649 \\u0623\\u0633\\u0626\\u0644\\u062a\\u0643\",\"sub_heading\":\"\\u062a\\u0639\\u0644\\u0645 \\u0643\\u0644 \\u0645\\u0627 \\u062a\\u062d\\u062a\\u0627\\u062c \\u0625\\u0644\\u0649 \\u0645\\u0639\\u0631\\u0641\\u062a\\u0647 \\u0644\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0648\\u0623\\u0645\\u0627\\u0646.\"},\"es\":{\"heading\":\"Env\\u00edo de dinero con QRPay Pro: respuestas a sus preguntas\",\"sub_heading\":\"Aprenda todo lo que necesita saber para transferir fondos de forma segura y sin esfuerzo.\"},\"fr\":{\"heading\":\"Env\\u00edo de dinero con QRPay Pro: respuestas a sus preguntas\",\"sub_heading\":\"Apprenez tout ce que vous devez savoir pour transf\\u00e9rer des fonds sans effort et en toute s\\u00e9curit\\u00e9.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0928\\u093e: \\u0906\\u092a\\u0915\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0909\\u0924\\u094d\\u0924\\u0930\",\"sub_heading\":\"\\u0938\\u0939\\u091c\\u0924\\u093e \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0924\\u0930\\u0940\\u0915\\u0947 \\u0938\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0906\\u092a\\u0915\\u094b \\u091c\\u094b \\u0915\\u0941\\u091b \\u092d\\u0940 \\u091c\\u093e\\u0928\\u0928\\u0947 \\u0915\\u0940 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915\\u0924\\u093e \\u0939\\u0948, \\u0909\\u0938\\u0947 \\u091c\\u093e\\u0928\\u0947\\u0902\\u0964\"}},\"items\":{\"67249650b0783\":{\"language\":{\"en\":{\"question\":\"How can I send money to someone with QRPay Pro?\",\"answer\":\"Simply enter the recipient\\u2019s QRPay Pro ID, email, or phone number, or scan their QR code. Once you confirm the details, the funds will be sent instantly to their account.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u0634\\u062e\\u0635 \\u0645\\u0627 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\\u061f\",\"answer\":\"\\u0645\\u0627 \\u0639\\u0644\\u064a\\u0643 \\u0633\\u0648\\u0649 \\u0625\\u062f\\u062e\\u0627\\u0644 \\u0645\\u0639\\u0631\\u0641 QRPay Pro \\u0623\\u0648 \\u0627\\u0644\\u0628\\u0631\\u064a\\u062f \\u0627\\u0644\\u0625\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a \\u0623\\u0648 \\u0631\\u0642\\u0645 \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645\\u060c \\u0623\\u0648 \\u0645\\u0633\\u062d \\u0631\\u0645\\u0632 QR \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0647 \\u0636\\u0648\\u0626\\u064a\\u064b\\u0627. \\u0628\\u0645\\u062c\\u0631\\u062f \\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644\\u060c \\u0633\\u064a\\u062a\\u0645 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0647\\u0645.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo puedo enviar dinero a alguien con QRPay Pro?\",\"answer\":\"Simplemente ingrese el ID, el correo electr\\u00f3nico o el n\\u00famero de tel\\u00e9fono de QRPay Pro del destinatario, o escanee su c\\u00f3digo QR. Una vez que confirme los detalles, los fondos se enviar\\u00e1n instant\\u00e1neamente a su cuenta.\"},\"fr\":{\"question\":\"\\u00bfC\\u00f3mo puedo enviar dinero a alguien con QRPay Pro?\",\"answer\":\"Entrez simplement l\'identifiant QRPay Pro, l\'e-mail ou le num\\u00e9ro de t\\u00e9l\\u00e9phone du destinataire, ou scannez son code QR. Une fois les d\\u00e9tails confirm\\u00e9s, les fonds seront envoy\\u00e9s instantan\\u00e9ment sur leur compte.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay Pro \\u0938\\u0947 \\u0915\\u093f\\u0938\\u0940 \\u0915\\u094b \\u092a\\u0948\\u0938\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u092c\\u0938 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u0940 QRPay \\u092a\\u094d\\u0930\\u094b \\u0906\\u0908\\u0921\\u0940, \\u0908\\u092e\\u0947\\u0932, \\u092f\\u093e \\u092b\\u093c\\u094b\\u0928 \\u0928\\u0902\\u092c\\u0930 \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902, \\u092f\\u093e \\u0909\\u0928\\u0915\\u0947 QR \\u0915\\u094b\\u0921 \\u0915\\u094b \\u0938\\u094d\\u0915\\u0948\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964 \\u090f\\u0915 \\u092c\\u093e\\u0930 \\u091c\\u092c \\u0906\\u092a \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930 \\u0932\\u0947\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0924\\u094b \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0924\\u0941\\u0930\\u0902\\u0924 \\u0909\\u0928\\u0915\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u092d\\u0947\\u091c \\u0926\\u0940 \\u091c\\u093e\\u090f\\u0917\\u0940\\u0964\"}},\"id\":\"67249650b0783\"},\"6724965aec660\":{\"language\":{\"en\":{\"question\":\"Are there any fees for sending money?\",\"answer\":\"QRPay Pro has competitive fees for money transfers, which may vary depending on the currency and destination. All fees are shown before you confirm the transaction, so there are no surprises.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u061f\",\"answer\":\"\\u0644\\u062f\\u0649 QRPay Pro \\u0631\\u0633\\u0648\\u0645 \\u062a\\u0646\\u0627\\u0641\\u0633\\u064a\\u0629 \\u0644\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u060c \\u0648\\u0627\\u0644\\u062a\\u064a \\u0642\\u062f \\u062a\\u062e\\u062a\\u0644\\u0641 \\u062d\\u0633\\u0628 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0629 \\u0648\\u0627\\u0644\\u0648\\u062c\\u0647\\u0629. \\u064a\\u062a\\u0645 \\u0639\\u0631\\u0636 \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0631\\u0633\\u0648\\u0645 \\u0642\\u0628\\u0644 \\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629\\u060c \\u0644\\u0630\\u0644\\u0643 \\u0644\\u0627 \\u062a\\u0648\\u062c\\u062f \\u0645\\u0641\\u0627\\u062c\\u0622\\u062a.\"},\"es\":{\"question\":\"\\u00bfHay alguna tarifa por enviar dinero?\",\"answer\":\"QRPay Pro tiene tarifas competitivas para transferencias de dinero, que pueden variar seg\\u00fan la moneda y el destino. Todas las tarifas se muestran antes de confirmar la transacci\\u00f3n, para que no haya sorpresas.\"},\"fr\":{\"question\":\"\\u00bfHay alguna tarifa por enviar dinero?\",\"answer\":\"QRPay Pro propose des frais comp\\u00e9titifs pour les transferts d\'argent, qui peuvent varier en fonction de la devise et de la destination. Tous les frais sont affich\\u00e9s avant que vous confirmiez la transaction, il n\'y a donc pas de surprises.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u094b\\u0908 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0939\\u0948?\",\"answer\":\"QRPay Pro \\u092e\\u0947\\u0902 \\u0927\\u0928 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092a\\u094d\\u0930\\u0924\\u093f\\u0938\\u094d\\u092a\\u0930\\u094d\\u0927\\u0940 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0939\\u0948, \\u091c\\u094b \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0914\\u0930 \\u0917\\u0902\\u0924\\u0935\\u094d\\u092f \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u092d\\u093f\\u0928\\u094d\\u0928 \\u0939\\u094b \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0932\\u0947\\u0928-\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u0938\\u092d\\u0940 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0926\\u093f\\u0916\\u093e\\u090f \\u091c\\u093e\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0907\\u0938\\u0932\\u093f\\u090f \\u0915\\u094b\\u0908 \\u0906\\u0936\\u094d\\u091a\\u0930\\u094d\\u092f \\u0928\\u0939\\u0940\\u0902 \\u0939\\u0948\\u0964\"}},\"id\":\"6724965aec660\"},\"672496649c9a2\":{\"language\":{\"en\":{\"question\":\"Can I send money internationally?\",\"answer\":\"Yes! QRPay Pro supports international transfers. If the recipient\\u2019s currency differs, QRPay Pro will convert your funds at the current exchange rate, making global transfers simple and hassle-free.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u062f\\u0648\\u0644\\u064a\\u0627\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645! \\u064a\\u062f\\u0639\\u0645 QRPay Pro \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u062f\\u0648\\u0644\\u064a\\u0629. \\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646\\u062a \\u0639\\u0645\\u0644\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645 \\u0645\\u062e\\u062a\\u0644\\u0641\\u0629\\u060c \\u0641\\u0633\\u064a\\u0642\\u0648\\u0645 QRPay Pro \\u0628\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0628\\u0633\\u0639\\u0631 \\u0627\\u0644\\u0635\\u0631\\u0641 \\u0627\\u0644\\u062d\\u0627\\u0644\\u064a\\u060c \\u0645\\u0645\\u0627 \\u064a\\u062c\\u0639\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645\\u064a\\u0629 \\u0628\\u0633\\u064a\\u0637\\u0629 \\u0648\\u062e\\u0627\\u0644\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u062a\\u0627\\u0639\\u0628.\"},\"es\":{\"question\":\"\\u00bfPuedo enviar dinero internacionalmente?\",\"answer\":\"\\u00a1S\\u00ed! QRPay Pro admite transferencias internacionales. Si la moneda del destinatario es diferente, QRPay Pro convertir\\u00e1 sus fondos al tipo de cambio actual, haciendo que las transferencias globales sean simples y sin complicaciones.\"},\"fr\":{\"question\":\"\\u00bfPuedo enviar dinero internacionalmente?\",\"answer\":\"Oui! QRPay Pro prend en charge les virements internationaux. Si la devise du destinataire diff\\u00e8re, QRPay Pro convertira vos fonds au taux de change actuel, rendant les transferts mondiaux simples et sans tracas.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u0905\\u0902\\u0924\\u0930\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0938\\u094d\\u0924\\u0930 \\u092a\\u0930 \\u092a\\u0948\\u0938\\u093e \\u092d\\u0947\\u091c \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0939\\u093e\\u0901! QRPay \\u092a\\u094d\\u0930\\u094b \\u0905\\u0902\\u0924\\u0930\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948\\u0964 \\u092f\\u0926\\u093f \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u0940 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u092d\\u093f\\u0928\\u094d\\u0928 \\u0939\\u0948, \\u0924\\u094b QRPay Pro \\u0906\\u092a\\u0915\\u0947 \\u092b\\u0902\\u0921 \\u0915\\u094b \\u0935\\u0930\\u094d\\u0924\\u092e\\u093e\\u0928 \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0926\\u0930 \\u092a\\u0930 \\u092a\\u0930\\u093f\\u0935\\u0930\\u094d\\u0924\\u093f\\u0924 \\u0915\\u0930 \\u0926\\u0947\\u0917\\u093e, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0935\\u0948\\u0936\\u094d\\u0935\\u093f\\u0915 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0938\\u0930\\u0932 \\u0914\\u0930 \\u092a\\u0930\\u0947\\u0936\\u093e\\u0928\\u0940 \\u092e\\u0941\\u0915\\u094d\\u0924 \\u0939\\u094b \\u091c\\u093e\\u090f\\u0917\\u093e\\u0964\"}},\"id\":\"672496649c9a2\"},\"672496727c783\":{\"language\":{\"en\":{\"question\":\"How secure is it to send money through QRPay Pro?\",\"answer\":\"Your security is our top priority. QRPay Pro uses advanced encryption and authentication methods to ensure your transactions are safe and secure, giving you peace of mind with every transfer.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0645\\u062f\\u0649 \\u0623\\u0645\\u0627\\u0646 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0639\\u0628\\u0631 QRPay Pro\\u061f\",\"answer\":\"\\u0623\\u0645\\u0646\\u0643 \\u0647\\u0648 \\u0623\\u0648\\u0644\\u0648\\u064a\\u062a\\u0646\\u0627 \\u0627\\u0644\\u0642\\u0635\\u0648\\u0649. \\u064a\\u0633\\u062a\\u062e\\u062f\\u0645 QRPay Pro \\u0623\\u0633\\u0627\\u0644\\u064a\\u0628 \\u0627\\u0644\\u062a\\u0634\\u0641\\u064a\\u0631 \\u0648\\u0627\\u0644\\u0645\\u0635\\u0627\\u062f\\u0642\\u0629 \\u0627\\u0644\\u0645\\u062a\\u0642\\u062f\\u0645\\u0629 \\u0644\\u0636\\u0645\\u0627\\u0646 \\u0623\\u0646 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u0643 \\u0622\\u0645\\u0646\\u0629 \\u0648\\u0645\\u0623\\u0645\\u0648\\u0646\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0645\\u0646\\u062d\\u0643 \\u0631\\u0627\\u062d\\u0629 \\u0627\\u0644\\u0628\\u0627\\u0644 \\u0645\\u0639 \\u0643\\u0644 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u062a\\u062d\\u0648\\u064a\\u0644.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 tan seguro es enviar dinero a trav\\u00e9s de QRPay Pro?\",\"answer\":\"Su seguridad es nuestra principal prioridad. QRPay Pro utiliza m\\u00e9todos avanzados de cifrado y autenticaci\\u00f3n para garantizar que sus transacciones sean seguras, brind\\u00e1ndole tranquilidad con cada transferencia.\"},\"fr\":{\"question\":\"\\u00bfQu\\u00e9 tan seguro es enviar dinero a trav\\u00e9s de QRPay Pro?\",\"answer\":\"Votre s\\u00e9curit\\u00e9 est notre priorit\\u00e9 absolue. QRPay Pro utilise des m\\u00e9thodes avanc\\u00e9es de cryptage et d\'authentification pour garantir la s\\u00e9curit\\u00e9 de vos transactions, vous offrant ainsi une tranquillit\\u00e9 d\'esprit \\u00e0 chaque transfert.\"},\"hi\":{\"question\":\"QRPay Pro \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0928\\u093e \\u0915\\u093f\\u0924\\u0928\\u093e \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0939\\u0948?\",\"answer\":\"\\u0906\\u092a\\u0915\\u0940 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0939\\u092e\\u093e\\u0930\\u0940 \\u0938\\u0930\\u094d\\u0935\\u094b\\u091a\\u094d\\u091a \\u092a\\u094d\\u0930\\u093e\\u0925\\u092e\\u093f\\u0915\\u0924\\u093e \\u0939\\u0948. QRPay Pro \\u092f\\u0939 \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0909\\u0928\\u094d\\u0928\\u0924 \\u090f\\u0928\\u094d\\u0915\\u094d\\u0930\\u093f\\u092a\\u094d\\u0936\\u0928 \\u0914\\u0930 \\u092a\\u094d\\u0930\\u092e\\u093e\\u0923\\u0940\\u0915\\u0930\\u0923 \\u0935\\u093f\\u0927\\u093f\\u092f\\u094b\\u0902 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948 \\u0915\\u093f \\u0906\\u092a\\u0915\\u093e \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0914\\u0930 \\u0938\\u0902\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0939\\u0948, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0906\\u092a\\u0915\\u094b \\u0939\\u0930 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u092e\\u093e\\u0928\\u0938\\u093f\\u0915 \\u0936\\u093e\\u0902\\u0924\\u093f \\u092e\\u093f\\u0932\\u0924\\u0940 \\u0939\\u0948\\u0964\"}},\"id\":\"672496727c783\"}}}', 1, 1, '2024-11-01 14:50:11', '2024-11-06 19:25:28');
INSERT INTO `frontend_header_section_faqs` VALUES (7, 7, 'personal', '{\"language\":{\"en\":{\"heading\":\"Quick Answers About QRPay Pro\\u2019s Payment Link Feature\",\"sub_heading\":\"Find out how to create, share, and receive payments securely using QRPay Pro\\u2019s payment links.\"},\"ar\":{\"heading\":\"\\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0633\\u0631\\u064a\\u0639\\u0629 \\u062d\\u0648\\u0644 \\u0645\\u064a\\u0632\\u0629 \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0641\\u064a QRPay Pro\",\"sub_heading\":\"\\u062a\\u0639\\u0631\\u0641 \\u0639\\u0644\\u0649 \\u0643\\u064a\\u0641\\u064a\\u0629 \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0648\\u0645\\u0634\\u0627\\u0631\\u0643\\u062a\\u0647\\u0627 \\u0648\\u0627\\u0633\\u062a\\u0644\\u0627\\u0645\\u0647\\u0627 \\u0628\\u0634\\u0643\\u0644 \\u0622\\u0645\\u0646 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0631\\u0648\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0640 QRPay Pro.\"},\"es\":{\"heading\":\"Respuestas r\\u00e1pidas sobre la funci\\u00f3n de enlace de pago de QRPay Pro\",\"sub_heading\":\"Descubra c\\u00f3mo crear, compartir y recibir pagos de forma segura utilizando los enlaces de pago de QRPay Pro.\"},\"fr\":{\"heading\":\"Respuestas r\\u00e1pidas sobre la funci\\u00f3n de enlace de pago de QRPay Pro\",\"sub_heading\":\"D\\u00e9couvrez comment cr\\u00e9er, partager et recevoir des paiements en toute s\\u00e9curit\\u00e9 \\u00e0 l\'aide des liens de paiement de QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0924\\u094d\\u0935\\u0930\\u093f\\u0924 \\u0909\\u0924\\u094d\\u0924\\u0930\",\"sub_heading\":\"QRPay Pro \\u0915\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u092c\\u0928\\u093e\\u0928\\u0947, \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0914\\u0930 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u093e \\u0924\\u0930\\u0940\\u0915\\u093e \\u091c\\u093e\\u0928\\u0947\\u0902\\u0964\"}},\"items\":{\"6724979300b40\":{\"language\":{\"en\":{\"question\":\"How do I create a payment link in QRPay Pro?\",\"answer\":\"To create a payment link, navigate to the Payment Link option in your QRPay Pro account. Enter the amount and currency, generate the link, and you\\u2019re ready to share it.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u0623\\u0642\\u0648\\u0645 \\u0628\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u0627\\u0628\\u0637 \\u062f\\u0641\\u0639 \\u0641\\u064a QRPay Pro\\u061f\",\"answer\":\"\\u0644\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u0627\\u0628\\u0637 \\u062f\\u0641\\u0639\\u060c \\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u062e\\u064a\\u0627\\u0631 \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643. \\u0623\\u062f\\u062e\\u0644 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a \\u0648\\u0627\\u0644\\u0639\\u0645\\u0644\\u0629\\u060c \\u0648\\u0623\\u0646\\u0634\\u0626 \\u0627\\u0644\\u0631\\u0627\\u0628\\u0637\\u060c \\u0648\\u0633\\u062a\\u0643\\u0648\\u0646 \\u062c\\u0627\\u0647\\u0632\\u064b\\u0627 \\u0644\\u0645\\u0634\\u0627\\u0631\\u0643\\u062a\\u0647.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo creo un enlace de pago en QRPay Pro?\",\"answer\":\"Para crear un enlace de pago, navegue hasta la opci\\u00f3n Enlace de pago en su cuenta QRPay Pro. Ingrese el monto y la moneda, genere el enlace y estar\\u00e1 listo para compartirlo.\"},\"fr\":{\"question\":\"\\u00bfC\\u00f3mo creo un enlace de pago en QRPay Pro?\",\"answer\":\"Pour cr\\u00e9er un lien de paiement, acc\\u00e9dez \\u00e0 l\'option Lien de paiement dans votre compte QRPay Pro. Entrez le montant et la devise, g\\u00e9n\\u00e9rez le lien et vous \\u00eates pr\\u00eat \\u00e0 le partager.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay Pro \\u092e\\u0947\\u0902 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0915\\u0948\\u0938\\u0947 \\u092c\\u0928\\u093e\\u090a\\u0902?\",\"answer\":\"\\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u092c\\u0928\\u093e\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0901\\u0964 \\u0930\\u093e\\u0936\\u093f \\u0914\\u0930 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902, \\u0932\\u093f\\u0902\\u0915 \\u091c\\u0928\\u0930\\u0947\\u091f \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u0906\\u092a \\u0907\\u0938\\u0947 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0924\\u0948\\u092f\\u093e\\u0930 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724979300b40\"},\"6724979f4c153\":{\"language\":{\"en\":{\"question\":\"Are there any fees for using a payment link?\",\"answer\":\"A small transaction fee may apply to payment link transactions. You\\u2019ll see the fee before you confirm the link creation, ensuring transparency and no hidden costs.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0644\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639\\u061f\",\"answer\":\"\\u0642\\u062f \\u064a\\u062a\\u0645 \\u062a\\u0637\\u0628\\u064a\\u0642 \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0629 \\u0635\\u063a\\u064a\\u0631\\u0629 \\u0639\\u0644\\u0649 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639. \\u0633\\u062a\\u0631\\u0649 \\u0627\\u0644\\u0631\\u0633\\u0648\\u0645 \\u0642\\u0628\\u0644 \\u062a\\u0623\\u0643\\u064a\\u062f \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0627\\u0644\\u0631\\u0627\\u0628\\u0637\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0636\\u0645\\u0646 \\u0627\\u0644\\u0634\\u0641\\u0627\\u0641\\u064a\\u0629 \\u0648\\u0639\\u062f\\u0645 \\u0648\\u062c\\u0648\\u062f \\u062a\\u0643\\u0627\\u0644\\u064a\\u0641 \\u0645\\u062e\\u0641\\u064a\\u0629.\"},\"es\":{\"question\":\"\\u00bfHay alguna tarifa por usar un enlace de pago?\",\"answer\":\"Es posible que se aplique una peque\\u00f1a tarifa de transacci\\u00f3n a las transacciones de enlace de pago. Ver\\u00e1 la tarifa antes de confirmar la creaci\\u00f3n del enlace, lo que garantiza transparencia y sin costos ocultos.\"},\"fr\":{\"question\":\"\\u00bfHay alguna tarifa por usar un enlace de pago?\",\"answer\":\"Des frais de transaction minimes peuvent s\'appliquer aux transactions avec lien de paiement. Vous verrez les frais avant de confirmer la cr\\u00e9ation du lien, garantissant ainsi la transparence et l\\u2019absence de co\\u00fbts cach\\u00e9s.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u094b\\u0908 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0939\\u0948?\",\"answer\":\"\\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u092a\\u0930 \\u090f\\u0915 \\u091b\\u094b\\u091f\\u093e \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0932\\u093e\\u0917\\u0942 \\u0939\\u094b \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0932\\u093f\\u0902\\u0915 \\u0928\\u093f\\u0930\\u094d\\u092e\\u093e\\u0923 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u0906\\u092a\\u0915\\u094b \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0926\\u093f\\u0916\\u093e\\u0908 \\u0926\\u0947\\u0917\\u093e, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u092a\\u093e\\u0930\\u0926\\u0930\\u094d\\u0936\\u093f\\u0924\\u093e \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0939\\u094b\\u0917\\u0940 \\u0914\\u0930 \\u0915\\u094b\\u0908 \\u091b\\u093f\\u092a\\u0940 \\u0939\\u0941\\u0908 \\u0932\\u093e\\u0917\\u0924 \\u0928\\u0939\\u0940\\u0902 \\u0939\\u094b\\u0917\\u0940\\u0964\"}},\"id\":\"6724979f4c153\"},\"672497ae69f26\":{\"language\":{\"en\":{\"question\":\"Can I share a payment link with someone outside my country?\",\"answer\":\"Yes, QRPay Pro supports international payments. If the payer\\u2019s currency is different, QRPay Pro will handle the currency conversion, making it easy to receive global payments.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0645\\u0634\\u0627\\u0631\\u0643\\u0629 \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0645\\u0639 \\u0634\\u062e\\u0635 \\u062e\\u0627\\u0631\\u062c \\u0628\\u0644\\u062f\\u064a\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c QRPay Pro \\u064a\\u062f\\u0639\\u0645 \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0627\\u0644\\u062f\\u0648\\u0644\\u064a\\u0629. \\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646\\u062a \\u0639\\u0645\\u0644\\u0629 \\u0627\\u0644\\u062f\\u0627\\u0641\\u0639 \\u0645\\u062e\\u062a\\u0644\\u0641\\u0629\\u060c \\u0641\\u0633\\u064a\\u0642\\u0648\\u0645 QRPay Pro \\u0628\\u0627\\u0644\\u062a\\u0639\\u0627\\u0645\\u0644 \\u0645\\u0639 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0647\\u0644 \\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645\\u064a\\u0629.\"},\"es\":{\"question\":\"\\u00bfPuedo compartir un enlace de pago con alguien fuera de mi pa\\u00eds?\",\"answer\":\"S\\u00ed, QRPay Pro admite pagos internacionales. Si la moneda del pagador es diferente, QRPay Pro se encargar\\u00e1 de la conversi\\u00f3n de moneda, lo que facilitar\\u00e1 la recepci\\u00f3n de pagos globales.\"},\"fr\":{\"question\":\"\\u00bfPuedo compartir un enlace de pago con alguien fuera de mi pa\\u00eds?\",\"answer\":\"Oui, QRPay Pro prend en charge les paiements internationaux. Si la devise du payeur est diff\\u00e9rente, QRPay Pro se chargera de la conversion de devise, facilitant ainsi la r\\u00e9ception de paiements internationaux.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u0926\\u0947\\u0936 \\u0915\\u0947 \\u092c\\u093e\\u0939\\u0930 \\u0915\\u0947 \\u0915\\u093f\\u0938\\u0940 \\u0935\\u094d\\u092f\\u0915\\u094d\\u0924\\u093f \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0939\\u093e\\u0901, QRPay Pro \\u0905\\u0902\\u0924\\u0930\\u094d\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948\\u0964 \\u092f\\u0926\\u093f \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u0940 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0905\\u0932\\u0917 \\u0939\\u0948, \\u0924\\u094b QRPay \\u092a\\u094d\\u0930\\u094b \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0930\\u0942\\u092a\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u094b \\u0938\\u0902\\u092d\\u093e\\u0932 \\u0932\\u0947\\u0917\\u093e, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0935\\u0948\\u0936\\u094d\\u0935\\u093f\\u0915 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0928\\u093e \\u0906\\u0938\\u093e\\u0928 \\u0939\\u094b \\u091c\\u093e\\u090f\\u0917\\u093e\\u0964\"}},\"id\":\"672497ae69f26\"},\"672497b8544d1\":{\"language\":{\"en\":{\"question\":\"How secure is a payment link?\",\"answer\":\"QRPay Pro\\u2019s payment links are encrypted and designed with security in mind. Each link is unique, and QRPay Pro uses advanced protection to ensure your transactions are safe and private.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0645\\u062f\\u0649 \\u0623\\u0645\\u0627\\u0646 \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639\\u061f\",\"answer\":\"\\u0631\\u0648\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0640 QRPay Pro \\u0645\\u0634\\u0641\\u0631\\u0629 \\u0648\\u0645\\u0635\\u0645\\u0645\\u0629 \\u0645\\u0639 \\u0623\\u062e\\u0630 \\u0627\\u0644\\u0623\\u0645\\u0627\\u0646 \\u0641\\u064a \\u0627\\u0644\\u0627\\u0639\\u062a\\u0628\\u0627\\u0631. \\u0643\\u0644 \\u0631\\u0627\\u0628\\u0637 \\u0641\\u0631\\u064a\\u062f \\u0645\\u0646 \\u0646\\u0648\\u0639\\u0647\\u060c \\u0648\\u064a\\u0633\\u062a\\u062e\\u062f\\u0645 QRPay Pro \\u062d\\u0645\\u0627\\u064a\\u0629 \\u0645\\u062a\\u0642\\u062f\\u0645\\u0629 \\u0644\\u0636\\u0645\\u0627\\u0646 \\u0623\\u0646 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u0643 \\u0622\\u0645\\u0646\\u0629 \\u0648\\u062e\\u0627\\u0635\\u0629.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 tan seguro es un enlace de pago?\",\"answer\":\"Los enlaces de pago de QRPay Pro est\\u00e1n encriptados y dise\\u00f1ados teniendo en cuenta la seguridad. Cada enlace es \\u00fanico y QRPay Pro utiliza protecci\\u00f3n avanzada para garantizar que sus transacciones sean seguras y privadas.\"},\"fr\":{\"question\":\"\\u00bfQu\\u00e9 tan seguro es un enlace de pago?\",\"answer\":\"Les liens de paiement de QRPay Pro sont crypt\\u00e9s et con\\u00e7us dans un souci de s\\u00e9curit\\u00e9. Chaque lien est unique et QRPay Pro utilise une protection avanc\\u00e9e pour garantir que vos transactions sont s\\u00e9curis\\u00e9es et priv\\u00e9es.\"},\"hi\":{\"question\":\"\\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0915\\u093f\\u0924\\u0928\\u093e \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0939\\u0948?\",\"answer\":\"QRPay Pro \\u0915\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u090f\\u0928\\u094d\\u0915\\u094d\\u0930\\u093f\\u092a\\u094d\\u091f\\u0947\\u0921 \\u0939\\u0948\\u0902 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0915\\u094b \\u0927\\u094d\\u092f\\u093e\\u0928 \\u092e\\u0947\\u0902 \\u0930\\u0916\\u0915\\u0930 \\u0921\\u093f\\u091c\\u093c\\u093e\\u0907\\u0928 \\u0915\\u093f\\u090f \\u0917\\u090f \\u0939\\u0948\\u0902\\u0964 \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u0932\\u093f\\u0902\\u0915 \\u0905\\u0926\\u094d\\u0935\\u093f\\u0924\\u0940\\u092f \\u0939\\u0948, \\u0914\\u0930 QRPay Pro \\u092f\\u0939 \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0909\\u0928\\u094d\\u0928\\u0924 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948 \\u0915\\u093f \\u0906\\u092a\\u0915\\u093e \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0914\\u0930 \\u0928\\u093f\\u091c\\u0940 \\u0939\\u0948\\u0964\"}},\"id\":\"672497b8544d1\"}}}', 1, 1, '2024-11-01 14:55:33', '2024-11-06 19:31:49');
INSERT INTO `frontend_header_section_faqs` VALUES (8, 8, 'personal', '{\"language\":{\"en\":{\"heading\":\"Common Questions About Requesting Money with QRPay Pro\",\"sub_heading\":\"Get the information you need to easily request funds from others using QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0634\\u0627\\u0626\\u0639\\u0629 \\u062d\\u0648\\u0644 \\u0637\\u0644\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\",\"sub_heading\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u062a\\u062d\\u062a\\u0627\\u062c\\u0647\\u0627 \\u0644\\u0637\\u0644\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0622\\u062e\\u0631\\u064a\\u0646 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro.\"},\"es\":{\"heading\":\"Preguntas comunes sobre c\\u00f3mo solicitar dinero con QRPay Pro\",\"sub_heading\":\"Obtenga la informaci\\u00f3n que necesita para solicitar fondos f\\u00e1cilmente a otras personas utilizando QRPay Pro.\"},\"fr\":{\"heading\":\"Preguntas comunes sobre c\\u00f3mo solicitar dinero con QRPay Pro\",\"sub_heading\":\"Obtenez les informations dont vous avez besoin pour demander facilement des fonds \\u00e0 d\'autres personnes en utilisant QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u0947 \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0938\\u093e\\u092e\\u093e\\u0928\\u094d\\u092f \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u0926\\u0942\\u0938\\u0930\\u094b\\u0902 \\u0938\\u0947 \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0915\\u093e \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"67249881b2a60\":{\"language\":{\"en\":{\"question\":\"How do I request money using QRPay Pro?\",\"answer\":\"To request money, go to the Request Money feature, enter the recipient\'s QRPay Pro ID and the amount, then send your request. The recipient will receive a notification to complete the transaction.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0637\\u0644\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\\u061f\",\"answer\":\"\\u0644\\u0637\\u0644\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u060c \\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u0645\\u064a\\u0632\\u0629 \\u0637\\u0644\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u060c \\u0648\\u0623\\u062f\\u062e\\u0644 \\u0645\\u0639\\u0631\\u0641 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645 \\u0648\\u0627\\u0644\\u0645\\u0628\\u0644\\u063a\\u060c \\u062b\\u0645 \\u0623\\u0631\\u0633\\u0644 \\u0637\\u0644\\u0628\\u0643. \\u0633\\u064a\\u062a\\u0644\\u0642\\u0649 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645 \\u0625\\u0634\\u0639\\u0627\\u0631\\u064b\\u0627 \\u0644\\u0625\\u0643\\u0645\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo solicito dinero usando QRPay Pro?\",\"answer\":\"Para solicitar dinero, vaya a la funci\\u00f3n Solicitar dinero, ingrese el ID de QRPay Pro del destinatario y el monto, luego env\\u00ede su solicitud. El destinatario recibir\\u00e1 una notificaci\\u00f3n para completar la transacci\\u00f3n.\"},\"fr\":{\"question\":\"\\u00bfC\\u00f3mo solicito dinero usando QRPay Pro?\",\"answer\":\"Pour demander de l\'argent, acc\\u00e9dez \\u00e0 la fonction Demander de l\'argent, saisissez l\'identifiant QRPay Pro du destinataire et le montant, puis envoyez votre demande. Le destinataire recevra une notification pour finaliser la transaction.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay Pro \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u093e \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u0915\\u0948\\u0938\\u0947 \\u0915\\u0930\\u0942\\u0901?\",\"answer\":\"\\u0927\\u0928 \\u0915\\u093e \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u0927\\u0928 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0902, \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u0940 QRPay \\u092a\\u094d\\u0930\\u094b \\u0906\\u0908\\u0921\\u0940 \\u0914\\u0930 \\u0930\\u093e\\u0936\\u093f \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902, \\u092b\\u093f\\u0930 \\u0905\\u092a\\u0928\\u093e \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u092d\\u0947\\u091c\\u0947\\u0902\\u0964 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u094b \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u092a\\u0942\\u0930\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u090f\\u0915 \\u0905\\u0927\\u093f\\u0938\\u0942\\u091a\\u0928\\u093e \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0939\\u094b\\u0917\\u0940\\u0964\"}},\"id\":\"67249881b2a60\"},\"6724988f15b27\":{\"language\":{\"en\":{\"question\":\"Can I customize my payment request?\",\"answer\":\"Yes, you can add a note or description to your payment request to specify what the funds are for, making it clear to the recipient.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u062a\\u062e\\u0635\\u064a\\u0635 \\u0637\\u0644\\u0628 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u064a\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0625\\u0636\\u0627\\u0641\\u0629 \\u0645\\u0644\\u0627\\u062d\\u0638\\u0629 \\u0623\\u0648 \\u0648\\u0635\\u0641 \\u0644\\u0637\\u0644\\u0628 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u0644\\u062a\\u062d\\u062f\\u064a\\u062f \\u0627\\u0644\\u063a\\u0631\\u0636 \\u0645\\u0646 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0648\\u0636\\u062d \\u0627\\u0644\\u0623\\u0645\\u0631 \\u0644\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645.\"},\"es\":{\"question\":\"\\u00bfPuedo personalizar mi solicitud de pago?\",\"answer\":\"S\\u00ed, puede agregar una nota o descripci\\u00f3n a su solicitud de pago para especificar para qu\\u00e9 son los fondos, dej\\u00e1ndolo claro al destinatario.\"},\"fr\":{\"question\":\"\\u00bfPuedo personalizar mi solicitud de pago?\",\"answer\":\"Oui, vous pouvez ajouter une note ou une description \\u00e0 votre demande de paiement pour pr\\u00e9ciser \\u00e0 quoi servent les fonds, ce qui sera clair pour le destinataire.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u0905\\u092a\\u0928\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u0905\\u0928\\u0941\\u0915\\u0942\\u0932\\u093f\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0939\\u093e\\u0902, \\u0906\\u092a \\u0905\\u092a\\u0928\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u092e\\u0947\\u0902 \\u090f\\u0915 \\u0928\\u094b\\u091f \\u092f\\u093e \\u0935\\u093f\\u0935\\u0930\\u0923 \\u091c\\u094b\\u0921\\u093c \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902 \\u0924\\u093e\\u0915\\u093f \\u092f\\u0939 \\u0928\\u093f\\u0930\\u094d\\u0926\\u093f\\u0937\\u094d\\u091f \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e \\u0938\\u0915\\u0947 \\u0915\\u093f \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0915\\u093f\\u0938 \\u0932\\u093f\\u090f \\u0939\\u0948, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u094b \\u092f\\u0939 \\u0938\\u094d\\u092a\\u0937\\u094d\\u091f \\u0939\\u094b \\u0938\\u0915\\u0947\\u0964\"}},\"id\":\"6724988f15b27\"},\"6724989e50c58\":{\"language\":{\"en\":{\"question\":\"What happens if the recipient doesn\\u2019t respond to my request?\",\"answer\":\"If the recipient does not respond, you can resend the request or follow up with them directly. Notifications will inform you if the request has been viewed or accepted.\"},\"ar\":{\"question\":\"\\u0645\\u0627\\u0630\\u0627 \\u064a\\u062d\\u062f\\u062b \\u0625\\u0630\\u0627 \\u0644\\u0645 \\u064a\\u0633\\u062a\\u062c\\u0628 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645 \\u0644\\u0637\\u0644\\u0628\\u064a\\u061f\",\"answer\":\"\\u0625\\u0630\\u0627 \\u0644\\u0645 \\u064a\\u0633\\u062a\\u062c\\u0628 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645\\u060c \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0625\\u0639\\u0627\\u062f\\u0629 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0637\\u0644\\u0628 \\u0623\\u0648 \\u0627\\u0644\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0645\\u0639\\u0647 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629. \\u0633\\u062a\\u062e\\u0628\\u0631\\u0643 \\u0627\\u0644\\u0625\\u0634\\u0639\\u0627\\u0631\\u0627\\u062a \\u0625\\u0630\\u0627 \\u062a\\u0645 \\u0639\\u0631\\u0636 \\u0627\\u0644\\u0637\\u0644\\u0628 \\u0623\\u0648 \\u0642\\u0628\\u0648\\u0644\\u0647.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 pasa si el destinatario no responde a mi solicitud?\",\"answer\":\"Si el destinatario no responde, puede reenviar la solicitud o hacer un seguimiento con \\u00e9l directamente. Las notificaciones le informar\\u00e1n si la solicitud ha sido vista o aceptada.\"},\"fr\":{\"question\":\"\\u00bfQu\\u00e9 pasa si el destinatario no responde a mi solicitud?\",\"answer\":\"Si le destinataire ne r\\u00e9pond pas, vous pouvez renvoyer la demande ou faire un suivi directement aupr\\u00e8s de lui. Les notifications vous informeront si la demande a \\u00e9t\\u00e9 consult\\u00e9e ou accept\\u00e9e.\"},\"hi\":{\"question\":\"\\u092f\\u0926\\u093f \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u092e\\u0947\\u0930\\u0947 \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u0915\\u093e \\u091c\\u0935\\u093e\\u092c \\u0928\\u0939\\u0940\\u0902 \\u0926\\u0947\\u0924\\u093e \\u0939\\u0948 \\u0924\\u094b \\u0915\\u094d\\u092f\\u093e \\u0939\\u094b\\u0917\\u093e?\",\"answer\":\"\\u092f\\u0926\\u093f \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u091c\\u0935\\u093e\\u092c \\u0928\\u0939\\u0940\\u0902 \\u0926\\u0947\\u0924\\u093e \\u0939\\u0948, \\u0924\\u094b \\u0906\\u092a \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u0926\\u094b\\u092c\\u093e\\u0930\\u093e \\u092d\\u0947\\u091c \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902 \\u092f\\u093e \\u0938\\u0940\\u0927\\u0947 \\u0909\\u0928\\u0938\\u0947 \\u0938\\u0902\\u092a\\u0930\\u094d\\u0915 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u092f\\u0926\\u093f \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u0926\\u0947\\u0916\\u093e \\u0917\\u092f\\u093e \\u0939\\u0948 \\u092f\\u093e \\u0938\\u094d\\u0935\\u0940\\u0915\\u093e\\u0930 \\u0915\\u0930 \\u0932\\u093f\\u092f\\u093e \\u0917\\u092f\\u093e \\u0939\\u0948 \\u0924\\u094b \\u0938\\u0942\\u091a\\u0928\\u093e\\u090f\\u0902 \\u0906\\u092a\\u0915\\u094b \\u0938\\u0942\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902\\u0917\\u0940\\u0964\"}},\"id\":\"6724989e50c58\"},\"672498a9af0c5\":{\"language\":{\"en\":{\"question\":\"Are there any fees associated with requesting money?\",\"answer\":\"QRPay Pro does not charge fees for sending a payment request. However, standard transaction fees may apply when the recipient sends the money to you.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0637\\u0644\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u061f\",\"answer\":\"\\u0644\\u0627 \\u064a\\u0641\\u0631\\u0636 QRPay Pro \\u0631\\u0633\\u0648\\u0645\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0637\\u0644\\u0628 \\u0627\\u0644\\u062f\\u0641\\u0639. \\u0648\\u0645\\u0639 \\u0630\\u0644\\u0643\\u060c \\u0642\\u062f \\u064a\\u062a\\u0645 \\u062a\\u0637\\u0628\\u064a\\u0642 \\u0631\\u0633\\u0648\\u0645 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0642\\u064a\\u0627\\u0633\\u064a\\u0629 \\u0639\\u0646\\u062f\\u0645\\u0627 \\u064a\\u0631\\u0633\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u064a\\u0643.\"},\"es\":{\"question\":\"\\u00bfHay alg\\u00fan cargo asociado con la solicitud de dinero?\",\"answer\":\"QRPay Pro no cobra tarifas por enviar una solicitud de pago. Sin embargo, es posible que se apliquen tarifas de transacci\\u00f3n est\\u00e1ndar cuando el destinatario le env\\u00ede el dinero.\"},\"fr\":{\"question\":\"\\u00bfHay alg\\u00fan cargo asociado con la solicitud de dinero?\",\"answer\":\"QRPay Pro ne facture pas de frais pour l\'envoi d\'une demande de paiement. Cependant, des frais de transaction standards peuvent s\'appliquer lorsque le destinataire vous envoie l\'argent.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092a\\u0948\\u0938\\u0947 \\u0915\\u093e \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u091c\\u0941\\u0921\\u093c\\u0940 \\u0915\\u094b\\u0908 \\u092b\\u0940\\u0938 \\u0939\\u0948?\",\"answer\":\"QRPay Pro \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u094b\\u0908 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0928\\u0939\\u0940\\u0902 \\u0932\\u0947\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0939\\u093e\\u0932\\u093e\\u0901\\u0915\\u093f, \\u091c\\u092c \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0906\\u092a\\u0915\\u094b \\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0924\\u093e \\u0939\\u0948 \\u0924\\u094b \\u092e\\u093e\\u0928\\u0915 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0932\\u093e\\u0917\\u0942 \\u0939\\u094b \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964\"}},\"id\":\"672498a9af0c5\"}}}', 1, 1, '2024-11-01 14:59:32', '2024-11-06 19:36:54');
INSERT INTO `frontend_header_section_faqs` VALUES (9, 9, 'personal', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About QRPay Pro Remittance\",\"sub_heading\":\"Learn more about sending money internationally with QRPay Pro\\u2019s remittance feature.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u062e\\u062f\\u0645\\u0629 \\u062a\\u062d\\u0648\\u064a\\u0644 QRPay Pro\",\"sub_heading\":\"\\u062a\\u0639\\u0631\\u0641 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0632\\u064a\\u062f \\u062d\\u0648\\u0644 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u062f\\u0648\\u0644\\u064a\\u064b\\u0627 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0645\\u064a\\u0632\\u0629 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0641\\u064a QRPay Pro.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre las remesas QRPay Pro\",\"sub_heading\":\"Obtenga m\\u00e1s informaci\\u00f3n sobre c\\u00f3mo enviar dinero internacionalmente con la funci\\u00f3n de remesas de QRPay Pro.\"},\"fr\":{\"heading\":\"Foire aux questions sur les versements QRPay Pro\",\"sub_heading\":\"Apprenez-en davantage sur l\\u2019envoi d\\u2019argent \\u00e0 l\\u2019international gr\\u00e2ce \\u00e0 la fonction de versement de QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0930\\u0947\\u092e\\u093f\\u091f\\u0947\\u0902\\u0938 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0940 \\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0905\\u0902\\u0924\\u0930\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0938\\u094d\\u0924\\u0930 \\u092a\\u0930 \\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0914\\u0930 \\u091c\\u093e\\u0928\\u0947\\u0902\\u0964\"}},\"items\":{\"672499543b114\":{\"language\":{\"en\":{\"question\":\"How do I send money internationally using QRPay Pro?\",\"answer\":\"To send remittance funds, navigate to the Remittance feature, enter the recipient\\u2019s information and the amount, select your transfer method, and confirm the transaction to initiate the transfer.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u062f\\u0648\\u0644\\u064a\\u064b\\u0627 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\\u061f\",\"answer\":\"\\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0623\\u0645\\u0648\\u0627\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u060c \\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u0645\\u064a\\u0632\\u0629 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u060c \\u0648\\u0623\\u062f\\u062e\\u0644 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645 \\u0648\\u0627\\u0644\\u0645\\u0628\\u0644\\u063a\\u060c \\u0648\\u062d\\u062f\\u062f \\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643\\u060c \\u0648\\u0623\\u0643\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629 \\u0644\\u0628\\u062f\\u0621 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo env\\u00edo dinero internacionalmente usando QRPay Pro?\",\"answer\":\"Para enviar fondos de remesas, navegue hasta la funci\\u00f3n Remesas, ingrese la informaci\\u00f3n del destinatario y el monto, seleccione su m\\u00e9todo de transferencia y confirme la transacci\\u00f3n para iniciar la transferencia.\"},\"fr\":{\"question\":\"Comment envoyer de l\'argent \\u00e0 l\'international en utilisant QRPay Pro ?\",\"answer\":\"Pour envoyer des fonds de transfert, acc\\u00e9dez \\u00e0 la fonction Remise de fonds, saisissez les informations du destinataire et le montant, s\\u00e9lectionnez votre m\\u00e9thode de transfert et confirmez la transaction pour lancer le transfert.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay Pro \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u0905\\u0902\\u0924\\u0930\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0938\\u094d\\u0924\\u0930 \\u092a\\u0930 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0942\\u0902?\",\"answer\":\"\\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u0928\\u093f\\u0927\\u093f \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0901, \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u0940 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0914\\u0930 \\u0930\\u093e\\u0936\\u093f \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902, \\u0905\\u092a\\u0928\\u0940 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0935\\u093f\\u0927\\u093f \\u091a\\u0941\\u0928\\u0947\\u0902, \\u0914\\u0930 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0936\\u0941\\u0930\\u0942 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"672499543b114\"},\"6724995e77e13\":{\"language\":{\"en\":{\"question\":\"What transfer methods can I use for remittances?\",\"answer\":\"You can choose to send funds directly to a recipient\\u2019s bank account or opt for cash pickup at designated locations, depending on what is most convenient for the recipient.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0647\\u064a \\u0637\\u0631\\u0642 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u062a\\u064a \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645\\u0647\\u0627 \\u0644\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0627\\u0644\\u064a\\u0629\\u061f\",\"answer\":\"\\u064a\\u0645\\u0643\\u0646\\u0643 \\u0627\\u062e\\u062a\\u064a\\u0627\\u0631 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u062d\\u0633\\u0627\\u0628 \\u0627\\u0644\\u0628\\u0646\\u0643\\u064a \\u0644\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645 \\u0623\\u0648 \\u0627\\u062e\\u062a\\u064a\\u0627\\u0631 \\u062a\\u062d\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0627\\u0644\\u0646\\u0642\\u062f\\u064a\\u0629 \\u0645\\u0646 \\u0645\\u0648\\u0627\\u0642\\u0639 \\u0645\\u062d\\u062f\\u062f\\u0629\\u060c \\u0627\\u0639\\u062a\\u0645\\u0627\\u062f\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u0645\\u0627 \\u0647\\u0648 \\u0623\\u0643\\u062b\\u0631 \\u0645\\u0644\\u0627\\u0621\\u0645\\u0629 \\u0644\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 m\\u00e9todos de transferencia puedo utilizar para env\\u00edos de remesas?\",\"answer\":\"Puede optar por enviar fondos directamente a la cuenta bancaria del destinatario u optar por el retiro en ventanilla en ubicaciones designadas, seg\\u00fan lo que sea m\\u00e1s conveniente para el destinatario.\"},\"fr\":{\"question\":\"Quelles m\\u00e9thodes de transfert puis-je utiliser pour les envois de fonds ?\",\"answer\":\"Vous pouvez choisir d\\u2019envoyer des fonds directement sur le compte bancaire d\\u2019un destinataire ou opter pour un retrait d\\u2019esp\\u00e8ces \\u00e0 des endroits d\\u00e9sign\\u00e9s, en fonction de ce qui convient le mieux au destinataire.\"},\"hi\":{\"question\":\"\\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092e\\u0948\\u0902 \\u0915\\u093f\\u0928 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0935\\u093f\\u0927\\u093f\\u092f\\u094b\\u0902 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0902?\",\"answer\":\"\\u0906\\u092a \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u0947 \\u092c\\u0948\\u0902\\u0915 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0938\\u0940\\u0927\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u092d\\u0947\\u091c\\u0928\\u093e \\u091a\\u0941\\u0928 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902 \\u092f\\u093e \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0938\\u092c\\u0938\\u0947 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e\\u091c\\u0928\\u0915 \\u0915\\u094d\\u092f\\u093e \\u0939\\u0948, \\u0907\\u0938\\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0928\\u093f\\u0930\\u094d\\u0926\\u093f\\u0937\\u094d\\u091f \\u0938\\u094d\\u0925\\u093e\\u0928\\u094b\\u0902 \\u092a\\u0930 \\u0928\\u0915\\u0926\\u0940 \\u0932\\u0947\\u0928\\u0947 \\u0915\\u093e \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a \\u091a\\u0941\\u0928 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724995e77e13\"},\"6724996710b39\":{\"language\":{\"en\":{\"question\":\"How long does it take for the funds to arrive?\",\"answer\":\"Transfer times vary based on the chosen method and destination country. Most transactions are processed quickly, but bank transfers may take longer depending on international banking protocols.\"},\"ar\":{\"question\":\"\\u0643\\u0645 \\u0645\\u0646 \\u0627\\u0644\\u0648\\u0642\\u062a \\u064a\\u0633\\u062a\\u063a\\u0631\\u0642 \\u0648\\u0635\\u0648\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u061f\",\"answer\":\"\\u062a\\u062e\\u062a\\u0644\\u0641 \\u0623\\u0648\\u0642\\u0627\\u062a \\u0627\\u0644\\u0646\\u0642\\u0644 \\u0628\\u0646\\u0627\\u0621\\u064b \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u0645\\u062e\\u062a\\u0627\\u0631\\u0629 \\u0648\\u0628\\u0644\\u062f \\u0627\\u0644\\u0648\\u062c\\u0647\\u0629. \\u062a\\u062a\\u0645 \\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0645\\u0639\\u0638\\u0645 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0628\\u0633\\u0631\\u0639\\u0629\\u060c \\u0648\\u0644\\u0643\\u0646 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0635\\u0631\\u0641\\u064a\\u0629 \\u0642\\u062f \\u062a\\u0633\\u062a\\u063a\\u0631\\u0642 \\u0648\\u0642\\u062a\\u064b\\u0627 \\u0623\\u0637\\u0648\\u0644 \\u0627\\u0639\\u062a\\u0645\\u0627\\u062f\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0628\\u0631\\u0648\\u062a\\u0648\\u0643\\u0648\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0635\\u0631\\u0641\\u064a\\u0629 \\u0627\\u0644\\u062f\\u0648\\u0644\\u064a\\u0629.\"},\"es\":{\"question\":\"\\u00bfCu\\u00e1nto tiempo tardan en llegar los fondos?\",\"answer\":\"Los tiempos de transferencia var\\u00edan seg\\u00fan el m\\u00e9todo elegido y el pa\\u00eds de destino. La mayor\\u00eda de las transacciones se procesan r\\u00e1pidamente, pero las transferencias bancarias pueden tardar m\\u00e1s seg\\u00fan los protocolos bancarios internacionales.\"},\"fr\":{\"question\":\"Combien de temps faut-il pour que les fonds arrivent ?\",\"answer\":\"Les temps de transfert varient en fonction de la m\\u00e9thode choisie et du pays de destination. La plupart des transactions sont trait\\u00e9es rapidement, mais les virements bancaires peuvent prendre plus de temps en fonction des protocoles bancaires internationaux.\"},\"hi\":{\"question\":\"\\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0906\\u0928\\u0947 \\u092e\\u0947\\u0902 \\u0915\\u093f\\u0924\\u0928\\u093e \\u0938\\u092e\\u092f \\u0932\\u0917\\u0924\\u093e \\u0939\\u0948?\",\"answer\":\"\\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u093e \\u0938\\u092e\\u092f \\u091a\\u0941\\u0928\\u0940 \\u0917\\u0908 \\u0935\\u093f\\u0927\\u093f \\u0914\\u0930 \\u0917\\u0902\\u0924\\u0935\\u094d\\u092f \\u0926\\u0947\\u0936 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0905\\u0932\\u0917-\\u0905\\u0932\\u0917 \\u0939\\u094b\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0905\\u0927\\u093f\\u0915\\u093e\\u0902\\u0936 \\u0932\\u0947\\u0928-\\u0926\\u0947\\u0928 \\u0936\\u0940\\u0918\\u094d\\u0930\\u0924\\u093e \\u0938\\u0947 \\u0938\\u0902\\u0938\\u093e\\u0927\\u093f\\u0924 \\u0939\\u094b \\u091c\\u093e\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0932\\u0947\\u0915\\u093f\\u0928 \\u0905\\u0902\\u0924\\u0930\\u094d\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u092c\\u0948\\u0902\\u0915\\u093f\\u0902\\u0917 \\u092a\\u094d\\u0930\\u094b\\u091f\\u094b\\u0915\\u0949\\u0932 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u092c\\u0948\\u0902\\u0915 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u092e\\u0947\\u0902 \\u0905\\u0927\\u093f\\u0915 \\u0938\\u092e\\u092f \\u0932\\u0917 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964\"}},\"id\":\"6724996710b39\"},\"67249970f157e\":{\"language\":{\"en\":{\"question\":\"Are there fees for sending remittance funds?\",\"answer\":\"Yes, fees may apply based on the amount sent and the transfer method selected. You will be informed of any applicable fees before confirming your transaction, ensuring transparency.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0631\\u0633\\u0648\\u0645 \\u0639\\u0644\\u0649 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0623\\u0645\\u0648\\u0627\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u0642\\u062f \\u064a\\u062a\\u0645 \\u0641\\u0631\\u0636 \\u0631\\u0633\\u0648\\u0645 \\u0628\\u0646\\u0627\\u0621\\u064b \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0645\\u0631\\u0633\\u0644 \\u0648\\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0645\\u062d\\u062f\\u062f\\u0629. \\u0633\\u064a\\u062a\\u0645 \\u0625\\u0628\\u0644\\u0627\\u063a\\u0643 \\u0628\\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0637\\u0628\\u0642\\u0629 \\u0642\\u0628\\u0644 \\u062a\\u0623\\u0643\\u064a\\u062f \\u0645\\u0639\\u0627\\u0645\\u0644\\u062a\\u0643\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0636\\u0645\\u0646 \\u0627\\u0644\\u0634\\u0641\\u0627\\u0641\\u064a\\u0629.\"},\"es\":{\"question\":\"\\u00bfExisten tarifas por enviar fondos de remesas?\",\"answer\":\"S\\u00ed, se pueden aplicar tarifas seg\\u00fan el monto enviado y el m\\u00e9todo de transferencia seleccionado. Se le informar\\u00e1 de las tarifas aplicables antes de confirmar su transacci\\u00f3n, lo que garantiza la transparencia.\"},\"fr\":{\"question\":\"Y a-t-il des frais pour l\'envoi de fonds\\u00a0?\",\"answer\":\"Oui, des frais peuvent s\'appliquer en fonction du montant envoy\\u00e9 et de la m\\u00e9thode de transfert s\\u00e9lectionn\\u00e9e. Vous serez inform\\u00e9 des frais applicables avant de confirmer votre transaction, garantissant ainsi la transparence.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u0928\\u093f\\u0927\\u093f \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u094b\\u0908 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0939\\u0948?\",\"answer\":\"\\u0939\\u093e\\u0902, \\u092d\\u0947\\u091c\\u0940 \\u0917\\u0908 \\u0930\\u093e\\u0936\\u093f \\u0914\\u0930 \\u091a\\u092f\\u0928\\u093f\\u0924 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0935\\u093f\\u0927\\u093f \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0932\\u093e\\u0917\\u0942 \\u0939\\u094b \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u092a\\u093e\\u0930\\u0926\\u0930\\u094d\\u0936\\u093f\\u0924\\u093e \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0941\\u090f, \\u0906\\u092a\\u0915\\u0947 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u0906\\u092a\\u0915\\u094b \\u0915\\u093f\\u0938\\u0940 \\u092d\\u0940 \\u0932\\u093e\\u0917\\u0942 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0938\\u0942\\u091a\\u093f\\u0924 \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e\\u090f\\u0917\\u093e\\u0964\"}},\"id\":\"67249970f157e\"}}}', 1, 1, '2024-11-01 15:03:03', '2024-11-07 10:19:06');
INSERT INTO `frontend_header_section_faqs` VALUES (10, 10, 'personal', '{\"language\":{\"en\":{\"heading\":\"Common Questions About Adding Money to QRPay Pro\",\"sub_heading\":\"Find answers to your queries regarding the process of adding funds to your QRPay Pro account.\"},\"ar\":{\"heading\":\"\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0634\\u0627\\u0626\\u0639\\u0629 \\u062d\\u0648\\u0644 \\u0625\\u0636\\u0627\\u0641\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 QRPay Pro\",\"sub_heading\":\"\\u0627\\u0628\\u062d\\u062b \\u0639\\u0646 \\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0644\\u0627\\u0633\\u062a\\u0641\\u0633\\u0627\\u0631\\u0627\\u062a\\u0643 \\u0627\\u0644\\u0645\\u062a\\u0639\\u0644\\u0642\\u0629 \\u0628\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0625\\u0636\\u0627\\u0641\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643.\"},\"es\":{\"heading\":\"Preguntas comunes sobre c\\u00f3mo agregar dinero a QRPay Pro\",\"sub_heading\":\"Encuentre respuestas a sus consultas sobre el proceso de agregar fondos a su cuenta QRPay Pro.\"},\"fr\":{\"heading\":\"Preguntas comunes sobre c\\u00f3mo agregar dinero a QRPay Pro\",\"sub_heading\":\"Trouvez des r\\u00e9ponses \\u00e0 vos questions concernant le processus d\'ajout de fonds \\u00e0 votre compte QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092e\\u0947\\u0902 \\u092a\\u0948\\u0938\\u0947 \\u091c\\u094b\\u0921\\u093c\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0938\\u093e\\u092e\\u093e\\u0928\\u094d\\u092f \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u091c\\u094b\\u0921\\u093c\\u0928\\u0947 \\u0915\\u0940 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0915\\u0947 \\u0938\\u0902\\u092c\\u0902\\u0927 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u0916\\u094b\\u091c\\u0947\\u0902\\u0964\"}},\"items\":{\"67249a42c7f45\":{\"language\":{\"en\":{\"question\":\"How can I add money to my QRPay Pro account?\",\"answer\":\"To add money, navigate to the Add Money feature, select your funding source, enter the desired amount, and confirm the transaction. Your funds will be available shortly after the process is complete.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0625\\u0636\\u0627\\u0641\\u0629 \\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u064a\\u061f\",\"answer\":\"\\u0644\\u0625\\u0636\\u0627\\u0641\\u0629 \\u0623\\u0645\\u0648\\u0627\\u0644\\u060c \\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u0645\\u064a\\u0632\\u0629 \\\"\\u0625\\u0636\\u0627\\u0641\\u0629 \\u0623\\u0645\\u0648\\u0627\\u0644\\\"\\u060c \\u0648\\u062d\\u062f\\u062f \\u0645\\u0635\\u062f\\u0631 \\u0627\\u0644\\u062a\\u0645\\u0648\\u064a\\u0644 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\\u060c \\u0648\\u0623\\u062f\\u062e\\u0644 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628\\u060c \\u0648\\u0642\\u0645 \\u0628\\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629. \\u0633\\u062a\\u0643\\u0648\\u0646 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0645\\u062a\\u0627\\u062d\\u0629 \\u0628\\u0639\\u062f \\u0648\\u0642\\u062a \\u0642\\u0635\\u064a\\u0631 \\u0645\\u0646 \\u0627\\u0643\\u062a\\u0645\\u0627\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo puedo agregar dinero a mi cuenta QRPay Pro?\",\"answer\":\"Para agregar dinero, navegue hasta la funci\\u00f3n Agregar dinero, seleccione su fuente de financiamiento, ingrese el monto deseado y confirme la transacci\\u00f3n. Sus fondos estar\\u00e1n disponibles poco despu\\u00e9s de que se complete el proceso.\"},\"fr\":{\"question\":\"\\u00bfC\\u00f3mo puedo agregar dinero a mi cuenta QRPay Pro?\",\"answer\":\"Pour ajouter de l\'argent, acc\\u00e9dez \\u00e0 la fonction Ajouter de l\'argent, s\\u00e9lectionnez votre source de financement, entrez le montant souhait\\u00e9 et confirmez la transaction. Vos fonds seront disponibles peu de temps apr\\u00e8s la fin du processus.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u091c\\u094b\\u0921\\u093c \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u092a\\u0948\\u0938\\u0947 \\u091c\\u094b\\u0921\\u093c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u092a\\u0948\\u0938\\u0947 \\u091c\\u094b\\u0921\\u093c\\u0947\\u0902 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0901, \\u0905\\u092a\\u0928\\u0947 \\u092b\\u0902\\u0921\\u093f\\u0902\\u0917 \\u0938\\u094d\\u0930\\u094b\\u0924 \\u0915\\u093e \\u091a\\u092f\\u0928 \\u0915\\u0930\\u0947\\u0902, \\u0935\\u093e\\u0902\\u091b\\u093f\\u0924 \\u0930\\u093e\\u0936\\u093f \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\\u0964 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u092a\\u0942\\u0930\\u0940 \\u0939\\u094b\\u0928\\u0947 \\u0915\\u0947 \\u0924\\u0941\\u0930\\u0902\\u0924 \\u092c\\u093e\\u0926 \\u0906\\u092a\\u0915\\u0940 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0939\\u094b \\u091c\\u093e\\u090f\\u0917\\u0940\\u0964\"}},\"id\":\"67249a42c7f45\"},\"67249a4d05c52\":{\"language\":{\"en\":{\"question\":\"What payment methods are available for adding money?\",\"answer\":\"You can add money using various methods, including bank transfers, debit\\/credit cards, and other supported payment options. Choose the method that works best for you.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0647\\u064a \\u0637\\u0631\\u0642 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u0645\\u062a\\u0627\\u062d\\u0629 \\u0644\\u0625\\u0636\\u0627\\u0641\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u061f\",\"answer\":\"\\u064a\\u0645\\u0643\\u0646\\u0643 \\u0625\\u0636\\u0627\\u0641\\u0629 \\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0637\\u0631\\u0642 \\u0645\\u062e\\u062a\\u0644\\u0641\\u0629\\u060c \\u0628\\u0645\\u0627 \\u0641\\u064a \\u0630\\u0644\\u0643 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0635\\u0631\\u0641\\u064a\\u0629 \\u0648\\u0628\\u0637\\u0627\\u0642\\u0627\\u062a \\u0627\\u0644\\u062e\\u0635\\u0645\\/\\u0627\\u0644\\u0627\\u0626\\u062a\\u0645\\u0627\\u0646 \\u0648\\u062e\\u064a\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u0645\\u062f\\u0639\\u0648\\u0645\\u0629 \\u0627\\u0644\\u0623\\u062e\\u0631\\u0649. \\u0627\\u062e\\u062a\\u0631 \\u0627\\u0644\\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u062a\\u064a \\u062a\\u0646\\u0627\\u0633\\u0628\\u0643 \\u0628\\u0634\\u0643\\u0644 \\u0623\\u0641\\u0636\\u0644.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 m\\u00e9todos de pago est\\u00e1n disponibles para agregar dinero?\",\"answer\":\"Puede agregar dinero utilizando varios m\\u00e9todos, incluidas transferencias bancarias, tarjetas de d\\u00e9bito\\/cr\\u00e9dito y otras opciones de pago admitidas. Elija el m\\u00e9todo que funcione mejor para usted.\"},\"fr\":{\"question\":\"\\u00bfQu\\u00e9 m\\u00e9todos de pago est\\u00e1n disponibles para agregar dinero?\",\"answer\":\"Vous pouvez ajouter de l\'argent en utilisant diverses m\\u00e9thodes, notamment les virements bancaires, les cartes de d\\u00e9bit\\/cr\\u00e9dit et d\'autres options de paiement prises en charge. Choisissez la m\\u00e9thode qui vous convient le mieux.\"},\"hi\":{\"question\":\"\\u092a\\u0948\\u0938\\u0947 \\u091c\\u094b\\u0921\\u093c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u094c\\u0928 \\u0938\\u0940 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0935\\u093f\\u0927\\u093f\\u092f\\u093e\\u0901 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0939\\u0948\\u0902?\",\"answer\":\"\\u0906\\u092a \\u092c\\u0948\\u0902\\u0915 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923, \\u0921\\u0947\\u092c\\u093f\\u091f\\/\\u0915\\u094d\\u0930\\u0947\\u0921\\u093f\\u091f \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0914\\u0930 \\u0905\\u0928\\u094d\\u092f \\u0938\\u092e\\u0930\\u094d\\u0925\\u093f\\u0924 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a\\u094b\\u0902 \\u0938\\u0939\\u093f\\u0924 \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u0924\\u0930\\u0940\\u0915\\u094b\\u0902 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u091c\\u094b\\u0921\\u093c \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0935\\u0939 \\u0924\\u0930\\u0940\\u0915\\u093e \\u091a\\u0941\\u0928\\u0947\\u0902 \\u091c\\u094b \\u0906\\u092a\\u0915\\u0947 \\u0932\\u093f\\u090f \\u0938\\u092c\\u0938\\u0947 \\u0905\\u091a\\u094d\\u091b\\u093e \\u0915\\u093e\\u092e \\u0915\\u0930\\u0947\\u0964\"}},\"id\":\"67249a4d05c52\"},\"67249a57d5602\":{\"language\":{\"en\":{\"question\":\"Are there any fees associated with adding money?\",\"answer\":\"Fees may apply depending on the payment method you choose. You will be informed of any applicable fees before confirming your transaction to ensure transparency.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0625\\u0636\\u0627\\u0641\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u061f\",\"answer\":\"\\u0642\\u062f \\u064a\\u062a\\u0645 \\u062a\\u0637\\u0628\\u064a\\u0642 \\u0631\\u0633\\u0648\\u0645 \\u0627\\u0639\\u062a\\u0645\\u0627\\u062f\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062a\\u064a \\u062a\\u062e\\u062a\\u0627\\u0631\\u0647\\u0627. \\u0633\\u064a\\u062a\\u0645 \\u0625\\u0628\\u0644\\u0627\\u063a\\u0643 \\u0628\\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0637\\u0628\\u0642\\u0629 \\u0642\\u0628\\u0644 \\u062a\\u0623\\u0643\\u064a\\u062f \\u0645\\u0639\\u0627\\u0645\\u0644\\u062a\\u0643 \\u0644\\u0636\\u0645\\u0627\\u0646 \\u0627\\u0644\\u0634\\u0641\\u0627\\u0641\\u064a\\u0629.\"},\"es\":{\"question\":\"\\u00bfHay alguna tarifa asociada con agregar dinero?\",\"answer\":\"Es posible que se apliquen tarifas seg\\u00fan el m\\u00e9todo de pago que elija. Se le informar\\u00e1 de cualquier tarifa aplicable antes de confirmar su transacci\\u00f3n para garantizar la transparencia.\"},\"fr\":{\"question\":\"\\u00bfHay alguna tarifa asociada con agregar dinero?\",\"answer\":\"Des frais peuvent s\'appliquer selon le mode de paiement que vous choisissez. Vous serez inform\\u00e9 des frais applicables avant de confirmer votre transaction pour garantir la transparence.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092a\\u0948\\u0938\\u0947 \\u091c\\u094b\\u0921\\u093c\\u0928\\u0947 \\u0938\\u0947 \\u091c\\u0941\\u0921\\u093c\\u0940 \\u0915\\u094b\\u0908 \\u092b\\u0940\\u0938 \\u0939\\u0948?\",\"answer\":\"\\u0906\\u092a\\u0915\\u0947 \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u091a\\u0941\\u0928\\u0940 \\u0917\\u0908 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0935\\u093f\\u0927\\u093f \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0932\\u093e\\u0917\\u0942 \\u0939\\u094b \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u092a\\u093e\\u0930\\u0926\\u0930\\u094d\\u0936\\u093f\\u0924\\u093e \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0906\\u092a\\u0915\\u0947 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u0906\\u092a\\u0915\\u094b \\u0915\\u093f\\u0938\\u0940 \\u092d\\u0940 \\u0932\\u093e\\u0917\\u0942 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0938\\u0942\\u091a\\u093f\\u0924 \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e\\u090f\\u0917\\u093e\\u0964\"}},\"id\":\"67249a57d5602\"},\"67249a62a7ea6\":{\"language\":{\"en\":{\"question\":\"How long does it take for the funds to reflect in my account?\",\"answer\":\"Funds are typically added to your QRPay Pro account instantly, but some methods may take a little longer to process. You will receive a notification confirming the addition of funds once completed.\"},\"ar\":{\"question\":\"\\u0643\\u0645 \\u0645\\u0646 \\u0627\\u0644\\u0648\\u0642\\u062a \\u064a\\u0633\\u062a\\u063a\\u0631\\u0642 \\u0638\\u0647\\u0648\\u0631 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628\\u064a\\u061f\",\"answer\":\"\\u0639\\u0627\\u062f\\u0629\\u064b \\u0645\\u0627 \\u062a\\u062a\\u0645 \\u0625\\u0636\\u0627\\u0641\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631\\u060c \\u0648\\u0644\\u0643\\u0646 \\u0642\\u062f \\u062a\\u0633\\u062a\\u063a\\u0631\\u0642 \\u0628\\u0639\\u0636 \\u0627\\u0644\\u0637\\u0631\\u0642 \\u0648\\u0642\\u062a\\u064b\\u0627 \\u0623\\u0637\\u0648\\u0644 \\u0642\\u0644\\u064a\\u0644\\u0627\\u064b \\u0644\\u0644\\u0645\\u0639\\u0627\\u0644\\u062c\\u0629. \\u0633\\u0648\\u0641 \\u062a\\u062a\\u0644\\u0642\\u0649 \\u0625\\u0634\\u0639\\u0627\\u0631\\u064b\\u0627 \\u064a\\u0624\\u0643\\u062f \\u0625\\u0636\\u0627\\u0641\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0645\\u062c\\u0631\\u062f \\u0627\\u0643\\u062a\\u0645\\u0627\\u0644\\u0647\\u0627.\"},\"es\":{\"question\":\"\\u00bfCu\\u00e1nto tiempo tardan los fondos en reflejarse en mi cuenta?\",\"answer\":\"Por lo general, los fondos se agregan a su cuenta QRPay Pro al instante, pero algunos m\\u00e9todos pueden tardar un poco m\\u00e1s en procesarse. Recibir\\u00e1 una notificaci\\u00f3n confirmando la adici\\u00f3n de fondos una vez completada.\"},\"fr\":{\"question\":\"\\u00bfCu\\u00e1nto tiempo tardan los fondos en reflejarse en mi cuenta?\",\"answer\":\"Les fonds sont g\\u00e9n\\u00e9ralement ajout\\u00e9s instantan\\u00e9ment \\u00e0 votre compte QRPay Pro, mais certaines m\\u00e9thodes peuvent prendre un peu plus de temps \\u00e0 traiter. Vous recevrez une notification confirmant l\\u2019ajout de fonds une fois termin\\u00e9.\"},\"hi\":{\"question\":\"\\u092e\\u0947\\u0930\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u092a\\u094d\\u0930\\u0926\\u0930\\u094d\\u0936\\u093f\\u0924 \\u0939\\u094b\\u0928\\u0947 \\u092e\\u0947\\u0902 \\u0915\\u093f\\u0924\\u0928\\u093e \\u0938\\u092e\\u092f \\u0932\\u0917\\u0924\\u093e \\u0939\\u0948?\",\"answer\":\"\\u0906\\u092e \\u0924\\u094c\\u0930 \\u092a\\u0930 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0906\\u092a\\u0915\\u0947 QRPay Pro \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0924\\u0941\\u0930\\u0902\\u0924 \\u091c\\u094b\\u0921\\u093c \\u0926\\u0940 \\u091c\\u093e\\u0924\\u0940 \\u0939\\u0948, \\u0932\\u0947\\u0915\\u093f\\u0928 \\u0915\\u0941\\u091b \\u0924\\u0930\\u0940\\u0915\\u094b\\u0902 \\u0915\\u094b \\u0938\\u0902\\u0938\\u093e\\u0927\\u093f\\u0924 \\u0939\\u094b\\u0928\\u0947 \\u092e\\u0947\\u0902 \\u0925\\u094b\\u0921\\u093c\\u093e \\u0905\\u0927\\u093f\\u0915 \\u0938\\u092e\\u092f \\u0932\\u0917 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u092a\\u0942\\u0930\\u093e \\u0939\\u094b\\u0928\\u0947 \\u092a\\u0930 \\u0906\\u092a\\u0915\\u094b \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u091c\\u094b\\u0921\\u093c\\u0928\\u0947 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0940 \\u090f\\u0915 \\u0905\\u0927\\u093f\\u0938\\u0942\\u091a\\u0928\\u093e \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0939\\u094b\\u0917\\u0940\\u0964\"}},\"id\":\"67249a62a7ea6\"}}}', 1, 1, '2024-11-01 15:07:03', '2024-11-06 19:47:36');
INSERT INTO `frontend_header_section_faqs` VALUES (11, 11, 'personal', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About Withdrawing Money\",\"sub_heading\":\"Get answers to your questions regarding the withdrawal process in QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\",\"sub_heading\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0644\\u0623\\u0633\\u0626\\u0644\\u062a\\u0643 \\u0627\\u0644\\u0645\\u062a\\u0639\\u0644\\u0642\\u0629 \\u0628\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0641\\u064a QRPay Pro.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre retirar dinero\",\"sub_heading\":\"Obtenga respuestas a sus preguntas sobre el proceso de retiro en QRPay Pro.\"},\"fr\":{\"heading\":\"Preguntas frecuentes sobre retirar dinero\",\"sub_heading\":\"Obtenez des r\\u00e9ponses \\u00e0 vos questions concernant le processus de retrait dans QRPay Pro.\"},\"hi\":{\"heading\":\"\\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092e\\u0947\\u0902 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0915\\u0947 \\u0938\\u0902\\u092c\\u0902\\u0927 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"67249ae86d181\":{\"language\":{\"en\":{\"question\":\"How do I withdraw money from my QRPay Pro account?\",\"answer\":\"To withdraw money, navigate to the Withdraw Money feature, choose your preferred withdrawal method, enter the amount you want to withdraw, and confirm the transaction. Your funds will be transferred promptly.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u0646 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u064a\\u061f\",\"answer\":\"\\u0644\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u060c \\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u0645\\u064a\\u0632\\u0629 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u060c \\u0648\\u0627\\u062e\\u062a\\u0631 \\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0645\\u0641\\u0636\\u0644\\u0629 \\u0644\\u062f\\u064a\\u0643\\u060c \\u0648\\u0623\\u062f\\u062e\\u0644 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0630\\u064a \\u062a\\u0631\\u064a\\u062f \\u0633\\u062d\\u0628\\u0647\\u060c \\u062b\\u0645 \\u0642\\u0645 \\u0628\\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629. \\u0633\\u064a\\u062a\\u0645 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo retiro dinero de mi cuenta QRPay Pro?\",\"answer\":\"Para retirar dinero, navegue hasta la funci\\u00f3n Retirar dinero, elija su m\\u00e9todo de retiro preferido, ingrese el monto que desea retirar y confirme la transacci\\u00f3n. Sus fondos ser\\u00e1n transferidos de inmediato.\"},\"fr\":{\"question\":\"\\u00bfC\\u00f3mo retiro dinero de mi cuenta QRPay Pro?\",\"answer\":\"Pour retirer de l\'argent, acc\\u00e9dez \\u00e0 la fonction Retirer de l\'argent, choisissez votre m\\u00e9thode de retrait pr\\u00e9f\\u00e9r\\u00e9e, saisissez le montant que vous souhaitez retirer et confirmez la transaction. Vos fonds seront transf\\u00e9r\\u00e9s rapidement.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u0938\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0942\\u0902?\",\"answer\":\"\\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u0947 \\u0915\\u0940 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0901, \\u0905\\u092a\\u0928\\u0940 \\u092a\\u0938\\u0902\\u0926\\u0940\\u0926\\u093e \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0935\\u093f\\u0927\\u093f \\u091a\\u0941\\u0928\\u0947\\u0902, \\u0935\\u0939 \\u0930\\u093e\\u0936\\u093f \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902 \\u091c\\u093f\\u0938\\u0947 \\u0906\\u092a \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u093e \\u091a\\u093e\\u0939\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0914\\u0930 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\\u0964 \\u0906\\u092a\\u0915\\u093e \\u092b\\u0902\\u0921 \\u0924\\u0941\\u0930\\u0902\\u0924 \\u091f\\u094d\\u0930\\u093e\\u0902\\u0938\\u092b\\u0930 \\u0915\\u0930 \\u0926\\u093f\\u092f\\u093e \\u091c\\u093e\\u090f\\u0917\\u093e.\"}},\"id\":\"67249ae86d181\"},\"67249af3303d6\":{\"language\":{\"en\":{\"question\":\"What withdrawal methods are available?\",\"answer\":\"You can withdraw money via various methods, including direct bank transfers and digital wallets. Choose the option that is most convenient for you.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0647\\u064a \\u0637\\u0631\\u0642 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0645\\u062a\\u0627\\u062d\\u0629\\u061f\",\"answer\":\"\\u064a\\u0645\\u0643\\u0646\\u0643 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0639\\u0628\\u0631 \\u0637\\u0631\\u0642 \\u0645\\u062e\\u062a\\u0644\\u0641\\u0629\\u060c \\u0628\\u0645\\u0627 \\u0641\\u064a \\u0630\\u0644\\u0643 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0635\\u0631\\u0641\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0648\\u0627\\u0644\\u0645\\u062d\\u0627\\u0641\\u0638 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a\\u0629. \\u0627\\u062e\\u062a\\u0631 \\u0627\\u0644\\u062e\\u064a\\u0627\\u0631 \\u0627\\u0644\\u0623\\u0643\\u062b\\u0631 \\u0645\\u0644\\u0627\\u0621\\u0645\\u0629 \\u0644\\u0643.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 m\\u00e9todos de retiro est\\u00e1n disponibles?\",\"answer\":\"Puede retirar dinero mediante varios m\\u00e9todos, incluidas transferencias bancarias directas y billeteras digitales. Elija la opci\\u00f3n que sea m\\u00e1s conveniente para usted.\"},\"fr\":{\"question\":\"\\u00bfQu\\u00e9 m\\u00e9todos de retiro est\\u00e1n disponibles?\",\"answer\":\"Vous pouvez retirer de l\'argent via diff\\u00e9rentes m\\u00e9thodes, notamment les virements bancaires directs et les portefeuilles num\\u00e9riques. Choisissez l\'option qui vous convient le mieux.\"},\"hi\":{\"question\":\"\\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0915\\u0947 \\u0915\\u094c\\u0928 \\u0938\\u0947 \\u0924\\u0930\\u0940\\u0915\\u0947 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0939\\u0948\\u0902?\",\"answer\":\"\\u0906\\u092a \\u0938\\u0940\\u0927\\u0947 \\u092c\\u0948\\u0902\\u0915 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0914\\u0930 \\u0921\\u093f\\u091c\\u093f\\u091f\\u0932 \\u0935\\u0949\\u0932\\u0947\\u091f \\u0938\\u0939\\u093f\\u0924 \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u0924\\u0930\\u0940\\u0915\\u094b\\u0902 \\u0938\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0935\\u0939 \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a \\u091a\\u0941\\u0928\\u0947\\u0902 \\u091c\\u094b \\u0906\\u092a\\u0915\\u0947 \\u0932\\u093f\\u090f \\u0938\\u092c\\u0938\\u0947 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e\\u091c\\u0928\\u0915 \\u0939\\u094b\\u0964\"}},\"id\":\"67249af3303d6\"},\"67249afc3c0e2\":{\"language\":{\"en\":{\"question\":\"Are there any fees associated with withdrawing money?\",\"answer\":\"Yes, there may be fees depending on the withdrawal method you select. You will be informed of any applicable fees before confirming your transaction to ensure transparency.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u0642\\u062f \\u062a\\u0643\\u0648\\u0646 \\u0647\\u0646\\u0627\\u0643 \\u0631\\u0633\\u0648\\u0645 \\u062d\\u0633\\u0628 \\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0627\\u0644\\u062a\\u064a \\u062a\\u062e\\u062a\\u0627\\u0631\\u0647\\u0627. \\u0633\\u064a\\u062a\\u0645 \\u0625\\u0628\\u0644\\u0627\\u063a\\u0643 \\u0628\\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0637\\u0628\\u0642\\u0629 \\u0642\\u0628\\u0644 \\u062a\\u0623\\u0643\\u064a\\u062f \\u0645\\u0639\\u0627\\u0645\\u0644\\u062a\\u0643 \\u0644\\u0636\\u0645\\u0627\\u0646 \\u0627\\u0644\\u0634\\u0641\\u0627\\u0641\\u064a\\u0629.\"},\"es\":{\"question\":\"\\u00bfExiste alguna tarifa asociada con el retiro de dinero?\",\"answer\":\"S\\u00ed, puede haber tarifas seg\\u00fan el m\\u00e9todo de retiro que seleccione. Se le informar\\u00e1 de cualquier tarifa aplicable antes de confirmar su transacci\\u00f3n para garantizar la transparencia.\"},\"fr\":{\"question\":\"\\u00bfExiste alguna tarifa asociada con el retiro de dinero?\",\"answer\":\"Oui, des frais peuvent \\u00eatre factur\\u00e9s selon la m\\u00e9thode de retrait que vous s\\u00e9lectionnez. Vous serez inform\\u00e9 des frais applicables avant de confirmer votre transaction pour garantir la transparence.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u0947 \\u0938\\u0947 \\u091c\\u0941\\u0921\\u093c\\u0940 \\u0915\\u094b\\u0908 \\u092b\\u0940\\u0938 \\u0939\\u0948?\",\"answer\":\"\\u0939\\u093e\\u0902, \\u0906\\u092a\\u0915\\u0947 \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u091a\\u0941\\u0928\\u0940 \\u0917\\u0908 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0935\\u093f\\u0927\\u093f \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0939\\u094b \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u092a\\u093e\\u0930\\u0926\\u0930\\u094d\\u0936\\u093f\\u0924\\u093e \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0906\\u092a\\u0915\\u0947 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u0906\\u092a\\u0915\\u094b \\u0915\\u093f\\u0938\\u0940 \\u092d\\u0940 \\u0932\\u093e\\u0917\\u0942 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0938\\u0942\\u091a\\u093f\\u0924 \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e\\u090f\\u0917\\u093e\\u0964\"}},\"id\":\"67249afc3c0e2\"},\"67249b0490b2a\":{\"language\":{\"en\":{\"question\":\"How long does it take for my withdrawal to process?\",\"answer\":\"Withdrawal processing times can vary based on the method chosen. Bank transfers may take longer than digital wallet withdrawals, but you will receive a notification confirming when the transfer is complete.\"},\"ar\":{\"question\":\"\\u0643\\u0645 \\u0645\\u0646 \\u0627\\u0644\\u0648\\u0642\\u062a \\u062a\\u0633\\u062a\\u063a\\u0631\\u0642 \\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u064a\\u061f\",\"answer\":\"\\u064a\\u0645\\u0643\\u0646 \\u0623\\u0646 \\u062a\\u062e\\u062a\\u0644\\u0641 \\u0623\\u0648\\u0642\\u0627\\u062a \\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0628\\u0646\\u0627\\u0621\\u064b \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u0645\\u062e\\u062a\\u0627\\u0631\\u0629. \\u0642\\u062f \\u062a\\u0633\\u062a\\u063a\\u0631\\u0642 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0635\\u0631\\u0641\\u064a\\u0629 \\u0648\\u0642\\u062a\\u064b\\u0627 \\u0623\\u0637\\u0648\\u0644 \\u0645\\u0646 \\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0645\\u062d\\u0641\\u0638\\u0629 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a\\u0629\\u060c \\u0648\\u0644\\u0643\\u0646\\u0643 \\u0633\\u062a\\u062a\\u0644\\u0642\\u0649 \\u0625\\u0634\\u0639\\u0627\\u0631\\u064b\\u0627 \\u064a\\u0624\\u0643\\u062f \\u0645\\u0648\\u0639\\u062f \\u0627\\u0643\\u062a\\u0645\\u0627\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644.\"},\"es\":{\"question\":\"\\u00bfCu\\u00e1nto tiempo lleva procesar mi retiro?\",\"answer\":\"Los tiempos de procesamiento de retiros pueden variar seg\\u00fan el m\\u00e9todo elegido. Las transferencias bancarias pueden tardar m\\u00e1s que los retiros de billetera digital, pero recibir\\u00e1s una notificaci\\u00f3n confirmando cuando se complete la transferencia.\"},\"fr\":{\"question\":\"\\u00bfCu\\u00e1nto tiempo lleva procesar mi retiro?\",\"answer\":\"Les d\\u00e9lais de traitement des retraits peuvent varier en fonction de la m\\u00e9thode choisie. Les virements bancaires peuvent prendre plus de temps que les retraits sur portefeuille num\\u00e9rique, mais vous recevrez une notification confirmant la fin du transfert.\"},\"hi\":{\"question\":\"\\u092e\\u0947\\u0930\\u0940 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0915\\u0940 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u092e\\u0947\\u0902 \\u0915\\u093f\\u0924\\u0928\\u093e \\u0938\\u092e\\u092f \\u0932\\u0917\\u0947\\u0917\\u093e?\",\"answer\":\"\\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0915\\u093e \\u0938\\u092e\\u092f \\u091a\\u0941\\u0928\\u0940 \\u0917\\u0908 \\u0935\\u093f\\u0927\\u093f \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u092d\\u093f\\u0928\\u094d\\u0928 \\u0939\\u094b \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u092c\\u0948\\u0902\\u0915 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u092e\\u0947\\u0902 \\u0921\\u093f\\u091c\\u093f\\u091f\\u0932 \\u0935\\u0949\\u0932\\u0947\\u091f \\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0915\\u0940 \\u0924\\u0941\\u0932\\u0928\\u093e \\u092e\\u0947\\u0902 \\u0905\\u0927\\u093f\\u0915 \\u0938\\u092e\\u092f \\u0932\\u0917 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948, \\u0932\\u0947\\u0915\\u093f\\u0928 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u0923 \\u092a\\u0942\\u0930\\u093e \\u0939\\u094b\\u0928\\u0947 \\u092a\\u0930 \\u0906\\u092a\\u0915\\u094b \\u0907\\u0938\\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0940 \\u090f\\u0915 \\u0905\\u0927\\u093f\\u0938\\u0942\\u091a\\u0928\\u093e \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0939\\u094b\\u0917\\u0940\\u0964\"}},\"id\":\"67249b0490b2a\"}}}', 1, 1, '2024-11-01 15:09:49', '2024-11-06 20:03:57');
INSERT INTO `frontend_header_section_faqs` VALUES (12, 12, 'personal', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About Making Payments\",\"sub_heading\":\"Find answers to your questions regarding the payment process in QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u062f\\u0641\\u0639\\u0627\\u062a\",\"sub_heading\":\"\\u0627\\u0628\\u062d\\u062b \\u0639\\u0646 \\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0644\\u0623\\u0633\\u0626\\u0644\\u062a\\u0643 \\u0627\\u0644\\u0645\\u062a\\u0639\\u0644\\u0642\\u0629 \\u0628\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0641\\u064a QRPay Pro.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre c\\u00f3mo realizar pagos\",\"sub_heading\":\"Encuentre respuestas a sus preguntas sobre el proceso de pago en QRPay Pro.\"},\"fr\":{\"heading\":\"Preguntas frecuentes sobre c\\u00f3mo realizar pagos\",\"sub_heading\":\"Trouvez les r\\u00e9ponses \\u00e0 vos questions concernant le processus de paiement dans QRPay Pro.\"},\"hi\":{\"heading\":\"\\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092e\\u0947\\u0902 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0915\\u0947 \\u0938\\u0902\\u092c\\u0902\\u0927 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u0916\\u094b\\u091c\\u0947\\u0902\\u0964\"}},\"items\":{\"67249c393562d\":{\"language\":{\"en\":{\"question\":\"How can I make a payment using QRPay Pro?\",\"answer\":\"To make a payment, navigate to the Make Payment feature, select the QRPay Pro merchant you wish to pay, enter the payment amount, and confirm the transaction. Your funds will be transferred instantly.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\\u061f\",\"answer\":\"\\u0644\\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u062f\\u0641\\u0639\\u060c \\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u0645\\u064a\\u0632\\u0629 \\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u062f\\u0641\\u0639\\u060c \\u0648\\u062d\\u062f\\u062f \\u062a\\u0627\\u062c\\u0631 QRPay Pro \\u0627\\u0644\\u0630\\u064a \\u062a\\u0631\\u063a\\u0628 \\u0641\\u064a \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0644\\u0647\\u060c \\u0648\\u0623\\u062f\\u062e\\u0644 \\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u062f\\u0641\\u0639\\u060c \\u0648\\u0642\\u0645 \\u0628\\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629. \\u0633\\u064a\\u062a\\u0645 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo puedo realizar un pago usando QRPay Pro?\",\"answer\":\"Para realizar un pago, navegue hasta la funci\\u00f3n Realizar pago, seleccione el comerciante de QRPay Pro al que desea pagar, ingrese el monto del pago y confirme la transacci\\u00f3n. Sus fondos se transferir\\u00e1n instant\\u00e1neamente.\"},\"fr\":{\"question\":\"\\u00bfC\\u00f3mo puedo realizar un pago usando QRPay Pro?\",\"answer\":\"Pour effectuer un paiement, acc\\u00e9dez \\u00e0 la fonction Effectuer un paiement, s\\u00e9lectionnez le commer\\u00e7ant QRPay Pro que vous souhaitez payer, saisissez le montant du paiement et confirmez la transaction. Vos fonds seront transf\\u00e9r\\u00e9s instantan\\u00e9ment.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0948\\u0938\\u0947 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0902?\",\"answer\":\"\\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0947\\u0902 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0901, \\u0909\\u0938 QRPay \\u092a\\u094d\\u0930\\u094b \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u0940 \\u0915\\u093e \\u091a\\u092f\\u0928 \\u0915\\u0930\\u0947\\u0902 \\u091c\\u093f\\u0938\\u0947 \\u0906\\u092a \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0928\\u093e \\u091a\\u093e\\u0939\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0930\\u093e\\u0936\\u093f \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\\u0964 \\u0906\\u092a\\u0915\\u093e \\u092b\\u0902\\u0921 \\u0924\\u0941\\u0930\\u0902\\u0924 \\u091f\\u094d\\u0930\\u093e\\u0902\\u0938\\u092b\\u0930 \\u0915\\u0930 \\u0926\\u093f\\u092f\\u093e \\u091c\\u093e\\u090f\\u0917\\u093e.\"}},\"id\":\"67249c393562d\"},\"67249c41c0e30\":{\"language\":{\"en\":{\"question\":\"Can I pay any merchant with QRPay Pro?\",\"answer\":\"No, payments can only be made to merchants registered on the QRPay Pro platform. Ensure you are paying a QRPay Pro merchant to complete your transaction successfully.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0644\\u0623\\u064a \\u062a\\u0627\\u062c\\u0631 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\\u061f\",\"answer\":\"\\u0644\\u0627\\u060c \\u0644\\u0627 \\u064a\\u0645\\u0643\\u0646 \\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u062f\\u0641\\u0639\\u0627\\u062a \\u0625\\u0644\\u0627 \\u0644\\u0644\\u062a\\u062c\\u0627\\u0631 \\u0627\\u0644\\u0645\\u0633\\u062c\\u0644\\u064a\\u0646 \\u0639\\u0644\\u0649 \\u0645\\u0646\\u0635\\u0629 QRPay Pro. \\u062a\\u0623\\u0643\\u062f \\u0645\\u0646 \\u0623\\u0646\\u0643 \\u062a\\u062f\\u0641\\u0639 \\u0644\\u062a\\u0627\\u062c\\u0631 QRPay Pro \\u0644\\u0625\\u0643\\u0645\\u0627\\u0644 \\u0645\\u0639\\u0627\\u0645\\u0644\\u062a\\u0643 \\u0628\\u0646\\u062c\\u0627\\u062d.\"},\"es\":{\"question\":\"\\u00bfPuedo pagarle a cualquier comerciante con QRPay Pro?\",\"answer\":\"No, los pagos s\\u00f3lo se pueden realizar a comercios registrados en la plataforma QRPay Pro. Aseg\\u00farese de pagarle a un comerciante de QRPay Pro para completar su transacci\\u00f3n con \\u00e9xito.\"},\"fr\":{\"question\":\"\\u00bfPuedo pagarle a cualquier comerciante con QRPay Pro?\",\"answer\":\"Non, les paiements ne peuvent \\u00eatre effectu\\u00e9s qu\'aux commer\\u00e7ants inscrits sur la plateforme QRPay Pro. Assurez-vous de payer un commer\\u00e7ant QRPay Pro pour terminer votre transaction avec succ\\u00e8s.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 QRPay Pro \\u0938\\u0947 \\u0915\\u093f\\u0938\\u0940 \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u0940 \\u0915\\u094b \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0928\\u0939\\u0940\\u0902, \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0947\\u0935\\u0932 QRPay Pro \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e \\u092a\\u0930 \\u092a\\u0902\\u091c\\u0940\\u0915\\u0943\\u0924 \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u093f\\u092f\\u094b\\u0902 \\u0915\\u094b \\u0939\\u0940 \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902 \\u0915\\u093f \\u0906\\u092a \\u0905\\u092a\\u0928\\u093e \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0938\\u092b\\u0932\\u0924\\u093e\\u092a\\u0942\\u0930\\u094d\\u0935\\u0915 \\u092a\\u0942\\u0930\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f QRPay \\u092a\\u094d\\u0930\\u094b \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u0940 \\u0915\\u094b \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930 \\u0930\\u0939\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"67249c41c0e30\"},\"67249c49ca78c\":{\"language\":{\"en\":{\"question\":\"Are there any fees for making payments with QRPay Pro?\",\"answer\":\"QRPay Pro typically does not charge fees for making payments. However, individual merchants may have their own policies regarding fees, so it\'s advisable to check before confirming your payment.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0639\\u0646\\u062f \\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u062f\\u0641\\u0639\\u0627\\u062a \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\\u061f\",\"answer\":\"\\u0644\\u0627 \\u064a\\u0641\\u0631\\u0636 QRPay Pro \\u0639\\u0627\\u062f\\u0629\\u064b \\u0631\\u0633\\u0648\\u0645\\u064b\\u0627 \\u0645\\u0642\\u0627\\u0628\\u0644 \\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u062f\\u0641\\u0639\\u0627\\u062a. \\u0648\\u0645\\u0639 \\u0630\\u0644\\u0643\\u060c \\u0642\\u062f \\u064a\\u0643\\u0648\\u0646 \\u0644\\u062f\\u0649 \\u0627\\u0644\\u062a\\u062c\\u0627\\u0631 \\u0627\\u0644\\u0641\\u0631\\u062f\\u064a\\u064a\\u0646 \\u0633\\u064a\\u0627\\u0633\\u0627\\u062a\\u0647\\u0645 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0641\\u064a\\u0645\\u0627 \\u064a\\u062a\\u0639\\u0644\\u0642 \\u0628\\u0627\\u0644\\u0631\\u0633\\u0648\\u0645\\u060c \\u0644\\u0630\\u0627 \\u064a\\u064f\\u0646\\u0635\\u062d \\u0628\\u0627\\u0644\\u062a\\u062d\\u0642\\u0642 \\u0642\\u0628\\u0644 \\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u062f\\u0641\\u0639.\"},\"es\":{\"question\":\"\\u00bfHay alg\\u00fan cargo por realizar pagos con QRPay Pro?\",\"answer\":\"QRPay Pro normalmente no cobra tarifas por realizar pagos. Sin embargo, los comerciantes individuales pueden tener sus propias pol\\u00edticas con respecto a las tarifas, por lo que es recomendable verificar antes de confirmar su pago.\"},\"fr\":{\"question\":\"\\u00bfHay alg\\u00fan cargo por realizar pagos con QRPay Pro?\",\"answer\":\"QRPay Pro ne facture g\\u00e9n\\u00e9ralement pas de frais pour effectuer des paiements. Cependant, chaque commer\\u00e7ant peut avoir ses propres politiques concernant les frais, il est donc conseill\\u00e9 de v\\u00e9rifier avant de confirmer votre paiement.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e QRPay Pro \\u0938\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u092a\\u0930 \\u0915\\u094b\\u0908 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0939\\u0948?\",\"answer\":\"QRPay Pro \\u0906\\u092e\\u0924\\u094c\\u0930 \\u092a\\u0930 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0928\\u0939\\u0940\\u0902 \\u0932\\u0947\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0939\\u093e\\u0932\\u093e\\u0901\\u0915\\u093f, \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0915\\u0947 \\u0938\\u0902\\u092c\\u0902\\u0927 \\u092e\\u0947\\u0902 \\u0905\\u0932\\u0917-\\u0905\\u0932\\u0917 \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u093f\\u092f\\u094b\\u0902 \\u0915\\u0940 \\u0905\\u092a\\u0928\\u0940 \\u0928\\u0940\\u0924\\u093f\\u092f\\u093e\\u0902 \\u0939\\u094b \\u0938\\u0915\\u0924\\u0940 \\u0939\\u0948\\u0902, \\u0907\\u0938\\u0932\\u093f\\u090f \\u0938\\u0932\\u093e\\u0939 \\u0926\\u0940 \\u091c\\u093e\\u0924\\u0940 \\u0939\\u0948 \\u0915\\u093f \\u0905\\u092a\\u0928\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u091c\\u093e\\u0902\\u091a \\u0915\\u0930 \\u0932\\u0947\\u0902\\u0964\"}},\"id\":\"67249c49ca78c\"},\"67249c52ce2d3\":{\"language\":{\"en\":{\"question\":\"How will I know if my payment was successful?\",\"answer\":\"Once you confirm the payment, you will receive a notification confirming the success of your transaction. You can also check your transaction history for confirmation.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u0623\\u0639\\u0631\\u0641 \\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646\\u062a \\u062f\\u0641\\u0639\\u062a\\u064a \\u0646\\u0627\\u062c\\u062d\\u0629\\u061f\",\"answer\":\"\\u0628\\u0645\\u062c\\u0631\\u062f \\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u062f\\u0641\\u0639\\u060c \\u0633\\u062a\\u062a\\u0644\\u0642\\u0649 \\u0625\\u0634\\u0639\\u0627\\u0631\\u064b\\u0627 \\u064a\\u0624\\u0643\\u062f \\u0646\\u062c\\u0627\\u062d \\u0645\\u0639\\u0627\\u0645\\u0644\\u062a\\u0643. \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0623\\u064a\\u0636\\u064b\\u0627 \\u0627\\u0644\\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0633\\u062c\\u0644 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u0643 \\u0644\\u0644\\u062a\\u0623\\u0643\\u064a\\u062f.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo sabr\\u00e9 si mi pago fue exitoso?\",\"answer\":\"Una vez que confirmes el pago, recibir\\u00e1s una notificaci\\u00f3n confirmando el \\u00e9xito de tu transacci\\u00f3n. Tambi\\u00e9n puede consultar su historial de transacciones para confirmarlo.\"},\"fr\":{\"question\":\"\\u00bfC\\u00f3mo sabr\\u00e9 si mi pago fue exitoso?\",\"answer\":\"Une fois le paiement confirm\\u00e9, vous recevrez une notification confirmant le succ\\u00e8s de votre transaction. Vous pouvez \\u00e9galement consulter l\\u2019historique de vos transactions pour confirmation.\"},\"hi\":{\"question\":\"\\u092e\\u0941\\u091d\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u092a\\u0924\\u093e \\u091a\\u0932\\u0947\\u0917\\u093e \\u0915\\u093f \\u092e\\u0947\\u0930\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u092b\\u0932 \\u0939\\u0941\\u0906?\",\"answer\":\"\\u090f\\u0915 \\u092c\\u093e\\u0930 \\u091c\\u092c \\u0906\\u092a \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930 \\u0926\\u0947\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0924\\u094b \\u0906\\u092a\\u0915\\u094b \\u0905\\u092a\\u0928\\u0947 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u0938\\u092b\\u0932\\u0924\\u093e \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0940 \\u090f\\u0915 \\u0905\\u0927\\u093f\\u0938\\u0942\\u091a\\u0928\\u093e \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0939\\u094b\\u0917\\u0940\\u0964 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0906\\u092a \\u0905\\u092a\\u0928\\u093e \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0907\\u0924\\u093f\\u0939\\u093e\\u0938 \\u092d\\u0940 \\u0926\\u0947\\u0916 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"67249c52ce2d3\"}}}', 1, 1, '2024-11-01 15:15:25', '2024-11-06 20:10:08');
INSERT INTO `frontend_header_section_faqs` VALUES (13, 13, 'personal', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About Money Out\",\"sub_heading\":\"Find answers to your questions regarding the money withdrawal process in QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0627\\u0644\\u0635\\u0627\\u062f\\u0631\\u0629\",\"sub_heading\":\"\\u0627\\u0628\\u062d\\u062b \\u0639\\u0646 \\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0644\\u0623\\u0633\\u0626\\u0644\\u062a\\u0643 \\u0627\\u0644\\u0645\\u062a\\u0639\\u0644\\u0642\\u0629 \\u0628\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a QRPay Pro.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre retiros de dinero\",\"sub_heading\":\"Encuentre respuestas a sus preguntas sobre el proceso de retiro de dinero en QRPay Pro.\"},\"fr\":{\"heading\":\"Preguntas frecuentes sobre retiros de dinero\",\"sub_heading\":\"Trouvez des r\\u00e9ponses \\u00e0 vos questions concernant le processus de retrait d\'argent dans QRPay Pro.\"},\"hi\":{\"heading\":\"\\u092e\\u0928\\u0940 \\u0906\\u0909\\u091f \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092e\\u0947\\u0902 \\u0927\\u0928 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0915\\u0947 \\u0938\\u0902\\u092c\\u0902\\u0927 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u0916\\u094b\\u091c\\u0947\\u0902\\u0964\"}},\"items\":{\"67249d34d9feb\":{\"language\":{\"en\":{\"question\":\"How can I withdraw money from my QRPay Pro account?\",\"answer\":\"To withdraw money, go to the Money Out feature, select a QRPay Pro agent, enter the withdrawal amount, and confirm the transaction. Your funds will be transferred to the agent securely.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u0646 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u064a\\u061f\",\"answer\":\"\\u0644\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u060c \\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u0645\\u064a\\u0632\\u0629 Money Out\\u060c \\u0648\\u062d\\u062f\\u062f \\u0648\\u0643\\u064a\\u0644 QRPay Pro\\u060c \\u0648\\u0623\\u062f\\u062e\\u0644 \\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0633\\u062d\\u0628\\u060c \\u0648\\u0642\\u0645 \\u0628\\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629. \\u0633\\u064a\\u062a\\u0645 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0648\\u0643\\u064a\\u0644 \\u0628\\u0634\\u0643\\u0644 \\u0622\\u0645\\u0646.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo puedo retirar dinero de mi cuenta QRPay Pro?\",\"answer\":\"Para retirar dinero, vaya a la funci\\u00f3n Retiro de dinero, seleccione un agente de QRPay Pro, ingrese el monto del retiro y confirme la transacci\\u00f3n. Sus fondos se transferir\\u00e1n al agente de forma segura.\"},\"fr\":{\"question\":\"\\u00bfC\\u00f3mo puedo retirar dinero de mi cuenta QRPay Pro?\",\"answer\":\"Pour retirer de l\'argent, acc\\u00e9dez \\u00e0 la fonction Money Out, s\\u00e9lectionnez un agent QRPay Pro, saisissez le montant du retrait et confirmez la transaction. Vos fonds seront transf\\u00e9r\\u00e9s \\u00e0 l\'agent en toute s\\u00e9curit\\u00e9.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u0938\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u092e\\u0928\\u0940 \\u0906\\u0909\\u091f \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0902, QRPay \\u092a\\u094d\\u0930\\u094b \\u090f\\u091c\\u0947\\u0902\\u091f \\u0915\\u093e \\u091a\\u092f\\u0928 \\u0915\\u0930\\u0947\\u0902, \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0930\\u093e\\u0936\\u093f \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\\u0964 \\u0906\\u092a\\u0915\\u0940 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u090f\\u091c\\u0947\\u0902\\u091f \\u0915\\u094b \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u093f\\u0924 \\u0915\\u0930 \\u0926\\u0940 \\u091c\\u093e\\u090f\\u0917\\u0940\\u0964\"}},\"id\":\"67249d34d9feb\"},\"67249d3e34b04\":{\"language\":{\"en\":{\"question\":\"Who can I withdraw money to?\",\"answer\":\"You can only withdraw money to authorized QRPay Pro agents registered on the QRPay Pro platform. Make sure you select a trusted agent for your transaction.\"},\"ar\":{\"question\":\"\\u0644\\u0645\\u0646 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u061f\",\"answer\":\"\\u064a\\u0645\\u0643\\u0646\\u0643 \\u0641\\u0642\\u0637 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u0648\\u0643\\u0644\\u0627\\u0621 QRPay Pro \\u0627\\u0644\\u0645\\u0639\\u062a\\u0645\\u062f\\u064a\\u0646 \\u0627\\u0644\\u0645\\u0633\\u062c\\u0644\\u064a\\u0646 \\u0639\\u0644\\u0649 \\u0645\\u0646\\u0635\\u0629 QRPay Pro. \\u062a\\u0623\\u0643\\u062f \\u0645\\u0646 \\u062a\\u062d\\u062f\\u064a\\u062f \\u0648\\u0643\\u064a\\u0644 \\u0645\\u0648\\u062b\\u0648\\u0642 \\u0628\\u0647 \\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u062a\\u0643.\"},\"es\":{\"question\":\"\\u00bfA qui\\u00e9n puedo retirar dinero?\",\"answer\":\"S\\u00f3lo puedes retirar dinero a agentes autorizados de QRPay Pro registrados en la plataforma QRPay Pro. Aseg\\u00farese de seleccionar un agente confiable para su transacci\\u00f3n.\"},\"fr\":{\"question\":\"\\u00bfA qui\\u00e9n puedo retirar dinero?\",\"answer\":\"Vous ne pouvez retirer de l\'argent qu\'aux agents QRPay Pro autoris\\u00e9s enregistr\\u00e9s sur la plateforme QRPay Pro. Assurez-vous de s\\u00e9lectionner un agent de confiance pour votre transaction.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 \\u0915\\u093f\\u0938\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0906\\u092a \\u0915\\u0947\\u0935\\u0932 QRPay Pro \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e \\u092a\\u0930 \\u092a\\u0902\\u091c\\u0940\\u0915\\u0943\\u0924 \\u0905\\u0927\\u093f\\u0915\\u0943\\u0924 QRPay Pro \\u090f\\u091c\\u0947\\u0902\\u091f\\u094b\\u0902 \\u0938\\u0947 \\u0939\\u0940 \\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902 \\u0915\\u093f \\u0906\\u092a \\u0905\\u092a\\u0928\\u0947 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u090f\\u0915 \\u0935\\u093f\\u0936\\u094d\\u0935\\u0938\\u0928\\u0940\\u092f \\u090f\\u091c\\u0947\\u0902\\u091f \\u0915\\u093e \\u091a\\u092f\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"67249d3e34b04\"},\"67249d4923da9\":{\"language\":{\"en\":{\"question\":\"Are there any fees associated with withdrawing money?\",\"answer\":\"Typically, QRPay Pro does not charge fees for withdrawing funds to agents. However, some agents may have their own fee structures, so it\'s a good idea to verify before proceeding with your withdrawal.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u061f\",\"answer\":\"\\u0639\\u0627\\u062f\\u0629\\u064b\\u060c \\u0644\\u0627 \\u064a\\u0641\\u0631\\u0636 QRPay Pro \\u0631\\u0633\\u0648\\u0645\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0648\\u0643\\u0644\\u0627\\u0621. \\u0648\\u0645\\u0639 \\u0630\\u0644\\u0643\\u060c \\u0642\\u062f \\u064a\\u0643\\u0648\\u0646 \\u0644\\u062f\\u0649 \\u0628\\u0639\\u0636 \\u0627\\u0644\\u0648\\u0643\\u0644\\u0627\\u0621 \\u0647\\u064a\\u0627\\u0643\\u0644 \\u0631\\u0633\\u0648\\u0645 \\u062e\\u0627\\u0635\\u0629 \\u0628\\u0647\\u0645\\u060c \\u0644\\u0630\\u0627 \\u0645\\u0646 \\u0627\\u0644\\u062c\\u064a\\u062f \\u0627\\u0644\\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646\\u0647\\u0627 \\u0642\\u0628\\u0644 \\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0633\\u062d\\u0628.\"},\"es\":{\"question\":\"\\u00bfExiste alguna tarifa asociada con el retiro de dinero?\",\"answer\":\"Normalmente, QRPay Pro no cobra tarifas por retirar fondos a los agentes. Sin embargo, algunos agentes pueden tener sus propias estructuras de tarifas, por lo que es una buena idea verificarlo antes de continuar con el retiro.\"},\"fr\":{\"question\":\"\\u00bfExiste alguna tarifa asociada con el retiro de dinero?\",\"answer\":\"En r\\u00e8gle g\\u00e9n\\u00e9rale, QRPay Pro ne facture pas de frais pour le retrait de fonds aux agents. Cependant, certains agents peuvent avoir leurs propres structures de frais, c\'est donc une bonne id\\u00e9e de v\\u00e9rifier avant de proc\\u00e9der \\u00e0 votre retrait.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u0947 \\u0938\\u0947 \\u091c\\u0941\\u0921\\u093c\\u0940 \\u0915\\u094b\\u0908 \\u092b\\u0940\\u0938 \\u0939\\u0948?\",\"answer\":\"\\u0906\\u092e\\u0924\\u094c\\u0930 \\u092a\\u0930, QRPay Pro \\u090f\\u091c\\u0947\\u0902\\u091f\\u094b\\u0902 \\u0938\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0928\\u0939\\u0940\\u0902 \\u0932\\u0947\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0939\\u093e\\u0932\\u093e\\u0901\\u0915\\u093f, \\u0915\\u0941\\u091b \\u090f\\u091c\\u0947\\u0902\\u091f\\u094b\\u0902 \\u0915\\u0940 \\u0905\\u092a\\u0928\\u0940 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0938\\u0902\\u0930\\u091a\\u0928\\u093e \\u0939\\u094b \\u0938\\u0915\\u0924\\u0940 \\u0939\\u0948, \\u0907\\u0938\\u0932\\u093f\\u090f \\u0906\\u092a\\u0915\\u0940 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0906\\u0917\\u0947 \\u092c\\u0922\\u093c\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u0938\\u0924\\u094d\\u092f\\u093e\\u092a\\u093f\\u0924 \\u0915\\u0930\\u0928\\u093e \\u090f\\u0915 \\u0905\\u091a\\u094d\\u091b\\u093e \\u0935\\u093f\\u091a\\u093e\\u0930 \\u0939\\u0948\\u0964\"}},\"id\":\"67249d4923da9\"},\"67249d51e9538\":{\"language\":{\"en\":{\"question\":\"How will I know when my withdrawal is complete?\",\"answer\":\"After confirming your withdrawal, you will receive a notification once the funds have been successfully sent to the QRPay Pro agent. You can also check your transaction history for confirmation.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u0623\\u0639\\u0631\\u0641 \\u0645\\u062a\\u0649 \\u0627\\u0643\\u062a\\u0645\\u0644 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u064a\\u061f\",\"answer\":\"\\u0628\\u0639\\u062f \\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0633\\u062d\\u0628\\u060c \\u0633\\u062a\\u062a\\u0644\\u0642\\u0649 \\u0625\\u0634\\u0639\\u0627\\u0631\\u064b\\u0627 \\u0628\\u0645\\u062c\\u0631\\u062f \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0646\\u062c\\u0627\\u062d \\u0625\\u0644\\u0649 \\u0648\\u0643\\u064a\\u0644 QRPay Pro. \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0623\\u064a\\u0636\\u064b\\u0627 \\u0627\\u0644\\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0633\\u062c\\u0644 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u0643 \\u0644\\u0644\\u062a\\u0623\\u0643\\u064a\\u062f.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo sabr\\u00e9 cuando se complete mi retiro?\",\"answer\":\"Despu\\u00e9s de confirmar su retiro, recibir\\u00e1 una notificaci\\u00f3n una vez que los fondos se hayan enviado exitosamente al agente de QRPay Pro. Tambi\\u00e9n puede consultar su historial de transacciones para confirmarlo.\"},\"fr\":{\"question\":\"\\u00bfC\\u00f3mo sabr\\u00e9 cuando se complete mi retiro?\",\"answer\":\"Apr\\u00e8s avoir confirm\\u00e9 votre retrait, vous recevrez une notification une fois que les fonds auront \\u00e9t\\u00e9 envoy\\u00e9s avec succ\\u00e8s \\u00e0 l\'agent QRPay Pro. Vous pouvez \\u00e9galement consulter l\\u2019historique de vos transactions pour confirmation.\"},\"hi\":{\"question\":\"\\u091c\\u092c \\u092e\\u0947\\u0930\\u0940 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u092a\\u0942\\u0930\\u0940 \\u0939\\u094b \\u091c\\u093e\\u090f\\u0917\\u0940 \\u0924\\u094b \\u092e\\u0941\\u091d\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u092a\\u0924\\u093e \\u091a\\u0932\\u0947\\u0917\\u093e?\",\"answer\":\"\\u0906\\u092a\\u0915\\u0940 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0926, QRPay \\u092a\\u094d\\u0930\\u094b \\u090f\\u091c\\u0947\\u0902\\u091f \\u0915\\u094b \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0938\\u092b\\u0932\\u0924\\u093e\\u092a\\u0942\\u0930\\u094d\\u0935\\u0915 \\u092d\\u0947\\u091c\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u092a\\u0930 \\u0906\\u092a\\u0915\\u094b \\u090f\\u0915 \\u0905\\u0927\\u093f\\u0938\\u0942\\u091a\\u0928\\u093e \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0939\\u094b\\u0917\\u0940\\u0964 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0906\\u092a \\u0905\\u092a\\u0928\\u093e \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0907\\u0924\\u093f\\u0939\\u093e\\u0938 \\u092d\\u0940 \\u0926\\u0947\\u0916 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"67249d51e9538\"}}}', 1, 1, '2024-11-01 15:19:36', '2024-11-06 20:17:18');
INSERT INTO `frontend_header_section_faqs` VALUES (14, 14, 'personal', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About QRPay Pro Virtual Card\",\"sub_heading\":\"Find answers to your questions regarding virtual card creation and usage.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0628\\u0637\\u0627\\u0642\\u0629 QRPay Pro \\u0627\\u0644\\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629\",\"sub_heading\":\"\\u0627\\u0628\\u062d\\u062b \\u0639\\u0646 \\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0644\\u0623\\u0633\\u0626\\u0644\\u062a\\u0643 \\u0627\\u0644\\u0645\\u062a\\u0639\\u0644\\u0642\\u0629 \\u0628\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0627\\u0644\\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629 \\u0648\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645\\u0647\\u0627.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre la tarjeta virtual QRPay Pro\",\"sub_heading\":\"Encuentre respuestas a sus preguntas sobre la creaci\\u00f3n y el uso de tarjetas virtuales.\"},\"fr\":{\"heading\":\"Preguntas frecuentes sobre la tarjeta virtual QRPay Pro\",\"sub_heading\":\"Trouvez les r\\u00e9ponses \\u00e0 vos questions concernant la cr\\u00e9ation et l\'utilisation de cartes virtuelles.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"\\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0928\\u093f\\u0930\\u094d\\u092e\\u093e\\u0923 \\u0914\\u0930 \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0947 \\u0938\\u0902\\u092c\\u0902\\u0927 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u0916\\u094b\\u091c\\u0947\\u0902\\u0964\"}},\"items\":{\"67249deaa7d38\":{\"language\":{\"en\":{\"question\":\"How do I create a virtual card using QRPay Pro?\",\"answer\":\"To create a virtual card, go to the Virtual Card feature in your QRPay Pro app, click on \\\"Create a Virtual Card,\\\" and follow the prompts to set your preferences and generate your card.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u0623\\u0642\\u0648\\u0645 \\u0628\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\\u061f\",\"answer\":\"\\u0644\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629\\u060c \\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u0645\\u064a\\u0632\\u0629 Virtual Card \\u0641\\u064a \\u062a\\u0637\\u0628\\u064a\\u0642 QRPay Pro\\u060c \\u0648\\u0627\\u0646\\u0642\\u0631 \\u0639\\u0644\\u0649 \\\"\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629\\\"\\u060c \\u0648\\u0627\\u062a\\u0628\\u0639 \\u0627\\u0644\\u0645\\u0637\\u0627\\u0644\\u0628\\u0627\\u062a \\u0644\\u062a\\u0639\\u064a\\u064a\\u0646 \\u062a\\u0641\\u0636\\u064a\\u0644\\u0627\\u062a\\u0643 \\u0648\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0628\\u0637\\u0627\\u0642\\u062a\\u0643.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo creo una tarjeta virtual usando QRPay Pro?\",\"answer\":\"Para crear una tarjeta virtual, vaya a la funci\\u00f3n Tarjeta virtual en su aplicaci\\u00f3n QRPay Pro, haga clic en \\\"Crear una tarjeta virtual\\\" y siga las instrucciones para configurar sus preferencias y generar su tarjeta.\"},\"fr\":{\"question\":\"\\u00bfC\\u00f3mo creo una tarjeta virtual usando QRPay Pro?\",\"answer\":\"Pour cr\\u00e9er une carte virtuelle, acc\\u00e9dez \\u00e0 la fonctionnalit\\u00e9 Carte virtuelle de votre application QRPay Pro, cliquez sur \\u00ab Cr\\u00e9er une carte virtuelle \\u00bb et suivez les invites pour d\\u00e9finir vos pr\\u00e9f\\u00e9rences et g\\u00e9n\\u00e9rer votre carte.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay Pro \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0915\\u0948\\u0938\\u0947 \\u092c\\u0928\\u093e\\u090a\\u0902?\",\"answer\":\"\\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u092c\\u0928\\u093e\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0910\\u092a \\u092e\\u0947\\u0902 \\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0902, \\\"\\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u092c\\u0928\\u093e\\u090f\\u0902\\\" \\u092a\\u0930 \\u0915\\u094d\\u0932\\u093f\\u0915 \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u0905\\u092a\\u0928\\u0940 \\u092a\\u094d\\u0930\\u093e\\u0925\\u092e\\u093f\\u0915\\u0924\\u093e\\u090f\\u0902 \\u0928\\u093f\\u0930\\u094d\\u0927\\u093e\\u0930\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0914\\u0930 \\u0905\\u092a\\u0928\\u093e \\u0915\\u093e\\u0930\\u094d\\u0921 \\u092c\\u0928\\u093e\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0938\\u0902\\u0915\\u0947\\u0924\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"67249deaa7d38\"},\"67249df3e5e68\":{\"language\":{\"en\":{\"question\":\"Can I use my QRPay Pro virtual card for international transactions?\",\"answer\":\"Yes, QRPay Pro virtual cards can typically be used for international transactions as long as the merchant accepts card payments. Check with the merchant for their accepted payment methods.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0628\\u0637\\u0627\\u0642\\u0629 QRPay Pro \\u0627\\u0644\\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u064a \\u0644\\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u062f\\u0648\\u0644\\u064a\\u0629\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u064a\\u0645\\u0643\\u0646 \\u0639\\u0627\\u062f\\u0629\\u064b \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0628\\u0637\\u0627\\u0642\\u0627\\u062a QRPay Pro \\u0627\\u0644\\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629 \\u0644\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u062f\\u0648\\u0644\\u064a\\u0629 \\u0637\\u0627\\u0644\\u0645\\u0627 \\u0623\\u0646 \\u0627\\u0644\\u062a\\u0627\\u062c\\u0631 \\u064a\\u0642\\u0628\\u0644 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0628\\u0627\\u0644\\u0628\\u0637\\u0627\\u0642\\u0629. \\u062a\\u062d\\u0642\\u0642 \\u0645\\u0639 \\u0627\\u0644\\u062a\\u0627\\u062c\\u0631 \\u0644\\u0645\\u0639\\u0631\\u0641\\u0629 \\u0637\\u0631\\u0642 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u0645\\u0642\\u0628\\u0648\\u0644\\u0629 \\u0644\\u062f\\u064a\\u0647.\"},\"es\":{\"question\":\"\\u00bfPuedo utilizar mi tarjeta virtual QRPay Pro para transacciones internacionales?\",\"answer\":\"S\\u00ed, las tarjetas virtuales QRPay Pro normalmente se pueden utilizar para transacciones internacionales siempre que el comerciante acepte pagos con tarjeta. Consulte con el comerciante cu\\u00e1les son los m\\u00e9todos de pago aceptados.\"},\"fr\":{\"question\":\"\\u00bfPuedo utilizar mi tarjeta virtual QRPay Pro para transacciones internacionales?\",\"answer\":\"Oui, les cartes virtuelles QRPay Pro peuvent g\\u00e9n\\u00e9ralement \\u00eatre utilis\\u00e9es pour les transactions internationales tant que le commer\\u00e7ant accepte les paiements par carte. V\\u00e9rifiez aupr\\u00e8s du commer\\u00e7ant ses m\\u00e9thodes de paiement accept\\u00e9es.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u0905\\u0902\\u0924\\u0930\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0902?\",\"answer\":\"\\u0939\\u093e\\u0902, QRPay Pro \\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0906\\u092e \\u0924\\u094c\\u0930 \\u092a\\u0930 \\u0905\\u0902\\u0924\\u0930\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948, \\u091c\\u092c \\u0924\\u0915 \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u0940 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0938\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u094d\\u0935\\u0940\\u0915\\u093e\\u0930 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u0940 \\u0938\\u0947 \\u0909\\u0928\\u0915\\u0940 \\u0938\\u094d\\u0935\\u0940\\u0915\\u0943\\u0924 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0935\\u093f\\u0927\\u093f\\u092f\\u094b\\u0902 \\u0915\\u0940 \\u091c\\u093e\\u0901\\u091a \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"67249df3e5e68\"},\"67249e0019f6d\":{\"language\":{\"en\":{\"question\":\"Is it safe to use a virtual card for online purchases?\",\"answer\":\"Absolutely! QRPay Pro\'s virtual card feature provides an additional layer of security by keeping your actual credit card details private, reducing the risk of fraud.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0645\\u0646 \\u0627\\u0644\\u0622\\u0645\\u0646 \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0627\\u0644\\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629 \\u0644\\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0627\\u0644\\u0634\\u0631\\u0627\\u0621 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0625\\u0646\\u062a\\u0631\\u0646\\u062a\\u061f\",\"answer\":\"\\u0642\\u0637\\u0639\\u0627\\u064b! \\u062a\\u0648\\u0641\\u0631 \\u0645\\u064a\\u0632\\u0629 \\u0627\\u0644\\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0640 QRPay Pro \\u0637\\u0628\\u0642\\u0629 \\u0625\\u0636\\u0627\\u0641\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0623\\u0645\\u0627\\u0646 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0627\\u0644\\u062d\\u0641\\u0627\\u0638 \\u0639\\u0644\\u0649 \\u062e\\u0635\\u0648\\u0635\\u064a\\u0629 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0628\\u0637\\u0627\\u0642\\u062a\\u0643 \\u0627\\u0644\\u0627\\u0626\\u062a\\u0645\\u0627\\u0646\\u064a\\u0629 \\u0627\\u0644\\u0641\\u0639\\u0644\\u064a\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0642\\u0644\\u0644 \\u0645\\u0646 \\u0645\\u062e\\u0627\\u0637\\u0631 \\u0627\\u0644\\u0627\\u062d\\u062a\\u064a\\u0627\\u0644.\"},\"es\":{\"question\":\"\\u00bfEs seguro utilizar una tarjeta virtual para compras online?\",\"answer\":\"\\u00a1Absolutamente! La funci\\u00f3n de tarjeta virtual de QRPay Pro proporciona una capa adicional de seguridad al mantener privados los datos reales de su tarjeta de cr\\u00e9dito, lo que reduce el riesgo de fraude.\"},\"fr\":{\"question\":\"\\u00bfEs seguro utilizar una tarjeta virtual para compras online?\",\"answer\":\"Absolument! La fonctionnalit\\u00e9 de carte virtuelle de QRPay Pro offre une couche de s\\u00e9curit\\u00e9 suppl\\u00e9mentaire en gardant les d\\u00e9tails de votre carte de cr\\u00e9dit confidentiels, r\\u00e9duisant ainsi le risque de fraude.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u0911\\u0928\\u0932\\u093e\\u0907\\u0928 \\u0916\\u0930\\u0940\\u0926\\u093e\\u0930\\u0940 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0928\\u093e \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0939\\u0948?\",\"answer\":\"\\u092c\\u093f\\u0932\\u094d\\u0915\\u0941\\u0932! QRPay Pro \\u0915\\u093e \\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u092b\\u0940\\u091a\\u0930 \\u0906\\u092a\\u0915\\u0947 \\u0935\\u093e\\u0938\\u094d\\u0924\\u0935\\u093f\\u0915 \\u0915\\u094d\\u0930\\u0947\\u0921\\u093f\\u091f \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0915\\u094b \\u0928\\u093f\\u091c\\u0940 \\u0930\\u0916\\u0915\\u0930 \\u0927\\u094b\\u0916\\u093e\\u0927\\u0921\\u093c\\u0940 \\u0915\\u0947 \\u091c\\u094b\\u0916\\u093f\\u092e \\u0915\\u094b \\u0915\\u092e \\u0915\\u0930\\u0915\\u0947 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0915\\u0940 \\u090f\\u0915 \\u0905\\u0924\\u093f\\u0930\\u093f\\u0915\\u094d\\u0924 \\u092a\\u0930\\u0924 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948\\u0964\"}},\"id\":\"67249e0019f6d\"},\"67249e0e36550\":{\"language\":{\"en\":{\"question\":\"Can I set limits on my virtual card?\",\"answer\":\"Yes, when generating your virtual card, you can set spending limits and an expiration date based on your preferences, allowing you to manage your spending effectively.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0648\\u0636\\u0639 \\u062d\\u062f\\u0648\\u062f \\u0639\\u0644\\u0649 \\u0628\\u0637\\u0627\\u0642\\u062a\\u064a \\u0627\\u0644\\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u0639\\u0646\\u062f \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0628\\u0637\\u0627\\u0642\\u062a\\u0643 \\u0627\\u0644\\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629\\u060c \\u064a\\u0645\\u0643\\u0646\\u0643 \\u062a\\u0639\\u064a\\u064a\\u0646 \\u062d\\u062f\\u0648\\u062f \\u0627\\u0644\\u0625\\u0646\\u0641\\u0627\\u0642 \\u0648\\u062a\\u0627\\u0631\\u064a\\u062e \\u0627\\u0646\\u062a\\u0647\\u0627\\u0621 \\u0627\\u0644\\u0635\\u0644\\u0627\\u062d\\u064a\\u0629 \\u0628\\u0646\\u0627\\u0621\\u064b \\u0639\\u0644\\u0649 \\u062a\\u0641\\u0636\\u064a\\u0644\\u0627\\u062a\\u0643\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0645\\u062d \\u0644\\u0643 \\u0628\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0625\\u0646\\u0641\\u0627\\u0642\\u0643 \\u0628\\u0641\\u0639\\u0627\\u0644\\u064a\\u0629.\"},\"es\":{\"question\":\"\\u00bfPuedo poner l\\u00edmites a mi tarjeta virtual?\",\"answer\":\"S\\u00ed, al generar tu tarjeta virtual, puedes establecer l\\u00edmites de gasto y una fecha de vencimiento seg\\u00fan tus preferencias, permiti\\u00e9ndote administrar tus gastos de manera efectiva.\"},\"fr\":{\"question\":\"\\u00bfPuedo poner l\\u00edmites a mi tarjeta virtual?\",\"answer\":\"Oui, lors de la g\\u00e9n\\u00e9ration de votre carte virtuelle, vous pouvez d\\u00e9finir des limites de d\\u00e9penses et une date d\'expiration en fonction de vos pr\\u00e9f\\u00e9rences, vous permettant ainsi de g\\u00e9rer efficacement vos d\\u00e9penses.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u092a\\u0930 \\u0938\\u0940\\u092e\\u093e \\u0928\\u093f\\u0930\\u094d\\u0927\\u093e\\u0930\\u093f\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0939\\u093e\\u0902, \\u0905\\u092a\\u0928\\u093e \\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u092c\\u0928\\u093e\\u0924\\u0947 \\u0938\\u092e\\u092f, \\u0906\\u092a \\u0905\\u092a\\u0928\\u0940 \\u092a\\u094d\\u0930\\u093e\\u0925\\u092e\\u093f\\u0915\\u0924\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0916\\u0930\\u094d\\u091a \\u0938\\u0940\\u092e\\u093e \\u0914\\u0930 \\u0938\\u092e\\u093e\\u092a\\u094d\\u0924\\u093f \\u0924\\u093f\\u0925\\u093f \\u0928\\u093f\\u0930\\u094d\\u0927\\u093e\\u0930\\u093f\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0906\\u092a \\u0905\\u092a\\u0928\\u0947 \\u0916\\u0930\\u094d\\u091a \\u0915\\u094b \\u092a\\u094d\\u0930\\u092d\\u093e\\u0935\\u0940 \\u0922\\u0902\\u0917 \\u0938\\u0947 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"67249e0e36550\"}}}', 1, 1, '2024-11-01 15:22:40', '2024-11-07 09:57:24');
INSERT INTO `frontend_header_section_faqs` VALUES (15, 15, 'personal', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About QRPay Pro Gift Cards\",\"sub_heading\":\"Find answers to your questions regarding gift card purchases and usage.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0628\\u0637\\u0627\\u0642\\u0627\\u062a \\u0647\\u062f\\u0627\\u064a\\u0627 QRPay Pro\",\"sub_heading\":\"\\u0627\\u0628\\u062d\\u062b \\u0639\\u0646 \\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0644\\u0623\\u0633\\u0626\\u0644\\u062a\\u0643 \\u0627\\u0644\\u0645\\u062a\\u0639\\u0644\\u0642\\u0629 \\u0628\\u0634\\u0631\\u0627\\u0621 \\u0628\\u0637\\u0627\\u0642\\u0627\\u062a \\u0627\\u0644\\u0647\\u062f\\u0627\\u064a\\u0627 \\u0648\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645\\u0647\\u0627.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre las tarjetas regalo QRPay Pro\",\"sub_heading\":\"Encuentre respuestas a sus preguntas sobre la compra y el uso de tarjetas de regalo.\"},\"fr\":{\"heading\":\"Preguntas frecuentes sobre las tarjetas regalo QRPay Pro\",\"sub_heading\":\"Trouvez les r\\u00e9ponses \\u00e0 vos questions concernant les achats et l\'utilisation des cartes-cadeaux.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0917\\u093f\\u092b\\u093c\\u094d\\u091f \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"\\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0938\\u0947 \\u0916\\u0930\\u0940\\u0926\\u093e\\u0930\\u0940 \\u0914\\u0930 \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0947 \\u0938\\u0902\\u092c\\u0902\\u0927 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u0916\\u094b\\u091c\\u0947\\u0902\\u0964\"}},\"items\":{\"67249ebe7ac0b\":{\"language\":{\"en\":{\"question\":\"How do I purchase a gift card through QRPay Pro?\",\"answer\":\"To purchase a gift card, navigate to the Gift Card section in your QRPay Pro app, select the gift card you wish to buy, enter the recipient\\u2019s details, and make the payment.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0634\\u0631\\u0627\\u0621 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0647\\u062f\\u0627\\u064a\\u0627 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 QRPay Pro\\u061f\",\"answer\":\"\\u0644\\u0634\\u0631\\u0627\\u0621 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0647\\u062f\\u0627\\u064a\\u0627\\u060c \\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u0642\\u0633\\u0645 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0647\\u062f\\u0627\\u064a\\u0627 \\u0641\\u064a \\u062a\\u0637\\u0628\\u064a\\u0642 QRPay Pro\\u060c \\u0648\\u062d\\u062f\\u062f \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0647\\u062f\\u0627\\u064a\\u0627 \\u0627\\u0644\\u062a\\u064a \\u062a\\u0631\\u063a\\u0628 \\u0641\\u064a \\u0634\\u0631\\u0627\\u0626\\u0647\\u0627\\u060c \\u0648\\u0623\\u062f\\u062e\\u0644 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645\\u060c \\u0648\\u0642\\u0645 \\u0628\\u0627\\u0644\\u062f\\u0641\\u0639.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo compro una tarjeta de regalo a trav\\u00e9s de QRPay Pro?\",\"answer\":\"Para comprar una tarjeta de regalo, navegue hasta la secci\\u00f3n Tarjeta de regalo en su aplicaci\\u00f3n QRPay Pro, seleccione la tarjeta de regalo que desea comprar, ingrese los detalles del destinatario y realice el pago.\"},\"fr\":{\"question\":\"\\u00bfC\\u00f3mo compro una tarjeta de regalo a trav\\u00e9s de QRPay Pro?\",\"answer\":\"Pour acheter une carte-cadeau, acc\\u00e9dez \\u00e0 la section Carte-cadeau de votre application QRPay Pro, s\\u00e9lectionnez la carte-cadeau que vous souhaitez acheter, saisissez les coordonn\\u00e9es du destinataire et effectuez le paiement.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0915\\u0948\\u0938\\u0947 \\u0916\\u0930\\u0940\\u0926\\u0942\\u0902?\",\"answer\":\"\\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0916\\u0930\\u0940\\u0926\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0910\\u092a \\u092e\\u0947\\u0902 \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0905\\u0928\\u0941\\u092d\\u093e\\u0917 \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0901, \\u0935\\u0939 \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u091a\\u0941\\u0928\\u0947\\u0902 \\u091c\\u093f\\u0938\\u0947 \\u0906\\u092a \\u0916\\u0930\\u0940\\u0926\\u0928\\u093e \\u091a\\u093e\\u0939\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u093e \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"67249ebe7ac0b\"},\"67249ec84ff4e\":{\"language\":{\"en\":{\"question\":\"Can I customize the amount on the gift card?\",\"answer\":\"Yes, when purchasing a gift card, you can choose the amount to load onto the card, allowing for personalized gifting options.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u062a\\u062e\\u0635\\u064a\\u0635 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0645\\u0648\\u062c\\u0648\\u062f \\u0639\\u0644\\u0649 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0647\\u062f\\u0627\\u064a\\u0627\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u0639\\u0646\\u062f \\u0634\\u0631\\u0627\\u0621 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0647\\u062f\\u0627\\u064a\\u0627\\u060c \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0627\\u062e\\u062a\\u064a\\u0627\\u0631 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0630\\u064a \\u062a\\u0631\\u064a\\u062f \\u062a\\u062d\\u0645\\u064a\\u0644\\u0647 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0628\\u0637\\u0627\\u0642\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0645\\u062d \\u0628\\u062e\\u064a\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0647\\u062f\\u0627\\u064a\\u0627 \\u0627\\u0644\\u0634\\u062e\\u0635\\u064a\\u0629.\"},\"es\":{\"question\":\"\\u00bfPuedo personalizar el importe de la tarjeta regalo?\",\"answer\":\"S\\u00ed, al comprar una tarjeta de regalo, puede elegir el monto a cargar en la tarjeta, lo que permite opciones de obsequio personalizadas.\"},\"fr\":{\"question\":\"\\u00bfPuedo personalizar el importe de la tarjeta regalo?\",\"answer\":\"Oui, lors de l\'achat d\'une carte-cadeau, vous pouvez choisir le montant \\u00e0 charger sur la carte, permettant ainsi des options de cadeaux personnalis\\u00e9es.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u092a\\u0930 \\u0930\\u093e\\u0936\\u093f \\u0905\\u0928\\u0941\\u0915\\u0942\\u0932\\u093f\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0939\\u093e\\u0902, \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0916\\u0930\\u0940\\u0926\\u0924\\u0947 \\u0938\\u092e\\u092f, \\u0906\\u092a \\u0915\\u093e\\u0930\\u094d\\u0921 \\u092a\\u0930 \\u0932\\u094b\\u0921 \\u0915\\u0940 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0940 \\u0930\\u093e\\u0936\\u093f \\u091a\\u0941\\u0928 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0935\\u0948\\u092f\\u0915\\u094d\\u0924\\u093f\\u0915\\u0943\\u0924 \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0926\\u0947\\u0928\\u0947 \\u0915\\u0947 \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a \\u0915\\u0940 \\u0905\\u0928\\u0941\\u092e\\u0924\\u093f \\u092e\\u093f\\u0932\\u0924\\u0940 \\u0939\\u0948\\u0964\"}},\"id\":\"67249ec84ff4e\"},\"67249ed114449\":{\"language\":{\"en\":{\"question\":\"How will the recipient receive the gift card?\",\"answer\":\"The recipient will receive their digital gift card via email or SMS, depending on the details you provided during the purchase.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u0633\\u064a\\u062d\\u0635\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645 \\u0639\\u0644\\u0649 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0647\\u062f\\u064a\\u0629\\u061f\",\"answer\":\"\\u0633\\u064a\\u062a\\u0644\\u0642\\u0649 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0647\\u062f\\u0627\\u064a\\u0627 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a\\u0629 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0647 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0628\\u0631\\u064a\\u062f \\u0627\\u0644\\u0625\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a \\u0623\\u0648 \\u0627\\u0644\\u0631\\u0633\\u0627\\u0626\\u0644 \\u0627\\u0644\\u0646\\u0635\\u064a\\u0629 \\u0627\\u0644\\u0642\\u0635\\u064a\\u0631\\u0629\\u060c \\u0627\\u0639\\u062a\\u0645\\u0627\\u062f\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u062a\\u064a \\u0642\\u062f\\u0645\\u062a\\u0647\\u0627 \\u0623\\u062b\\u0646\\u0627\\u0621 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0634\\u0631\\u0627\\u0621.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo recibir\\u00e1 el destinatario la tarjeta regalo?\",\"answer\":\"El destinatario recibir\\u00e1 su tarjeta regalo digital por correo electr\\u00f3nico o SMS, dependiendo de los datos que hayas proporcionado durante la compra.\"},\"fr\":{\"question\":\"\\u00bfC\\u00f3mo recibir\\u00e1 el destinatario la tarjeta regalo?\",\"answer\":\"Le destinataire recevra sa carte cadeau num\\u00e9rique par e-mail ou SMS, en fonction des informations que vous avez fournies lors de l\'achat.\"},\"hi\":{\"question\":\"\\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u094b \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0915\\u0948\\u0938\\u0947 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0939\\u094b\\u0917\\u093e?\",\"answer\":\"\\u0916\\u0930\\u0940\\u0926\\u093e\\u0930\\u0940 \\u0915\\u0947 \\u0926\\u094c\\u0930\\u093e\\u0928 \\u0906\\u092a\\u0915\\u0947 \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u093f\\u090f \\u0917\\u090f \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930, \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u094b \\u0905\\u092a\\u0928\\u093e \\u0921\\u093f\\u091c\\u093f\\u091f\\u0932 \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0908\\u092e\\u0947\\u0932 \\u092f\\u093e \\u090f\\u0938\\u090f\\u092e\\u090f\\u0938 \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0939\\u094b\\u0917\\u093e\\u0964\"}},\"id\":\"67249ed114449\"},\"67249ed819948\":{\"language\":{\"en\":{\"question\":\"Can gift cards be used internationally?\",\"answer\":\"Gift cards can typically be used at merchants that accept them; however, it\\u2019s important to check the specific terms and conditions of the gift card provider to ensure it can be used internationally.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646 \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0628\\u0637\\u0627\\u0642\\u0627\\u062a \\u0627\\u0644\\u0647\\u062f\\u0627\\u064a\\u0627 \\u062f\\u0648\\u0644\\u064a\\u064b\\u0627\\u061f\",\"answer\":\"\\u064a\\u0645\\u0643\\u0646 \\u0639\\u0627\\u062f\\u0629\\u064b \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0628\\u0637\\u0627\\u0642\\u0627\\u062a \\u0627\\u0644\\u0647\\u062f\\u0627\\u064a\\u0627 \\u0644\\u062f\\u0649 \\u0627\\u0644\\u062a\\u062c\\u0627\\u0631 \\u0627\\u0644\\u0630\\u064a\\u0646 \\u064a\\u0642\\u0628\\u0644\\u0648\\u0646\\u0647\\u0627\\u061b \\u0648\\u0645\\u0639 \\u0630\\u0644\\u0643\\u060c \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0647\\u0645 \\u0627\\u0644\\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0627\\u0644\\u0634\\u0631\\u0648\\u0637 \\u0648\\u0627\\u0644\\u0623\\u062d\\u0643\\u0627\\u0645 \\u0627\\u0644\\u0645\\u062d\\u062f\\u062f\\u0629 \\u0644\\u0645\\u0648\\u0641\\u0631 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0647\\u062f\\u0627\\u064a\\u0627 \\u0644\\u0644\\u062a\\u0623\\u0643\\u062f \\u0645\\u0646 \\u0625\\u0645\\u0643\\u0627\\u0646\\u064a\\u0629 \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645\\u0647\\u0627 \\u062f\\u0648\\u0644\\u064a\\u064b\\u0627.\"},\"es\":{\"question\":\"\\u00bfSe pueden utilizar las tarjetas de regalo a nivel internacional?\",\"answer\":\"Las tarjetas de regalo normalmente se pueden utilizar en comercios que las acepten; sin embargo, es importante verificar los t\\u00e9rminos y condiciones espec\\u00edficos del proveedor de la tarjeta de regalo para asegurarse de que pueda usarse internacionalmente.\"},\"fr\":{\"question\":\"\\u00bfSe pueden utilizar las tarjetas de regalo a nivel internacional?\",\"answer\":\"Les cartes-cadeaux peuvent g\\u00e9n\\u00e9ralement \\u00eatre utilis\\u00e9es chez les commer\\u00e7ants qui les acceptent\\u00a0; cependant, il est important de v\\u00e9rifier les conditions g\\u00e9n\\u00e9rales sp\\u00e9cifiques du fournisseur de la carte-cadeau pour s\\u2019assurer qu\\u2019elle peut \\u00eatre utilis\\u00e9e \\u00e0 l\\u2019international.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0905\\u0902\\u0924\\u0930\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0938\\u094d\\u0924\\u0930 \\u092a\\u0930 \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948?\",\"answer\":\"\\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0906\\u092e \\u0924\\u094c\\u0930 \\u092a\\u0930 \\u0909\\u0928 \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u093f\\u092f\\u094b\\u0902 \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948 \\u091c\\u094b \\u0909\\u0928\\u094d\\u0939\\u0947\\u0902 \\u0938\\u094d\\u0935\\u0940\\u0915\\u093e\\u0930 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902; \\u0939\\u093e\\u0932\\u093e\\u0901\\u0915\\u093f, \\u092f\\u0939 \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0924\\u093e \\u0915\\u0947 \\u0935\\u093f\\u0936\\u093f\\u0937\\u094d\\u091f \\u0928\\u093f\\u092f\\u092e\\u094b\\u0902 \\u0914\\u0930 \\u0936\\u0930\\u094d\\u0924\\u094b\\u0902 \\u0915\\u0940 \\u091c\\u093e\\u0901\\u091a \\u0915\\u0930\\u0928\\u093e \\u092e\\u0939\\u0924\\u094d\\u0935\\u092a\\u0942\\u0930\\u094d\\u0923 \\u0939\\u0948 \\u0915\\u093f \\u0907\\u0938\\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0905\\u0902\\u0924\\u0930\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0938\\u094d\\u0924\\u0930 \\u092a\\u0930 \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964\"}},\"id\":\"67249ed819948\"}}}', 1, 1, '2024-11-01 15:26:11', '2024-11-07 10:02:44');
INSERT INTO `frontend_header_section_faqs` VALUES (16, 16, 'personal', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About QRPay Pro Bill Pay\",\"sub_heading\":\"Get answers to your questions about managing and paying your bills through QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 QRPay Pro Bill Pay\",\"sub_heading\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0644\\u0623\\u0633\\u0626\\u0644\\u062a\\u0643 \\u062d\\u0648\\u0644 \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0648\\u062f\\u0641\\u0639 \\u0641\\u0648\\u0627\\u062a\\u064a\\u0631\\u0643 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 QRPay Pro.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre el pago de facturas QRPay Pro\",\"sub_heading\":\"Obtenga respuestas a sus preguntas sobre c\\u00f3mo administrar y pagar sus facturas a trav\\u00e9s de QRPay Pro.\"},\"fr\":{\"heading\":\"Foire aux questions sur le paiement de factures QRPay Pro\",\"sub_heading\":\"Obtenez des r\\u00e9ponses \\u00e0 vos questions sur la gestion et le paiement de vos factures via QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092c\\u093f\\u0932 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u0905\\u092a\\u0928\\u0947 \\u092c\\u093f\\u0932\\u094b\\u0902 \\u0915\\u0947 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u0928 \\u0914\\u0930 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"67249f947409b\":{\"language\":{\"en\":{\"question\":\"How do I pay my bills using QRPay Pro?\",\"answer\":\"To pay your bills, go to the Bill Pay section in your QRPay Pro app, select the type of bill, enter the required details, and confirm your payment.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u062f\\u0641\\u0639 \\u0641\\u0648\\u0627\\u062a\\u064a\\u0631\\u064a \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\\u061f\",\"answer\":\"\\u0644\\u062f\\u0641\\u0639 \\u0641\\u0648\\u0627\\u062a\\u064a\\u0631\\u0643\\u060c \\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u0642\\u0633\\u0645 \\\"\\u062f\\u0641\\u0639 \\u0627\\u0644\\u0641\\u0648\\u0627\\u062a\\u064a\\u0631\\\" \\u0641\\u064a \\u062a\\u0637\\u0628\\u064a\\u0642 QRPay Pro\\u060c \\u0648\\u062d\\u062f\\u062f \\u0646\\u0648\\u0639 \\u0627\\u0644\\u0641\\u0627\\u062a\\u0648\\u0631\\u0629\\u060c \\u0648\\u0623\\u062f\\u062e\\u0644 \\u0627\\u0644\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628\\u0629\\u060c \\u0648\\u0623\\u0643\\u062f \\u0627\\u0644\\u062f\\u0641\\u0639.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo pago mis facturas usando QRPay Pro?\",\"answer\":\"Para pagar sus facturas, vaya a la secci\\u00f3n Pago de facturas en su aplicaci\\u00f3n QRPay Pro, seleccione el tipo de factura, ingrese los detalles requeridos y confirme su pago.\"},\"fr\":{\"question\":\"Comment payer mes factures avec QRPay Pro ?\",\"answer\":\"Pour payer vos factures, acc\\u00e9dez \\u00e0 la section Bill Pay de votre application QRPay Pro, s\\u00e9lectionnez le type de facture, saisissez les d\\u00e9tails requis et confirmez votre paiement.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay Pro \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u0905\\u092a\\u0928\\u0947 \\u092c\\u093f\\u0932\\u094b\\u0902 \\u0915\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0948\\u0938\\u0947 \\u0915\\u0930\\u0942\\u0901?\",\"answer\":\"\\u0905\\u092a\\u0928\\u0947 \\u092c\\u093f\\u0932\\u094b\\u0902 \\u0915\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0910\\u092a \\u092e\\u0947\\u0902 \\u092c\\u093f\\u0932 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0905\\u0928\\u0941\\u092d\\u093e\\u0917 \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0902, \\u092c\\u093f\\u0932 \\u0915\\u093e \\u092a\\u094d\\u0930\\u0915\\u093e\\u0930 \\u091a\\u0941\\u0928\\u0947\\u0902, \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915 \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u0905\\u092a\\u0928\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"67249f947409b\"},\"67249f9dc45ee\":{\"language\":{\"en\":{\"question\":\"What types of bills can I pay through QRPay Pro?\",\"answer\":\"You can pay a variety of bills, including utilities, internet, mobile services, and more. Check the available options in the app for specifics.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0647\\u064a \\u0623\\u0646\\u0648\\u0627\\u0639 \\u0627\\u0644\\u0641\\u0648\\u0627\\u062a\\u064a\\u0631 \\u0627\\u0644\\u062a\\u064a \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u062f\\u0641\\u0639\\u0647\\u0627 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 QRPay Pro\\u061f\",\"answer\":\"\\u064a\\u0645\\u0643\\u0646\\u0643 \\u062f\\u0641\\u0639 \\u0645\\u062c\\u0645\\u0648\\u0639\\u0629 \\u0645\\u062a\\u0646\\u0648\\u0639\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0641\\u0648\\u0627\\u062a\\u064a\\u0631\\u060c \\u0628\\u0645\\u0627 \\u0641\\u064a \\u0630\\u0644\\u0643 \\u0641\\u0648\\u0627\\u062a\\u064a\\u0631 \\u0627\\u0644\\u0645\\u0631\\u0627\\u0641\\u0642 \\u0648\\u0627\\u0644\\u0625\\u0646\\u062a\\u0631\\u0646\\u062a \\u0648\\u062e\\u062f\\u0645\\u0627\\u062a \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0648\\u0627\\u0644\\u0645\\u0632\\u064a\\u062f. \\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0627\\u0644\\u062e\\u064a\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0645\\u062a\\u0627\\u062d\\u0629 \\u0641\\u064a \\u0627\\u0644\\u062a\\u0637\\u0628\\u064a\\u0642 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 tipos de facturas puedo pagar a trav\\u00e9s de QRPay Pro?\",\"answer\":\"Puede pagar una variedad de facturas, incluidos servicios p\\u00fablicos, Internet, servicios m\\u00f3viles y m\\u00e1s. Consulte las opciones disponibles en la aplicaci\\u00f3n para conocer m\\u00e1s detalles.\"},\"fr\":{\"question\":\"Quels types de factures puis-je payer via QRPay Pro\\u00a0?\",\"answer\":\"Vous pouvez payer diverses factures, notamment les services publics, Internet, les services mobiles, etc. V\\u00e9rifiez les options disponibles dans l\'application pour plus de d\\u00e9tails.\"},\"hi\":{\"question\":\"QRPay Pro \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u092e\\u0948\\u0902 \\u0915\\u093f\\u0938 \\u092a\\u094d\\u0930\\u0915\\u093e\\u0930 \\u0915\\u0947 \\u092c\\u093f\\u0932\\u094b\\u0902 \\u0915\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0902?\",\"answer\":\"\\u0906\\u092a \\u0909\\u092a\\u092f\\u094b\\u0917\\u093f\\u0924\\u093e\\u0913\\u0902, \\u0907\\u0902\\u091f\\u0930\\u0928\\u0947\\u091f, \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u0938\\u0947\\u0935\\u093e\\u0913\\u0902 \\u0914\\u0930 \\u0905\\u0928\\u094d\\u092f \\u0938\\u0939\\u093f\\u0924 \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u092a\\u094d\\u0930\\u0915\\u093e\\u0930 \\u0915\\u0947 \\u092c\\u093f\\u0932\\u094b\\u0902 \\u0915\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0935\\u093f\\u0936\\u093f\\u0937\\u094d\\u091f\\u0924\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0910\\u092a \\u092e\\u0947\\u0902 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a\\u094b\\u0902 \\u0915\\u0940 \\u091c\\u093e\\u0901\\u091a \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"67249f9dc45ee\"},\"67249fa828e69\":{\"language\":{\"en\":{\"question\":\"Is there a limit on the amount I can pay for my bills?\",\"answer\":\"There may be transaction limits depending on your account type and settings. Please refer to the QRPay guidelines or your account information for specific limits.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u062d\\u062f \\u0644\\u0644\\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0630\\u064a \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u062f\\u0641\\u0639\\u0647 \\u0645\\u0642\\u0627\\u0628\\u0644 \\u0641\\u0648\\u0627\\u062a\\u064a\\u0631\\u064a\\u061f\",\"answer\":\"\\u0642\\u062f \\u062a\\u0643\\u0648\\u0646 \\u0647\\u0646\\u0627\\u0643 \\u062d\\u062f\\u0648\\u062f \\u0644\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0627\\u0639\\u062a\\u0645\\u0627\\u062f\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u0646\\u0648\\u0639 \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0648\\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a\\u0643. \\u064a\\u0631\\u062c\\u0649 \\u0627\\u0644\\u0631\\u062c\\u0648\\u0639 \\u0625\\u0644\\u0649 \\u0625\\u0631\\u0634\\u0627\\u062f\\u0627\\u062a QRPay \\u0623\\u0648 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0644\\u0645\\u0639\\u0631\\u0641\\u0629 \\u0627\\u0644\\u062d\\u062f\\u0648\\u062f \\u0627\\u0644\\u0645\\u062d\\u062f\\u062f\\u0629.\"},\"es\":{\"question\":\"\\u00bfExiste un l\\u00edmite en el monto que puedo pagar por mis facturas?\",\"answer\":\"Puede haber l\\u00edmites de transacciones seg\\u00fan el tipo y la configuraci\\u00f3n de su cuenta. Consulte las pautas de QRPay o la informaci\\u00f3n de su cuenta para conocer l\\u00edmites espec\\u00edficos.\"},\"fr\":{\"question\":\"Y a-t-il une limite au montant que je peux payer pour mes factures ?\",\"answer\":\"Il peut y avoir des limites de transactions en fonction de votre type de compte et de vos param\\u00e8tres. Veuillez vous r\\u00e9f\\u00e9rer aux directives QRPay ou aux informations de votre compte pour conna\\u00eetre les limites sp\\u00e9cifiques.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u092c\\u093f\\u0932\\u094b\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0940 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0940 \\u0930\\u093e\\u0936\\u093f \\u0915\\u0940 \\u0915\\u094b\\u0908 \\u0938\\u0940\\u092e\\u093e \\u0924\\u092f \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0906\\u092a\\u0915\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u0915\\u0947 \\u092a\\u094d\\u0930\\u0915\\u093e\\u0930 \\u0914\\u0930 \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917\\u094d\\u0938 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u0938\\u0940\\u092e\\u093e\\u090f\\u0901 \\u0939\\u094b \\u0938\\u0915\\u0924\\u0940 \\u0939\\u0948\\u0902\\u0964 \\u0915\\u0943\\u092a\\u092f\\u093e \\u0935\\u093f\\u0936\\u093f\\u0937\\u094d\\u091f \\u0938\\u0940\\u092e\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f QRPay \\u0926\\u093f\\u0936\\u093e\\u0928\\u093f\\u0930\\u094d\\u0926\\u0947\\u0936 \\u092f\\u093e \\u0905\\u092a\\u0928\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u0915\\u0940 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0926\\u0947\\u0916\\u0947\\u0902\\u0964\"}},\"id\":\"67249fa828e69\"},\"67249fb08d569\":{\"language\":{\"en\":{\"question\":\"How will I know if my bill payment was successful?\",\"answer\":\"Once your payment is processed, you will receive a notification confirming the transaction. You can also check your transaction history for details.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u0633\\u0623\\u0639\\u0631\\u0641 \\u0645\\u0627 \\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646 \\u062f\\u0641\\u0639 \\u0641\\u0627\\u062a\\u0648\\u0631\\u062a\\u064a \\u0646\\u0627\\u062c\\u062d\\u064b\\u0627\\u061f\",\"answer\":\"\\u0628\\u0645\\u062c\\u0631\\u062f \\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u062f\\u0641\\u0639\\u062a\\u0643\\u060c \\u0633\\u062a\\u062a\\u0644\\u0642\\u0649 \\u0625\\u0634\\u0639\\u0627\\u0631\\u064b\\u0627 \\u064a\\u0624\\u0643\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629. \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0623\\u064a\\u0636\\u064b\\u0627 \\u0627\\u0644\\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0633\\u062c\\u0644 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u0643 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo sabr\\u00e9 si el pago de mi factura fue exitoso?\",\"answer\":\"Una vez que se procese su pago, recibir\\u00e1 una notificaci\\u00f3n confirmando la transacci\\u00f3n. Tambi\\u00e9n puede consultar su historial de transacciones para obtener m\\u00e1s detalles.\"},\"fr\":{\"question\":\"Comment saurai-je si le paiement de ma facture a r\\u00e9ussi\\u00a0?\",\"answer\":\"Une fois votre paiement trait\\u00e9, vous recevrez une notification confirmant la transaction. Vous pouvez \\u00e9galement consulter l\'historique de vos transactions pour plus de d\\u00e9tails.\"},\"hi\":{\"question\":\"\\u092e\\u0941\\u091d\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u092a\\u0924\\u093e \\u091a\\u0932\\u0947\\u0917\\u093e \\u0915\\u093f \\u092e\\u0947\\u0930\\u093e \\u092c\\u093f\\u0932 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u092b\\u0932 \\u0930\\u0939\\u093e?\",\"answer\":\"\\u090f\\u0915 \\u092c\\u093e\\u0930 \\u0906\\u092a\\u0915\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u0902\\u0938\\u093e\\u0927\\u093f\\u0924 \\u0939\\u094b \\u091c\\u093e\\u0928\\u0947 \\u092a\\u0930, \\u0906\\u092a\\u0915\\u094b \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0940 \\u090f\\u0915 \\u0905\\u0927\\u093f\\u0938\\u0942\\u091a\\u0928\\u093e \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0939\\u094b\\u0917\\u0940\\u0964 \\u0906\\u092a \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u093e \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0907\\u0924\\u093f\\u0939\\u093e\\u0938 \\u092d\\u0940 \\u0926\\u0947\\u0916 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"67249fb08d569\"}}}', 1, 1, '2024-11-01 15:29:44', '2024-11-07 10:09:40');
INSERT INTO `frontend_header_section_faqs` VALUES (17, 17, 'personal', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About QRPay Pro Mobile Top-Up\",\"sub_heading\":\"Find answers to common questions regarding mobile top-ups with QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f QRPay Pro \\u0644\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644\",\"sub_heading\":\"\\u0627\\u0639\\u062b\\u0631 \\u0639\\u0644\\u0649 \\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0644\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0634\\u0627\\u0626\\u0639\\u0629 \\u0627\\u0644\\u0645\\u062a\\u0639\\u0644\\u0642\\u0629 \\u0628\\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre la recarga m\\u00f3vil QRPay Pro\",\"sub_heading\":\"Encuentre respuestas a preguntas comunes sobre recargas m\\u00f3viles con QRPay Pro.\"},\"fr\":{\"heading\":\"Foire aux questions sur la recharge mobile QRPay Pro\",\"sub_heading\":\"Trouvez des r\\u00e9ponses aux questions courantes concernant les recharges mobiles avec QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0938\\u0947 \\u0938\\u0902\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0938\\u093e\\u092e\\u093e\\u0928\\u094d\\u092f \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u0916\\u094b\\u091c\\u0947\\u0902\\u0964\"}},\"items\":{\"6724a058ae1cd\":{\"language\":{\"en\":{\"question\":\"How do I top up my mobile phone using QRPay Pro?\",\"answer\":\"To top up your mobile phone, navigate to the Mobile Top-Up section in your QRPay Pro app, select your carrier, enter the phone number, choose the amount, and confirm the transaction.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u0623\\u0642\\u0648\\u0645 \\u0628\\u062a\\u0639\\u0628\\u0626\\u0629 \\u0647\\u0627\\u062a\\u0641\\u064a \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\\u061f\",\"answer\":\"\\u0644\\u062a\\u0639\\u0628\\u0626\\u0629 \\u0647\\u0627\\u062a\\u0641\\u0643 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644\\u060c \\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u0642\\u0633\\u0645 \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0641\\u064a \\u062a\\u0637\\u0628\\u064a\\u0642 QRPay Pro\\u060c \\u0648\\u062d\\u062f\\u062f \\u0645\\u0634\\u063a\\u0644 \\u0634\\u0628\\u0643\\u0629 \\u0627\\u0644\\u062c\\u0648\\u0627\\u0644\\u060c \\u0648\\u0623\\u062f\\u062e\\u0644 \\u0631\\u0642\\u0645 \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641\\u060c \\u0648\\u0627\\u062e\\u062a\\u0631 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a\\u060c \\u0648\\u0623\\u0643\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo recargo mi tel\\u00e9fono m\\u00f3vil usando QRPay Pro?\",\"answer\":\"Para recargar su tel\\u00e9fono m\\u00f3vil, navegue hasta la secci\\u00f3n Recarga m\\u00f3vil en su aplicaci\\u00f3n QRPay Pro, seleccione su operador, ingrese el n\\u00famero de tel\\u00e9fono, elija el monto y confirme la transacci\\u00f3n.\"},\"fr\":{\"question\":\"Comment recharger mon t\\u00e9l\\u00e9phone mobile avec QRPay Pro\\u00a0?\",\"answer\":\"Pour recharger votre t\\u00e9l\\u00e9phone mobile, acc\\u00e9dez \\u00e0 la section Recharge mobile de votre application QRPay Pro, s\\u00e9lectionnez votre op\\u00e9rateur, saisissez le num\\u00e9ro de t\\u00e9l\\u00e9phone, choisissez le montant et confirmez la transaction.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay Pro \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u0905\\u092a\\u0928\\u0947 \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u092b\\u093c\\u094b\\u0928 \\u0915\\u093e \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0915\\u0948\\u0938\\u0947 \\u0915\\u0930\\u0942\\u0901?\",\"answer\":\"\\u0905\\u092a\\u0928\\u0947 \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u092b\\u093c\\u094b\\u0928 \\u0915\\u094b \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0910\\u092a \\u092e\\u0947\\u0902 \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0905\\u0928\\u0941\\u092d\\u093e\\u0917 \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0901, \\u0905\\u092a\\u0928\\u093e \\u0935\\u093e\\u0939\\u0915 \\u091a\\u0941\\u0928\\u0947\\u0902, \\u092b\\u093c\\u094b\\u0928 \\u0928\\u0902\\u092c\\u0930 \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902, \\u0930\\u093e\\u0936\\u093f \\u091a\\u0941\\u0928\\u0947\\u0902 \\u0914\\u0930 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724a058ae1cd\"},\"6724a06157016\":{\"language\":{\"en\":{\"question\":\"Can I top up a mobile number that belongs to someone else?\",\"answer\":\"Yes, you can recharge the mobile account of another person by entering their phone number in the Mobile Top-Up section.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0642\\u0645 \\u062c\\u0648\\u0627\\u0644 \\u064a\\u062e\\u0635 \\u0634\\u062e\\u0635 \\u0622\\u062e\\u0631\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0625\\u0639\\u0627\\u062f\\u0629 \\u0634\\u062d\\u0646 \\u062d\\u0633\\u0627\\u0628 \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0644\\u0634\\u062e\\u0635 \\u0622\\u062e\\u0631 \\u0639\\u0646 \\u0637\\u0631\\u064a\\u0642 \\u0625\\u062f\\u062e\\u0627\\u0644 \\u0631\\u0642\\u0645 \\u0647\\u0627\\u062a\\u0641\\u0647 \\u0641\\u064a \\u0642\\u0633\\u0645 \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644.\"},\"es\":{\"question\":\"\\u00bfPuedo recargar un n\\u00famero de m\\u00f3vil que pertenece a otra persona?\",\"answer\":\"S\\u00ed, puedes recargar la cuenta m\\u00f3vil de otra persona ingresando su n\\u00famero de tel\\u00e9fono en la secci\\u00f3n Recarga M\\u00f3vil.\"},\"fr\":{\"question\":\"Puis-je recharger un num\\u00e9ro de mobile appartenant \\u00e0 quelqu\'un d\'autre ?\",\"answer\":\"Oui, vous pouvez recharger le compte mobile d\'une autre personne en saisissant son num\\u00e9ro de t\\u00e9l\\u00e9phone dans la section Recharge Mobile.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u0909\\u0938 \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u0928\\u0902\\u092c\\u0930 \\u0915\\u094b \\u091f\\u0949\\u092a \\u0905\\u092a \\u0915\\u0930\\u093e \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0902 \\u091c\\u094b \\u0915\\u093f\\u0938\\u0940 \\u0914\\u0930 \\u0915\\u093e \\u0939\\u0948?\",\"answer\":\"\\u0939\\u093e\\u0902, \\u0906\\u092a \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0905\\u0928\\u0941\\u092d\\u093e\\u0917 \\u092e\\u0947\\u0902 \\u0915\\u093f\\u0938\\u0940 \\u0905\\u0928\\u094d\\u092f \\u0935\\u094d\\u092f\\u0915\\u094d\\u0924\\u093f \\u0915\\u093e \\u092b\\u093c\\u094b\\u0928 \\u0928\\u0902\\u092c\\u0930 \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0915\\u0947 \\u0909\\u0938\\u0915\\u0947 \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u0916\\u093e\\u0924\\u0947 \\u0915\\u094b \\u0930\\u093f\\u091a\\u093e\\u0930\\u094d\\u091c \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724a06157016\"},\"6724a06c7de3a\":{\"language\":{\"en\":{\"question\":\"Are there any fees associated with mobile top-ups?\",\"answer\":\"Mobile top-ups may incur a small service fee, depending on your mobile carrier and the amount being topped up. Please check the details in the app before confirming your transaction.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644\\u061f\",\"answer\":\"\\u0642\\u062f \\u062a\\u0624\\u062f\\u064a \\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u0641\\u0631\\u0636 \\u0631\\u0633\\u0648\\u0645 \\u062e\\u062f\\u0645\\u0629 \\u0628\\u0633\\u064a\\u0637\\u0629\\u060c \\u0627\\u0639\\u062a\\u0645\\u0627\\u062f\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u0645\\u0634\\u063a\\u0644 \\u0634\\u0628\\u0643\\u0629 \\u0627\\u0644\\u062c\\u0648\\u0627\\u0644 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u0648\\u0627\\u0644\\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0630\\u064a \\u062a\\u062a\\u0645 \\u062a\\u0639\\u0628\\u0626\\u062a\\u0647. \\u064a\\u0631\\u062c\\u0649 \\u0627\\u0644\\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0627\\u0644\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0641\\u064a \\u0627\\u0644\\u062a\\u0637\\u0628\\u064a\\u0642 \\u0642\\u0628\\u0644 \\u062a\\u0623\\u0643\\u064a\\u062f \\u0645\\u0639\\u0627\\u0645\\u0644\\u062a\\u0643.\"},\"es\":{\"question\":\"\\u00bfHay alguna tarifa asociada con las recargas m\\u00f3viles?\",\"answer\":\"Las recargas m\\u00f3viles pueden generar una peque\\u00f1a tarifa de servicio, dependiendo de su operador de telefon\\u00eda m\\u00f3vil y del monto que se recargue. Verifique los detalles en la aplicaci\\u00f3n antes de confirmar su transacci\\u00f3n.\"},\"fr\":{\"question\":\"Y a-t-il des frais associ\\u00e9s aux recharges mobiles ?\",\"answer\":\"Les recharges mobiles peuvent entra\\u00eener des frais de service minimes, en fonction de votre op\\u00e9rateur mobile et du montant recharg\\u00e9. Veuillez v\\u00e9rifier les d\\u00e9tails dans l\'application avant de confirmer votre transaction.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0938\\u0947 \\u091c\\u0941\\u0921\\u093c\\u0940 \\u0915\\u094b\\u0908 \\u092b\\u0940\\u0938 \\u0939\\u0948?\",\"answer\":\"\\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u091f\\u0949\\u092a-\\u0905\\u092a \\u092a\\u0930 \\u090f\\u0915 \\u091b\\u094b\\u091f\\u093e \\u0938\\u093e \\u0938\\u0947\\u0935\\u093e \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0932\\u0917 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948, \\u091c\\u094b \\u0906\\u092a\\u0915\\u0947 \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u0935\\u093e\\u0939\\u0915 \\u0914\\u0930 \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0915\\u0940 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0940 \\u0930\\u093e\\u0936\\u093f \\u092a\\u0930 \\u0928\\u093f\\u0930\\u094d\\u092d\\u0930 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0915\\u0943\\u092a\\u092f\\u093e \\u0905\\u092a\\u0928\\u0947 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u0910\\u092a \\u092e\\u0947\\u0902 \\u0935\\u093f\\u0935\\u0930\\u0923 \\u091c\\u093e\\u0902\\u091a\\u0947\\u0902\\u0964\"}},\"id\":\"6724a06c7de3a\"},\"6724a0758e02b\":{\"language\":{\"en\":{\"question\":\"How will I know if my mobile top-up was successful?\",\"answer\":\"You will receive a confirmation notification once your mobile top-up is processed successfully. You can also check your transaction history for details.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u0623\\u0639\\u0631\\u0641 \\u0645\\u0627 \\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646\\u062a \\u0639\\u0645\\u0644\\u064a\\u0629 \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0647\\u0627\\u062a\\u0641\\u064a \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0646\\u0627\\u062c\\u062d\\u0629\\u061f\",\"answer\":\"\\u0633\\u062a\\u062a\\u0644\\u0642\\u0649 \\u0625\\u0634\\u0639\\u0627\\u0631 \\u062a\\u0623\\u0643\\u064a\\u062f \\u0628\\u0645\\u062c\\u0631\\u062f \\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0647\\u0627\\u062a\\u0641\\u0643 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0628\\u0646\\u062c\\u0627\\u062d. \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0623\\u064a\\u0636\\u064b\\u0627 \\u0627\\u0644\\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0633\\u062c\\u0644 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u0643 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo sabr\\u00e9 si mi recarga m\\u00f3vil fue exitosa?\",\"answer\":\"Recibir\\u00e1s una notificaci\\u00f3n de confirmaci\\u00f3n una vez que tu recarga m\\u00f3vil se procese con \\u00e9xito. Tambi\\u00e9n puede consultar su historial de transacciones para obtener m\\u00e1s detalles.\"},\"fr\":{\"question\":\"Comment saurai-je si ma recharge mobile a r\\u00e9ussi ?\",\"answer\":\"Vous recevrez une notification de confirmation une fois que votre recharge mobile aura \\u00e9t\\u00e9 trait\\u00e9e avec succ\\u00e8s. Vous pouvez \\u00e9galement consulter l\'historique de vos transactions pour plus de d\\u00e9tails.\"},\"hi\":{\"question\":\"\\u092e\\u0941\\u091d\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u092a\\u0924\\u093e \\u091a\\u0932\\u0947\\u0917\\u093e \\u0915\\u093f \\u092e\\u0947\\u0930\\u093e \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0938\\u092b\\u0932 \\u0930\\u0939\\u093e?\",\"answer\":\"\\u090f\\u0915 \\u092c\\u093e\\u0930 \\u0906\\u092a\\u0915\\u093e \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0938\\u092b\\u0932\\u0924\\u093e\\u092a\\u0942\\u0930\\u094d\\u0935\\u0915 \\u0938\\u0902\\u0938\\u093e\\u0927\\u093f\\u0924 \\u0939\\u094b \\u091c\\u093e\\u0928\\u0947 \\u092a\\u0930 \\u0906\\u092a\\u0915\\u094b \\u090f\\u0915 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f\\u0915\\u0930\\u0923 \\u0938\\u0942\\u091a\\u0928\\u093e \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0939\\u094b\\u0917\\u0940\\u0964 \\u0906\\u092a \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u093e \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0907\\u0924\\u093f\\u0939\\u093e\\u0938 \\u092d\\u0940 \\u0926\\u0947\\u0916 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724a0758e02b\"}}}', 1, 1, '2024-11-01 15:33:01', '2024-11-07 10:29:30');
INSERT INTO `frontend_header_section_faqs` VALUES (18, 18, 'business', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About Receiving Payments with QRPay Pro\",\"sub_heading\":\"Learn more about using QRPay Pro\\u2019s QR Code feature to accept payments easily and securely.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\",\"sub_heading\":\"\\u062a\\u0639\\u0631\\u0641 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0632\\u064a\\u062f \\u062d\\u0648\\u0644 \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0645\\u064a\\u0632\\u0629 QR Code \\u0641\\u064a QRPay Pro \\u0644\\u0642\\u0628\\u0648\\u0644 \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0648\\u0623\\u0645\\u0627\\u0646.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre la recepci\\u00f3n de pagos con QRPay Pro\",\"sub_heading\":\"Obtenga m\\u00e1s informaci\\u00f3n sobre el uso de la funci\\u00f3n C\\u00f3digo QR de QRPay Pro para aceptar pagos de forma f\\u00e1cil y segura.\"},\"fr\":{\"heading\":\"Questions fr\\u00e9quemment pos\\u00e9es sur la r\\u00e9ception de paiements avec QRPay Pro\",\"sub_heading\":\"Apprenez-en davantage sur l\\u2019utilisation de la fonctionnalit\\u00e9 QR Code de QRPay Pro pour accepter les paiements facilement et en toute s\\u00e9curit\\u00e9.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"\\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u094d\\u0935\\u0940\\u0915\\u093e\\u0930 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f QRPay Pro \\u0915\\u0947 QR \\u0915\\u094b\\u0921 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0914\\u0930 \\u091c\\u093e\\u0928\\u0947\\u0902\\u0964\"}},\"items\":{\"6724b71841d76\":{\"language\":{\"en\":{\"question\":\"Do I need to create a new QR Code for each transaction?\",\"answer\":\"No, QRPay Pro provides each merchant account with a unique, permanent QR Code upon registration. Use this QR Code repeatedly to accept payments without generating a new code each time.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0623\\u062d\\u062a\\u0627\\u062c \\u0625\\u0644\\u0649 \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u0645\\u0632 QR \\u062c\\u062f\\u064a\\u062f \\u0644\\u0643\\u0644 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0629\\u061f\",\"answer\":\"\\u0644\\u0627\\u060c \\u064a\\u0648\\u0641\\u0631 QRPay Pro \\u0644\\u0643\\u0644 \\u062d\\u0633\\u0627\\u0628 \\u062a\\u0627\\u062c\\u0631 \\u0631\\u0645\\u0632 QR \\u0641\\u0631\\u064a\\u062f \\u0648\\u062f\\u0627\\u0626\\u0645 \\u0639\\u0646\\u062f \\u0627\\u0644\\u062a\\u0633\\u062c\\u064a\\u0644. \\u0627\\u0633\\u062a\\u062e\\u062f\\u0645 \\u0631\\u0645\\u0632 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639\\u0629 \\u0647\\u0630\\u0627 \\u0628\\u0634\\u0643\\u0644 \\u0645\\u062a\\u0643\\u0631\\u0631 \\u0644\\u0642\\u0628\\u0648\\u0644 \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u062f\\u0648\\u0646 \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u0645\\u0632 \\u062c\\u062f\\u064a\\u062f \\u0641\\u064a \\u0643\\u0644 \\u0645\\u0631\\u0629.\"},\"es\":{\"question\":\"\\u00bfNecesito crear un nuevo c\\u00f3digo QR para cada transacci\\u00f3n?\",\"answer\":\"No, QRPay Pro proporciona a cada cuenta de comerciante un c\\u00f3digo QR \\u00fanico y permanente al registrarse. Utilice este c\\u00f3digo QR repetidamente para aceptar pagos sin generar un c\\u00f3digo nuevo cada vez.\"},\"fr\":{\"question\":\"Dois-je cr\\u00e9er un nouveau QR Code pour chaque transaction ?\",\"answer\":\"Non, QRPay Pro fournit \\u00e0 chaque compte marchand un code QR unique et permanent lors de l\'inscription. Utilisez ce QR Code \\u00e0 plusieurs reprises pour accepter des paiements sans g\\u00e9n\\u00e9rer de nouveau code \\u00e0 chaque fois.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0941\\u091d\\u0947 \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u090f\\u0915 \\u0928\\u092f\\u093e \\u0915\\u094d\\u092f\\u0942\\u0906\\u0930 \\u0915\\u094b\\u0921 \\u092c\\u0928\\u093e\\u0928\\u0947 \\u0915\\u0940 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915\\u0924\\u093e \\u0939\\u0948?\",\"answer\":\"\\u0928\\u0939\\u0940\\u0902, \\u0915\\u094d\\u092f\\u0942\\u0906\\u0930\\u092a\\u0947 \\u092a\\u094d\\u0930\\u094b \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u0940 \\u0916\\u093e\\u0924\\u0947 \\u0915\\u094b \\u092a\\u0902\\u091c\\u0940\\u0915\\u0930\\u0923 \\u092a\\u0930 \\u090f\\u0915 \\u0905\\u0926\\u094d\\u0935\\u093f\\u0924\\u0940\\u092f, \\u0938\\u094d\\u0925\\u093e\\u092f\\u0940 \\u0915\\u094d\\u092f\\u0942\\u0906\\u0930 \\u0915\\u094b\\u0921 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0939\\u0930 \\u092c\\u093e\\u0930 \\u0928\\u092f\\u093e \\u0915\\u094b\\u0921 \\u091c\\u0928\\u0930\\u0947\\u091f \\u0915\\u093f\\u090f \\u092c\\u093f\\u0928\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u094d\\u0935\\u0940\\u0915\\u093e\\u0930 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0938 \\u0915\\u094d\\u092f\\u0942\\u0906\\u0930 \\u0915\\u094b\\u0921 \\u0915\\u093e \\u092c\\u093e\\u0930-\\u092c\\u093e\\u0930 \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724b71841d76\"},\"6724b7243f9d9\":{\"language\":{\"en\":{\"question\":\"What payment methods can customers use when scanning my QR Code?\",\"answer\":\"Customers can pay using various methods that QRPay Pro supports. The platform handles the process seamlessly, ensuring secure and efficient transactions.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0647\\u064a \\u0637\\u0631\\u0642 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062a\\u064a \\u064a\\u0645\\u0643\\u0646 \\u0644\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645\\u0647\\u0627 \\u0639\\u0646\\u062f \\u0645\\u0633\\u062d \\u0631\\u0645\\u0632 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639\\u0629 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u064a\\u061f\",\"answer\":\"\\u064a\\u0645\\u0643\\u0646 \\u0644\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0637\\u0631\\u0642 \\u0645\\u062e\\u062a\\u0644\\u0641\\u0629 \\u064a\\u062f\\u0639\\u0645\\u0647\\u0627 QRPay Pro. \\u062a\\u062a\\u0639\\u0627\\u0645\\u0644 \\u0627\\u0644\\u0645\\u0646\\u0635\\u0629 \\u0645\\u0639 \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0628\\u0633\\u0644\\u0627\\u0633\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0636\\u0645\\u0646 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0622\\u0645\\u0646\\u0629 \\u0648\\u0641\\u0639\\u0627\\u0644\\u0629.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 m\\u00e9todos de pago pueden utilizar los clientes al escanear mi c\\u00f3digo QR?\",\"answer\":\"Los clientes pueden pagar utilizando varios m\\u00e9todos compatibles con QRPay Pro. La plataforma maneja el proceso sin problemas, garantizando transacciones seguras y eficientes.\"},\"fr\":{\"question\":\"Quels modes de paiement les clients peuvent-ils utiliser lorsqu\'ils scannent mon QR Code\\u00a0?\",\"answer\":\"Les clients peuvent payer en utilisant diverses m\\u00e9thodes prises en charge par QRPay Pro. La plateforme g\\u00e8re le processus de mani\\u00e8re transparente, garantissant des transactions s\\u00e9curis\\u00e9es et efficaces.\"},\"hi\":{\"question\":\"\\u092e\\u0947\\u0930\\u0947 \\u0915\\u094d\\u092f\\u0942\\u0906\\u0930 \\u0915\\u094b\\u0921 \\u0915\\u094b \\u0938\\u094d\\u0915\\u0948\\u0928 \\u0915\\u0930\\u0924\\u0947 \\u0938\\u092e\\u092f \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915 \\u0915\\u093f\\u0928 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0935\\u093f\\u0927\\u093f\\u092f\\u094b\\u0902 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902?\",\"answer\":\"\\u0917\\u094d\\u0930\\u093e\\u0939\\u0915 QRPay Pro \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u093f\\u0924 \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u0924\\u0930\\u0940\\u0915\\u094b\\u0902 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0914\\u0930 \\u0915\\u0941\\u0936\\u0932 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0941\\u090f \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0915\\u094b \\u0928\\u093f\\u0930\\u094d\\u092c\\u093e\\u0927 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0938\\u0902\\u092d\\u093e\\u0932\\u0924\\u093e \\u0939\\u0948\\u0964\"}},\"id\":\"6724b7243f9d9\"},\"6724b72f02292\":{\"language\":{\"en\":{\"question\":\"Can customers from other countries pay me using the QR Code?\",\"answer\":\"Yes, QRPay Pro\\u2019s multi-currency support allows you to accept payments from customers worldwide. The platform automatically manages any necessary currency conversion.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646 \\u0644\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0645\\u0646 \\u0628\\u0644\\u062f\\u0627\\u0646 \\u0623\\u062e\\u0631\\u0649 \\u0623\\u0646 \\u064a\\u062f\\u0641\\u0639\\u0648\\u0627 \\u0644\\u064a \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0631\\u0645\\u0632 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639\\u0629\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u064a\\u062a\\u064a\\u062d \\u0644\\u0643 \\u062f\\u0639\\u0645 QRPay Pro \\u0645\\u062a\\u0639\\u062f\\u062f \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0642\\u0628\\u0648\\u0644 \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0641\\u064a \\u062c\\u0645\\u064a\\u0639 \\u0623\\u0646\\u062d\\u0627\\u0621 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645. \\u062a\\u0642\\u0648\\u0645 \\u0627\\u0644\\u0645\\u0646\\u0635\\u0629 \\u062a\\u0644\\u0642\\u0627\\u0626\\u064a\\u064b\\u0627 \\u0628\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0623\\u064a \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0636\\u0631\\u0648\\u0631\\u064a \\u0644\\u0644\\u0639\\u0645\\u0644\\u0629.\"},\"es\":{\"question\":\"\\u00bfPueden los clientes de otros pa\\u00edses pagarme mediante el C\\u00f3digo QR?\",\"answer\":\"S\\u00ed, el soporte multidivisa de QRPay Pro le permite aceptar pagos de clientes de todo el mundo. La plataforma gestiona autom\\u00e1ticamente cualquier conversi\\u00f3n de moneda necesaria.\"},\"fr\":{\"question\":\"Les clients d\'autres pays peuvent-ils me payer en utilisant le QR Code ?\",\"answer\":\"Oui, la prise en charge multidevises de QRPay Pro vous permet d\'accepter les paiements de clients du monde entier. La plateforme g\\u00e8re automatiquement toute conversion de devise n\\u00e9cessaire.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u0905\\u0928\\u094d\\u092f \\u0926\\u0947\\u0936\\u094b\\u0902 \\u0915\\u0947 \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915 \\u0915\\u094d\\u092f\\u0942\\u0906\\u0930 \\u0915\\u094b\\u0921 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u092e\\u0941\\u091d\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902?\",\"answer\":\"\\u0939\\u093e\\u0901, QRPay Pro \\u0915\\u093e \\u092c\\u0939\\u0941-\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u0928 \\u0906\\u092a\\u0915\\u094b \\u0926\\u0941\\u0928\\u093f\\u092f\\u093e \\u092d\\u0930 \\u0915\\u0947 \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915\\u094b\\u0902 \\u0938\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u094d\\u0935\\u0940\\u0915\\u093e\\u0930 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0940 \\u0905\\u0928\\u0941\\u092e\\u0924\\u093f \\u0926\\u0947\\u0924\\u093e \\u0939\\u0948\\u0964 \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e \\u0938\\u094d\\u0935\\u091a\\u093e\\u0932\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0915\\u093f\\u0938\\u0940 \\u092d\\u0940 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0930\\u0942\\u092a\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u093e \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948\\u0964\"}},\"id\":\"6724b72f02292\"},\"6724b73908a8c\":{\"language\":{\"en\":{\"question\":\"How will I know if a payment is successful?\",\"answer\":\"QRPay Pro sends real-time notifications for every transaction, so you\\u2019ll instantly know when a payment has been received, allowing for better cash flow tracking.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u0623\\u0639\\u0631\\u0641 \\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646\\u062a \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0646\\u0627\\u062c\\u062d\\u0629\\u061f\",\"answer\":\"\\u064a\\u0631\\u0633\\u0644 QRPay Pro \\u0625\\u0634\\u0639\\u0627\\u0631\\u0627\\u062a \\u0641\\u064a \\u0627\\u0644\\u0648\\u0642\\u062a \\u0627\\u0644\\u0641\\u0639\\u0644\\u064a \\u0644\\u0643\\u0644 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0629\\u060c \\u0644\\u0630\\u0644\\u0643 \\u0633\\u062a\\u0639\\u0631\\u0641 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631 \\u0645\\u062a\\u0649 \\u062a\\u0645 \\u0627\\u0633\\u062a\\u0644\\u0627\\u0645 \\u0627\\u0644\\u062f\\u0641\\u0639\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0645\\u062d \\u0628\\u062a\\u062a\\u0628\\u0639 \\u0627\\u0644\\u062a\\u062f\\u0641\\u0642 \\u0627\\u0644\\u0646\\u0642\\u062f\\u064a \\u0628\\u0634\\u0643\\u0644 \\u0623\\u0641\\u0636\\u0644.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo sabr\\u00e9 si un pago se realiz\\u00f3 correctamente?\",\"answer\":\"QRPay Pro env\\u00eda notificaciones en tiempo real para cada transacci\\u00f3n, por lo que sabr\\u00e1 instant\\u00e1neamente cu\\u00e1ndo se recibi\\u00f3 un pago, lo que permitir\\u00e1 un mejor seguimiento del flujo de efectivo.\"},\"fr\":{\"question\":\"Comment saurai-je si un paiement a r\\u00e9ussi\\u00a0?\",\"answer\":\"QRPay Pro envoie des notifications en temps r\\u00e9el pour chaque transaction, de sorte que vous saurez instantan\\u00e9ment quand un paiement a \\u00e9t\\u00e9 re\\u00e7u, permettant ainsi un meilleur suivi des flux de tr\\u00e9sorerie.\"},\"hi\":{\"question\":\"\\u092e\\u0941\\u091d\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u092a\\u0924\\u093e \\u091a\\u0932\\u0947\\u0917\\u093e \\u0915\\u093f \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u092b\\u0932 \\u0939\\u0941\\u0906 \\u0939\\u0948?\",\"answer\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0935\\u093e\\u0938\\u094d\\u0924\\u0935\\u093f\\u0915 \\u0938\\u092e\\u092f \\u0938\\u0942\\u091a\\u0928\\u093e\\u090f\\u0902 \\u092d\\u0947\\u091c\\u0924\\u093e \\u0939\\u0948, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0906\\u092a\\u0915\\u094b \\u0924\\u0941\\u0930\\u0902\\u0924 \\u092a\\u0924\\u093e \\u091a\\u0932 \\u091c\\u093e\\u090f\\u0917\\u093e \\u0915\\u093f \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u092c \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0939\\u0941\\u0906 \\u0939\\u0948, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u092c\\u0947\\u0939\\u0924\\u0930 \\u0928\\u0915\\u0926\\u0940 \\u092a\\u094d\\u0930\\u0935\\u093e\\u0939 \\u091f\\u094d\\u0930\\u0948\\u0915\\u093f\\u0902\\u0917 \\u0915\\u0940 \\u0905\\u0928\\u0941\\u092e\\u0924\\u093f \\u092e\\u093f\\u0932\\u0924\\u0940 \\u0939\\u0948\\u0964\"}},\"id\":\"6724b73908a8c\"}}}', 1, 1, '2024-11-01 17:10:04', '2024-11-06 17:23:25');
INSERT INTO `frontend_header_section_faqs` VALUES (19, 19, 'business', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About Currency Exchange in QRPay Pro\",\"sub_heading\":\"Learn more about securely managing currency exchanges with QRPay Pro\\u2019s powerful tools.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0641\\u064a QRPay Pro\",\"sub_heading\":\"\\u062a\\u0639\\u0631\\u0641 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0632\\u064a\\u062f \\u062d\\u0648\\u0644 \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0628\\u0634\\u0643\\u0644 \\u0622\\u0645\\u0646 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0623\\u062f\\u0648\\u0627\\u062a QRPay Pro \\u0627\\u0644\\u0642\\u0648\\u064a\\u0629.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre el cambio de divisas en QRPay Pro\",\"sub_heading\":\"Obtenga m\\u00e1s informaci\\u00f3n sobre c\\u00f3mo gestionar de forma segura los cambios de divisas con las potentes herramientas de QRPay Pro.\"},\"fr\":{\"heading\":\"Questions fr\\u00e9quemment pos\\u00e9es sur le change de devises dans QRPay Pro\",\"sub_heading\":\"Apprenez-en davantage sur la gestion s\\u00e9curis\\u00e9e des \\u00e9changes de devises avec les puissants outils de QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092e\\u0947\\u0902 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0936\\u0915\\u094d\\u0924\\u093f\\u0936\\u093e\\u0932\\u0940 \\u091f\\u0942\\u0932 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0915\\u094b \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0914\\u0930 \\u091c\\u093e\\u0928\\u0947\\u0902\\u0964\"}},\"items\":{\"6724b7d49624e\":{\"language\":{\"en\":{\"question\":\"What exchange rates does QRPay Pro use for currency conversion?\",\"answer\":\"QRPay Pro uses real-time exchange rates provided by trusted financial data sources, ensuring that you get accurate and fair rates during each conversion.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0647\\u064a \\u0623\\u0633\\u0639\\u0627\\u0631 \\u0627\\u0644\\u0635\\u0631\\u0641 \\u0627\\u0644\\u062a\\u064a \\u064a\\u0633\\u062a\\u062e\\u062f\\u0645\\u0647\\u0627 QRPay Pro \\u0644\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a\\u061f\",\"answer\":\"\\u064a\\u0633\\u062a\\u062e\\u062f\\u0645 QRPay Pro \\u0623\\u0633\\u0639\\u0627\\u0631 \\u0627\\u0644\\u0635\\u0631\\u0641 \\u0641\\u064a \\u0627\\u0644\\u0648\\u0642\\u062a \\u0627\\u0644\\u0641\\u0639\\u0644\\u064a \\u0627\\u0644\\u062a\\u064a \\u062a\\u0648\\u0641\\u0631\\u0647\\u0627 \\u0645\\u0635\\u0627\\u062f\\u0631 \\u0627\\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0627\\u0644\\u0645\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0648\\u062b\\u0648\\u0642\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0636\\u0645\\u0646 \\u062d\\u0635\\u0648\\u0644\\u0643 \\u0639\\u0644\\u0649 \\u0623\\u0633\\u0639\\u0627\\u0631 \\u062f\\u0642\\u064a\\u0642\\u0629 \\u0648\\u0639\\u0627\\u062f\\u0644\\u0629 \\u0623\\u062b\\u0646\\u0627\\u0621 \\u0643\\u0644 \\u062a\\u062d\\u0648\\u064a\\u0644.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 tipos de cambio utiliza QRPay Pro para la conversi\\u00f3n de moneda?\",\"answer\":\"QRPay Pro utiliza tipos de cambio en tiempo real proporcionados por fuentes de datos financieros confiables, lo que garantiza que obtenga tasas precisas y justas durante cada conversi\\u00f3n.\"},\"fr\":{\"question\":\"Quels taux de change QRPay Pro utilise-t-il pour la conversion de devises\\u00a0?\",\"answer\":\"QRPay Pro utilise des taux de change en temps r\\u00e9el fournis par des sources de donn\\u00e9es financi\\u00e8res fiables, garantissant que vous obtenez des taux pr\\u00e9cis et \\u00e9quitables lors de chaque conversion.\"},\"hi\":{\"question\":\"\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0930\\u0942\\u092a\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u0947 \\u0932\\u093f\\u090f QRPay Pro \\u0915\\u093f\\u0938 \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0926\\u0930\\u094b\\u0902 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948?\",\"answer\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0935\\u093f\\u0936\\u094d\\u0935\\u0938\\u0928\\u0940\\u092f \\u0935\\u093f\\u0924\\u094d\\u0924\\u0940\\u092f \\u0921\\u0947\\u091f\\u093e \\u0938\\u094d\\u0930\\u094b\\u0924\\u094b\\u0902 \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0940 \\u0917\\u0908 \\u0935\\u093e\\u0938\\u094d\\u0924\\u0935\\u093f\\u0915 \\u0938\\u092e\\u092f \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0926\\u0930\\u094b\\u0902 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948, \\u092f\\u0939 \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948 \\u0915\\u093f \\u0906\\u092a\\u0915\\u094b \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u0930\\u0942\\u092a\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u0947 \\u0926\\u094c\\u0930\\u093e\\u0928 \\u0938\\u091f\\u0940\\u0915 \\u0914\\u0930 \\u0909\\u091a\\u093f\\u0924 \\u0926\\u0930\\u0947\\u0902 \\u092e\\u093f\\u0932\\u0947\\u0902\\u0964\"}},\"id\":\"6724b7d49624e\"},\"6724b7dd6cb4d\":{\"language\":{\"en\":{\"question\":\"Are there any fees for currency exchange in QRPay Pro?\",\"answer\":\"QRPay Pro may charge a small service fee for each currency exchange transaction. You can view any applicable fees before confirming the exchange.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0644\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0641\\u064a QRPay Pro\\u061f\",\"answer\":\"\\u064a\\u0633\\u062a\\u062e\\u062f\\u0645 QRPay Pro \\u0623\\u0633\\u0639\\u0627\\u0631 \\u0627\\u0644\\u0635\\u0631\\u0641 \\u0641\\u064a \\u0627\\u0644\\u0648\\u0642\\u062a \\u0627\\u0644\\u0641\\u0639\\u0644\\u064a \\u0627\\u0644\\u062a\\u064a \\u062a\\u0648\\u0641\\u0631\\u0647\\u0627 \\u0645\\u0635\\u0627\\u062f\\u0631 \\u0627\\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0627\\u0644\\u0645\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0648\\u062b\\u0648\\u0642\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0636\\u0645\\u0646 \\u062d\\u0635\\u0648\\u0644\\u0643 \\u0639\\u0644\\u0649 \\u0623\\u0633\\u0639\\u0627\\u0631 \\u062f\\u0642\\u064a\\u0642\\u0629 \\u0648\\u0639\\u0627\\u062f\\u0644\\u0629 \\u0623\\u062b\\u0646\\u0627\\u0621 \\u0643\\u0644 \\u062a\\u062d\\u0648\\u064a\\u0644.\"},\"es\":{\"question\":\"\\u00bfHay alguna tarifa por el cambio de moneda en QRPay Pro?\",\"answer\":\"QRPay Pro utiliza tipos de cambio en tiempo real proporcionados por fuentes de datos financieros confiables, lo que garantiza que obtenga tasas precisas y justas durante cada conversi\\u00f3n.\"},\"fr\":{\"question\":\"Y a-t-il des frais pour le change de devises dans QRPay Pro\\u00a0?\",\"answer\":\"QRPay Pro utilise des taux de change en temps r\\u00e9el fournis par des sources de donn\\u00e9es financi\\u00e8res fiables, garantissant que vous obtenez des taux pr\\u00e9cis et \\u00e9quitables lors de chaque conversion.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e QRPay Pro \\u092e\\u0947\\u0902 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u094b\\u0908 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0939\\u0948?\",\"answer\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0935\\u093f\\u0936\\u094d\\u0935\\u0938\\u0928\\u0940\\u092f \\u0935\\u093f\\u0924\\u094d\\u0924\\u0940\\u092f \\u0921\\u0947\\u091f\\u093e \\u0938\\u094d\\u0930\\u094b\\u0924\\u094b\\u0902 \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0940 \\u0917\\u0908 \\u0935\\u093e\\u0938\\u094d\\u0924\\u0935\\u093f\\u0915 \\u0938\\u092e\\u092f \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0926\\u0930\\u094b\\u0902 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948, \\u092f\\u0939 \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948 \\u0915\\u093f \\u0906\\u092a\\u0915\\u094b \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u0930\\u0942\\u092a\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u0947 \\u0926\\u094c\\u0930\\u093e\\u0928 \\u0938\\u091f\\u0940\\u0915 \\u0914\\u0930 \\u0909\\u091a\\u093f\\u0924 \\u0926\\u0930\\u0947\\u0902 \\u092e\\u093f\\u0932\\u0947\\u0902\\u0964\"}},\"id\":\"6724b7dd6cb4d\"},\"6724b7e620e85\":{\"language\":{\"en\":{\"question\":\"How quickly is the currency exchange processed?\",\"answer\":\"Currency exchanges in QRPay Pro are processed instantly. Once you confirm the exchange, the converted funds are immediately available in your account in the target currency.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0645\\u062f\\u0649 \\u0633\\u0631\\u0639\\u0629 \\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a\\u061f\",\"answer\":\"\\u062a\\u062a\\u0645 \\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0641\\u064a QRPay Pro \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631. \\u0628\\u0645\\u062c\\u0631\\u062f \\u062a\\u0623\\u0643\\u064a\\u062f \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062a\\u0628\\u0627\\u062f\\u0644\\u060c \\u062a\\u0635\\u0628\\u062d \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0627\\u0644\\u0645\\u062d\\u0648\\u0644\\u0629 \\u0645\\u062a\\u0627\\u062d\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0628\\u0627\\u0644\\u0639\\u0645\\u0644\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0647\\u062f\\u0641\\u0629.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 tan r\\u00e1pido se procesa el cambio de moneda?\",\"answer\":\"Los cambios de moneda en QRPay Pro se procesan instant\\u00e1neamente. Una vez que confirme el cambio, los fondos convertidos estar\\u00e1n disponibles inmediatamente en su cuenta en la moneda de destino.\"},\"fr\":{\"question\":\"\\u00c0 quelle vitesse le change de devises est-il trait\\u00e9\\u00a0?\",\"answer\":\"Les \\u00e9changes de devises dans QRPay Pro sont trait\\u00e9s instantan\\u00e9ment. Une fois l\'\\u00e9change confirm\\u00e9, les fonds convertis sont imm\\u00e9diatement disponibles sur votre compte dans la devise cible.\"},\"hi\":{\"question\":\"\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0915\\u093f\\u0924\\u0928\\u0940 \\u091c\\u0932\\u094d\\u0926\\u0940 \\u0938\\u0902\\u0938\\u093e\\u0927\\u093f\\u0924 \\u0939\\u094b\\u0924\\u093e \\u0939\\u0948?\",\"answer\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092e\\u0947\\u0902 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0924\\u0941\\u0930\\u0902\\u0924 \\u0938\\u0902\\u0938\\u093e\\u0927\\u093f\\u0924 \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e\\u0924\\u093e \\u0939\\u0948\\u0964 \\u090f\\u0915 \\u092c\\u093e\\u0930 \\u091c\\u092c \\u0906\\u092a \\u090f\\u0915\\u094d\\u0938\\u091a\\u0947\\u0902\\u091c \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930 \\u0926\\u0947\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0924\\u094b \\u092a\\u0930\\u093f\\u0935\\u0930\\u094d\\u0924\\u093f\\u0924 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0924\\u0941\\u0930\\u0902\\u0924 \\u0906\\u092a\\u0915\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0932\\u0915\\u094d\\u0937\\u094d\\u092f \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u092e\\u0947\\u0902 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0939\\u094b \\u091c\\u093e\\u0924\\u0940 \\u0939\\u0948\\u0964\"}},\"id\":\"6724b7e620e85\"},\"6724b7ef0316f\":{\"language\":{\"en\":{\"question\":\"Can I exchange multiple currencies within my account?\",\"answer\":\"Yes, QRPay Pro supports multi-currency accounts, allowing you to exchange between various supported currencies seamlessly. This feature is ideal for merchants serving customers from different countries.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0633\\u062a\\u0628\\u062f\\u0627\\u0644 \\u0639\\u0645\\u0644\\u0627\\u062a \\u0645\\u062a\\u0639\\u062f\\u062f\\u0629 \\u062f\\u0627\\u062e\\u0644 \\u062d\\u0633\\u0627\\u0628\\u064a\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u064a\\u062f\\u0639\\u0645 QRPay Pro \\u0627\\u0644\\u062d\\u0633\\u0627\\u0628\\u0627\\u062a \\u0645\\u062a\\u0639\\u062f\\u062f\\u0629 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0645\\u062d \\u0644\\u0643 \\u0628\\u0627\\u0644\\u062a\\u0628\\u0627\\u062f\\u0644 \\u0628\\u064a\\u0646 \\u0645\\u062e\\u062a\\u0644\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u062f\\u0639\\u0648\\u0645\\u0629 \\u0628\\u0633\\u0644\\u0627\\u0633\\u0629. \\u0647\\u0630\\u0647 \\u0627\\u0644\\u0645\\u064a\\u0632\\u0629 \\u0645\\u062b\\u0627\\u0644\\u064a\\u0629 \\u0644\\u0644\\u062a\\u062c\\u0627\\u0631 \\u0627\\u0644\\u0630\\u064a\\u0646 \\u064a\\u062e\\u062f\\u0645\\u0648\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0645\\u0646 \\u0645\\u062e\\u062a\\u0644\\u0641 \\u0627\\u0644\\u0628\\u0644\\u062f\\u0627\\u0646.\"},\"es\":{\"question\":\"\\u00bfPuedo cambiar varias monedas dentro de mi cuenta?\",\"answer\":\"S\\u00ed, QRPay Pro admite cuentas multidivisa, lo que le permite intercambiar entre varias monedas admitidas sin problemas. Esta caracter\\u00edstica es ideal para comerciantes que atienden a clientes de diferentes pa\\u00edses.\"},\"fr\":{\"question\":\"Puis-je \\u00e9changer plusieurs devises sur mon compte ?\",\"answer\":\"Oui, QRPay Pro prend en charge les comptes multi-devises, vous permettant d\'\\u00e9changer de mani\\u00e8re transparente entre diff\\u00e9rentes devises prises en charge. Cette fonctionnalit\\u00e9 est id\\u00e9ale pour les commer\\u00e7ants servant des clients de diff\\u00e9rents pays.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u090f\\u0915\\u093e\\u0927\\u093f\\u0915 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u093e \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0939\\u093e\\u0901, QRPay \\u092a\\u094d\\u0930\\u094b \\u092c\\u0939\\u0941-\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0916\\u093e\\u0924\\u094b\\u0902 \\u0915\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0906\\u092a \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u0938\\u092e\\u0930\\u094d\\u0925\\u093f\\u0924 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u092c\\u0940\\u091a \\u0928\\u093f\\u0930\\u094d\\u092c\\u093e\\u0927 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u092f\\u0939 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u0926\\u0947\\u0936\\u094b\\u0902 \\u0915\\u0947 \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915\\u094b\\u0902 \\u0915\\u094b \\u0938\\u0947\\u0935\\u093e \\u0926\\u0947\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u093f\\u092f\\u094b\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0906\\u0926\\u0930\\u094d\\u0936 \\u0939\\u0948\\u0964\"}},\"id\":\"6724b7ef0316f\"}}}', 1, 1, '2024-11-01 17:13:13', '2024-11-07 10:33:20');
INSERT INTO `frontend_header_section_faqs` VALUES (20, 20, 'business', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About QRPay Pro Payment Link\",\"sub_heading\":\"Discover how QRPay Pro Payment Links make collecting payments easy and secure for merchants.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 QRPay Pro\",\"sub_heading\":\"\\u0627\\u0643\\u062a\\u0634\\u0641 \\u0643\\u064a\\u0641 \\u062a\\u062c\\u0639\\u0644 \\u0631\\u0648\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 QRPay Pro \\u0639\\u0645\\u0644\\u064a\\u0629 \\u062a\\u062d\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0633\\u0647\\u0644\\u0629 \\u0648\\u0622\\u0645\\u0646\\u0629 \\u0644\\u0644\\u062a\\u062c\\u0627\\u0631.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre el enlace de pago QRPay Pro\",\"sub_heading\":\"Descubra c\\u00f3mo los enlaces de pago QRPay Pro hacen que el cobro de pagos sea f\\u00e1cil y seguro para los comerciantes.\"},\"fr\":{\"heading\":\"Foire aux questions sur le lien de paiement QRPay Pro\",\"sub_heading\":\"D\\u00e9couvrez comment les liens de paiement QRPay Pro rendent la collecte des paiements facile et s\\u00e9curis\\u00e9e pour les commer\\u00e7ants.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"\\u091c\\u093e\\u0928\\u0947\\u0902 \\u0915\\u093f \\u0915\\u0948\\u0938\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u093f\\u092f\\u094b\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u090f\\u0915\\u0924\\u094d\\u0930 \\u0915\\u0930\\u0928\\u093e \\u0906\\u0938\\u093e\\u0928 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u092c\\u0928\\u093e\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"items\":{\"6724b915e0842\":{\"language\":{\"en\":{\"question\":\"How do I create a payment link in QRPay Pro?\",\"answer\":\"To create a payment link, log in to your QRPay Pro merchant dashboard, enter the amount and payment details, and generate the link. You can then share this link with your customers for quick and easy payment.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u0623\\u0642\\u0648\\u0645 \\u0628\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u0627\\u0628\\u0637 \\u062f\\u0641\\u0639 \\u0641\\u064a QRPay Pro\\u061f\",\"answer\":\"\\u0644\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u0627\\u0628\\u0637 \\u062f\\u0641\\u0639\\u060c \\u0642\\u0645 \\u0628\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u0644\\u0648\\u062d\\u0629 \\u062a\\u062d\\u0643\\u0645 \\u0627\\u0644\\u062a\\u0627\\u062c\\u0631 QRPay Pro\\u060c \\u0648\\u0623\\u062f\\u062e\\u0644 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a \\u0648\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u062f\\u0641\\u0639\\u060c \\u062b\\u0645 \\u0642\\u0645 \\u0628\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0627\\u0644\\u0631\\u0627\\u0628\\u0637. \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0628\\u0639\\u062f \\u0630\\u0644\\u0643 \\u0645\\u0634\\u0627\\u0631\\u0643\\u0629 \\u0647\\u0630\\u0627 \\u0627\\u0644\\u0631\\u0627\\u0628\\u0637 \\u0645\\u0639 \\u0639\\u0645\\u0644\\u0627\\u0626\\u0643 \\u0644\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639 \\u0648\\u0627\\u0644\\u0633\\u0647\\u0644.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo creo un enlace de pago en QRPay Pro?\",\"answer\":\"Para crear un enlace de pago, inicie sesi\\u00f3n en su panel de comerciante QRPay Pro, ingrese el monto y los detalles del pago y genere el enlace. Luego puede compartir este enlace con sus clientes para realizar un pago r\\u00e1pido y sencillo.\"},\"fr\":{\"question\":\"Comment cr\\u00e9er un lien de paiement dans QRPay Pro ?\",\"answer\":\"Pour cr\\u00e9er un lien de paiement, connectez-vous \\u00e0 votre tableau de bord marchand QRPay Pro, saisissez le montant et les d\\u00e9tails du paiement, puis g\\u00e9n\\u00e9rez le lien. Vous pourrez ensuite partager ce lien avec vos clients pour un paiement simple et rapide.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay Pro \\u092e\\u0947\\u0902 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0915\\u0948\\u0938\\u0947 \\u092c\\u0928\\u093e\\u090a\\u0902?\",\"answer\":\"\\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u092c\\u0928\\u093e\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u092e\\u0930\\u094d\\u091a\\u0947\\u0902\\u091f \\u0921\\u0948\\u0936\\u092c\\u094b\\u0930\\u094d\\u0921 \\u092e\\u0947\\u0902 \\u0932\\u0949\\u0917 \\u0907\\u0928 \\u0915\\u0930\\u0947\\u0902, \\u0930\\u093e\\u0936\\u093f \\u0914\\u0930 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902, \\u0914\\u0930 \\u0932\\u093f\\u0902\\u0915 \\u091c\\u0947\\u0928\\u0930\\u0947\\u091f \\u0915\\u0930\\u0947\\u0902\\u0964 \\u092b\\u093f\\u0930 \\u0906\\u092a \\u0924\\u094d\\u0935\\u0930\\u093f\\u0924 \\u0914\\u0930 \\u0906\\u0938\\u093e\\u0928 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0938 \\u0932\\u093f\\u0902\\u0915 \\u0915\\u094b \\u0905\\u092a\\u0928\\u0947 \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915\\u094b\\u0902 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724b915e0842\"},\"6724b9207c65f\":{\"language\":{\"en\":{\"question\":\"Can I customize the payment link details for different transactions?\",\"answer\":\"Yes, QRPay Pro allows you to add specific details for each payment link, such as the payment amount, description, and expiration date, to match the needs of each transaction.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u062a\\u062e\\u0635\\u064a\\u0635 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0645\\u062e\\u062a\\u0644\\u0641\\u0629\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u064a\\u062a\\u064a\\u062d \\u0644\\u0643 QRPay Pro \\u0625\\u0636\\u0627\\u0641\\u0629 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0645\\u062d\\u062f\\u062f\\u0629 \\u0644\\u0643\\u0644 \\u0631\\u0627\\u0628\\u0637 \\u062f\\u0641\\u0639\\u060c \\u0645\\u062b\\u0644 \\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u062f\\u0641\\u0639\\u0629 \\u0648\\u0627\\u0644\\u0648\\u0635\\u0641 \\u0648\\u062a\\u0627\\u0631\\u064a\\u062e \\u0627\\u0646\\u062a\\u0647\\u0627\\u0621 \\u0627\\u0644\\u0635\\u0644\\u0627\\u062d\\u064a\\u0629\\u060c \\u0644\\u062a\\u062a\\u0646\\u0627\\u0633\\u0628 \\u0645\\u0639 \\u0627\\u062d\\u062a\\u064a\\u0627\\u062c\\u0627\\u062a \\u0643\\u0644 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0629.\"},\"es\":{\"question\":\"\\u00bfPuedo personalizar los detalles del enlace de pago para diferentes transacciones?\",\"answer\":\"S\\u00ed, QRPay Pro le permite agregar detalles espec\\u00edficos para cada enlace de pago, como el monto del pago, la descripci\\u00f3n y la fecha de vencimiento, para satisfacer las necesidades de cada transacci\\u00f3n.\"},\"fr\":{\"question\":\"Puis-je personnaliser les d\\u00e9tails du lien de paiement pour diff\\u00e9rentes transactions\\u00a0?\",\"answer\":\"Oui, QRPay Pro vous permet d\'ajouter des d\\u00e9tails sp\\u00e9cifiques pour chaque lien de paiement, tels que le montant du paiement, la description et la date d\'expiration, pour r\\u00e9pondre aux besoins de chaque transaction.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0915\\u094b \\u0905\\u0928\\u0941\\u0915\\u0942\\u0932\\u093f\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0939\\u093e\\u0902, \\u0915\\u094d\\u092f\\u0942\\u0906\\u0930\\u092a\\u0947 \\u092a\\u094d\\u0930\\u094b \\u0906\\u092a\\u0915\\u094b \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915\\u0924\\u093e\\u0913\\u0902 \\u0938\\u0947 \\u092e\\u0947\\u0932 \\u0916\\u093e\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0935\\u093f\\u0936\\u093f\\u0937\\u094d\\u091f \\u0935\\u093f\\u0935\\u0930\\u0923 \\u091c\\u094b\\u0921\\u093c\\u0928\\u0947 \\u0915\\u0940 \\u0905\\u0928\\u0941\\u092e\\u0924\\u093f \\u0926\\u0947\\u0924\\u093e \\u0939\\u0948, \\u091c\\u0948\\u0938\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0930\\u093e\\u0936\\u093f, \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0914\\u0930 \\u0938\\u092e\\u093e\\u092a\\u094d\\u0924\\u093f \\u0924\\u093f\\u0925\\u093f\\u0964\"}},\"id\":\"6724b9207c65f\"},\"6724b94031cd3\":{\"language\":{\"en\":{\"question\":\"Are there any fees for using the payment link feature in QRPay Pro?\",\"answer\":\"QRPay Pro may charge a nominal fee for processing payments through payment links. You can view and confirm any applicable fees before finalizing each transaction.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0642\\u0627\\u0628\\u0644 \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u062e\\u0627\\u0635\\u064a\\u0629 \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0641\\u064a QRPay Pro\\u061f\",\"answer\":\"\\u0642\\u062f \\u064a\\u0641\\u0631\\u0636 QRPay Pro \\u0631\\u0633\\u0648\\u0645\\u064b\\u0627 \\u0631\\u0645\\u0632\\u064a\\u0629 \\u0645\\u0642\\u0627\\u0628\\u0644 \\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0631\\u0648\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639. \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0639\\u0631\\u0636 \\u0648\\u062a\\u0623\\u0643\\u064a\\u062f \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0637\\u0628\\u0642\\u0629 \\u0642\\u0628\\u0644 \\u0627\\u0644\\u0627\\u0646\\u062a\\u0647\\u0627\\u0621 \\u0645\\u0646 \\u0643\\u0644 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0629.\"},\"es\":{\"question\":\"\\u00bfExiste alguna tarifa por utilizar la funci\\u00f3n de enlace de pago en QRPay Pro?\",\"answer\":\"QRPay Pro puede cobrar una tarifa nominal por procesar pagos a trav\\u00e9s de enlaces de pago. Puede ver y confirmar las tarifas aplicables antes de finalizar cada transacci\\u00f3n.\"},\"fr\":{\"question\":\"Y a-t-il des frais pour l\'utilisation de la fonction de lien de paiement dans QRPay Pro\\u00a0?\",\"answer\":\"QRPay Pro peut facturer des frais nominaux pour le traitement des paiements via des liens de paiement. Vous pouvez consulter et confirmer tous les frais applicables avant de finaliser chaque transaction.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e QRPay Pro \\u092e\\u0947\\u0902 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u094b\\u0908 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0939\\u0948?\",\"answer\":\"QRPay Pro \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u0902\\u0938\\u093e\\u0927\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092e\\u093e\\u092e\\u0942\\u0932\\u0940 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0932\\u0947 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0906\\u092a \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u094b \\u0905\\u0902\\u0924\\u093f\\u092e \\u0930\\u0942\\u092a \\u0926\\u0947\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u0915\\u093f\\u0938\\u0940 \\u092d\\u0940 \\u0932\\u093e\\u0917\\u0942 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0915\\u094b \\u0926\\u0947\\u0916 \\u0914\\u0930 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724b94031cd3\"},\"6724b94bef252\":{\"language\":{\"en\":{\"question\":\"Is it safe to share payment links with customers?\",\"answer\":\"Yes, QRPay Pro prioritizes security, and all payment links are encrypted. This ensures that each transaction is protected, allowing you to share links with peace of mind.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0645\\u0646 \\u0627\\u0644\\u0622\\u0645\\u0646 \\u0645\\u0634\\u0627\\u0631\\u0643\\u0629 \\u0631\\u0648\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0645\\u0639 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u064a\\u0639\\u0637\\u064a QRPay Pro \\u0627\\u0644\\u0623\\u0648\\u0644\\u0648\\u064a\\u0629 \\u0644\\u0644\\u0623\\u0645\\u0646\\u060c \\u0648\\u064a\\u062a\\u0645 \\u062a\\u0634\\u0641\\u064a\\u0631 \\u062c\\u0645\\u064a\\u0639 \\u0631\\u0648\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639. \\u0648\\u0647\\u0630\\u0627 \\u064a\\u0636\\u0645\\u0646 \\u062d\\u0645\\u0627\\u064a\\u0629 \\u0643\\u0644 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0645\\u062d \\u0644\\u0643 \\u0628\\u0645\\u0634\\u0627\\u0631\\u0643\\u0629 \\u0627\\u0644\\u0631\\u0648\\u0627\\u0628\\u0637 \\u0645\\u0639 \\u0631\\u0627\\u062d\\u0629 \\u0627\\u0644\\u0628\\u0627\\u0644.\"},\"es\":{\"question\":\"\\u00bfEs seguro compartir enlaces de pago con los clientes?\",\"answer\":\"S\\u00ed, QRPay Pro prioriza la seguridad y todos los enlaces de pago est\\u00e1n encriptados. Esto garantiza que cada transacci\\u00f3n est\\u00e9 protegida, lo que le permite compartir enlaces con tranquilidad.\"},\"fr\":{\"question\":\"Est-il s\\u00e9curis\\u00e9 de partager des liens de paiement avec des clients\\u00a0?\",\"answer\":\"Oui, QRPay Pro donne la priorit\\u00e9 \\u00e0 la s\\u00e9curit\\u00e9 et tous les liens de paiement sont crypt\\u00e9s. Cela garantit que chaque transaction est prot\\u00e9g\\u00e9e, vous permettant de partager des liens en toute s\\u00e9r\\u00e9nit\\u00e9.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915\\u094b\\u0902 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930\\u0928\\u093e \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0939\\u0948?\",\"answer\":\"\\u0939\\u093e\\u0901, QRPay Pro \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0915\\u094b \\u092a\\u094d\\u0930\\u093e\\u0925\\u092e\\u093f\\u0915\\u0924\\u093e \\u0926\\u0947\\u0924\\u093e \\u0939\\u0948, \\u0914\\u0930 \\u0938\\u092d\\u0940 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u090f\\u0928\\u094d\\u0915\\u094d\\u0930\\u093f\\u092a\\u094d\\u091f\\u0947\\u0921 \\u0939\\u0948\\u0902\\u0964 \\u092f\\u0939 \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948 \\u0915\\u093f \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0939\\u0948, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0906\\u092a \\u092e\\u0928 \\u0915\\u0940 \\u0936\\u093e\\u0902\\u0924\\u093f \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0932\\u093f\\u0902\\u0915 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724b94bef252\"}}}', 1, 1, '2024-11-01 17:18:31', '2024-11-06 17:35:24');
INSERT INTO `frontend_header_section_faqs` VALUES (21, 21, 'business', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About Withdrawing Money\",\"sub_heading\":\"Learn more about how to securely and efficiently withdraw your funds from QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\",\"sub_heading\":\"\\u062a\\u0639\\u0631\\u0641 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0632\\u064a\\u062f \\u062d\\u0648\\u0644 \\u0643\\u064a\\u0641\\u064a\\u0629 \\u0633\\u062d\\u0628 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0628\\u0634\\u0643\\u0644 \\u0622\\u0645\\u0646 \\u0648\\u0641\\u0639\\u0627\\u0644 \\u0645\\u0646 QRPay Pro.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre retirar dinero\",\"sub_heading\":\"Obtenga m\\u00e1s informaci\\u00f3n sobre c\\u00f3mo retirar sus fondos de QRPay Pro de forma segura y eficiente.\"},\"fr\":{\"heading\":\"Foire aux questions sur le retrait d\'argent\",\"sub_heading\":\"Apprenez-en davantage sur la mani\\u00e8re de retirer vos fonds de mani\\u00e8re s\\u00e9curis\\u00e9e et efficace de QRPay Pro.\"},\"hi\":{\"heading\":\"\\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"QRPay Pro \\u0938\\u0947 \\u0905\\u092a\\u0928\\u0940 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0914\\u0930 \\u0915\\u0941\\u0936\\u0932\\u0924\\u093e\\u092a\\u0942\\u0930\\u094d\\u0935\\u0915 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u0947 \\u0915\\u0947 \\u0924\\u0930\\u0940\\u0915\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0914\\u0930 \\u091c\\u093e\\u0928\\u0947\\u0902\\u0964\"}},\"items\":{\"6724b9ed0c9d7\":{\"language\":{\"en\":{\"question\":\"How long does it take to withdraw money from QRPay Pro?\",\"answer\":\"Withdrawal times may vary depending on the method chosen. Bank transfers generally take 1-3 business days, while digital wallet transfers are often faster. You\\u2019ll receive a notification once the transfer is completed.\"},\"ar\":{\"question\":\"\\u0643\\u0645 \\u0645\\u0646 \\u0627\\u0644\\u0648\\u0642\\u062a \\u064a\\u0633\\u062a\\u063a\\u0631\\u0642 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u0646 QRPay Pro\\u061f\",\"answer\":\"\\u0642\\u062f \\u062a\\u062e\\u062a\\u0644\\u0641 \\u0623\\u0648\\u0642\\u0627\\u062a \\u0627\\u0644\\u0633\\u062d\\u0628 \\u062d\\u0633\\u0628 \\u0627\\u0644\\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u0645\\u062e\\u062a\\u0627\\u0631\\u0629. \\u062a\\u0633\\u062a\\u063a\\u0631\\u0642 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0635\\u0631\\u0641\\u064a\\u0629 \\u0639\\u0627\\u062f\\u0629\\u064b \\u0645\\u0646 1 \\u0625\\u0644\\u0649 3 \\u0623\\u064a\\u0627\\u0645 \\u0639\\u0645\\u0644\\u060c \\u0641\\u064a \\u062d\\u064a\\u0646 \\u0623\\u0646 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0645\\u062d\\u0641\\u0638\\u0629 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a\\u0629 \\u063a\\u0627\\u0644\\u0628\\u064b\\u0627 \\u0645\\u0627 \\u062a\\u0643\\u0648\\u0646 \\u0623\\u0633\\u0631\\u0639. \\u0633\\u062a\\u062a\\u0644\\u0642\\u0649 \\u0625\\u0634\\u0639\\u0627\\u0631\\u064b\\u0627 \\u0628\\u0645\\u062c\\u0631\\u062f \\u0627\\u0643\\u062a\\u0645\\u0627\\u0644 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0646\\u0642\\u0644.\"},\"es\":{\"question\":\"\\u00bfCu\\u00e1nto tiempo se tarda en retirar dinero de QRPay Pro?\",\"answer\":\"Los tiempos de retiro pueden variar seg\\u00fan el m\\u00e9todo elegido. Las transferencias bancarias generalmente demoran entre 1 y 3 d\\u00edas h\\u00e1biles, mientras que las transferencias de billetera digital suelen ser m\\u00e1s r\\u00e1pidas. Recibir\\u00e1s una notificaci\\u00f3n una vez que se complete la transferencia.\"},\"fr\":{\"question\":\"Combien de temps faut-il pour retirer de l\'argent de QRPay Pro ?\",\"answer\":\"Les d\\u00e9lais de retrait peuvent varier selon la m\\u00e9thode choisie. Les virements bancaires prennent g\\u00e9n\\u00e9ralement 1 \\u00e0 3 jours ouvrables, tandis que les transferts de portefeuille num\\u00e9rique sont souvent plus rapides. Vous recevrez une notification une fois le transfert termin\\u00e9.\"},\"hi\":{\"question\":\"QRPay Pro \\u0938\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u0947 \\u092e\\u0947\\u0902 \\u0915\\u093f\\u0924\\u0928\\u093e \\u0938\\u092e\\u092f \\u0932\\u0917\\u0924\\u093e \\u0939\\u0948?\",\"answer\":\"\\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0915\\u093e \\u0938\\u092e\\u092f \\u091a\\u0941\\u0928\\u0940 \\u0917\\u0908 \\u0935\\u093f\\u0927\\u093f \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u092d\\u093f\\u0928\\u094d\\u0928 \\u0939\\u094b \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u092c\\u0948\\u0902\\u0915 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u092e\\u0947\\u0902 \\u0906\\u092e \\u0924\\u094c\\u0930 \\u092a\\u0930 1-3 \\u0915\\u093e\\u0930\\u094d\\u092f\\u0926\\u093f\\u0935\\u0938 \\u0932\\u0917\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u091c\\u092c\\u0915\\u093f \\u0921\\u093f\\u091c\\u093f\\u091f\\u0932 \\u0935\\u0949\\u0932\\u0947\\u091f \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u0924\\u0947\\u091c\\u093c \\u0939\\u094b\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u0923 \\u092a\\u0942\\u0930\\u093e \\u0939\\u094b\\u0924\\u0947 \\u0939\\u0940 \\u0906\\u092a\\u0915\\u094b \\u090f\\u0915 \\u0938\\u0942\\u091a\\u0928\\u093e \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0939\\u094b\\u0917\\u0940\\u0964\"}},\"id\":\"6724b9ed0c9d7\"},\"6724b9f78212d\":{\"language\":{\"en\":{\"question\":\"What are the fees associated with withdrawals on QRPay Pro?\",\"answer\":\"QRPay Pro may charge a small fee for withdrawals, depending on the transfer method and destination. You\\u2019ll be able to view any applicable fees before confirming the withdrawal.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0647\\u064a \\u0627\\u0644\\u0631\\u0633\\u0648\\u0645 \\u0627\\u0644\\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0639\\u0644\\u0649 QRPay Pro\\u061f\",\"answer\":\"\\u0642\\u062f \\u064a\\u0641\\u0631\\u0636 QRPay Pro \\u0631\\u0633\\u0648\\u0645\\u064b\\u0627 \\u0628\\u0633\\u064a\\u0637\\u0629 \\u0639\\u0644\\u0649 \\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0627\\u0644\\u0633\\u062d\\u0628\\u060c \\u0627\\u0639\\u062a\\u0645\\u0627\\u062f\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0648\\u0627\\u0644\\u0648\\u062c\\u0647\\u0629. \\u0633\\u062a\\u062a\\u0645\\u0643\\u0646 \\u0645\\u0646 \\u0639\\u0631\\u0636 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0637\\u0628\\u0642\\u0629 \\u0642\\u0628\\u0644 \\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0633\\u062d\\u0628.\"},\"es\":{\"question\":\"\\u00bfCu\\u00e1les son las tarifas asociadas con los retiros en QRPay Pro?\",\"answer\":\"QRPay Pro puede cobrar una peque\\u00f1a tarifa por los retiros, seg\\u00fan el m\\u00e9todo de transferencia y el destino. Podr\\u00e1s ver las tarifas aplicables antes de confirmar el retiro.\"},\"fr\":{\"question\":\"Quels sont les frais associ\\u00e9s aux retraits sur QRPay Pro ?\",\"answer\":\"QRPay Pro peut facturer des frais minimes pour les retraits, en fonction de la m\\u00e9thode de transfert et de la destination. Vous pourrez consulter tous les frais applicables avant de confirmer le retrait.\"},\"hi\":{\"question\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u0930 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0938\\u0947 \\u091c\\u0941\\u0921\\u093c\\u0940 \\u092b\\u0940\\u0938 \\u0915\\u094d\\u092f\\u093e \\u0939\\u0948?\",\"answer\":\"\\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0935\\u093f\\u0927\\u093f \\u0914\\u0930 \\u0917\\u0902\\u0924\\u0935\\u094d\\u092f \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930, QRPay Pro \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u090f\\u0915 \\u091b\\u094b\\u091f\\u093e \\u0938\\u093e \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0932\\u0947 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0906\\u092a \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u0915\\u094b\\u0908 \\u092d\\u0940 \\u0932\\u093e\\u0917\\u0942 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0926\\u0947\\u0916 \\u0938\\u0915\\u0947\\u0902\\u0917\\u0947\\u0964\"}},\"id\":\"6724b9f78212d\"},\"6724ba008303b\":{\"language\":{\"en\":{\"question\":\"Can I withdraw money to multiple accounts?\",\"answer\":\"Yes, QRPay Pro allows you to set up multiple withdrawal methods, such as different bank accounts or digital wallets. Select your preferred account each time you make a withdrawal.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0627\\u062a \\u0645\\u062a\\u0639\\u062f\\u062f\\u0629\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u064a\\u062a\\u064a\\u062d \\u0644\\u0643 QRPay Pro \\u0625\\u0639\\u062f\\u0627\\u062f \\u0637\\u0631\\u0642 \\u0633\\u062d\\u0628 \\u0645\\u062a\\u0639\\u062f\\u062f\\u0629\\u060c \\u0645\\u062b\\u0644 \\u0627\\u0644\\u062d\\u0633\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u0645\\u0635\\u0631\\u0641\\u064a\\u0629 \\u0627\\u0644\\u0645\\u062e\\u062a\\u0644\\u0641\\u0629 \\u0623\\u0648 \\u0627\\u0644\\u0645\\u062d\\u0627\\u0641\\u0638 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a\\u0629. \\u0627\\u062e\\u062a\\u0631 \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0627\\u0644\\u0645\\u0641\\u0636\\u0644 \\u0641\\u064a \\u0643\\u0644 \\u0645\\u0631\\u0629 \\u062a\\u0642\\u0648\\u0645 \\u0641\\u064a\\u0647\\u0627 \\u0628\\u0627\\u0644\\u0633\\u062d\\u0628.\"},\"es\":{\"question\":\"\\u00bfPuedo retirar dinero a varias cuentas?\",\"answer\":\"S\\u00ed, QRPay Pro te permite configurar m\\u00faltiples m\\u00e9todos de retiro, como diferentes cuentas bancarias o billeteras digitales. Seleccione su cuenta preferida cada vez que realice un retiro.\"},\"fr\":{\"question\":\"Puis-je retirer de l\\u2019argent sur plusieurs comptes ?\",\"answer\":\"Oui, QRPay Pro vous permet de configurer plusieurs m\\u00e9thodes de retrait, telles que diff\\u00e9rents comptes bancaires ou portefeuilles num\\u00e9riques. S\\u00e9lectionnez votre compte pr\\u00e9f\\u00e9r\\u00e9 \\u00e0 chaque fois que vous effectuez un retrait.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u0915\\u0908 \\u0916\\u093e\\u0924\\u094b\\u0902 \\u0938\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0939\\u093e\\u0902, QRPay Pro \\u0906\\u092a\\u0915\\u094b \\u0915\\u0908 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0935\\u093f\\u0927\\u093f\\u092f\\u093e\\u0902 \\u0938\\u0947\\u091f \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0940 \\u0905\\u0928\\u0941\\u092e\\u0924\\u093f \\u0926\\u0947\\u0924\\u093e \\u0939\\u0948, \\u091c\\u0948\\u0938\\u0947 \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u092c\\u0948\\u0902\\u0915 \\u0916\\u093e\\u0924\\u0947 \\u092f\\u093e \\u0921\\u093f\\u091c\\u093f\\u091f\\u0932 \\u0935\\u0949\\u0932\\u0947\\u091f\\u0964 \\u0939\\u0930 \\u092c\\u093e\\u0930 \\u091c\\u092c \\u0906\\u092a \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0915\\u0930\\u0947\\u0902 \\u0924\\u094b \\u0905\\u092a\\u0928\\u093e \\u092a\\u0938\\u0902\\u0926\\u0940\\u0926\\u093e \\u0916\\u093e\\u0924\\u093e \\u091a\\u0941\\u0928\\u0947\\u0902\\u0964\"}},\"id\":\"6724ba008303b\"},\"6724ba0d8176c\":{\"language\":{\"en\":{\"question\":\"Are there withdrawal limits on QRPay Pro?\",\"answer\":\"QRPay Pro may impose daily or transaction-based withdrawal limits based on your account level and regional regulations. You can view your specific limits in your QRPay Pro dashboard under Withdrawal Settings.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u062d\\u062f\\u0648\\u062f \\u0644\\u0644\\u0633\\u062d\\u0628 \\u0639\\u0644\\u0649 QRPay Pro\\u061f\",\"answer\":\"\\u0642\\u062f \\u064a\\u0641\\u0631\\u0636 QRPay Pro \\u062d\\u062f\\u0648\\u062f \\u0633\\u062d\\u0628 \\u064a\\u0648\\u0645\\u064a\\u0629 \\u0623\\u0648 \\u0642\\u0627\\u0626\\u0645\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0628\\u0646\\u0627\\u0621\\u064b \\u0639\\u0644\\u0649 \\u0645\\u0633\\u062a\\u0648\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0648\\u0627\\u0644\\u0644\\u0648\\u0627\\u0626\\u062d \\u0627\\u0644\\u0625\\u0642\\u0644\\u064a\\u0645\\u064a\\u0629. \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0639\\u0631\\u0636 \\u062d\\u062f\\u0648\\u062f\\u0643 \\u0627\\u0644\\u0645\\u062d\\u062f\\u062f\\u0629 \\u0641\\u064a \\u0644\\u0648\\u062d\\u0629 \\u062a\\u062d\\u0643\\u0645 QRPay Pro \\u0636\\u0645\\u0646 \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u0627\\u0644\\u0633\\u062d\\u0628.\"},\"es\":{\"question\":\"\\u00bfExisten l\\u00edmites de retiro en QRPay Pro?\",\"answer\":\"QRPay Pro puede imponer l\\u00edmites de retiro diarios o basados \\u200b\\u200ben transacciones seg\\u00fan el nivel de su cuenta y las regulaciones regionales. Puede ver sus l\\u00edmites espec\\u00edficos en su panel de QRPay Pro en Configuraci\\u00f3n de retiro.\"},\"fr\":{\"question\":\"Y a-t-il des limites de retrait sur QRPay Pro ?\",\"answer\":\"QRPay Pro peut imposer des limites de retrait quotidiennes ou bas\\u00e9es sur les transactions en fonction du niveau de votre compte et des r\\u00e9glementations r\\u00e9gionales. Vous pouvez consulter vos limites sp\\u00e9cifiques dans votre tableau de bord QRPay Pro sous Param\\u00e8tres de retrait.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e QRPay Pro \\u092a\\u0930 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0915\\u0940 \\u0915\\u094b\\u0908 \\u0938\\u0940\\u092e\\u093e \\u0939\\u0948?\",\"answer\":\"QRPay Pro \\u0906\\u092a\\u0915\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u0915\\u0947 \\u0938\\u094d\\u0924\\u0930 \\u0914\\u0930 \\u0915\\u094d\\u0937\\u0947\\u0924\\u094d\\u0930\\u0940\\u092f \\u0928\\u093f\\u092f\\u092e\\u094b\\u0902 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0926\\u0948\\u0928\\u093f\\u0915 \\u092f\\u093e \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928-\\u0906\\u0927\\u093e\\u0930\\u093f\\u0924 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0938\\u0940\\u092e\\u093e \\u0932\\u0917\\u093e \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0906\\u092a \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917\\u094d\\u0938 \\u0915\\u0947 \\u0924\\u0939\\u0924 \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0921\\u0948\\u0936\\u092c\\u094b\\u0930\\u094d\\u0921 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0940 \\u0935\\u093f\\u0936\\u093f\\u0937\\u094d\\u091f \\u0938\\u0940\\u092e\\u093e\\u090f\\u0901 \\u0926\\u0947\\u0916 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724ba0d8176c\"}}}', 1, 1, '2024-11-01 17:22:09', '2024-11-06 17:54:27');
INSERT INTO `frontend_header_section_faqs` VALUES (22, 22, 'business', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About Gateway Settings\",\"sub_heading\":\"Learn more about configuring and managing your QRPay Pro payment gateway.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u0627\\u0644\\u0628\\u0648\\u0627\\u0628\\u0629\",\"sub_heading\":\"\\u062a\\u0639\\u0631\\u0641 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0632\\u064a\\u062f \\u062d\\u0648\\u0644 \\u062a\\u0643\\u0648\\u064a\\u0646 \\u0648\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0628\\u0648\\u0627\\u0628\\u0629 \\u0627\\u0644\\u062f\\u0641\\u0639 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre la configuraci\\u00f3n de la puerta de enlace\",\"sub_heading\":\"Obtenga m\\u00e1s informaci\\u00f3n sobre c\\u00f3mo configurar y administrar su pasarela de pago QRPay Pro.\"},\"fr\":{\"heading\":\"Questions fr\\u00e9quemment pos\\u00e9es sur les param\\u00e8tres de la passerelle\",\"sub_heading\":\"Apprenez-en davantage sur la configuration et la gestion de votre passerelle de paiement QRPay Pro.\"},\"hi\":{\"heading\":\"\\u0917\\u0947\\u091f\\u0935\\u0947 \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917\\u094d\\u0938 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"\\u0905\\u092a\\u0928\\u0947 QRPay Pro \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0917\\u0947\\u091f\\u0935\\u0947 \\u0915\\u094b \\u0915\\u0949\\u0928\\u094d\\u092b\\u093c\\u093f\\u0917\\u0930 \\u0915\\u0930\\u0928\\u0947 \\u0914\\u0930 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0927\\u093f\\u0915 \\u091c\\u093e\\u0928\\u0947\\u0902\\u0964\"}},\"items\":{\"6724baa2af921\":{\"language\":{\"en\":{\"question\":\"Can I integrate QRPay Pro\\u2019s payment gateway with my existing e-commerce platform?\",\"answer\":\"Yes, QRPay Pro\\u2019s payment gateway is designed to integrate seamlessly with various e-commerce platforms. Generate API keys from the QRPay Pro dashboard and follow the integration guide for a smooth setup.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u062f\\u0645\\u062c \\u0628\\u0648\\u0627\\u0628\\u0629 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0640 QRPay Pro \\u0645\\u0639 \\u0645\\u0646\\u0635\\u0629 \\u0627\\u0644\\u062a\\u062c\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0625\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a\\u0629 \\u0627\\u0644\\u062d\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u064a\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u062a\\u0645 \\u062a\\u0635\\u0645\\u064a\\u0645 \\u0628\\u0648\\u0627\\u0628\\u0629 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0640 QRPay Pro \\u0644\\u062a\\u062a\\u0643\\u0627\\u0645\\u0644 \\u0628\\u0633\\u0644\\u0627\\u0633\\u0629 \\u0645\\u0639 \\u0645\\u0646\\u0635\\u0627\\u062a \\u0627\\u0644\\u062a\\u062c\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0625\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a\\u0629 \\u0627\\u0644\\u0645\\u062e\\u062a\\u0644\\u0641\\u0629. \\u0642\\u0645 \\u0628\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0645\\u0641\\u0627\\u062a\\u064a\\u062d API \\u0645\\u0646 \\u0644\\u0648\\u062d\\u0629 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a QRPay Pro \\u0648\\u0627\\u062a\\u0628\\u0639 \\u062f\\u0644\\u064a\\u0644 \\u0627\\u0644\\u062a\\u0643\\u0627\\u0645\\u0644 \\u0644\\u0625\\u0639\\u062f\\u0627\\u062f \\u0633\\u0644\\u0633.\"},\"es\":{\"question\":\"\\u00bfPuedo integrar la pasarela de pago de QRPay Pro con mi\",\"answer\":\"S\\u00ed, la pasarela de pago de QRPay Pro est\\u00e1 dise\\u00f1ada para integrarse perfectamente con varias plataformas de comercio electr\\u00f3nico. Genere claves API desde el panel de QRPay Pro y siga la gu\\u00eda de integraci\\u00f3n para una configuraci\\u00f3n sin problemas.\"},\"fr\":{\"question\":\"Puis-je int\\u00e9grer la passerelle de paiement QRPay\",\"answer\":\"Oui, la passerelle de paiement de QRPay Pro est con\\u00e7ue pour s\'int\\u00e9grer de mani\\u00e8re transparente \\u00e0 diverses plateformes de commerce \\u00e9lectronique. G\\u00e9n\\u00e9rez des cl\\u00e9s API \\u00e0 partir du tableau de bord QRPay Pro et suivez le guide d\'int\\u00e9gration pour une configuration fluide.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 QRPay Pro \\u0915\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0917\\u0947\\u091f\\u0935\\u0947 \\u0915\\u094b \\u0905\\u092a\\u0928\\u0947 \\u092e\\u094c\\u091c\\u0942\\u0926\\u093e \\u0908-\\u0915\\u0949\\u092e\\u0930\\u094d\\u0938 \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u0949\\u0930\\u094d\\u092e \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u090f\\u0915\\u0940\\u0915\\u0943\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0902?\",\"answer\":\"\\u0939\\u093e\\u0901, QRPay Pro \\u0915\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0917\\u0947\\u091f\\u0935\\u0947 \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u0908-\\u0915\\u0949\\u092e\\u0930\\u094d\\u0938 \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093e\\u0930\\u094d\\u092e\\u094b\\u0902 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0938\\u0939\\u091c\\u0924\\u093e \\u0938\\u0947 \\u090f\\u0915\\u0940\\u0915\\u0943\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0921\\u093f\\u091c\\u093c\\u093e\\u0907\\u0928 \\u0915\\u093f\\u092f\\u093e \\u0917\\u092f\\u093e \\u0939\\u0948\\u0964 QRPay Pro \\u0921\\u0948\\u0936\\u092c\\u094b\\u0930\\u094d\\u0921 \\u0938\\u0947 API \\u0915\\u0941\\u0902\\u091c\\u0940 \\u091c\\u0947\\u0928\\u0930\\u0947\\u091f \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u0938\\u0941\\u091a\\u093e\\u0930\\u0942 \\u0938\\u0947\\u091f\\u0905\\u092a \\u0915\\u0947 \\u0932\\u093f\\u090f \\u090f\\u0915\\u0940\\u0915\\u0930\\u0923 \\u0917\\u093e\\u0907\\u0921 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724baa2af921\"},\"6724baaee5bf9\":{\"language\":{\"en\":{\"question\":\"How secure is the QRPay Pro payment gateway?\",\"answer\":\"QRPay Pro uses top-tier security measures, including encryption and 2FA, to ensure that all transactions are protected. You can also enable additional security settings in the Gateway Settings for enhanced protection.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0645\\u062f\\u0649 \\u0623\\u0645\\u0627\\u0646 \\u0628\\u0648\\u0627\\u0628\\u0629 \\u0627\\u0644\\u062f\\u0641\\u0639 QRPay Pro\\u061f\",\"answer\":\"\\u064a\\u0633\\u062a\\u062e\\u062f\\u0645 QRPay Pro \\u062a\\u062f\\u0627\\u0628\\u064a\\u0631 \\u0623\\u0645\\u0646\\u064a\\u0629 \\u0639\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0648\\u0649\\u060c \\u0628\\u0645\\u0627 \\u0641\\u064a \\u0630\\u0644\\u0643 \\u0627\\u0644\\u062a\\u0634\\u0641\\u064a\\u0631 \\u0648\\u0627\\u0644\\u0645\\u0635\\u0627\\u062f\\u0642\\u0629 \\u0627\\u0644\\u062b\\u0646\\u0627\\u0626\\u064a\\u0629 (2FA)\\u060c \\u0644\\u0636\\u0645\\u0627\\u0646 \\u062d\\u0645\\u0627\\u064a\\u0629 \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a. \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0623\\u064a\\u0636\\u064b\\u0627 \\u062a\\u0645\\u0643\\u064a\\u0646 \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u0627\\u0644\\u0623\\u0645\\u0627\\u0646 \\u0627\\u0644\\u0625\\u0636\\u0627\\u0641\\u064a\\u0629 \\u0641\\u064a \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u0627\\u0644\\u0628\\u0648\\u0627\\u0628\\u0629 \\u0644\\u062a\\u0639\\u0632\\u064a\\u0632 \\u0627\\u0644\\u062d\\u0645\\u0627\\u064a\\u0629.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 tan segura es la pasarela de pago QRPay Pro?\",\"answer\":\"QRPay Pro utiliza medidas de seguridad de primer nivel, incluido el cifrado y 2FA, para garantizar que todas las transacciones est\\u00e9n protegidas. Tambi\\u00e9n puede habilitar configuraciones de seguridad adicionales en la Configuraci\\u00f3n de la puerta de enlace para una protecci\\u00f3n mejorada.\"},\"fr\":{\"question\":\"Dans quelle mesure la passerelle de paiement QRPay Pro est-elle s\\u00e9curis\\u00e9e\\u00a0?\",\"answer\":\"QRPay Pro utilise des mesures de s\\u00e9curit\\u00e9 de haut niveau, notamment le cryptage et le 2FA, pour garantir que toutes les transactions sont prot\\u00e9g\\u00e9es. Vous pouvez \\u00e9galement activer des param\\u00e8tres de s\\u00e9curit\\u00e9 suppl\\u00e9mentaires dans les param\\u00e8tres de la passerelle pour une protection am\\u00e9lior\\u00e9e.\"},\"hi\":{\"question\":\"QRPay Pro \\u092a\\u0947\\u092e\\u0947\\u0902\\u091f \\u0917\\u0947\\u091f\\u0935\\u0947 \\u0915\\u093f\\u0924\\u0928\\u093e \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0939\\u0948?\",\"answer\":\"\\u092f\\u0939 \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u093f \\u0938\\u092d\\u0940 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0939\\u0948\\u0902, QRPay Pro \\u090f\\u0928\\u094d\\u0915\\u094d\\u0930\\u093f\\u092a\\u094d\\u0936\\u0928 \\u0914\\u0930 2FA \\u0938\\u0939\\u093f\\u0924 \\u0936\\u0940\\u0930\\u094d\\u0937 \\u0938\\u094d\\u0924\\u0930\\u0940\\u092f \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0909\\u092a\\u093e\\u092f\\u094b\\u0902 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948\\u0964 \\u092c\\u0947\\u0939\\u0924\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0906\\u092a \\u0917\\u0947\\u091f\\u0935\\u0947 \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917\\u094d\\u0938 \\u092e\\u0947\\u0902 \\u0905\\u0924\\u093f\\u0930\\u093f\\u0915\\u094d\\u0924 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917\\u094d\\u0938 \\u092d\\u0940 \\u0938\\u0915\\u094d\\u0937\\u092e \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724baaee5bf9\"},\"6724bab99f88e\":{\"language\":{\"en\":{\"question\":\"What payment methods can I offer through QRPay Pro\\u2019s gateway?\",\"answer\":\"QRPay Pro supports multiple payment methods, including QR code payments, bank transfers, and digital wallet options. Customize your available methods in the Gateway Settings to meet your customers\' needs.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0647\\u064a \\u0637\\u0631\\u0642 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062a\\u064a \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u062a\\u0642\\u062f\\u064a\\u0645\\u0647\\u0627 \\u0639\\u0628\\u0631 \\u0628\\u0648\\u0627\\u0628\\u0629 QRPay Pro\\u061f\",\"answer\":\"\\u064a\\u062f\\u0639\\u0645 QRPay Pro \\u0637\\u0631\\u0642 \\u062f\\u0641\\u0639 \\u0645\\u062a\\u0639\\u062f\\u062f\\u0629\\u060c \\u0628\\u0645\\u0627 \\u0641\\u064a \\u0630\\u0644\\u0643 \\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0631\\u0645\\u0632 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639\\u0629 \\u0648\\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0635\\u0631\\u0641\\u064a\\u0629 \\u0648\\u062e\\u064a\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0645\\u062d\\u0641\\u0638\\u0629 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a\\u0629. \\u0642\\u0645 \\u0628\\u062a\\u062e\\u0635\\u064a\\u0635 \\u0627\\u0644\\u0637\\u0631\\u0642 \\u0627\\u0644\\u0645\\u062a\\u0627\\u062d\\u0629 \\u0644\\u062f\\u064a\\u0643 \\u0641\\u064a \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u0627\\u0644\\u0628\\u0648\\u0627\\u0628\\u0629 \\u0644\\u062a\\u0644\\u0628\\u064a\\u0629 \\u0627\\u062d\\u062a\\u064a\\u0627\\u062c\\u0627\\u062a \\u0639\\u0645\\u0644\\u0627\\u0626\\u0643.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 m\\u00e9todos de pago puedo ofrecer a trav\\u00e9s de la pasarela de QRPay Pro?\",\"answer\":\"QRPay Pro admite m\\u00faltiples m\\u00e9todos de pago, incluidos pagos con c\\u00f3digos QR, transferencias bancarias y opciones de billetera digital. Personalice sus m\\u00e9todos disponibles en la Configuraci\\u00f3n de la puerta de enlace para satisfacer las necesidades de sus clientes.\"},\"fr\":{\"question\":\"Quelles m\\u00e9thodes de paiement puis-je proposer via la passerelle QRPay Pro\\u00a0?\",\"answer\":\"QRPay Pro prend en charge plusieurs m\\u00e9thodes de paiement, notamment les paiements par code QR, les virements bancaires et les options de portefeuille num\\u00e9rique. Personnalisez vos m\\u00e9thodes disponibles dans les param\\u00e8tres de la passerelle pour r\\u00e9pondre aux besoins de vos clients.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0917\\u0947\\u091f\\u0935\\u0947 \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u0915\\u094c\\u0928 \\u0938\\u0940 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0935\\u093f\\u0927\\u093f\\u092f\\u093e\\u0902 \\u092a\\u0947\\u0936 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0902?\",\"answer\":\"QRPay Pro \\u0915\\u0908 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0935\\u093f\\u0927\\u093f\\u092f\\u094b\\u0902 \\u0915\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948, \\u091c\\u093f\\u0938\\u092e\\u0947\\u0902 QR \\u0915\\u094b\\u0921 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928, \\u092c\\u0948\\u0902\\u0915 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0914\\u0930 \\u0921\\u093f\\u091c\\u093f\\u091f\\u0932 \\u0935\\u0949\\u0932\\u0947\\u091f \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a \\u0936\\u093e\\u092e\\u093f\\u0932 \\u0939\\u0948\\u0902\\u0964 \\u0905\\u092a\\u0928\\u0947 \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915\\u094b\\u0902 \\u0915\\u0940 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915\\u0924\\u093e\\u0913\\u0902 \\u0915\\u094b \\u092a\\u0942\\u0930\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0917\\u0947\\u091f\\u0935\\u0947 \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917\\u094d\\u0938 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0940 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0935\\u093f\\u0927\\u093f\\u092f\\u094b\\u0902 \\u0915\\u094b \\u0905\\u0928\\u0941\\u0915\\u0942\\u0932\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724bab99f88e\"},\"6724bac43610b\":{\"language\":{\"en\":{\"question\":\"Can I view transaction details for payments made through the gateway?\",\"answer\":\"Yes, QRPay Pro\\u2019s dashboard includes comprehensive transaction logs. You can track and review payment details, manage refunds, and analyze performance directly within the Gateway Settings.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0644\\u0627\\u0637\\u0644\\u0627\\u0639 \\u0639\\u0644\\u0649 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u062a\\u0645\\u062a \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0628\\u0648\\u0627\\u0628\\u0629\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u062a\\u062a\\u0636\\u0645\\u0646 \\u0644\\u0648\\u062d\\u0629 \\u062a\\u062d\\u0643\\u0645 QRPay Pro \\u0633\\u062c\\u0644\\u0627\\u062a \\u0634\\u0627\\u0645\\u0644\\u0629 \\u0644\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a. \\u064a\\u0645\\u0643\\u0646\\u0643 \\u062a\\u062a\\u0628\\u0639 \\u0648\\u0645\\u0631\\u0627\\u062c\\u0639\\u0629 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0648\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0645\\u0628\\u0627\\u0644\\u063a \\u0627\\u0644\\u0645\\u0633\\u062a\\u0631\\u062f\\u0629 \\u0648\\u062a\\u062d\\u0644\\u064a\\u0644 \\u0627\\u0644\\u0623\\u062f\\u0627\\u0621 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0636\\u0645\\u0646 \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u0627\\u0644\\u0628\\u0648\\u0627\\u0628\\u0629.\"},\"es\":{\"question\":\"\\u00bfPuedo ver los detalles de las transacciones de pagos realizados a trav\\u00e9s de la pasarela?\",\"answer\":\"S\\u00ed, el panel de control de QRPay Pro incluye registros de transacciones completos. Puede realizar un seguimiento y revisar los detalles de pago, administrar reembolsos y analizar el rendimiento directamente en la Configuraci\\u00f3n de la puerta de enlace.\"},\"fr\":{\"question\":\"Puis-je afficher les d\\u00e9tails des transactions pour les paiements effectu\\u00e9s via la passerelle\\u00a0?\",\"answer\":\"Oui, le tableau de bord de QRPay Pro comprend des journaux de transactions complets. Vous pouvez suivre et consulter les d\\u00e9tails du paiement, g\\u00e9rer les remboursements et analyser les performances directement dans les param\\u00e8tres de la passerelle.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u0917\\u0947\\u091f\\u0935\\u0947 \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u0915\\u093f\\u090f \\u0917\\u090f \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0947 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0926\\u0947\\u0916 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0939\\u093e\\u0901, QRPay Pro \\u0915\\u0947 \\u0921\\u0948\\u0936\\u092c\\u094b\\u0930\\u094d\\u0921 \\u092e\\u0947\\u0902 \\u0935\\u094d\\u092f\\u093e\\u092a\\u0915 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0932\\u0949\\u0917 \\u0936\\u093e\\u092e\\u093f\\u0932 \\u0939\\u0948\\u0902\\u0964 \\u0906\\u092a \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0935\\u093f\\u0935\\u0930\\u0923\\u094b\\u0902 \\u0915\\u094b \\u091f\\u094d\\u0930\\u0948\\u0915 \\u0914\\u0930 \\u0938\\u092e\\u0940\\u0915\\u094d\\u0937\\u093e \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0930\\u093f\\u092b\\u0902\\u0921 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902 \\u0914\\u0930 \\u0938\\u0940\\u0927\\u0947 \\u0917\\u0947\\u091f\\u0935\\u0947 \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917\\u094d\\u0938 \\u0915\\u0947 \\u092d\\u0940\\u0924\\u0930 \\u092a\\u094d\\u0930\\u0926\\u0930\\u094d\\u0936\\u0928 \\u0915\\u093e \\u0935\\u093f\\u0936\\u094d\\u0932\\u0947\\u0937\\u0923 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724bac43610b\"}}}', 1, 1, '2024-11-01 17:25:13', '2024-11-06 18:02:52');
INSERT INTO `frontend_header_section_faqs` VALUES (23, 23, 'business', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About API Key Management\",\"sub_heading\":\"Learn more about creating, using, and managing API keys with QRPay Pro\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0645\\u0641\\u0627\\u062a\\u064a\\u062d API\",\"sub_heading\":\"\\u062a\\u0639\\u0631\\u0641 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0632\\u064a\\u062f \\u062d\\u0648\\u0644 \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0645\\u0641\\u0627\\u062a\\u064a\\u062d API \\u0648\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645\\u0647\\u0627 \\u0648\\u0625\\u062f\\u0627\\u0631\\u062a\\u0647\\u0627 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre la gesti\\u00f3n de claves API\",\"sub_heading\":\"Obtenga m\\u00e1s informaci\\u00f3n sobre c\\u00f3mo crear, usar y administrar claves API con QRPay Pro\"},\"fr\":{\"heading\":\"Questions fr\\u00e9quemment pos\\u00e9es sur la gestion des cl\\u00e9s API\",\"sub_heading\":\"En savoir plus sur la cr\\u00e9ation, l\'utilisation et la gestion des cl\\u00e9s API avec QRPay Pro\"},\"hi\":{\"heading\":\"\\u090f\\u092a\\u0940\\u0906\\u0908 \\u0915\\u0941\\u0902\\u091c\\u0940 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u0928 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"QRPay Pro \\u0915\\u0947 \\u0938\\u093e\\u0925 API \\u0915\\u0941\\u0902\\u091c\\u093f\\u092f\\u093e\\u0901 \\u092c\\u0928\\u093e\\u0928\\u0947, \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0928\\u0947 \\u0914\\u0930 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0914\\u0930 \\u091c\\u093e\\u0928\\u0947\\u0902\"}},\"items\":{\"6724bb707bf2a\":{\"language\":{\"en\":{\"question\":\"How do I securely store my QRPay Pro API keys?\",\"answer\":\"Store your API keys in a secure environment, such as an encrypted server or a password manager, and avoid sharing keys with anyone. QRPay Pro also allows you to regenerate keys if you suspect any security risks.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u062a\\u062e\\u0632\\u064a\\u0646 \\u0645\\u0641\\u0627\\u062a\\u064a\\u062d QRPay Pro API \\u0628\\u0634\\u0643\\u0644 \\u0622\\u0645\\u0646\\u061f\",\"answer\":\"\\u0642\\u0645 \\u0628\\u062a\\u062e\\u0632\\u064a\\u0646 \\u0645\\u0641\\u0627\\u062a\\u064a\\u062d API \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643 \\u0641\\u064a \\u0628\\u064a\\u0626\\u0629 \\u0622\\u0645\\u0646\\u0629\\u060c \\u0645\\u062b\\u0644 \\u062e\\u0627\\u062f\\u0645 \\u0645\\u0634\\u0641\\u0631 \\u0623\\u0648 \\u0645\\u062f\\u064a\\u0631 \\u0643\\u0644\\u0645\\u0627\\u062a \\u0627\\u0644\\u0645\\u0631\\u0648\\u0631\\u060c \\u0648\\u062a\\u062c\\u0646\\u0628 \\u0645\\u0634\\u0627\\u0631\\u0643\\u0629 \\u0627\\u0644\\u0645\\u0641\\u0627\\u062a\\u064a\\u062d \\u0645\\u0639 \\u0623\\u064a \\u0634\\u062e\\u0635. \\u064a\\u0633\\u0645\\u062d \\u0644\\u0643 QRPay Pro \\u0623\\u064a\\u0636\\u064b\\u0627 \\u0628\\u0625\\u0639\\u0627\\u062f\\u0629 \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0627\\u0644\\u0645\\u0641\\u0627\\u062a\\u064a\\u062d \\u0625\\u0630\\u0627 \\u0643\\u0646\\u062a \\u062a\\u0634\\u0643 \\u0641\\u064a \\u0648\\u062c\\u0648\\u062f \\u0623\\u064a \\u0645\\u062e\\u0627\\u0637\\u0631 \\u0623\\u0645\\u0646\\u064a\\u0629.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo almaceno de forma segura mis claves API de QRPay Pro?\",\"answer\":\"Guarde sus claves API en un entorno seguro, como un servidor cifrado o un administrador de contrase\\u00f1as, y evite compartir claves con nadie. QRPay Pro tambi\\u00e9n le permite regenerar claves si sospecha alg\\u00fan riesgo de seguridad.\"},\"fr\":{\"question\":\"Comment stocker en toute s\\u00e9curit\\u00e9 mes cl\\u00e9s API QRPay Pro\\u00a0?\",\"answer\":\"Stockez vos cl\\u00e9s API dans un environnement s\\u00e9curis\\u00e9, tel qu\'un serveur crypt\\u00e9 ou un gestionnaire de mots de passe, et \\u00e9vitez de partager vos cl\\u00e9s avec qui que ce soit. QRPay Pro vous permet \\u00e9galement de r\\u00e9g\\u00e9n\\u00e9rer les cl\\u00e9s si vous soup\\u00e7onnez des risques de s\\u00e9curit\\u00e9.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 \\u0905\\u092a\\u0928\\u0940 QRPay \\u092a\\u094d\\u0930\\u094b \\u090f\\u092a\\u0940\\u0906\\u0908 \\u0915\\u0941\\u0902\\u091c\\u093f\\u092f\\u094b\\u0902 \\u0915\\u094b \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u0938\\u0902\\u0917\\u094d\\u0930\\u0939\\u0940\\u0924 \\u0915\\u0930\\u0942\\u0902?\",\"answer\":\"\\u0905\\u092a\\u0928\\u0940 \\u090f\\u092a\\u0940\\u0906\\u0908 \\u0915\\u0941\\u0902\\u091c\\u093f\\u092f\\u094b\\u0902 \\u0915\\u094b \\u090f\\u0915 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0935\\u093e\\u0924\\u093e\\u0935\\u0930\\u0923 \\u092e\\u0947\\u0902 \\u0938\\u0902\\u0917\\u094d\\u0930\\u0939\\u0940\\u0924 \\u0915\\u0930\\u0947\\u0902, \\u091c\\u0948\\u0938\\u0947 \\u090f\\u0928\\u094d\\u0915\\u094d\\u0930\\u093f\\u092a\\u094d\\u091f\\u0947\\u0921 \\u0938\\u0930\\u094d\\u0935\\u0930 \\u092f\\u093e \\u092a\\u093e\\u0938\\u0935\\u0930\\u094d\\u0921 \\u092e\\u0948\\u0928\\u0947\\u091c\\u0930, \\u0914\\u0930 \\u0915\\u093f\\u0938\\u0940 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0915\\u0941\\u0902\\u091c\\u093f\\u092f\\u093e\\u0901 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u092c\\u091a\\u0947\\u0902\\u0964 \\u092f\\u0926\\u093f \\u0906\\u092a\\u0915\\u094b \\u0915\\u093f\\u0938\\u0940 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u091c\\u094b\\u0916\\u093f\\u092e \\u0915\\u093e \\u0938\\u0902\\u0926\\u0947\\u0939 \\u0939\\u0948 \\u0924\\u094b QRPay \\u092a\\u094d\\u0930\\u094b \\u0906\\u092a\\u0915\\u094b \\u091a\\u093e\\u092c\\u093f\\u092f\\u093e\\u0901 \\u092a\\u0941\\u0928: \\u0909\\u0924\\u094d\\u092a\\u0928\\u094d\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0940 \\u092d\\u0940 \\u0905\\u0928\\u0941\\u092e\\u0924\\u093f \\u0926\\u0947\\u0924\\u093e \\u0939\\u0948\\u0964\"}},\"id\":\"6724bb707bf2a\"},\"6724bb7b309e9\":{\"language\":{\"en\":{\"question\":\"Can I create multiple API keys for different uses?\",\"answer\":\"Yes, QRPay Pro allows you to generate multiple API keys with specific permissions for each, so you can control access based on usage, team members, or integration needs.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0645\\u0641\\u0627\\u062a\\u064a\\u062d API \\u0645\\u062a\\u0639\\u062f\\u062f\\u0629 \\u0644\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645\\u0627\\u062a \\u0645\\u062e\\u062a\\u0644\\u0641\\u0629\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u064a\\u062a\\u064a\\u062d \\u0644\\u0643 QRPay Pro \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0645\\u0641\\u0627\\u062a\\u064a\\u062d API \\u0645\\u062a\\u0639\\u062f\\u062f\\u0629 \\u0628\\u0623\\u0630\\u0648\\u0646\\u0627\\u062a \\u0645\\u062d\\u062f\\u062f\\u0629 \\u0644\\u0643\\u0644 \\u0645\\u0646\\u0647\\u0627\\u060c \\u062d\\u062a\\u0649 \\u062a\\u062a\\u0645\\u0643\\u0646 \\u0645\\u0646 \\u0627\\u0644\\u062a\\u062d\\u0643\\u0645 \\u0641\\u064a \\u0627\\u0644\\u0648\\u0635\\u0648\\u0644 \\u0628\\u0646\\u0627\\u0621\\u064b \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0623\\u0648 \\u0623\\u0639\\u0636\\u0627\\u0621 \\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0623\\u0648 \\u0627\\u062d\\u062a\\u064a\\u0627\\u062c\\u0627\\u062a \\u0627\\u0644\\u062a\\u0643\\u0627\\u0645\\u0644.\"},\"es\":{\"question\":\"\\u00bfPuedo crear varias claves API para diferentes usos?\",\"answer\":\"S\\u00ed, QRPay Pro te permite generar m\\u00faltiples claves API con permisos espec\\u00edficos para cada una, para que puedas controlar el acceso seg\\u00fan el uso, los miembros del equipo o las necesidades de integraci\\u00f3n.\"},\"fr\":{\"question\":\"Puis-je cr\\u00e9er plusieurs cl\\u00e9s API pour diff\\u00e9rentes utilisations\\u00a0?\",\"answer\":\"Oui, QRPay Pro vous permet de g\\u00e9n\\u00e9rer plusieurs cl\\u00e9s API avec des autorisations sp\\u00e9cifiques pour chacune, afin que vous puissiez contr\\u00f4ler l\'acc\\u00e8s en fonction de l\'utilisation, des membres de l\'\\u00e9quipe ou des besoins d\'int\\u00e9gration.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u0909\\u092a\\u092f\\u094b\\u0917\\u094b\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u090f\\u0915\\u093e\\u0927\\u093f\\u0915 \\u090f\\u092a\\u0940\\u0906\\u0908 \\u0915\\u0941\\u0902\\u091c\\u093f\\u092f\\u093e\\u0901 \\u092c\\u0928\\u093e \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0939\\u093e\\u0902, QRPay \\u092a\\u094d\\u0930\\u094b \\u0906\\u092a\\u0915\\u094b \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0935\\u093f\\u0936\\u093f\\u0937\\u094d\\u091f \\u0905\\u0928\\u0941\\u092e\\u0924\\u093f\\u092f\\u094b\\u0902 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0915\\u0908 \\u090f\\u092a\\u0940\\u0906\\u0908 \\u0915\\u0941\\u0902\\u091c\\u0940 \\u0909\\u0924\\u094d\\u092a\\u0928\\u094d\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0940 \\u0905\\u0928\\u0941\\u092e\\u0924\\u093f \\u0926\\u0947\\u0924\\u093e \\u0939\\u0948, \\u0924\\u093e\\u0915\\u093f \\u0906\\u092a \\u0909\\u092a\\u092f\\u094b\\u0917, \\u091f\\u0940\\u092e \\u0915\\u0947 \\u0938\\u0926\\u0938\\u094d\\u092f\\u094b\\u0902 \\u092f\\u093e \\u090f\\u0915\\u0940\\u0915\\u0930\\u0923 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915\\u0924\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u092a\\u0939\\u0941\\u0902\\u091a \\u0915\\u094b \\u0928\\u093f\\u092f\\u0902\\u0924\\u094d\\u0930\\u093f\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0947\\u0902\\u0964\"}},\"id\":\"6724bb7b309e9\"},\"6724bb84d207e\":{\"language\":{\"en\":{\"question\":\"What should I do if my API key is compromised?\",\"answer\":\"If your API key is compromised, immediately revoke it through the QRPay Pro dashboard and generate a new key. QRPay Pro\\u2019s secure dashboard allows for easy key management to protect your platform.\"},\"ar\":{\"question\":\"\\u0645\\u0627\\u0630\\u0627 \\u0639\\u0644\\u064a \\u0623\\u0646 \\u0623\\u0641\\u0639\\u0644 \\u0625\\u0630\\u0627 \\u062a\\u0645 \\u0627\\u062e\\u062a\\u0631\\u0627\\u0642 \\u0645\\u0641\\u062a\\u0627\\u062d API \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u064a\\u061f\",\"answer\":\"\\u0625\\u0630\\u0627 \\u062a\\u0645 \\u0627\\u062e\\u062a\\u0631\\u0627\\u0642 \\u0645\\u0641\\u062a\\u0627\\u062d API \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\\u060c \\u0641\\u0642\\u0645 \\u0628\\u0625\\u0644\\u063a\\u0627\\u0626\\u0647 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0644\\u0648\\u062d\\u0629 \\u062a\\u062d\\u0643\\u0645 QRPay Pro \\u0648\\u0642\\u0645 \\u0628\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0645\\u0641\\u062a\\u0627\\u062d \\u062c\\u062f\\u064a\\u062f. \\u062a\\u0633\\u0645\\u062d \\u0644\\u0648\\u062d\\u0629 \\u0627\\u0644\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0627\\u0644\\u0622\\u0645\\u0646\\u0629 \\u0644\\u0640 QRPay Pro \\u0628\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0645\\u0641\\u0627\\u062a\\u064a\\u062d \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0644\\u062d\\u0645\\u0627\\u064a\\u0629 \\u0627\\u0644\\u0646\\u0638\\u0627\\u0645 \\u0627\\u0644\\u0623\\u0633\\u0627\\u0633\\u064a \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 debo hacer si mi clave API est\\u00e1 comprometida?\",\"answer\":\"Si su clave API est\\u00e1 comprometida, revoquela inmediatamente a trav\\u00e9s del panel de QRPay Pro y genere una nueva clave. El panel seguro de QRPay Pro permite una f\\u00e1cil administraci\\u00f3n de claves para proteger su plataforma.\"},\"fr\":{\"question\":\"Que dois-je faire si ma cl\\u00e9 API est compromise\\u00a0?\",\"answer\":\"Si votre cl\\u00e9 API est compromise, r\\u00e9voquez-la imm\\u00e9diatement via le tableau de bord QRPay Pro et g\\u00e9n\\u00e9rez une nouvelle cl\\u00e9. Le tableau de bord s\\u00e9curis\\u00e9 de QRPay Pro permet une gestion facile des cl\\u00e9s pour prot\\u00e9ger votre plateforme.\"},\"hi\":{\"question\":\"\\u092f\\u0926\\u093f \\u092e\\u0947\\u0930\\u0940 \\u090f\\u092a\\u0940\\u0906\\u0908 \\u0915\\u0941\\u0902\\u091c\\u0940 \\u0938\\u0947 \\u091b\\u0947\\u0921\\u093c\\u091b\\u093e\\u0921\\u093c \\u0915\\u0940 \\u091c\\u093e\\u0924\\u0940 \\u0939\\u0948 \\u0924\\u094b \\u092e\\u0941\\u091d\\u0947 \\u0915\\u094d\\u092f\\u093e \\u0915\\u0930\\u0928\\u093e \\u091a\\u093e\\u0939\\u093f\\u090f?\",\"answer\":\"\\u092f\\u0926\\u093f \\u0906\\u092a\\u0915\\u0940 \\u090f\\u092a\\u0940\\u0906\\u0908 \\u0915\\u0941\\u0902\\u091c\\u0940 \\u0938\\u0947 \\u091b\\u0947\\u0921\\u093c\\u091b\\u093e\\u0921\\u093c \\u0915\\u0940 \\u0917\\u0908 \\u0939\\u0948, \\u0924\\u094b \\u0924\\u0941\\u0930\\u0902\\u0924 \\u0907\\u0938\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0921\\u0948\\u0936\\u092c\\u094b\\u0930\\u094d\\u0921 \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u0930\\u0926\\u094d\\u0926 \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u090f\\u0915 \\u0928\\u0908 \\u0915\\u0941\\u0902\\u091c\\u0940 \\u0909\\u0924\\u094d\\u092a\\u0928\\u094d\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964 QRPay Pro \\u0915\\u093e \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0921\\u0948\\u0936\\u092c\\u094b\\u0930\\u094d\\u0921 \\u0906\\u092a\\u0915\\u0947 \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e \\u0915\\u0940 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0906\\u0938\\u093e\\u0928 \\u0915\\u0941\\u0902\\u091c\\u0940 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u0928 \\u0915\\u0940 \\u0905\\u0928\\u0941\\u092e\\u0924\\u093f \\u0926\\u0947\\u0924\\u093e \\u0939\\u0948\\u0964\"}},\"id\":\"6724bb84d207e\"},\"6724bb8cc3c1a\":{\"language\":{\"en\":{\"question\":\"Do API keys in QRPay Pro have an expiration date?\",\"answer\":\"No, QRPay Pro API keys do not expire by default. However, you can manually revoke and regenerate them whenever needed to maintain the highest security standards.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0645\\u0641\\u0627\\u062a\\u064a\\u062d API \\u0641\\u064a QRPay Pro \\u0644\\u0647\\u0627 \\u062a\\u0627\\u0631\\u064a\\u062e \\u0627\\u0646\\u062a\\u0647\\u0627\\u0621 \\u0627\\u0644\\u0635\\u0644\\u0627\\u062d\\u064a\\u0629\\u061f\",\"answer\":\"\\u0644\\u0627\\u060c \\u0644\\u0627 \\u062a\\u0646\\u062a\\u0647\\u064a \\u0635\\u0644\\u0627\\u062d\\u064a\\u0629 \\u0645\\u0641\\u0627\\u062a\\u064a\\u062d QRPay Pro API \\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u064b\\u0627. \\u0648\\u0645\\u0639 \\u0630\\u0644\\u0643\\u060c \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0625\\u0644\\u063a\\u0627\\u0621\\u0647\\u0627 \\u0648\\u0625\\u0639\\u0627\\u062f\\u0629 \\u0625\\u0646\\u0634\\u0627\\u0626\\u0647\\u0627 \\u064a\\u062f\\u0648\\u064a\\u064b\\u0627 \\u0639\\u0646\\u062f \\u0627\\u0644\\u062d\\u0627\\u062c\\u0629 \\u0644\\u0644\\u062d\\u0641\\u0627\\u0638 \\u0639\\u0644\\u0649 \\u0623\\u0639\\u0644\\u0649 \\u0645\\u0639\\u0627\\u064a\\u064a\\u0631 \\u0627\\u0644\\u0623\\u0645\\u0627\\u0646.\"},\"es\":{\"question\":\"\\u00bfLas claves API en QRPay Pro tienen fecha de vencimiento?\",\"answer\":\"No, las claves API de QRPay Pro no caducan de forma predeterminada. Sin embargo, puede revocarlos y regenerarlos manualmente cuando sea necesario para mantener los m\\u00e1s altos est\\u00e1ndares de seguridad.\"},\"fr\":{\"question\":\"Les cl\\u00e9s API dans QRPay Pro ont-elles une date d\'expiration ?\",\"answer\":\"Non, les cl\\u00e9s API QRPay Pro n\'expirent pas par d\\u00e9faut. Cependant, vous pouvez les r\\u00e9voquer et les r\\u00e9g\\u00e9n\\u00e9rer manuellement chaque fois que n\\u00e9cessaire pour maintenir les normes de s\\u00e9curit\\u00e9 les plus \\u00e9lev\\u00e9es.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e QRPay Pro \\u092e\\u0947\\u0902 API \\u0915\\u0941\\u0902\\u091c\\u093f\\u092f\\u094b\\u0902 \\u0915\\u0940 \\u0915\\u094b\\u0908 \\u0938\\u092e\\u093e\\u092a\\u094d\\u0924\\u093f \\u0924\\u093f\\u0925\\u093f \\u0939\\u094b\\u0924\\u0940 \\u0939\\u0948?\",\"answer\":\"\\u0928\\u0939\\u0940\\u0902, QRPay Pro API \\u0915\\u0941\\u0902\\u091c\\u093f\\u092f\\u093e\\u0901 \\u0921\\u093f\\u092b\\u093c\\u0949\\u0932\\u094d\\u091f \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0938\\u092e\\u093e\\u092a\\u094d\\u0924 \\u0928\\u0939\\u0940\\u0902 \\u0939\\u094b\\u0924\\u0940 \\u0939\\u0948\\u0902\\u0964 \\u0939\\u093e\\u0932\\u093e\\u0901\\u0915\\u093f, \\u0909\\u091a\\u094d\\u091a\\u0924\\u092e \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u092e\\u093e\\u0928\\u0915\\u094b\\u0902 \\u0915\\u094b \\u092c\\u0928\\u093e\\u090f \\u0930\\u0916\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u091c\\u092c \\u092d\\u0940 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915\\u0924\\u093e \\u0939\\u094b \\u0906\\u092a \\u0909\\u0928\\u094d\\u0939\\u0947\\u0902 \\u092e\\u0948\\u0928\\u094d\\u092f\\u0941\\u0905\\u0932 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0930\\u0926\\u094d\\u0926 \\u0914\\u0930 \\u092a\\u0941\\u0928: \\u0909\\u0924\\u094d\\u092a\\u0928\\u094d\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724bb8cc3c1a\"}}}', 1, 1, '2024-11-01 17:28:38', '2024-11-07 10:36:29');
INSERT INTO `frontend_header_section_faqs` VALUES (24, 24, 'enterprise', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About Receiving Money as an Agent\",\"sub_heading\":\"Find answers to common questions on receiving funds through QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0643\\u0648\\u0643\\u064a\\u0644\",\"sub_heading\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0644\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0634\\u0627\\u0626\\u0639\\u0629 \\u062d\\u0648\\u0644 \\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 QRPay Pro.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre recibir dinero como agente\",\"sub_heading\":\"Encuentre respuestas a preguntas comunes sobre c\\u00f3mo recibir fondos a trav\\u00e9s de QRPay Pro.\"},\"fr\":{\"heading\":\"Questions fr\\u00e9quemment pos\\u00e9es sur la r\\u00e9ception d\'argent en tant qu\'agent\",\"sub_heading\":\"Trouvez des r\\u00e9ponses aux questions courantes sur la r\\u00e9ception de fonds via QRPay Pro.\"},\"hi\":{\"heading\":\"\\u090f\\u0915 \\u090f\\u091c\\u0947\\u0902\\u091f \\u0915\\u0947 \\u0930\\u0942\\u092a \\u092e\\u0947\\u0902 \\u0927\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u0927\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u092a\\u0930 \\u0938\\u093e\\u092e\\u093e\\u0928\\u094d\\u092f \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u0916\\u094b\\u091c\\u0947\\u0902\\u0964\"}},\"items\":{\"6724bdc8cae48\":{\"language\":{\"en\":{\"question\":\"How can I provide my account details to the sender?\",\"answer\":\"You can easily share your unique QRPay Pro QR code or account ID, allowing the sender to initiate a quick and secure transfer directly to your account.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u062a\\u0642\\u062f\\u064a\\u0645 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u062d\\u0633\\u0627\\u0628\\u064a \\u0644\\u0644\\u0645\\u0631\\u0633\\u0644\\u061f\",\"answer\":\"\\u064a\\u0645\\u0643\\u0646\\u0643 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0645\\u0634\\u0627\\u0631\\u0643\\u0629 \\u0631\\u0645\\u0632 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639\\u0629 QRPay Pro \\u0623\\u0648 \\u0645\\u0639\\u0631\\u0641 \\u0627\\u0644\\u062d\\u0633\\u0627\\u0628 \\u0627\\u0644\\u0641\\u0631\\u064a\\u062f \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0645\\u062d \\u0644\\u0644\\u0645\\u0631\\u0633\\u0644 \\u0628\\u0628\\u062f\\u0621 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0633\\u0631\\u064a\\u0639 \\u0648\\u0622\\u0645\\u0646 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0643.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo puedo proporcionar los detalles de mi cuenta al remitente?\",\"answer\":\"Puede compartir f\\u00e1cilmente su c\\u00f3digo QR exclusivo de QRPay Pro o su ID de cuenta, lo que permite al remitente iniciar una transferencia r\\u00e1pida y segura directamente a su cuenta.\"},\"fr\":{\"question\":\"Comment puis-je fournir les d\\u00e9tails de mon compte \\u00e0 l\'exp\\u00e9diteur\\u00a0?\",\"answer\":\"Vous pouvez facilement partager votre code QR QRPay Pro unique ou votre identifiant de compte, permettant \\u00e0 l\'exp\\u00e9diteur d\'initier un transfert rapide et s\\u00e9curis\\u00e9 directement vers votre compte.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 \\u092a\\u094d\\u0930\\u0947\\u0937\\u0915 \\u0915\\u094b \\u0905\\u092a\\u0928\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u0915\\u093e \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0915\\u0948\\u0938\\u0947 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0906\\u092a \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0905\\u092a\\u0928\\u093e \\u0905\\u0926\\u094d\\u0935\\u093f\\u0924\\u0940\\u092f QRPay \\u092a\\u094d\\u0930\\u094b QR \\u0915\\u094b\\u0921 \\u092f\\u093e \\u0916\\u093e\\u0924\\u093e \\u0906\\u0908\\u0921\\u0940 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u092a\\u094d\\u0930\\u0947\\u0937\\u0915 \\u0938\\u0940\\u0927\\u0947 \\u0906\\u092a\\u0915\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0924\\u094d\\u0935\\u0930\\u093f\\u0924 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0936\\u0941\\u0930\\u0942 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964\"}},\"id\":\"6724bdc8cae48\"},\"6724bdd20b54c\":{\"language\":{\"en\":{\"question\":\"Can I receive funds in multiple currencies?\",\"answer\":\"Yes, QRPay Pro supports multi-currency transactions, allowing you to receive payments in various currencies. The platform will handle the conversion based on current exchange rates.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0633\\u062a\\u0644\\u0627\\u0645 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0639\\u0645\\u0644\\u0627\\u062a \\u0645\\u062a\\u0639\\u062f\\u062f\\u0629\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u064a\\u062f\\u0639\\u0645 QRPay Pro \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0645\\u062a\\u0639\\u062f\\u062f\\u0629 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0645\\u062d \\u0644\\u0643 \\u0628\\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0628\\u0639\\u0645\\u0644\\u0627\\u062a \\u0645\\u062e\\u062a\\u0644\\u0641\\u0629. \\u0633\\u062a\\u062a\\u0639\\u0627\\u0645\\u0644 \\u0627\\u0644\\u0645\\u0646\\u0635\\u0629 \\u0645\\u0639 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0628\\u0646\\u0627\\u0621\\u064b \\u0639\\u0644\\u0649 \\u0623\\u0633\\u0639\\u0627\\u0631 \\u0627\\u0644\\u0635\\u0631\\u0641 \\u0627\\u0644\\u062d\\u0627\\u0644\\u064a\\u0629.\"},\"es\":{\"question\":\"\\u00bfPuedo recibir fondos en varias monedas?\",\"answer\":\"S\\u00ed, QRPay Pro admite transacciones multidivisa, lo que le permite recibir pagos en varias monedas. La plataforma manejar\\u00e1 la conversi\\u00f3n en funci\\u00f3n de los tipos de cambio actuales.\"},\"fr\":{\"question\":\"Puis-je recevoir des fonds dans plusieurs devises ?\",\"answer\":\"Oui, QRPay Pro prend en charge les transactions multidevises, vous permettant de recevoir des paiements dans diff\\u00e9rentes devises. La plateforme g\\u00e9rera la conversion en fonction des taux de change actuels.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0941\\u091d\\u0947 \\u0905\\u0928\\u0947\\u0915 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u092e\\u0947\\u0902 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0939\\u094b \\u0938\\u0915\\u0924\\u0940 \\u0939\\u0948?\",\"answer\":\"\\u0939\\u093e\\u0902, QRPay \\u092a\\u094d\\u0930\\u094b \\u092c\\u0939\\u0941-\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0906\\u092a \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u092e\\u0947\\u0902 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e \\u0935\\u0930\\u094d\\u0924\\u092e\\u093e\\u0928 \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0926\\u0930\\u094b\\u0902 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0930\\u0942\\u092a\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u094b \\u0938\\u0902\\u092d\\u093e\\u0932\\u0947\\u0917\\u093e\\u0964\"}},\"id\":\"6724bdd20b54c\"},\"6724bddc1a1e7\":{\"language\":{\"en\":{\"question\":\"Will I be notified when a payment is received?\",\"answer\":\"Absolutely. QRPay Pro sends instant notifications when a transfer is complete, so you can verify incoming funds in real time.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0633\\u064a\\u062a\\u0645 \\u0625\\u0639\\u0644\\u0627\\u0645\\u064a \\u0639\\u0646\\u062f \\u0627\\u0633\\u062a\\u0644\\u0627\\u0645 \\u0627\\u0644\\u062f\\u0641\\u0639\\u0629\\u061f\",\"answer\":\"\\u0642\\u0637\\u0639\\u0627\\u064b. \\u064a\\u0631\\u0633\\u0644 QRPay Pro \\u0625\\u0634\\u0639\\u0627\\u0631\\u0627\\u062a \\u0641\\u0648\\u0631\\u064a\\u0629 \\u0639\\u0646\\u062f \\u0627\\u0643\\u062a\\u0645\\u0627\\u0644 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0646\\u0642\\u0644\\u060c \\u062d\\u062a\\u0649 \\u062a\\u062a\\u0645\\u0643\\u0646 \\u0645\\u0646 \\u0627\\u0644\\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0627\\u0644\\u0648\\u0627\\u0631\\u062f\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0648\\u0642\\u062a \\u0627\\u0644\\u0641\\u0639\\u0644\\u064a.\"},\"es\":{\"question\":\"\\u00bfMe notificar\\u00e1n cuando se reciba un pago?\",\"answer\":\"Absolutamente. QRPay Pro env\\u00eda notificaciones instant\\u00e1neas cuando se completa una transferencia, para que puedas verificar los fondos entrantes en tiempo real.\"},\"fr\":{\"question\":\"Serai-je averti lorsqu\'un paiement sera re\\u00e7u\\u00a0?\",\"answer\":\"Absolument. QRPay Pro envoie des notifications instantan\\u00e9es lorsqu\'un transfert est termin\\u00e9, afin que vous puissiez v\\u00e9rifier les fonds entrants en temps r\\u00e9el.\"},\"hi\":{\"question\":\"\\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0939\\u094b\\u0928\\u0947 \\u092a\\u0930 \\u0915\\u094d\\u092f\\u093e \\u092e\\u0941\\u091d\\u0947 \\u0938\\u0942\\u091a\\u093f\\u0924 \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e\\u090f\\u0917\\u093e?\",\"answer\":\"\\u092c\\u093f\\u0932\\u094d\\u0915\\u0941\\u0932\\u0964 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u0923 \\u092a\\u0942\\u0930\\u093e \\u0939\\u094b\\u0928\\u0947 \\u092a\\u0930 QRPay Pro \\u0924\\u0941\\u0930\\u0902\\u0924 \\u0938\\u0942\\u091a\\u0928\\u093e\\u090f\\u0902 \\u092d\\u0947\\u091c\\u0924\\u093e \\u0939\\u0948, \\u0924\\u093e\\u0915\\u093f \\u0906\\u092a \\u0935\\u093e\\u0938\\u094d\\u0924\\u0935\\u093f\\u0915 \\u0938\\u092e\\u092f \\u092e\\u0947\\u0902 \\u0906\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092b\\u0902\\u0921 \\u0915\\u094b \\u0938\\u0924\\u094d\\u092f\\u093e\\u092a\\u093f\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0947\\u0902\\u0964\"}},\"id\":\"6724bddc1a1e7\"},\"6724bde6b81b2\":{\"language\":{\"en\":{\"question\":\"Is there a fee for receiving funds as an agent?\",\"answer\":\"Transaction fees may vary based on the currency and type of transfer. Check the QRPay Pro fee schedule in your account for detailed information.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0631\\u0633\\u0648\\u0645 \\u0644\\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0643\\u0648\\u0643\\u064a\\u0644\\u061f\",\"answer\":\"\\u0642\\u062f \\u062a\\u062e\\u062a\\u0644\\u0641 \\u0631\\u0633\\u0648\\u0645 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0628\\u0646\\u0627\\u0621\\u064b \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0629 \\u0648\\u0646\\u0648\\u0639 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644. \\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u062c\\u062f\\u0648\\u0644 \\u0631\\u0633\\u0648\\u0645 QRPay Pro \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0645\\u0641\\u0635\\u0644\\u0629.\"},\"es\":{\"question\":\"\\u00bfSe aplica una tarifa por recibir fondos como agente?\",\"answer\":\"Las tarifas de transacci\\u00f3n pueden variar seg\\u00fan la moneda y el tipo de transferencia. Consulte el programa de tarifas de QRPay Pro en su cuenta para obtener informaci\\u00f3n detallada.\"},\"fr\":{\"question\":\"Y a-t-il des frais pour recevoir des fonds en tant qu\'agent ?\",\"answer\":\"Les frais de transaction peuvent varier en fonction de la devise et du type de transfert. Consultez le bar\\u00e8me des frais QRPay Pro dans votre compte pour des informations d\\u00e9taill\\u00e9es.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u090f\\u091c\\u0947\\u0902\\u091f \\u0915\\u0947 \\u0930\\u0942\\u092a \\u092e\\u0947\\u0902 \\u0927\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u094b\\u0908 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0939\\u0948?\",\"answer\":\"\\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0914\\u0930 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u0947 \\u092a\\u094d\\u0930\\u0915\\u093e\\u0930 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u092d\\u093f\\u0928\\u094d\\u0928 \\u0939\\u094b \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0935\\u093f\\u0938\\u094d\\u0924\\u0943\\u0924 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 QRPay \\u092a\\u094d\\u0930\\u094b \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0905\\u0928\\u0941\\u0938\\u0942\\u091a\\u0940 \\u0915\\u0940 \\u091c\\u093e\\u0901\\u091a \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724bde6b81b2\"}}}', 1, 1, '2024-11-01 17:38:37', '2024-11-06 16:19:28');
INSERT INTO `frontend_header_section_faqs` VALUES (25, 25, 'enterprise', '{\"language\":{\"en\":{\"heading\":\"Common Questions About Exchanging Money on QRPay Pro\",\"sub_heading\":\"Find out more about currency exchange features for agents on QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0634\\u0627\\u0626\\u0639\\u0629 \\u062d\\u0648\\u0644 \\u062a\\u0628\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0639\\u0644\\u0649 QRPay Pro\",\"sub_heading\":\"\\u0627\\u0643\\u062a\\u0634\\u0641 \\u0627\\u0644\\u0645\\u0632\\u064a\\u062f \\u062d\\u0648\\u0644 \\u0645\\u064a\\u0632\\u0627\\u062a \\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0644\\u0644\\u0648\\u0643\\u0644\\u0627\\u0621 \\u0639\\u0644\\u0649 QRPay Pro.\"},\"es\":{\"heading\":\"Preguntas comunes sobre el intercambio de dinero en QRPay Pro\",\"sub_heading\":\"Obtenga m\\u00e1s informaci\\u00f3n sobre las funciones de cambio de moneda para agentes en QRPay Pro.\"},\"fr\":{\"heading\":\"Questions courantes sur l\'\\u00e9change d\'argent sur QRPay Pro\",\"sub_heading\":\"Apprenez-en davantage sur les fonctionnalit\\u00e9s de change pour les agents sur QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u0930 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u0947 \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0938\\u093e\\u092e\\u093e\\u0928\\u094d\\u092f \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u0930 \\u090f\\u091c\\u0947\\u0902\\u091f\\u094b\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0927\\u093f\\u0915 \\u091c\\u093e\\u0928\\u0947\\u0902\\u0964\"}},\"items\":{\"6724be8e0fec3\":{\"language\":{\"en\":{\"question\":\"How do I start a currency exchange in my QRPay Pro account?\",\"answer\":\"To begin an exchange, simply select the currency you currently hold and the currency you wish to receive. QRPay Pro will guide you through the rest of the process.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u0623\\u0628\\u062f\\u0623 \\u0641\\u064a \\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u064a\\u061f\",\"answer\":\"\\u0644\\u0628\\u062f\\u0621 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u062a\\u0628\\u0627\\u062f\\u0644\\u060c \\u0645\\u0627 \\u0639\\u0644\\u064a\\u0643 \\u0633\\u0648\\u0649 \\u062a\\u062d\\u062f\\u064a\\u062f \\u0627\\u0644\\u0639\\u0645\\u0644\\u0629 \\u0627\\u0644\\u062a\\u064a \\u062a\\u0645\\u062a\\u0644\\u0643\\u0647\\u0627 \\u062d\\u0627\\u0644\\u064a\\u064b\\u0627 \\u0648\\u0627\\u0644\\u0639\\u0645\\u0644\\u0629 \\u0627\\u0644\\u062a\\u064a \\u062a\\u0631\\u063a\\u0628 \\u0641\\u064a \\u062a\\u0644\\u0642\\u064a\\u0647\\u0627. \\u0633\\u064a\\u0631\\u0634\\u062f\\u0643 QRPay Pro \\u062e\\u0644\\u0627\\u0644 \\u0628\\u0642\\u064a\\u0629 \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo inicio un cambio de moneda en mi cuenta QRPay Pro?\",\"answer\":\"Para comenzar un intercambio, simplemente seleccione la moneda que posee actualmente y la moneda que desea recibir. QRPay Pro te guiar\\u00e1 por el resto del proceso.\"},\"fr\":{\"question\":\"Comment d\\u00e9marrer un \\u00e9change de devises sur mon compte QRPay Pro\\u00a0?\",\"answer\":\"Pour commencer un \\u00e9change, s\\u00e9lectionnez simplement la devise que vous d\\u00e9tenez actuellement et la devise que vous souhaitez recevoir. QRPay Pro vous guidera tout au long du processus.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0915\\u0948\\u0938\\u0947 \\u0936\\u0941\\u0930\\u0942 \\u0915\\u0930\\u0942\\u0902?\",\"answer\":\"\\u090f\\u0915\\u094d\\u0938\\u091a\\u0947\\u0902\\u091c \\u0936\\u0941\\u0930\\u0942 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u092c\\u0938 \\u0935\\u0939 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u091a\\u0941\\u0928\\u0947\\u0902 \\u091c\\u094b \\u0906\\u092a\\u0915\\u0947 \\u092a\\u093e\\u0938 \\u0935\\u0930\\u094d\\u0924\\u092e\\u093e\\u0928 \\u092e\\u0947\\u0902 \\u0939\\u0948 \\u0914\\u0930 \\u0935\\u0939 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u091c\\u093f\\u0938\\u0947 \\u0906\\u092a \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0928\\u093e \\u091a\\u093e\\u0939\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 QRPay Pro \\u092c\\u093e\\u0915\\u0940 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u092e\\u0947\\u0902 \\u0906\\u092a\\u0915\\u093e \\u092e\\u093e\\u0930\\u094d\\u0917\\u0926\\u0930\\u094d\\u0936\\u0928 \\u0915\\u0930\\u0947\\u0917\\u093e\\u0964\"}},\"id\":\"6724be8e0fec3\"},\"6724be9c949ab\":{\"language\":{\"en\":{\"question\":\"Are there fees associated with currency exchange?\",\"answer\":\"Yes, QRPay Pro applies a nominal fee for currency exchanges, which varies depending on the currencies involved. You can view the exact fee before confirming the transaction.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u064a\\u0637\\u0628\\u0642 QRPay Pro \\u0631\\u0633\\u0648\\u0645\\u064b\\u0627 \\u0631\\u0645\\u0632\\u064a\\u0629 \\u0639\\u0644\\u0649 \\u062a\\u0628\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a\\u060c \\u0648\\u0627\\u0644\\u062a\\u064a \\u062a\\u062e\\u062a\\u0644\\u0641 \\u0628\\u0627\\u062e\\u062a\\u0644\\u0627\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0639\\u0646\\u064a\\u0629. \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0639\\u0631\\u0636 \\u0627\\u0644\\u0631\\u0633\\u0648\\u0645 \\u0627\\u0644\\u062f\\u0642\\u064a\\u0642\\u0629 \\u0642\\u0628\\u0644 \\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629.\"},\"es\":{\"question\":\"\\u00bfExisten tarifas asociadas con el cambio de moneda?\",\"answer\":\"S\\u00ed, QRPay Pro aplica una tarifa nominal por los cambios de divisas, que var\\u00eda seg\\u00fan las monedas involucradas. Puede ver la tarifa exacta antes de confirmar la transacci\\u00f3n.\"},\"fr\":{\"question\":\"Y a-t-il des frais associ\\u00e9s au change de devises ?\",\"answer\":\"Oui, QRPay Pro applique des frais nominaux pour les \\u00e9changes de devises, qui varient en fonction des devises impliqu\\u00e9es. Vous pouvez consulter les frais exacts avant de confirmer la transaction.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0915\\u094b\\u0908 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u091c\\u0941\\u0921\\u093c\\u093e \\u0939\\u0941\\u0906 \\u0939\\u0948?\",\"answer\":\"\\u0939\\u093e\\u0902, QRPay Pro \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0915\\u0947 \\u0932\\u093f\\u090f \\u090f\\u0915 \\u092e\\u093e\\u092e\\u0942\\u0932\\u0940 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0932\\u093e\\u0917\\u0942 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948, \\u091c\\u094b \\u0936\\u093e\\u092e\\u093f\\u0932 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u092d\\u093f\\u0928\\u094d\\u0928 \\u0939\\u094b\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0906\\u092a \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u0938\\u091f\\u0940\\u0915 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0926\\u0947\\u0916 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724be9c949ab\"},\"6724bea5c68f8\":{\"language\":{\"en\":{\"question\":\"Can I see the exchange rate before confirming the transaction?\",\"answer\":\"Absolutely. QRPay Pro provides real-time exchange rates, so you can review the conversion details before completing your transaction.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0631\\u0624\\u064a\\u0629 \\u0633\\u0639\\u0631 \\u0627\\u0644\\u0635\\u0631\\u0641 \\u0642\\u0628\\u0644 \\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629\\u061f\",\"answer\":\"\\u0642\\u0637\\u0639\\u0627\\u064b. \\u064a\\u0648\\u0641\\u0631 QRPay Pro \\u0623\\u0633\\u0639\\u0627\\u0631 \\u0627\\u0644\\u0635\\u0631\\u0641 \\u0641\\u064a \\u0627\\u0644\\u0648\\u0642\\u062a \\u0627\\u0644\\u0641\\u0639\\u0644\\u064a\\u060c \\u062d\\u062a\\u0649 \\u062a\\u062a\\u0645\\u0643\\u0646 \\u0645\\u0646 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0629 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0642\\u0628\\u0644 \\u0625\\u0643\\u0645\\u0627\\u0644 \\u0645\\u0639\\u0627\\u0645\\u0644\\u062a\\u0643.\"},\"es\":{\"question\":\"\\u00bfPuedo ver el tipo de cambio antes de confirmar la transacci\\u00f3n?\",\"answer\":\"Absolutamente. QRPay Pro proporciona tipos de cambio en tiempo real, para que pueda revisar los detalles de la conversi\\u00f3n antes de completar su transacci\\u00f3n.\"},\"fr\":{\"question\":\"Puis-je voir le taux de change avant de confirmer la transaction ?\",\"answer\":\"Absolument. QRPay Pro fournit des taux de change en temps r\\u00e9el, vous permettant ainsi de consulter les d\\u00e9tails de la conversion avant de finaliser votre transaction.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0926\\u0930 \\u0926\\u0947\\u0916 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u092c\\u093f\\u0932\\u094d\\u0915\\u0941\\u0932\\u0964 QRPay \\u092a\\u094d\\u0930\\u094b \\u0935\\u093e\\u0938\\u094d\\u0924\\u0935\\u093f\\u0915 \\u0938\\u092e\\u092f \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0926\\u0930\\u0947\\u0902 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948, \\u0924\\u093e\\u0915\\u093f \\u0906\\u092a \\u0905\\u092a\\u0928\\u093e \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u092a\\u0942\\u0930\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u0930\\u0942\\u092a\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0915\\u0940 \\u0938\\u092e\\u0940\\u0915\\u094d\\u0937\\u093e \\u0915\\u0930 \\u0938\\u0915\\u0947\\u0902\\u0964\"}},\"id\":\"6724bea5c68f8\"},\"6724beae85a60\":{\"language\":{\"en\":{\"question\":\"Is there a limit to the amount I can exchange at one time?\",\"answer\":\"There may be limits based on your account type and transaction history. Refer to your QRPay Pro account settings or contact support to understand any specific limits that may apply.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u062d\\u062f \\u0644\\u0644\\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0630\\u064a \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0633\\u062a\\u0628\\u062f\\u0627\\u0644\\u0647 \\u0641\\u064a \\u0627\\u0644\\u0645\\u0631\\u0629 \\u0627\\u0644\\u0648\\u0627\\u062d\\u062f\\u0629\\u061f\",\"answer\":\"\\u0642\\u062f \\u062a\\u0643\\u0648\\u0646 \\u0647\\u0646\\u0627\\u0643 \\u062d\\u062f\\u0648\\u062f \\u0628\\u0646\\u0627\\u0621\\u064b \\u0639\\u0644\\u0649 \\u0646\\u0648\\u0639 \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0648\\u0633\\u062c\\u0644 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a. \\u0627\\u0631\\u062c\\u0639 \\u0625\\u0644\\u0649 \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u0623\\u0648 \\u0627\\u062a\\u0635\\u0644 \\u0628\\u0627\\u0644\\u062f\\u0639\\u0645 \\u0644\\u0641\\u0647\\u0645 \\u0623\\u064a \\u062d\\u062f\\u0648\\u062f \\u0645\\u062d\\u062f\\u062f\\u0629 \\u0642\\u062f \\u064a\\u062a\\u0645 \\u062a\\u0637\\u0628\\u064a\\u0642\\u0647\\u0627.\"},\"es\":{\"question\":\"\\u00bfExiste un l\\u00edmite en la cantidad que puedo cambiar a la vez?\",\"answer\":\"Puede haber l\\u00edmites seg\\u00fan su tipo de cuenta e historial de transacciones. Consulte la configuraci\\u00f3n de su cuenta QRPay Pro o comun\\u00edquese con el soporte para comprender los l\\u00edmites espec\\u00edficos que pueden aplicarse.\"},\"fr\":{\"question\":\"Y a-t-il une limite au montant que je peux \\u00e9changer en une seule fois ?\",\"answer\":\"Il peut y avoir des limites en fonction de votre type de compte et de votre historique de transactions. Reportez-vous aux param\\u00e8tres de votre compte QRPay Pro ou contactez l\'assistance pour comprendre les limites sp\\u00e9cifiques qui peuvent s\'appliquer.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0947\\u0930\\u0947 \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u090f\\u0915 \\u0938\\u092e\\u092f \\u092e\\u0947\\u0902 \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0915\\u0940 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0940 \\u0930\\u093e\\u0936\\u093f \\u0915\\u0940 \\u0915\\u094b\\u0908 \\u0938\\u0940\\u092e\\u093e \\u0939\\u0948?\",\"answer\":\"\\u0906\\u092a\\u0915\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u0915\\u0947 \\u092a\\u094d\\u0930\\u0915\\u093e\\u0930 \\u0914\\u0930 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0907\\u0924\\u093f\\u0939\\u093e\\u0938 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0938\\u0940\\u092e\\u093e\\u090f\\u0901 \\u0939\\u094b \\u0938\\u0915\\u0924\\u0940 \\u0939\\u0948\\u0902\\u0964 \\u0932\\u093e\\u0917\\u0942 \\u0939\\u094b\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0940 \\u0915\\u093f\\u0938\\u0940 \\u092d\\u0940 \\u0935\\u093f\\u0936\\u093f\\u0937\\u094d\\u091f \\u0938\\u0940\\u092e\\u093e \\u0915\\u094b \\u0938\\u092e\\u091d\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u0940 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u093e \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917 \\u0926\\u0947\\u0916\\u0947\\u0902 \\u092f\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u0928 \\u0938\\u0947 \\u0938\\u0902\\u092a\\u0930\\u094d\\u0915 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724beae85a60\"}}}', 1, 1, '2024-11-01 17:41:55', '2024-11-06 15:45:14');
INSERT INTO `frontend_header_section_faqs` VALUES (26, 26, 'enterprise', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About Adding Money on QRPay Pro\",\"sub_heading\":\"Learn more about funding your account as an agent on QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0625\\u0636\\u0627\\u0641\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0639\\u0644\\u0649 QRPay Pro\",\"sub_heading\":\"\\u062a\\u0639\\u0631\\u0641 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0632\\u064a\\u062f \\u062d\\u0648\\u0644 \\u062a\\u0645\\u0648\\u064a\\u0644 \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0643\\u0648\\u0643\\u064a\\u0644 \\u0639\\u0644\\u0649 QRPay Pro.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre c\\u00f3mo agregar dinero en QRPay Pro\",\"sub_heading\":\"Obtenga m\\u00e1s informaci\\u00f3n sobre c\\u00f3mo financiar su cuenta como agente en QRPay Pro.\"},\"fr\":{\"heading\":\"Questions fr\\u00e9quemment pos\\u00e9es sur l\'ajout d\'argent sur QRPay Pro\",\"sub_heading\":\"Apprenez-en davantage sur l\'approvisionnement de votre compte en tant qu\'agent sur QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u0930 \\u092a\\u0948\\u0938\\u0947 \\u091c\\u094b\\u0921\\u093c\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"QRPay Pro \\u092a\\u0930 \\u090f\\u0915 \\u090f\\u091c\\u0947\\u0902\\u091f \\u0915\\u0947 \\u0930\\u0942\\u092a \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u091c\\u092e\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0914\\u0930 \\u091c\\u093e\\u0928\\u0947\\u0902\\u0964\"}},\"items\":{\"6724bf77d41f0\":{\"language\":{\"en\":{\"question\":\"What methods can I use to add money to my QRPay Pro account?\",\"answer\":\"You can add money using various methods such as bank transfers, credit\\/debit cards, and other supported payment options available within the QRPay Pro platform.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0647\\u064a \\u0627\\u0644\\u0637\\u0631\\u0642 \\u0627\\u0644\\u062a\\u064a \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645\\u0647\\u0627 \\u0644\\u0625\\u0636\\u0627\\u0641\\u0629 \\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u064a\\u061f\",\"answer\":\"\\u064a\\u0645\\u0643\\u0646\\u0643 \\u0625\\u0636\\u0627\\u0641\\u0629 \\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0637\\u0631\\u0642 \\u0645\\u062e\\u062a\\u0644\\u0641\\u0629 \\u0645\\u062b\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0635\\u0631\\u0641\\u064a\\u0629 \\u0648\\u0628\\u0637\\u0627\\u0642\\u0627\\u062a \\u0627\\u0644\\u0627\\u0626\\u062a\\u0645\\u0627\\u0646\\/\\u0627\\u0644\\u062e\\u0635\\u0645 \\u0648\\u062e\\u064a\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u0645\\u062f\\u0639\\u0648\\u0645\\u0629 \\u0627\\u0644\\u0623\\u062e\\u0631\\u0649 \\u0627\\u0644\\u0645\\u062a\\u0648\\u0641\\u0631\\u0629 \\u0636\\u0645\\u0646 \\u0645\\u0646\\u0635\\u0629 QRPay Pro.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 m\\u00e9todos puedo utilizar para agregar dinero a mi cuenta QRPay Pro?\",\"answer\":\"Puede agregar dinero utilizando varios m\\u00e9todos, como transferencias bancarias, tarjetas de cr\\u00e9dito\\/d\\u00e9bito y otras opciones de pago admitidas disponibles dentro de la plataforma QRPay Pro.\"},\"fr\":{\"question\":\"Quelles m\\u00e9thodes puis-je utiliser pour ajouter de l\'argent sur mon compte QRPay Pro\\u00a0?\",\"answer\":\"Vous pouvez ajouter de l\'argent en utilisant diverses m\\u00e9thodes telles que les virements bancaires, les cartes de cr\\u00e9dit\\/d\\u00e9bit et d\'autres options de paiement prises en charge disponibles sur la plateforme QRPay Pro.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u092a\\u0948\\u0938\\u0947 \\u091c\\u094b\\u0921\\u093c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u093f\\u0928 \\u0924\\u0930\\u0940\\u0915\\u094b\\u0902 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0902?\",\"answer\":\"\\u0906\\u092a QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e \\u0915\\u0947 \\u092d\\u0940\\u0924\\u0930 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u0924\\u0930\\u0940\\u0915\\u094b\\u0902 \\u091c\\u0948\\u0938\\u0947 \\u092c\\u0948\\u0902\\u0915 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923, \\u0915\\u094d\\u0930\\u0947\\u0921\\u093f\\u091f\\/\\u0921\\u0947\\u092c\\u093f\\u091f \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0914\\u0930 \\u0905\\u0928\\u094d\\u092f \\u0938\\u092e\\u0930\\u094d\\u0925\\u093f\\u0924 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a\\u094b\\u0902 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u091c\\u094b\\u0921\\u093c \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724bf77d41f0\"},\"6724bf7fe857d\":{\"language\":{\"en\":{\"question\":\"Are there any fees associated with adding money?\",\"answer\":\"Yes, there may be transaction fees depending on the funding method you choose. You will be informed of any applicable fees before confirming your transaction.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0625\\u0636\\u0627\\u0641\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u0642\\u062f \\u062a\\u0643\\u0648\\u0646 \\u0647\\u0646\\u0627\\u0643 \\u0631\\u0633\\u0648\\u0645 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0627\\u0639\\u062a\\u0645\\u0627\\u062f\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u062a\\u0645\\u0648\\u064a\\u0644 \\u0627\\u0644\\u062a\\u064a \\u062a\\u062e\\u062a\\u0627\\u0631\\u0647\\u0627. \\u0633\\u064a\\u062a\\u0645 \\u0625\\u0628\\u0644\\u0627\\u063a\\u0643 \\u0628\\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0637\\u0628\\u0642\\u0629 \\u0642\\u0628\\u0644 \\u062a\\u0623\\u0643\\u064a\\u062f \\u0645\\u0639\\u0627\\u0645\\u0644\\u062a\\u0643.\"},\"es\":{\"question\":\"\\u00bfHay alguna tarifa asociada con agregar dinero?\",\"answer\":\"S\\u00ed, es posible que se apliquen tarifas de transacci\\u00f3n seg\\u00fan el m\\u00e9todo de financiaci\\u00f3n que elija. Se le informar\\u00e1 de las tarifas aplicables antes de confirmar su transacci\\u00f3n.\"},\"fr\":{\"question\":\"Y a-t-il des frais associ\\u00e9s \\u00e0 l\\u2019ajout d\\u2019argent\\u00a0?\",\"answer\":\"Oui, des frais de transaction peuvent s\'appliquer selon la m\\u00e9thode de financement que vous choisissez. Vous serez inform\\u00e9 des frais applicables avant de confirmer votre transaction.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092a\\u0948\\u0938\\u0947 \\u091c\\u094b\\u0921\\u093c\\u0928\\u0947 \\u0938\\u0947 \\u091c\\u0941\\u0921\\u093c\\u0940 \\u0915\\u094b\\u0908 \\u092b\\u0940\\u0938 \\u0939\\u0948?\",\"answer\":\"\\u0939\\u093e\\u0902, \\u0906\\u092a\\u0915\\u0947 \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u091a\\u0941\\u0928\\u0940 \\u0917\\u0908 \\u092b\\u0902\\u0921\\u093f\\u0902\\u0917 \\u0935\\u093f\\u0927\\u093f \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0939\\u094b \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0906\\u092a\\u0915\\u0947 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u0906\\u092a\\u0915\\u094b \\u0915\\u093f\\u0938\\u0940 \\u092d\\u0940 \\u0932\\u093e\\u0917\\u0942 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0938\\u0942\\u091a\\u093f\\u0924 \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e\\u090f\\u0917\\u093e\\u0964\"}},\"id\":\"6724bf7fe857d\"},\"6724bf8a1f02a\":{\"language\":{\"en\":{\"question\":\"How long does it take for the funds to be available in my account?\",\"answer\":\"Typically, funds added through bank transfers may take a few hours to reflect in your account, while credit\\/debit card transactions are usually processed instantly.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0627\\u0644\\u0645\\u062f\\u0629 \\u0627\\u0644\\u062a\\u064a \\u062a\\u0633\\u062a\\u063a\\u0631\\u0642\\u0647\\u0627 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u062d\\u062a\\u0649 \\u062a\\u0635\\u0628\\u062d \\u0645\\u062a\\u0627\\u062d\\u0629 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628\\u064a\\u061f\",\"answer\":\"\\u0639\\u0627\\u062f\\u0629\\u064b\\u060c \\u0642\\u062f \\u062a\\u0633\\u062a\\u063a\\u0631\\u0642 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0636\\u0627\\u0641\\u0629 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0635\\u0631\\u0641\\u064a\\u0629 \\u0628\\u0636\\u0639 \\u0633\\u0627\\u0639\\u0627\\u062a \\u0644\\u062a\\u0638\\u0647\\u0631 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628\\u0643\\u060c \\u0628\\u064a\\u0646\\u0645\\u0627 \\u062a\\u062a\\u0645 \\u0639\\u0627\\u062f\\u0629\\u064b \\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0627\\u0626\\u062a\\u0645\\u0627\\u0646\\/\\u0627\\u0644\\u062e\\u0635\\u0645 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631.\"},\"es\":{\"question\":\"\\u00bfCu\\u00e1nto tiempo tardan los fondos en estar disponibles en mi cuenta?\",\"answer\":\"Por lo general, los fondos agregados mediante transferencias bancarias pueden tardar algunas horas en reflejarse en su cuenta, mientras que las transacciones con tarjeta de cr\\u00e9dito\\/d\\u00e9bito generalmente se procesan instant\\u00e1neamente.\"},\"fr\":{\"question\":\"Combien de temps faut-il pour que les fonds soient disponibles sur mon compte ?\",\"answer\":\"En r\\u00e8gle g\\u00e9n\\u00e9rale, les fonds ajout\\u00e9s via les virements bancaires peuvent prendre quelques heures pour \\u00eatre refl\\u00e9t\\u00e9s sur votre compte, tandis que les transactions par carte de cr\\u00e9dit\\/d\\u00e9bit sont g\\u00e9n\\u00e9ralement trait\\u00e9es instantan\\u00e9ment.\"},\"hi\":{\"question\":\"\\u092e\\u0947\\u0930\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0939\\u094b\\u0928\\u0947 \\u092e\\u0947\\u0902 \\u0915\\u093f\\u0924\\u0928\\u093e \\u0938\\u092e\\u092f \\u0932\\u0917\\u0947\\u0917\\u093e?\",\"answer\":\"\\u0906\\u092e\\u0924\\u094c\\u0930 \\u092a\\u0930, \\u092c\\u0948\\u0902\\u0915 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u091c\\u094b\\u0921\\u093c\\u0947 \\u0917\\u090f \\u0927\\u0928 \\u0915\\u094b \\u0906\\u092a\\u0915\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u092a\\u094d\\u0930\\u0924\\u093f\\u092c\\u093f\\u0902\\u092c\\u093f\\u0924 \\u0939\\u094b\\u0928\\u0947 \\u092e\\u0947\\u0902 \\u0915\\u0941\\u091b \\u0918\\u0902\\u091f\\u0947 \\u0932\\u0917 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u091c\\u092c\\u0915\\u093f \\u0915\\u094d\\u0930\\u0947\\u0921\\u093f\\u091f\\/\\u0921\\u0947\\u092c\\u093f\\u091f \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0906\\u092e\\u0924\\u094c\\u0930 \\u092a\\u0930 \\u0924\\u0941\\u0930\\u0902\\u0924 \\u0938\\u0902\\u0938\\u093e\\u0927\\u093f\\u0924 \\u0939\\u094b\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724bf8a1f02a\"},\"6724bf92ac4e5\":{\"language\":{\"en\":{\"question\":\"Is there a limit on how much money I can add at one time?\",\"answer\":\"Yes, there may be limits based on your account type and transaction history. Please check your QRPay Pro account settings or reach out to customer support for specific limit details.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u062d\\u062f \\u0644\\u0639\\u062f\\u062f \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0627\\u0644\\u062a\\u064a \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0625\\u0636\\u0627\\u0641\\u062a\\u0647\\u0627 \\u0641\\u064a \\u0627\\u0644\\u0645\\u0631\\u0629 \\u0627\\u0644\\u0648\\u0627\\u062d\\u062f\\u0629\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u0642\\u062f \\u062a\\u0643\\u0648\\u0646 \\u0647\\u0646\\u0627\\u0643 \\u062d\\u062f\\u0648\\u062f \\u0628\\u0646\\u0627\\u0621\\u064b \\u0639\\u0644\\u0649 \\u0646\\u0648\\u0639 \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0648\\u0633\\u062c\\u0644 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a. \\u064a\\u0631\\u062c\\u0649 \\u0627\\u0644\\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u0623\\u0648 \\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639 \\u062f\\u0639\\u0645 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u062d\\u062f \\u0627\\u0644\\u0645\\u062d\\u062f\\u062f.\"},\"es\":{\"question\":\"\\u00bfExiste un l\\u00edmite de cu\\u00e1nto dinero puedo agregar a la vez?\",\"answer\":\"S\\u00ed, puede haber l\\u00edmites seg\\u00fan su tipo de cuenta e historial de transacciones. Verifique la configuraci\\u00f3n de su cuenta QRPay Pro o comun\\u00edquese con atenci\\u00f3n al cliente para obtener detalles de l\\u00edmites espec\\u00edficos.\"},\"fr\":{\"question\":\"Y a-t-il une limite au montant d\\u2019argent que je peux ajouter en une seule fois\\u00a0?\",\"answer\":\"Oui, il peut y avoir des limites en fonction de votre type de compte et de votre historique de transactions. Veuillez v\\u00e9rifier les param\\u00e8tres de votre compte QRPay Pro ou contacter le support client pour obtenir des d\\u00e9tails sp\\u00e9cifiques sur les limites.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u090f\\u0915 \\u092c\\u093e\\u0930 \\u092e\\u0947\\u0902 \\u0915\\u093f\\u0924\\u0928\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u091c\\u094b\\u0921\\u093c \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901 \\u0907\\u0938\\u0915\\u0940 \\u0915\\u094b\\u0908 \\u0938\\u0940\\u092e\\u093e \\u0939\\u0948?\",\"answer\":\"\\u0939\\u093e\\u0902, \\u0906\\u092a\\u0915\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u0915\\u0947 \\u092a\\u094d\\u0930\\u0915\\u093e\\u0930 \\u0914\\u0930 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0907\\u0924\\u093f\\u0939\\u093e\\u0938 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0938\\u0940\\u092e\\u093e\\u090f\\u0902 \\u0939\\u094b \\u0938\\u0915\\u0924\\u0940 \\u0939\\u0948\\u0902\\u0964 \\u0915\\u0943\\u092a\\u092f\\u093e \\u0905\\u092a\\u0928\\u0940 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u093e \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917 \\u091c\\u093e\\u0902\\u091a\\u0947\\u0902 \\u092f\\u093e \\u0935\\u093f\\u0936\\u093f\\u0937\\u094d\\u091f \\u0938\\u0940\\u092e\\u093e \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915 \\u0938\\u0939\\u093e\\u092f\\u0924\\u093e \\u0938\\u0947 \\u0938\\u0902\\u092a\\u0930\\u094d\\u0915 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724bf92ac4e5\"}}}', 1, 1, '2024-11-01 17:45:50', '2024-11-06 16:09:52');
INSERT INTO `frontend_header_section_faqs` VALUES (27, 27, 'enterprise', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About Withdrawing Money on QRPay Pro\",\"sub_heading\":\"Find answers to your queries regarding the withdrawal process as an agent on QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0639\\u0644\\u0649 QRPay Pro\",\"sub_heading\":\"\\u0627\\u0628\\u062d\\u062b \\u0639\\u0646 \\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0644\\u0627\\u0633\\u062a\\u0641\\u0633\\u0627\\u0631\\u0627\\u062a\\u0643 \\u0627\\u0644\\u0645\\u062a\\u0639\\u0644\\u0642\\u0629 \\u0628\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0643\\u0648\\u0643\\u064a\\u0644 \\u0639\\u0644\\u0649 QRPay Pro.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre retirar dinero en QRPay Pro\",\"sub_heading\":\"Encuentre respuestas a sus consultas sobre el proceso de retiro como agente en QRPay Pro.\"},\"fr\":{\"heading\":\"Questions fr\\u00e9quemment pos\\u00e9es sur le retrait d\'argent sur QRPay Pro\",\"sub_heading\":\"Trouvez des r\\u00e9ponses \\u00e0 vos questions concernant le processus de retrait en tant qu\'agent sur QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u0930 \\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u0930 \\u090f\\u0915 \\u090f\\u091c\\u0947\\u0902\\u091f \\u0915\\u0947 \\u0930\\u0942\\u092a \\u092e\\u0947\\u0902 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0915\\u0947 \\u0938\\u0902\\u092c\\u0902\\u0927 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u0916\\u094b\\u091c\\u0947\\u0902\\u0964\"}},\"items\":{\"6724c03924266\":{\"language\":{\"en\":{\"question\":\"How can I withdraw money from my QRPay Pro account?\",\"answer\":\"To withdraw money, log in to your account, navigate to the \\u2018Withdraw Money\\u2019 section, enter the amount, select your withdrawal method, and confirm the transaction.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u0646 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u064a\\u061f\",\"answer\":\"\\u0644\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u060c \\u0642\\u0645 \\u0628\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0643\\u060c \\u0648\\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u0642\\u0633\\u0645 \\\"\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\\"\\u060c \\u0648\\u0623\\u062f\\u062e\\u0644 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a\\u060c \\u0648\\u062d\\u062f\\u062f \\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643\\u060c \\u0648\\u0642\\u0645 \\u0628\\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo puedo retirar dinero de mi cuenta QRPay Pro?\",\"answer\":\"Para retirar dinero, inicie sesi\\u00f3n en su cuenta, navegue hasta la secci\\u00f3n \\\"Retirar dinero\\\", ingrese el monto, seleccione su m\\u00e9todo de retiro y confirme la transacci\\u00f3n.\"},\"fr\":{\"question\":\"Comment puis-je retirer de l\'argent de mon compte QRPay Pro ?\",\"answer\":\"Pour retirer de l\'argent, connectez-vous \\u00e0 votre compte, acc\\u00e9dez \\u00e0 la section \\u00ab Retirer de l\'argent \\u00bb, saisissez le montant, s\\u00e9lectionnez votre m\\u00e9thode de retrait et confirmez la transaction.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u0938\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u0905\\u092a\\u0928\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0932\\u0949\\u0917 \\u0907\\u0928 \\u0915\\u0930\\u0947\\u0902, \'\\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0947\\u0902\' \\u0905\\u0928\\u0941\\u092d\\u093e\\u0917 \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0902, \\u0930\\u093e\\u0936\\u093f \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902, \\u0905\\u092a\\u0928\\u0940 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0935\\u093f\\u0927\\u093f \\u091a\\u0941\\u0928\\u0947\\u0902 \\u0914\\u0930 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724c03924266\"},\"6724c04656b40\":{\"language\":{\"en\":{\"question\":\"What withdrawal methods are available on QRPay Pro?\",\"answer\":\"You can withdraw funds via bank transfer and other supported methods available in the withdrawal section of your QRPay Pro account.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0647\\u064a \\u0637\\u0631\\u0642 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0645\\u062a\\u0648\\u0641\\u0631\\u0629 \\u0639\\u0644\\u0649 QRPay Pro\\u061f\",\"answer\":\"\\u064a\\u0645\\u0643\\u0646\\u0643 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0639\\u0646 \\u0637\\u0631\\u064a\\u0642 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0635\\u0631\\u0641\\u064a \\u0648\\u0627\\u0644\\u0637\\u0631\\u0642 \\u0627\\u0644\\u0645\\u062f\\u0639\\u0648\\u0645\\u0629 \\u0627\\u0644\\u0623\\u062e\\u0631\\u0649 \\u0627\\u0644\\u0645\\u062a\\u0627\\u062d\\u0629 \\u0641\\u064a \\u0642\\u0633\\u0645 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 m\\u00e9todos de retiro est\\u00e1n disponibles en QRPay Pro?\",\"answer\":\"Puede retirar fondos mediante transferencia bancaria y otros m\\u00e9todos admitidos disponibles en la secci\\u00f3n de retiro de su cuenta QRPay Pro.\"},\"fr\":{\"question\":\"Quelles m\\u00e9thodes de retrait sont disponibles sur QRPay Pro ?\",\"answer\":\"Vous pouvez retirer des fonds par virement bancaire et d\'autres m\\u00e9thodes prises en charge disponibles dans la section retrait de votre compte QRPay Pro.\"},\"hi\":{\"question\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u0930 \\u0915\\u094c\\u0928 \\u0938\\u0940 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0935\\u093f\\u0927\\u093f\\u092f\\u093e\\u0902 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0939\\u0948\\u0902?\",\"answer\":\"\\u0906\\u092a \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u0915\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0905\\u0928\\u0941\\u092d\\u093e\\u0917 \\u092e\\u0947\\u0902 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u092c\\u0948\\u0902\\u0915 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0914\\u0930 \\u0905\\u0928\\u094d\\u092f \\u0938\\u092e\\u0930\\u094d\\u0925\\u093f\\u0924 \\u0924\\u0930\\u0940\\u0915\\u094b\\u0902 \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0928\\u093f\\u0915\\u093e\\u0932 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724c04656b40\"},\"6724c051c2e7a\":{\"language\":{\"en\":{\"question\":\"Are there any fees associated with withdrawing money?\",\"answer\":\"Yes, there may be transaction fees depending on the withdrawal method you choose. The fees will be displayed before you confirm your withdrawal.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u0642\\u062f \\u062a\\u0643\\u0648\\u0646 \\u0647\\u0646\\u0627\\u0643 \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0629 \\u0627\\u0639\\u062a\\u0645\\u0627\\u062f\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0627\\u0644\\u062a\\u064a \\u062a\\u062e\\u062a\\u0627\\u0631\\u0647\\u0627. \\u0633\\u064a\\u062a\\u0645 \\u0639\\u0631\\u0636 \\u0627\\u0644\\u0631\\u0633\\u0648\\u0645 \\u0642\\u0628\\u0644 \\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0633\\u062d\\u0628.\"},\"es\":{\"question\":\"\\u00bfExiste alguna tarifa asociada con el retiro de dinero?\",\"answer\":\"S\\u00ed, puede haber tarifas de transacci\\u00f3n seg\\u00fan el m\\u00e9todo de retiro que elija. Las tarifas se mostrar\\u00e1n antes de que confirme su retiro.\"},\"fr\":{\"question\":\"Y a-t-il des frais associ\\u00e9s au retrait d\\u2019argent ?\",\"answer\":\"Oui, des frais de transaction peuvent s\'appliquer selon la m\\u00e9thode de retrait que vous choisissez. Les frais seront affich\\u00e9s avant que vous confirmiez votre retrait.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u0947 \\u0938\\u0947 \\u091c\\u0941\\u0921\\u093c\\u0940 \\u0915\\u094b\\u0908 \\u092b\\u0940\\u0938 \\u0939\\u0948?\",\"answer\":\"\\u0939\\u093e\\u0902, \\u0906\\u092a\\u0915\\u0947 \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u091a\\u0941\\u0928\\u0940 \\u0917\\u0908 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0935\\u093f\\u0927\\u093f \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0932\\u0917 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0906\\u092a\\u0915\\u0940 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0938\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u092a\\u094d\\u0930\\u0926\\u0930\\u094d\\u0936\\u093f\\u0924 \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e\\u090f\\u0917\\u093e\\u0964\"}},\"id\":\"6724c051c2e7a\"},\"6724c05ceb7b1\":{\"language\":{\"en\":{\"question\":\"How long does it take for my withdrawal request to be processed?\",\"answer\":\"Withdrawal processing times may vary based on the method selected. Generally, bank transfers may take 1-3 business days to complete, while other methods may be faster.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0647\\u064a \\u0637\\u0631\\u0642 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0645\\u062a\\u0648\\u0641\\u0631\\u0629 \\u0639\\u0644\\u0649 QRPay Pro\\u061f\",\"answer\":\"\\u064a\\u0645\\u0643\\u0646\\u0643 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0639\\u0646 \\u0637\\u0631\\u064a\\u0642 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0635\\u0631\\u0641\\u064a \\u0648\\u0627\\u0644\\u0637\\u0631\\u0642 \\u0627\\u0644\\u0645\\u062f\\u0639\\u0648\\u0645\\u0629 \\u0627\\u0644\\u0623\\u062e\\u0631\\u0649 \\u0627\\u0644\\u0645\\u062a\\u0627\\u062d\\u0629 \\u0641\\u064a \\u0642\\u0633\\u0645 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 m\\u00e9todos de retiro est\\u00e1n disponibles en QRPay Pro?\",\"answer\":\"Puede retirar fondos mediante transferencia bancaria y otros m\\u00e9todos admitidos disponibles en la secci\\u00f3n de retiro de su cuenta QRPay Pro.\"},\"fr\":{\"question\":\"Quelles m\\u00e9thodes de retrait sont disponibles sur QRPay Pro ?\",\"answer\":\"Vous pouvez retirer des fonds par virement bancaire et d\'autres m\\u00e9thodes prises en charge disponibles dans la section retrait de votre compte QRPay Pro.\"},\"hi\":{\"question\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u0930 \\u0915\\u094c\\u0928 \\u0938\\u0940 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0935\\u093f\\u0927\\u093f\\u092f\\u093e\\u0902 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0939\\u0948\\u0902?\",\"answer\":\"\\u0906\\u092a \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u0915\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0905\\u0928\\u0941\\u092d\\u093e\\u0917 \\u092e\\u0947\\u0902 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u092c\\u0948\\u0902\\u0915 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0914\\u0930 \\u0905\\u0928\\u094d\\u092f \\u0938\\u092e\\u0930\\u094d\\u0925\\u093f\\u0924 \\u0924\\u0930\\u0940\\u0915\\u094b\\u0902 \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0928\\u093f\\u0915\\u093e\\u0932 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724c05ceb7b1\"}}}', 1, 1, '2024-11-01 17:49:03', '2024-11-06 16:35:43');
INSERT INTO `frontend_header_section_faqs` VALUES (28, 28, 'enterprise', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About Sending Money as an Agent on QRPay Pro\",\"sub_heading\":\"Find answers to common queries about the agent-to-agent money transfer process on QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0643\\u0648\\u0643\\u064a\\u0644 \\u0639\\u0644\\u0649 QRPay Pro\",\"sub_heading\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0644\\u0644\\u0627\\u0633\\u062a\\u0641\\u0633\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0634\\u0627\\u0626\\u0639\\u0629 \\u062d\\u0648\\u0644 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u0646 \\u0648\\u0643\\u064a\\u0644 \\u0625\\u0644\\u0649 \\u0648\\u0643\\u064a\\u0644 \\u0639\\u0644\\u0649 QRPay Pro.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre el env\\u00edo de dinero como agente en QRPay Pro\",\"sub_heading\":\"Encuentre respuestas a consultas comunes sobre el proceso de transferencia de dinero de agente a agente en QRPay Pro.\"},\"fr\":{\"heading\":\"Questions fr\\u00e9quemment pos\\u00e9es sur l\'envoi d\'argent en tant qu\'agent sur QRPay Pro\",\"sub_heading\":\"Trouvez des r\\u00e9ponses aux questions courantes sur le processus de transfert d\'argent d\'agent \\u00e0 agent sur QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay Pro \\u092a\\u0930 \\u090f\\u091c\\u0947\\u0902\\u091f \\u0915\\u0947 \\u0930\\u0942\\u092a \\u092e\\u0947\\u0902 \\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u0930 \\u090f\\u091c\\u0947\\u0902\\u091f-\\u091f\\u0942-\\u090f\\u091c\\u0947\\u0902\\u091f \\u0927\\u0928 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0938\\u093e\\u092e\\u093e\\u0928\\u094d\\u092f \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u0916\\u094b\\u091c\\u0947\\u0902\\u0964\"}},\"items\":{\"6724c1d0cda27\":{\"language\":{\"en\":{\"question\":\"How do I send money to another agent on QRPay Pro?\",\"answer\":\"To send money, log in to your account, navigate to the \\u2018Send Money\\u2019 section, enter the recipient agent\\u2019s details, specify the amount, review the transaction, and confirm to complete the transfer.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u0648\\u0643\\u064a\\u0644 \\u0622\\u062e\\u0631 \\u0639\\u0644\\u0649 QRPay Pro\\u061f\",\"answer\":\"\\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u060c \\u0642\\u0645 \\u0628\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0643\\u060c \\u0648\\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u0642\\u0633\\u0645 \\\"\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\\"\\u060c \\u0648\\u0623\\u062f\\u062e\\u0644 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0648\\u0643\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645\\u060c \\u0648\\u062d\\u062f\\u062f \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a\\u060c \\u0648\\u0631\\u0627\\u062c\\u0639 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629\\u060c \\u0648\\u0623\\u0643\\u062f \\u0625\\u0643\\u0645\\u0627\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo env\\u00edo dinero a otro agente en QRPay Pro?\",\"answer\":\"Para enviar dinero, inicie sesi\\u00f3n en su cuenta, navegue hasta la secci\\u00f3n \\\"Enviar dinero\\\", ingrese los detalles del agente destinatario, especifique el monto, revise la transacci\\u00f3n y confirme para completar la transferencia.\"},\"fr\":{\"question\":\"Comment envoyer de l\'argent \\u00e0 un autre agent sur QRPay Pro ?\",\"answer\":\"Pour envoyer de l\'argent, connectez-vous \\u00e0 votre compte, acc\\u00e9dez \\u00e0 la section \\u00ab Envoyer de l\'argent \\u00bb, saisissez les coordonn\\u00e9es de l\'agent destinataire, sp\\u00e9cifiez le montant, examinez la transaction et confirmez pour terminer le transfert.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay Pro \\u092a\\u0930 \\u0915\\u093f\\u0938\\u0940 \\u0905\\u0928\\u094d\\u092f \\u090f\\u091c\\u0947\\u0902\\u091f \\u0915\\u094b \\u092a\\u0948\\u0938\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0942\\u0902?\",\"answer\":\"\\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u0905\\u092a\\u0928\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0932\\u0949\\u0917 \\u0907\\u0928 \\u0915\\u0930\\u0947\\u0902, \'\\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0947\\u0902\' \\u0905\\u0928\\u0941\\u092d\\u093e\\u0917 \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0902, \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u090f\\u091c\\u0947\\u0902\\u091f \\u0915\\u093e \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902, \\u0930\\u093e\\u0936\\u093f \\u0928\\u093f\\u0930\\u094d\\u0926\\u093f\\u0937\\u094d\\u091f \\u0915\\u0930\\u0947\\u0902, \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u0938\\u092e\\u0940\\u0915\\u094d\\u0937\\u093e \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u092a\\u0942\\u0930\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724c1d0cda27\"},\"6724c1d930155\":{\"language\":{\"en\":{\"question\":\"Can I send money to users outside of the agent network?\",\"answer\":\"No, money transfers using the Send Money feature are strictly for agent-to-agent transactions within QRPay Pro.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u064a\\u0646 \\u062e\\u0627\\u0631\\u062c \\u0634\\u0628\\u0643\\u0629 \\u0627\\u0644\\u0648\\u0643\\u0644\\u0627\\u0621\\u061f\",\"answer\":\"\\u0644\\u0627\\u060c \\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0645\\u064a\\u0632\\u0629 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u062e\\u0635\\u0635\\u0629 \\u0641\\u0642\\u0637 \\u0644\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0645\\u0646 \\u0648\\u0643\\u064a\\u0644 \\u0625\\u0644\\u0649 \\u0648\\u0643\\u064a\\u0644 \\u062f\\u0627\\u062e\\u0644 QRPay Pro.\"},\"es\":{\"question\":\"\\u00bfPuedo enviar dinero a usuarios fuera de la red de agentes?\",\"answer\":\"No, las transferencias de dinero que utilizan la funci\\u00f3n Enviar dinero son estrictamente para transacciones de agente a agente dentro de QRPay Pro.\"},\"fr\":{\"question\":\"Puis-je envoyer de l\'argent \\u00e0 des utilisateurs en dehors du r\\u00e9seau d\'agents\\u00a0?\",\"answer\":\"Non, les transferts d\'argent utilisant la fonction Envoyer de l\'argent sont strictement destin\\u00e9s aux transactions d\'agent \\u00e0 agent au sein de QRPay Pro.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u090f\\u091c\\u0947\\u0902\\u091f \\u0928\\u0947\\u091f\\u0935\\u0930\\u094d\\u0915 \\u0915\\u0947 \\u092c\\u093e\\u0939\\u0930 \\u0915\\u0947 \\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e\\u0913\\u0902 \\u0915\\u094b \\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0928\\u0939\\u0940\\u0902, \\u0938\\u0947\\u0902\\u0921 \\u092e\\u0928\\u0940 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u0927\\u0928 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u0947\\u0935\\u0932 QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u092d\\u0940\\u0924\\u0930 \\u090f\\u091c\\u0947\\u0902\\u091f-\\u091f\\u0942-\\u090f\\u091c\\u0947\\u0902\\u091f \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0939\\u0948\\u0964\"}},\"id\":\"6724c1d930155\"},\"6724c1e36f91c\":{\"language\":{\"en\":{\"question\":\"Is there a limit on how much money I can send to another agent?\",\"answer\":\"Yes, there may be limits based on your account type and verification status. Check your account settings for specific sending limits.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u062d\\u062f \\u0644\\u0645\\u0642\\u062f\\u0627\\u0631 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0627\\u0644\\u062a\\u064a \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0625\\u0631\\u0633\\u0627\\u0644\\u0647\\u0627 \\u0625\\u0644\\u0649 \\u0648\\u0643\\u064a\\u0644 \\u0622\\u062e\\u0631\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u0642\\u062f \\u062a\\u0643\\u0648\\u0646 \\u0647\\u0646\\u0627\\u0643 \\u062d\\u062f\\u0648\\u062f \\u0628\\u0646\\u0627\\u0621\\u064b \\u0639\\u0644\\u0649 \\u0646\\u0648\\u0639 \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0648\\u062d\\u0627\\u0644\\u0629 \\u0627\\u0644\\u062a\\u062d\\u0642\\u0642. \\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0644\\u0645\\u0639\\u0631\\u0641\\u0629 \\u062d\\u062f\\u0648\\u062f \\u0627\\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0645\\u062d\\u062f\\u062f\\u0629.\"},\"es\":{\"question\":\"\\u00bfExiste un l\\u00edmite de cu\\u00e1nto dinero puedo enviar a otro agente?\",\"answer\":\"S\\u00ed, puede haber l\\u00edmites seg\\u00fan el tipo de cuenta y el estado de verificaci\\u00f3n. Verifique la configuraci\\u00f3n de su cuenta para conocer los l\\u00edmites de env\\u00edo espec\\u00edficos.\"},\"fr\":{\"question\":\"Y a-t-il une limite au montant d\\u2019argent que je peux envoyer \\u00e0 un autre agent ?\",\"answer\":\"Oui, il peut y avoir des limites en fonction de votre type de compte et de votre statut de v\\u00e9rification. V\\u00e9rifiez les param\\u00e8tres de votre compte pour conna\\u00eetre les limites d\'envoi sp\\u00e9cifiques.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u0907\\u0938 \\u092a\\u0930 \\u0915\\u094b\\u0908 \\u0938\\u0940\\u092e\\u093e \\u0939\\u0948 \\u0915\\u093f \\u092e\\u0948\\u0902 \\u0926\\u0942\\u0938\\u0930\\u0947 \\u090f\\u091c\\u0947\\u0902\\u091f \\u0915\\u094b \\u0915\\u093f\\u0924\\u0928\\u093e \\u092a\\u0948\\u0938\\u093e \\u092d\\u0947\\u091c \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0939\\u093e\\u0901, \\u0906\\u092a\\u0915\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u0915\\u0947 \\u092a\\u094d\\u0930\\u0915\\u093e\\u0930 \\u0914\\u0930 \\u0938\\u0924\\u094d\\u092f\\u093e\\u092a\\u0928 \\u0938\\u094d\\u0925\\u093f\\u0924\\u093f \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0938\\u0940\\u092e\\u093e\\u090f\\u0901 \\u0939\\u094b \\u0938\\u0915\\u0924\\u0940 \\u0939\\u0948\\u0902\\u0964 \\u0935\\u093f\\u0936\\u093f\\u0937\\u094d\\u091f \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0940 \\u0938\\u0940\\u092e\\u093e \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u0940 \\u0916\\u093e\\u0924\\u093e \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917 \\u091c\\u093e\\u0902\\u091a\\u0947\\u0902\\u0964\"}},\"id\":\"6724c1e36f91c\"},\"6724c1eec2967\":{\"language\":{\"en\":{\"question\":\"How will I be notified of a successful transfer?\",\"answer\":\"After sending money, you will receive a notification confirming the transaction. You can also view your transaction history in your QRPay Pro account for details.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u0633\\u064a\\u062a\\u0645 \\u0625\\u0639\\u0644\\u0627\\u0645\\u064a \\u0628\\u0646\\u062c\\u0627\\u062d \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0646\\u0642\\u0644\\u061f\",\"answer\":\"\\u0628\\u0639\\u062f \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u060c \\u0633\\u062a\\u062a\\u0644\\u0642\\u0649 \\u0625\\u0634\\u0639\\u0627\\u0631\\u064b\\u0627 \\u064a\\u0624\\u0643\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629. \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0623\\u064a\\u0636\\u064b\\u0627 \\u0639\\u0631\\u0636 \\u0633\\u062c\\u0644 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u0643 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo se me notificar\\u00e1 de una transferencia exitosa?\",\"answer\":\"Despu\\u00e9s de enviar dinero, recibir\\u00e1s una notificaci\\u00f3n confirmando la transacci\\u00f3n. Tambi\\u00e9n puede ver su historial de transacciones en su cuenta QRPay Pro para obtener m\\u00e1s detalles.\"},\"fr\":{\"question\":\"Comment serai-je inform\\u00e9 d\\u2019un transfert r\\u00e9ussi\\u00a0?\",\"answer\":\"Apr\\u00e8s avoir envoy\\u00e9 de l\'argent, vous recevrez une notification confirmant la transaction. Vous pouvez \\u00e9galement consulter l\'historique de vos transactions dans votre compte QRPay Pro pour plus de d\\u00e9tails.\"},\"hi\":{\"question\":\"\\u092e\\u0941\\u091d\\u0947 \\u0938\\u092b\\u0932 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0915\\u0948\\u0938\\u0947 \\u0938\\u0942\\u091a\\u093f\\u0924 \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e\\u090f\\u0917\\u093e?\",\"answer\":\"\\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0926, \\u0906\\u092a\\u0915\\u094b \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0940 \\u090f\\u0915 \\u0905\\u0927\\u093f\\u0938\\u0942\\u091a\\u0928\\u093e \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0939\\u094b\\u0917\\u0940\\u0964 \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0906\\u092a \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u093e \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0907\\u0924\\u093f\\u0939\\u093e\\u0938 \\u092d\\u0940 \\u0926\\u0947\\u0916 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724c1eec2967\"}}}', 1, 1, '2024-11-01 17:54:49', '2024-11-06 15:27:15');
INSERT INTO `frontend_header_section_faqs` VALUES (29, 29, 'enterprise', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About Money In on QRPay Pro\",\"sub_heading\":\"Get answers to your questions about transferring funds to users\' wallets.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 Money In \\u0639\\u0644\\u0649 QRPay Pro\",\"sub_heading\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0644\\u0623\\u0633\\u0626\\u0644\\u062a\\u0643 \\u062d\\u0648\\u0644 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u0645\\u062d\\u0627\\u0641\\u0638 \\u0627\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u064a\\u0646.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre la entrada de dinero en QRPay Pro\",\"sub_heading\":\"Obtenga respuestas a sus preguntas sobre la transferencia de fondos a las billeteras de los usuarios.\"},\"fr\":{\"heading\":\"Foire aux questions sur les entr\\u00e9es d\'argent sur QRPay Pro\",\"sub_heading\":\"Obtenez des r\\u00e9ponses \\u00e0 vos questions sur le transfert de fonds vers les portefeuilles des utilisateurs.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u0930 \\u092e\\u0928\\u0940 \\u0907\\u0928 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"\\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0935\\u0949\\u0932\\u0947\\u091f \\u092e\\u0947\\u0902 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"6724c54659e55\":{\"language\":{\"en\":{\"question\":\"How do I send money to a user\'s wallet using QRPay Pro?\",\"answer\":\"To send money, log in to your account, go to the \\u2018Money In\\u2019 section, select the user by entering their QRPay Pro ID, email, or phone number, specify the amount, review the details, and confirm the transfer.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u0645\\u062d\\u0641\\u0638\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\\u061f\",\"answer\":\"\\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u060c \\u0642\\u0645 \\u0628\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0643\\u060c \\u0648\\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u0642\\u0633\\u0645 \\\"Money In\\\"\\u060c \\u0648\\u062d\\u062f\\u062f \\u0627\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645 \\u0639\\u0646 \\u0637\\u0631\\u064a\\u0642 \\u0625\\u062f\\u062e\\u0627\\u0644 \\u0645\\u0639\\u0631\\u0641 QRPay Pro \\u0623\\u0648 \\u0627\\u0644\\u0628\\u0631\\u064a\\u062f \\u0627\\u0644\\u0625\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a \\u0623\\u0648 \\u0631\\u0642\\u0645 \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641\\u060c \\u0648\\u062d\\u062f\\u062f \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a\\u060c \\u0648\\u0631\\u0627\\u062c\\u0639 \\u0627\\u0644\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644\\u060c \\u0648\\u0642\\u0645 \\u0628\\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo env\\u00edo dinero a la billetera de un usuario usando QRPay Pro?\",\"answer\":\"Para enviar dinero, inicie sesi\\u00f3n en su cuenta, vaya a la secci\\u00f3n \\\"Ingreso de dinero\\\", seleccione el usuario ingresando su ID de QRPay Pro, correo electr\\u00f3nico o n\\u00famero de tel\\u00e9fono, especifique el monto, revise los detalles y confirme la transferencia.\"},\"fr\":{\"question\":\"Comment puis-je envoyer de l\'argent vers le portefeuille d\'un utilisateur \\u00e0 l\'aide de QRPay Pro\\u00a0?\",\"answer\":\"Pour envoyer de l\'argent, connectez-vous \\u00e0 votre compte, acc\\u00e9dez \\u00e0 la section \\u00ab Argent entrant \\u00bb, s\\u00e9lectionnez l\'utilisateur en saisissant son identifiant QRPay Pro, son adresse e-mail ou son num\\u00e9ro de t\\u00e9l\\u00e9phone, sp\\u00e9cifiez le montant, v\\u00e9rifiez les d\\u00e9tails et confirmez le transfert.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay Pro \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u0947 \\u0935\\u0949\\u0932\\u0947\\u091f \\u092e\\u0947\\u0902 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0942\\u0902?\",\"answer\":\"\\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u0905\\u092a\\u0928\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0932\\u0949\\u0917 \\u0907\\u0928 \\u0915\\u0930\\u0947\\u0902, \'\\u092e\\u0928\\u0940 \\u0907\\u0928\' \\u0905\\u0928\\u0941\\u092d\\u093e\\u0917 \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0902, \\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u093e \\u091a\\u092f\\u0928 \\u0909\\u0928\\u0915\\u0940 QRPay \\u092a\\u094d\\u0930\\u094b \\u0906\\u0908\\u0921\\u0940, \\u0908\\u092e\\u0947\\u0932 \\u092f\\u093e \\u092b\\u094b\\u0928 \\u0928\\u0902\\u092c\\u0930 \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0915\\u0947 \\u0915\\u0930\\u0947\\u0902, \\u0930\\u093e\\u0936\\u093f \\u0928\\u093f\\u0930\\u094d\\u0926\\u093f\\u0937\\u094d\\u091f \\u0915\\u0930\\u0947\\u0902, \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0915\\u0940 \\u0938\\u092e\\u0940\\u0915\\u094d\\u0937\\u093e \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724c54659e55\"},\"6724c54f0a9de\":{\"language\":{\"en\":{\"question\":\"What information do I need to send money to a user?\",\"answer\":\"You will need the recipient\'s QRPay Pro ID, email address, or phone number to successfully complete the transfer.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0647\\u064a \\u0627\\u0644\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u0623\\u062d\\u062a\\u0627\\u062c\\u0647\\u0627 \\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u061f\",\"answer\":\"\\u0633\\u062a\\u062d\\u062a\\u0627\\u062c \\u0625\\u0644\\u0649 \\u0645\\u0639\\u0631\\u0641 QRPay Pro \\u0623\\u0648 \\u0639\\u0646\\u0648\\u0627\\u0646 \\u0627\\u0644\\u0628\\u0631\\u064a\\u062f \\u0627\\u0644\\u0625\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a \\u0623\\u0648 \\u0631\\u0642\\u0645 \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645 \\u0644\\u0625\\u0643\\u0645\\u0627\\u0644 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0646\\u0642\\u0644 \\u0628\\u0646\\u062c\\u0627\\u062d.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 informaci\\u00f3n necesito para enviar dinero a un usuario?\",\"answer\":\"Necesitar\\u00e1 el ID de QRPay Pro, la direcci\\u00f3n de correo electr\\u00f3nico o el n\\u00famero de tel\\u00e9fono del destinatario para completar con \\u00e9xito la transferencia.\"},\"fr\":{\"question\":\"De quelles informations ai-je besoin pour envoyer de l\'argent \\u00e0 un utilisateur\\u00a0?\",\"answer\":\"Vous aurez besoin de l\'identifiant QRPay Pro, de l\'adresse e-mail ou du num\\u00e9ro de t\\u00e9l\\u00e9phone du destinataire pour r\\u00e9ussir le transfert.\"},\"hi\":{\"question\":\"\\u0915\\u093f\\u0938\\u0940 \\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u094b \\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092e\\u0941\\u091d\\u0947 \\u0915\\u093f\\u0938 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0915\\u0940 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915\\u0924\\u093e \\u0939\\u094b\\u0917\\u0940?\",\"answer\":\"\\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u094b \\u0938\\u092b\\u0932\\u0924\\u093e\\u092a\\u0942\\u0930\\u094d\\u0935\\u0915 \\u092a\\u0942\\u0930\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0906\\u092a\\u0915\\u094b \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u0940 QRPay \\u092a\\u094d\\u0930\\u094b \\u0906\\u0908\\u0921\\u0940, \\u0908\\u092e\\u0947\\u0932 \\u092a\\u0924\\u093e \\u092f\\u093e \\u092b\\u094b\\u0928 \\u0928\\u0902\\u092c\\u0930 \\u0915\\u0940 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915\\u0924\\u093e \\u0939\\u094b\\u0917\\u0940\\u0964\"}},\"id\":\"6724c54f0a9de\"},\"6724c556354b1\":{\"language\":{\"en\":{\"question\":\"Are there any fees for sending money to users?\",\"answer\":\"Fees may apply depending on the transaction amount and any applicable service charges. Please review the fee structure in your account settings for detailed information.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0644\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u064a\\u0646\\u061f\",\"answer\":\"\\u0642\\u062f \\u064a\\u062a\\u0645 \\u062a\\u0637\\u0628\\u064a\\u0642 \\u0631\\u0633\\u0648\\u0645 \\u0627\\u0639\\u062a\\u0645\\u0627\\u062f\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629 \\u0648\\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u062e\\u062f\\u0645\\u0629 \\u0645\\u0637\\u0628\\u0642\\u0629. \\u064a\\u0631\\u062c\\u0649 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0629 \\u0647\\u064a\\u0643\\u0644 \\u0627\\u0644\\u0631\\u0633\\u0648\\u0645 \\u0641\\u064a \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0645\\u0641\\u0635\\u0644\\u0629.\"},\"es\":{\"question\":\"\\u00bfHay alguna tarifa por enviar dinero a los usuarios?\",\"answer\":\"Es posible que se apliquen tarifas seg\\u00fan el monto de la transacci\\u00f3n y los cargos por servicio aplicables. Revise la estructura de tarifas en la configuraci\\u00f3n de su cuenta para obtener informaci\\u00f3n detallada.\"},\"fr\":{\"question\":\"Y a-t-il des frais pour envoyer de l\\u2019argent aux utilisateurs ?\",\"answer\":\"Des frais peuvent s\'appliquer en fonction du montant de la transaction et des frais de service applicables. Veuillez consulter la structure des frais dans les param\\u00e8tres de votre compte pour des informations d\\u00e9taill\\u00e9es.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e\\u0913\\u0902 \\u0915\\u094b \\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u094b\\u0908 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0939\\u0948?\",\"answer\":\"\\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0930\\u093e\\u0936\\u093f \\u0914\\u0930 \\u0915\\u093f\\u0938\\u0940 \\u092d\\u0940 \\u0932\\u093e\\u0917\\u0942 \\u0938\\u0947\\u0935\\u093e \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0932\\u093e\\u0917\\u0942 \\u0939\\u094b \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0935\\u093f\\u0938\\u094d\\u0924\\u0943\\u0924 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u0943\\u092a\\u092f\\u093e \\u0905\\u092a\\u0928\\u0940 \\u0916\\u093e\\u0924\\u093e \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917 \\u092e\\u0947\\u0902 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0938\\u0902\\u0930\\u091a\\u0928\\u093e \\u0915\\u0940 \\u0938\\u092e\\u0940\\u0915\\u094d\\u0937\\u093e \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724c556354b1\"},\"6724c5604f54d\":{\"language\":{\"en\":{\"question\":\"How long does it take for the funds to reach the user\'s wallet?\",\"answer\":\"Transfers are typically processed instantly, and the funds should appear in the recipient\'s wallet shortly after you complete the transaction.\"},\"ar\":{\"question\":\"\\u0643\\u0645 \\u0645\\u0646 \\u0627\\u0644\\u0648\\u0642\\u062a \\u064a\\u0633\\u062a\\u063a\\u0631\\u0642 \\u0648\\u0635\\u0648\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u0645\\u062d\\u0641\\u0638\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u061f\",\"answer\":\"\\u062a\\u062a\\u0645 \\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0639\\u0627\\u062f\\u0629\\u064b \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631\\u060c \\u0648\\u064a\\u062c\\u0628 \\u0623\\u0646 \\u062a\\u0638\\u0647\\u0631 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a \\u0645\\u062d\\u0641\\u0638\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645 \\u0628\\u0639\\u062f \\u0648\\u0642\\u062a \\u0642\\u0635\\u064a\\u0631 \\u0645\\u0646 \\u0625\\u0643\\u0645\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629.\"},\"es\":{\"question\":\"\\u00bfCu\\u00e1nto tiempo tardan los fondos en llegar a la billetera del usuario?\",\"answer\":\"Las transferencias generalmente se procesan instant\\u00e1neamente y los fondos deber\\u00edan aparecer en la billetera del destinatario poco despu\\u00e9s de completar la transacci\\u00f3n.\"},\"fr\":{\"question\":\"Combien de temps faut-il pour que les fonds atteignent le portefeuille de l\'utilisateur\\u00a0?\",\"answer\":\"Les transferts sont g\\u00e9n\\u00e9ralement trait\\u00e9s instantan\\u00e9ment et les fonds devraient appara\\u00eetre dans le portefeuille du destinataire peu de temps apr\\u00e8s la fin de la transaction.\"},\"hi\":{\"question\":\"\\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u0947 \\u0935\\u0949\\u0932\\u0947\\u091f \\u0924\\u0915 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u092a\\u0939\\u0941\\u0902\\u091a\\u0928\\u0947 \\u092e\\u0947\\u0902 \\u0915\\u093f\\u0924\\u0928\\u093e \\u0938\\u092e\\u092f \\u0932\\u0917\\u0924\\u093e \\u0939\\u0948?\",\"answer\":\"\\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0906\\u092e \\u0924\\u094c\\u0930 \\u092a\\u0930 \\u0924\\u0941\\u0930\\u0902\\u0924 \\u0938\\u0902\\u0938\\u093e\\u0927\\u093f\\u0924 \\u0939\\u094b\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0914\\u0930 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u092a\\u0942\\u0930\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0924\\u0941\\u0930\\u0902\\u0924 \\u092c\\u093e\\u0926 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u0947 \\u0935\\u0949\\u0932\\u0947\\u091f \\u092e\\u0947\\u0902 \\u0926\\u093f\\u0916\\u093e\\u0908 \\u0926\\u0947\\u0928\\u0940 \\u091a\\u093e\\u0939\\u093f\\u090f\\u0964\"}},\"id\":\"6724c5604f54d\"}}}', 1, 1, '2024-11-01 18:10:30', '2024-11-07 10:43:15');
INSERT INTO `frontend_header_section_faqs` VALUES (30, 30, 'enterprise', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About Bill Pay on QRPay Pro\",\"sub_heading\":\"Find answers to your questions about making bill payments on behalf of users.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u062f\\u0641\\u0639 \\u0627\\u0644\\u0641\\u0648\\u0627\\u062a\\u064a\\u0631 \\u0639\\u0644\\u0649 QRPay Pro\",\"sub_heading\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0644\\u0623\\u0633\\u0626\\u0644\\u062a\\u0643 \\u062d\\u0648\\u0644 \\u0633\\u062f\\u0627\\u062f \\u0627\\u0644\\u0641\\u0648\\u0627\\u062a\\u064a\\u0631 \\u0646\\u064a\\u0627\\u0628\\u0629 \\u0639\\u0646 \\u0627\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u064a\\u0646.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre el pago de facturas en QRPay Pro\",\"sub_heading\":\"Encuentre respuestas a sus preguntas sobre c\\u00f3mo realizar pagos de facturas en nombre de los usuarios.\"},\"fr\":{\"heading\":\"Foire aux questions sur le paiement de factures sur QRPay Pro\",\"sub_heading\":\"Trouvez les r\\u00e9ponses \\u00e0 vos questions sur le paiement des factures au nom des utilisateurs.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u0930 \\u092c\\u093f\\u0932 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"\\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e\\u0913\\u0902 \\u0915\\u0940 \\u0913\\u0930 \\u0938\\u0947 \\u092c\\u093f\\u0932 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u0916\\u094b\\u091c\\u0947\\u0902\\u0964\"}},\"items\":{\"6724c60951cc9\":{\"language\":{\"en\":{\"question\":\"How do I pay bills using QRPay Pro?\",\"answer\":\"To pay bills, log in to your account, navigate to the \\u2018Bill Pay\\u2019 section, select the bill type, enter the required details, review the payment information, and confirm the payment.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u062f\\u0641\\u0639 \\u0627\\u0644\\u0641\\u0648\\u0627\\u062a\\u064a\\u0631 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\\u061f\",\"answer\":\"\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u0641\\u0648\\u0627\\u062a\\u064a\\u0631\\u060c \\u0642\\u0645 \\u0628\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0643\\u060c \\u0648\\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u0642\\u0633\\u0645 \\\"\\u062f\\u0641\\u0639 \\u0627\\u0644\\u0641\\u0648\\u0627\\u062a\\u064a\\u0631\\\"\\u060c \\u062b\\u0645 \\u062d\\u062f\\u062f \\u0646\\u0648\\u0639 \\u0627\\u0644\\u0641\\u0627\\u062a\\u0648\\u0631\\u0629\\u060c \\u0648\\u0623\\u062f\\u062e\\u0644 \\u0627\\u0644\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628\\u0629\\u060c \\u0648\\u0645\\u0631\\u0627\\u062c\\u0639\\u0629 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0627\\u0644\\u062f\\u0641\\u0639\\u060c \\u062b\\u0645 \\u0642\\u0645 \\u0628\\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u062f\\u0641\\u0639.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo pago facturas usando QRPay Pro?\",\"answer\":\"Para pagar facturas, inicie sesi\\u00f3n en su cuenta, navegue hasta la secci\\u00f3n \\\"Pago de facturas\\\", seleccione el tipo de factura, ingrese los detalles requeridos, revise la informaci\\u00f3n de pago y confirme el pago.\"},\"fr\":{\"question\":\"Comment payer mes factures avec QRPay Pro\\u00a0?\",\"answer\":\"Pour payer vos factures, connectez-vous \\u00e0 votre compte, acc\\u00e9dez \\u00e0 la section \\u00ab\\u00a0Paiement de factures\\u00a0\\u00bb, s\\u00e9lectionnez le type de facture, saisissez les d\\u00e9tails requis, v\\u00e9rifiez les informations de paiement et confirmez le paiement.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay Pro \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u092c\\u093f\\u0932\\u094b\\u0902 \\u0915\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0948\\u0938\\u0947 \\u0915\\u0930\\u0942\\u0901?\",\"answer\":\"\\u092c\\u093f\\u0932\\u094b\\u0902 \\u0915\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u0905\\u092a\\u0928\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0932\\u0949\\u0917 \\u0907\\u0928 \\u0915\\u0930\\u0947\\u0902, \'\\u092c\\u093f\\u0932 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928\' \\u0905\\u0928\\u0941\\u092d\\u093e\\u0917 \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0901, \\u092c\\u093f\\u0932 \\u092a\\u094d\\u0930\\u0915\\u093e\\u0930 \\u0915\\u093e \\u091a\\u092f\\u0928 \\u0915\\u0930\\u0947\\u0902, \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915 \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902, \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0915\\u0940 \\u0938\\u092e\\u0940\\u0915\\u094d\\u0937\\u093e \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724c60951cc9\"},\"6724c6132c8f5\":{\"language\":{\"en\":{\"question\":\"What types of bills can I pay through QRPay Pro?\",\"answer\":\"You can pay a variety of bills including utilities, subscriptions, and other service-related payments, depending on the providers available in your area.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0647\\u064a \\u0623\\u0646\\u0648\\u0627\\u0639 \\u0627\\u0644\\u0641\\u0648\\u0627\\u062a\\u064a\\u0631 \\u0627\\u0644\\u062a\\u064a \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u062f\\u0641\\u0639\\u0647\\u0627 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 QRPay Pro\\u061f\",\"answer\":\"\\u064a\\u0645\\u0643\\u0646\\u0643 \\u062f\\u0641\\u0639 \\u0645\\u062c\\u0645\\u0648\\u0639\\u0629 \\u0645\\u062a\\u0646\\u0648\\u0639\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0641\\u0648\\u0627\\u062a\\u064a\\u0631 \\u0628\\u0645\\u0627 \\u0641\\u064a \\u0630\\u0644\\u0643 \\u0627\\u0644\\u0645\\u0631\\u0627\\u0641\\u0642 \\u0648\\u0627\\u0644\\u0627\\u0634\\u062a\\u0631\\u0627\\u0643\\u0627\\u062a \\u0648\\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0627\\u0644\\u0623\\u062e\\u0631\\u0649 \\u0627\\u0644\\u0645\\u062a\\u0639\\u0644\\u0642\\u0629 \\u0628\\u0627\\u0644\\u062e\\u062f\\u0645\\u0629\\u060c \\u0627\\u0639\\u062a\\u0645\\u0627\\u062f\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u0645\\u0642\\u062f\\u0645\\u064a \\u0627\\u0644\\u062e\\u062f\\u0645\\u0629 \\u0627\\u0644\\u0645\\u062a\\u0648\\u0641\\u0631\\u064a\\u0646 \\u0641\\u064a \\u0645\\u0646\\u0637\\u0642\\u062a\\u0643.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 tipos de facturas puedo pagar a trav\\u00e9s de QRPay Pro?\",\"answer\":\"Puede pagar una variedad de facturas, incluidos servicios p\\u00fablicos, suscripciones y otros pagos relacionados con servicios, seg\\u00fan los proveedores disponibles en su \\u00e1rea.\"},\"fr\":{\"question\":\"Quels types de factures puis-je payer via QRPay Pro\\u00a0?\",\"answer\":\"Vous pouvez payer diverses factures, notamment les services publics, les abonnements et autres paiements li\\u00e9s aux services, en fonction des fournisseurs disponibles dans votre r\\u00e9gion.\"},\"hi\":{\"question\":\"QRPay Pro \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u092e\\u0948\\u0902 \\u0915\\u093f\\u0938 \\u092a\\u094d\\u0930\\u0915\\u093e\\u0930 \\u0915\\u0947 \\u092c\\u093f\\u0932\\u094b\\u0902 \\u0915\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0902?\",\"answer\":\"\\u0906\\u092a \\u0905\\u092a\\u0928\\u0947 \\u0915\\u094d\\u0937\\u0947\\u0924\\u094d\\u0930 \\u092e\\u0947\\u0902 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0924\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0909\\u092a\\u092f\\u094b\\u0917\\u093f\\u0924\\u093e\\u0913\\u0902, \\u0938\\u0926\\u0938\\u094d\\u092f\\u0924\\u093e\\u0913\\u0902 \\u0914\\u0930 \\u0905\\u0928\\u094d\\u092f \\u0938\\u0947\\u0935\\u093e-\\u0938\\u0902\\u092c\\u0902\\u0927\\u093f\\u0924 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928\\u094b\\u0902 \\u0938\\u0939\\u093f\\u0924 \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u092a\\u094d\\u0930\\u0915\\u093e\\u0930 \\u0915\\u0947 \\u092c\\u093f\\u0932\\u094b\\u0902 \\u0915\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"6724c6132c8f5\"},\"6724c61b864ee\":{\"language\":{\"en\":{\"question\":\"Is there a fee for using the Bill Pay feature?\",\"answer\":\"Fees may apply based on the specific bill being paid and any associated service charges. Please check your account settings for detailed fee information.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0631\\u0633\\u0648\\u0645 \\u0644\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u062e\\u0627\\u0635\\u064a\\u0629 \\u062f\\u0641\\u0639 \\u0627\\u0644\\u0641\\u0627\\u062a\\u0648\\u0631\\u0629\\u061f\",\"answer\":\"\\u0642\\u062f \\u064a\\u062a\\u0645 \\u062a\\u0637\\u0628\\u064a\\u0642 \\u0627\\u0644\\u0631\\u0633\\u0648\\u0645 \\u0628\\u0646\\u0627\\u0621\\u064b \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0627\\u062a\\u0648\\u0631\\u0629 \\u0627\\u0644\\u0645\\u062d\\u062f\\u062f\\u0629 \\u0627\\u0644\\u062a\\u064a \\u064a\\u062a\\u0645 \\u062f\\u0641\\u0639\\u0647\\u0627 \\u0648\\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u062e\\u062f\\u0645\\u0629 \\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0647\\u0627. \\u064a\\u0631\\u062c\\u0649 \\u0627\\u0644\\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0645\\u0641\\u0635\\u0644\\u0629 \\u0639\\u0646 \\u0627\\u0644\\u0631\\u0633\\u0648\\u0645.\"},\"es\":{\"question\":\"\\u00bfSe aplica alg\\u00fan cargo por utilizar la funci\\u00f3n Pago de facturas?\",\"answer\":\"Es posible que se apliquen tarifas seg\\u00fan la factura espec\\u00edfica que se pague y los cargos de servicio asociados. Verifique la configuraci\\u00f3n de su cuenta para obtener informaci\\u00f3n detallada sobre las tarifas.\"},\"fr\":{\"question\":\"Y a-t-il des frais pour l\'utilisation de la fonction Bill Pay\\u00a0?\",\"answer\":\"Des frais peuvent s\'appliquer en fonction de la facture sp\\u00e9cifique \\u00e0 payer et des frais de service associ\\u00e9s. Veuillez v\\u00e9rifier les param\\u00e8tres de votre compte pour obtenir des informations d\\u00e9taill\\u00e9es sur les frais.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092c\\u093f\\u0932 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u094b\\u0908 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0939\\u0948?\",\"answer\":\"\\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u093f\\u090f \\u091c\\u093e \\u0930\\u0939\\u0947 \\u0935\\u093f\\u0936\\u093f\\u0937\\u094d\\u091f \\u092c\\u093f\\u0932 \\u0914\\u0930 \\u0915\\u093f\\u0938\\u0940 \\u092d\\u0940 \\u0938\\u0902\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0938\\u0947\\u0935\\u093e \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0932\\u093e\\u0917\\u0942 \\u0939\\u094b \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0915\\u0943\\u092a\\u092f\\u093e \\u0935\\u093f\\u0938\\u094d\\u0924\\u0943\\u0924 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u0940 \\u0916\\u093e\\u0924\\u093e \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917 \\u091c\\u093e\\u0902\\u091a\\u0947\\u0902\\u0964\"}},\"id\":\"6724c61b864ee\"},\"6724c6238ce71\":{\"language\":{\"en\":{\"question\":\"How will I know if my bill payment was successful?\",\"answer\":\"You will receive a notification confirming the successful payment, along with a transaction reference number for your records.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u0633\\u0623\\u0639\\u0631\\u0641 \\u0645\\u0627 \\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646 \\u062f\\u0641\\u0639 \\u0641\\u0627\\u062a\\u0648\\u0631\\u062a\\u064a \\u0646\\u0627\\u062c\\u062d\\u064b\\u0627\\u061f\",\"answer\":\"\\u0633\\u062a\\u062a\\u0644\\u0642\\u0649 \\u0625\\u0634\\u0639\\u0627\\u0631\\u064b\\u0627 \\u064a\\u0624\\u0643\\u062f \\u0646\\u062c\\u0627\\u062d \\u0627\\u0644\\u062f\\u0641\\u0639\\u060c \\u0628\\u0627\\u0644\\u0625\\u0636\\u0627\\u0641\\u0629 \\u0625\\u0644\\u0649 \\u0631\\u0642\\u0645 \\u0645\\u0631\\u062c\\u0639\\u064a \\u0644\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629 \\u0644\\u0644\\u0627\\u062d\\u062a\\u0641\\u0627\\u0638 \\u0628\\u0647 \\u0641\\u064a \\u0633\\u062c\\u0644\\u0627\\u062a\\u0643.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo sabr\\u00e9 si el pago de mi factura fue exitoso?\",\"answer\":\"Recibir\\u00e1 una notificaci\\u00f3n confirmando el pago exitoso, junto con un n\\u00famero de referencia de la transacci\\u00f3n para sus registros.\"},\"fr\":{\"question\":\"Comment saurai-je si le paiement de ma facture a r\\u00e9ussi\\u00a0?\",\"answer\":\"Vous recevrez une notification confirmant le paiement r\\u00e9ussi, ainsi qu\'un num\\u00e9ro de r\\u00e9f\\u00e9rence de transaction pour vos dossiers.\"},\"hi\":{\"question\":\"\\u092e\\u0941\\u091d\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u092a\\u0924\\u093e \\u091a\\u0932\\u0947\\u0917\\u093e \\u0915\\u093f \\u092e\\u0947\\u0930\\u093e \\u092c\\u093f\\u0932 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u092b\\u0932 \\u0930\\u0939\\u093e?\",\"answer\":\"\\u0906\\u092a\\u0915\\u094b \\u0905\\u092a\\u0928\\u0947 \\u0930\\u093f\\u0915\\u0949\\u0930\\u094d\\u0921 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0938\\u0902\\u0926\\u0930\\u094d\\u092d \\u0938\\u0902\\u0916\\u094d\\u092f\\u093e \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0938\\u092b\\u0932 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0940 \\u090f\\u0915 \\u0905\\u0927\\u093f\\u0938\\u0942\\u091a\\u0928\\u093e \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0939\\u094b\\u0917\\u0940\\u0964\"}},\"id\":\"6724c6238ce71\"}}}', 1, 1, '2024-11-01 18:13:52', '2024-11-06 16:52:49');
INSERT INTO `frontend_header_section_faqs` VALUES (31, 31, 'enterprise', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About Mobile Top-Up on QRPay Pro\",\"sub_heading\":\"Get answers to your queries regarding mobile top-ups for users.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0639\\u0644\\u0649 QRPay Pro\",\"sub_heading\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0644\\u0627\\u0633\\u062a\\u0641\\u0633\\u0627\\u0631\\u0627\\u062a\\u0643 \\u0627\\u0644\\u0645\\u062a\\u0639\\u0644\\u0642\\u0629 \\u0628\\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0644\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u064a\\u0646.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre la recarga m\\u00f3vil en QRPay Pro\",\"sub_heading\":\"Obt\\u00e9n respuesta a tus consultas sobre recargas de m\\u00f3vil para usuarios.\"},\"fr\":{\"heading\":\"Foire aux questions sur la recharge mobile sur QRPay Pro\",\"sub_heading\":\"Obtenez des r\\u00e9ponses \\u00e0 vos questions concernant les recharges mobiles pour les utilisateurs.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u0930 \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"\\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0915\\u0947 \\u0938\\u0902\\u092c\\u0902\\u0927 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"6724c6dbe65f0\":{\"language\":{\"en\":{\"question\":\"How can I top-up a mobile phone using QRPay Pro?\",\"answer\":\"To top-up a mobile phone, log in to your account, navigate to the \\u2018Mobile Top-Up\\u2019 section, enter the mobile number, select the amount, review the details, and confirm the transaction.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0647\\u0627\\u062a\\u0641\\u064a \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\\u061f\",\"answer\":\"\\u0644\\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0647\\u0627\\u062a\\u0641 \\u0645\\u062d\\u0645\\u0648\\u0644\\u060c \\u0642\\u0645 \\u0628\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0643\\u060c \\u0648\\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u0642\\u0633\\u0645 \\\"\\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644\\\"\\u060c \\u0648\\u0623\\u062f\\u062e\\u0644 \\u0631\\u0642\\u0645 \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644\\u060c \\u0648\\u062d\\u062f\\u062f \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a\\u060c \\u0648\\u0631\\u0627\\u062c\\u0639 \\u0627\\u0644\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644\\u060c \\u0648\\u0642\\u0645 \\u0628\\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo puedo recargar un tel\\u00e9fono m\\u00f3vil usando QRPay Pro?\",\"answer\":\"Para recargar un tel\\u00e9fono m\\u00f3vil, inicie sesi\\u00f3n en su cuenta, navegue hasta la secci\\u00f3n \\\"Recarga m\\u00f3vil\\\", ingrese el n\\u00famero de tel\\u00e9fono m\\u00f3vil, seleccione el monto, revise los detalles y confirme la transacci\\u00f3n.\"},\"fr\":{\"question\":\"Comment puis-je recharger un t\\u00e9l\\u00e9phone mobile avec QRPay Pro\\u00a0?\",\"answer\":\"Pour recharger un t\\u00e9l\\u00e9phone mobile, connectez-vous \\u00e0 votre compte, acc\\u00e9dez \\u00e0 la section \\u00ab Recharge mobile \\u00bb, saisissez le num\\u00e9ro de mobile, s\\u00e9lectionnez le montant, v\\u00e9rifiez les d\\u00e9tails et confirmez la transaction.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay Pro \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u092b\\u093c\\u094b\\u0928 \\u0915\\u093e \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0915\\u0948\\u0938\\u0947 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u092b\\u093c\\u094b\\u0928 \\u0915\\u094b \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u0905\\u092a\\u0928\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0932\\u0949\\u0917 \\u0907\\u0928 \\u0915\\u0930\\u0947\\u0902, \'\\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u091f\\u0949\\u092a-\\u0905\\u092a\' \\u0905\\u0928\\u0941\\u092d\\u093e\\u0917 \\u092a\\u0930 \\u091c\\u093e\\u090f\\u0901, \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u0928\\u0902\\u092c\\u0930 \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902, \\u0930\\u093e\\u0936\\u093f \\u0915\\u093e \\u091a\\u092f\\u0928 \\u0915\\u0930\\u0947\\u0902, \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0915\\u0940 \\u0938\\u092e\\u0940\\u0915\\u094d\\u0937\\u093e \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724c6dbe65f0\"},\"6724c6e520d82\":{\"language\":{\"en\":{\"question\":\"Which mobile networks can I top-up through QRPay Pro?\",\"answer\":\"QRPay Pro supports a variety of mobile networks. Please check the available networks in your area on the Mobile Top-Up page.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0647\\u064a \\u0634\\u0628\\u0643\\u0627\\u062a \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0627\\u0644\\u062a\\u064a \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0634\\u062d\\u0646\\u0647\\u0627 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 QRPay Pro\\u061f\",\"answer\":\"\\u064a\\u062f\\u0639\\u0645 QRPay Pro \\u0645\\u062c\\u0645\\u0648\\u0639\\u0629 \\u0645\\u062a\\u0646\\u0648\\u0639\\u0629 \\u0645\\u0646 \\u0634\\u0628\\u0643\\u0627\\u062a \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644. \\u064a\\u0631\\u062c\\u0649 \\u0627\\u0644\\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0627\\u0644\\u0634\\u0628\\u0643\\u0627\\u062a \\u0627\\u0644\\u0645\\u062a\\u0627\\u062d\\u0629 \\u0641\\u064a \\u0645\\u0646\\u0637\\u0642\\u062a\\u0643 \\u0639\\u0644\\u0649 \\u0635\\u0641\\u062d\\u0629 \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 redes m\\u00f3viles puedo recargar a trav\\u00e9s de QRPay Pro?\",\"answer\":\"QRPay Pro admite una variedad de redes m\\u00f3viles. Verifique las redes disponibles en su \\u00e1rea en la p\\u00e1gina de recarga m\\u00f3vil.\"},\"fr\":{\"question\":\"Quels r\\u00e9seaux mobiles puis-je recharger via QRPay Pro\\u00a0?\",\"answer\":\"QRPay Pro prend en charge une vari\\u00e9t\\u00e9 de r\\u00e9seaux mobiles. Veuillez v\\u00e9rifier les r\\u00e9seaux disponibles dans votre r\\u00e9gion sur la page Recharge mobile.\"},\"hi\":{\"question\":\"QRPay Pro \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u092e\\u0948\\u0902 \\u0915\\u094c\\u0928 \\u0938\\u0947 \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u0928\\u0947\\u091f\\u0935\\u0930\\u094d\\u0915 \\u0915\\u094b \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0902?\",\"answer\":\"QRPay Pro \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u092a\\u094d\\u0930\\u0915\\u093e\\u0930 \\u0915\\u0947 \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u0928\\u0947\\u091f\\u0935\\u0930\\u094d\\u0915 \\u0915\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0915\\u0943\\u092a\\u092f\\u093e \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u091f\\u0949\\u092a-\\u0905\\u092a \\u092a\\u0943\\u0937\\u094d\\u0920 \\u092a\\u0930 \\u0905\\u092a\\u0928\\u0947 \\u0915\\u094d\\u0937\\u0947\\u0924\\u094d\\u0930 \\u092e\\u0947\\u0902 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0928\\u0947\\u091f\\u0935\\u0930\\u094d\\u0915 \\u0915\\u0940 \\u091c\\u093e\\u0901\\u091a \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724c6e520d82\"},\"6724c6ed4d547\":{\"language\":{\"en\":{\"question\":\"Are there any fees associated with mobile top-ups?\",\"answer\":\"Fees may apply based on the top-up amount and the mobile network provider. Review your account settings for specific fee details.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644\\u061f\",\"answer\":\"\\u0642\\u062f \\u064a\\u062a\\u0645 \\u062a\\u0637\\u0628\\u064a\\u0642 \\u0631\\u0633\\u0648\\u0645 \\u0628\\u0646\\u0627\\u0621\\u064b \\u0639\\u0644\\u0649 \\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u062a\\u0639\\u0628\\u0626\\u0629 \\u0648\\u0645\\u0632\\u0648\\u062f \\u0634\\u0628\\u0643\\u0629 \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644. \\u0642\\u0645 \\u0628\\u0645\\u0631\\u0627\\u062c\\u0639\\u0629 \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0631\\u0633\\u0648\\u0645 \\u0627\\u0644\\u0645\\u062d\\u062f\\u062f\\u0629.\"},\"es\":{\"question\":\"\\u00bfHay alguna tarifa asociada con las recargas m\\u00f3viles?\",\"answer\":\"Es posible que se apliquen tarifas seg\\u00fan el monto de la recarga y el proveedor de la red m\\u00f3vil. Revise la configuraci\\u00f3n de su cuenta para obtener detalles de tarifas espec\\u00edficas.\"},\"fr\":{\"question\":\"Y a-t-il des frais associ\\u00e9s aux recharges mobiles ?\",\"answer\":\"Des frais peuvent s\'appliquer en fonction du montant de la recharge et du fournisseur de r\\u00e9seau mobile. V\\u00e9rifiez les param\\u00e8tres de votre compte pour conna\\u00eetre les d\\u00e9tails des frais sp\\u00e9cifiques.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0938\\u0947 \\u091c\\u0941\\u0921\\u093c\\u0940 \\u0915\\u094b\\u0908 \\u092b\\u0940\\u0938 \\u0939\\u0948?\",\"answer\":\"\\u0936\\u0941\\u0932\\u094d\\u0915 \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0930\\u093e\\u0936\\u093f \\u0914\\u0930 \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u0928\\u0947\\u091f\\u0935\\u0930\\u094d\\u0915 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0924\\u093e \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0932\\u093e\\u0917\\u0942 \\u0939\\u094b \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0935\\u093f\\u0936\\u093f\\u0937\\u094d\\u091f \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u0940 \\u0916\\u093e\\u0924\\u093e \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917 \\u0915\\u0940 \\u0938\\u092e\\u0940\\u0915\\u094d\\u0937\\u093e \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724c6ed4d547\"},\"6724c6f7db794\":{\"language\":{\"en\":{\"question\":\"How will I know if the mobile top-up was successful?\",\"answer\":\"You will receive a notification confirming the successful top-up along with a transaction reference number for your records.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u0633\\u0623\\u0639\\u0631\\u0641 \\u0645\\u0627 \\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646\\u062a \\u0639\\u0645\\u0644\\u064a\\u0629 \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0646\\u0627\\u062c\\u062d\\u0629\\u061f\",\"answer\":\"\\u0633\\u062a\\u062a\\u0644\\u0642\\u0649 \\u0625\\u0634\\u0639\\u0627\\u0631\\u064b\\u0627 \\u064a\\u0624\\u0643\\u062f \\u0646\\u062c\\u0627\\u062d \\u0639\\u0645\\u0644\\u064a\\u0629 \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0627\\u0644\\u0631\\u0635\\u064a\\u062f \\u0628\\u0627\\u0644\\u0625\\u0636\\u0627\\u0641\\u0629 \\u0625\\u0644\\u0649 \\u0631\\u0642\\u0645 \\u0645\\u0631\\u062c\\u0639\\u064a \\u0644\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629 \\u0644\\u0644\\u0627\\u062d\\u062a\\u0641\\u0627\\u0638 \\u0628\\u0647 \\u0641\\u064a \\u0633\\u062c\\u0644\\u0627\\u062a\\u0643.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo sabr\\u00e9 si la recarga m\\u00f3vil fue exitosa?\",\"answer\":\"Recibir\\u00e1s una notificaci\\u00f3n confirmando la recarga exitosa junto con un n\\u00famero de referencia de la transacci\\u00f3n para tus registros.\"},\"fr\":{\"question\":\"Comment saurai-je si la recharge mobile a r\\u00e9ussi ?\",\"answer\":\"Vous recevrez une notification confirmant la recharge r\\u00e9ussie ainsi qu\'un num\\u00e9ro de r\\u00e9f\\u00e9rence de transaction pour vos dossiers.\"},\"hi\":{\"question\":\"\\u092e\\u0941\\u091d\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u092a\\u0924\\u093e \\u091a\\u0932\\u0947\\u0917\\u093e \\u0915\\u093f \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0938\\u092b\\u0932 \\u0930\\u0939\\u093e?\",\"answer\":\"\\u0906\\u092a\\u0915\\u094b \\u0905\\u092a\\u0928\\u0947 \\u0930\\u093f\\u0915\\u0949\\u0930\\u094d\\u0921 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0938\\u0902\\u0926\\u0930\\u094d\\u092d \\u0938\\u0902\\u0916\\u094d\\u092f\\u093e \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0938\\u092b\\u0932 \\u091f\\u0949\\u092a-\\u0905\\u092a \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0940 \\u090f\\u0915 \\u0905\\u0927\\u093f\\u0938\\u0942\\u091a\\u0928\\u093e \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0939\\u094b\\u0917\\u0940\\u0964\"}},\"id\":\"6724c6f7db794\"}}}', 1, 1, '2024-11-01 18:17:20', '2024-11-06 17:07:21');
INSERT INTO `frontend_header_section_faqs` VALUES (32, 32, 'enterprise', '{\"language\":{\"en\":{\"heading\":\"Frequently Asked Questions About Remittance on QRPay Pro\",\"sub_heading\":\"Find answers to common questions regarding remittance services for agents.\"},\"ar\":{\"heading\":\"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0627\\u0644\\u064a\\u0629 \\u0639\\u0644\\u0649 QRPay Pro\",\"sub_heading\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0625\\u062c\\u0627\\u0628\\u0627\\u062a \\u0644\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0634\\u0627\\u0626\\u0639\\u0629 \\u0627\\u0644\\u0645\\u062a\\u0639\\u0644\\u0642\\u0629 \\u0628\\u062e\\u062f\\u0645\\u0627\\u062a \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0644\\u0644\\u0648\\u0643\\u0644\\u0627\\u0621.\"},\"es\":{\"heading\":\"Preguntas frecuentes sobre remesas en QRPay Pro\",\"sub_heading\":\"Encuentre respuestas a preguntas comunes sobre los servicios de remesas para agentes.\"},\"fr\":{\"heading\":\"Foire aux questions sur les versements sur QRPay Pro\",\"sub_heading\":\"Trouvez des r\\u00e9ponses aux questions courantes concernant les services de transfert de fonds pour les agents.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u0930 \\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0905\\u0915\\u094d\\u0938\\u0930 \\u092a\\u0942\\u091b\\u0947 \\u091c\\u093e\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\",\"sub_heading\":\"\\u090f\\u091c\\u0947\\u0902\\u091f\\u094b\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u0938\\u0947\\u0935\\u093e\\u0913\\u0902 \\u0938\\u0947 \\u0938\\u0902\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0938\\u093e\\u092e\\u093e\\u0928\\u094d\\u092f \\u092a\\u094d\\u0930\\u0936\\u094d\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u0916\\u094b\\u091c\\u0947\\u0902\\u0964\"}},\"items\":{\"6724c9041a665\":{\"language\":{\"en\":{\"question\":\"How do I send a remittance using QRPay Pro?\",\"answer\":\"To send a remittance, log into your account, select the \\u2018Remittance\\u2019 option, enter the recipient\'s details, choose the amount, review the transaction, and confirm the transfer.\"},\"ar\":{\"question\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0625\\u0631\\u0633\\u0627\\u0644 \\u062d\\u0648\\u0627\\u0644\\u0629 \\u0645\\u0627\\u0644\\u064a\\u0629 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\\u061f\",\"answer\":\"\\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u062d\\u0648\\u0627\\u0644\\u0629\\u060c \\u0642\\u0645 \\u0628\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0643\\u060c \\u062b\\u0645 \\u062d\\u062f\\u062f \\u062e\\u064a\\u0627\\u0631 \\\"\\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\\"\\u060c \\u0648\\u0623\\u062f\\u062e\\u0644 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645\\u060c \\u0648\\u0627\\u062e\\u062a\\u0631 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a\\u060c \\u0648\\u0631\\u0627\\u062c\\u0639 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629\\u060c \\u0648\\u0642\\u0645 \\u0628\\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644.\"},\"es\":{\"question\":\"\\u00bfC\\u00f3mo env\\u00edo una remesa usando QRPay Pro?\",\"answer\":\"Para enviar una remesa, inicie sesi\\u00f3n en su cuenta, seleccione la opci\\u00f3n \'Remesa\', ingrese los datos del destinatario, elija el monto, revise la transacci\\u00f3n y confirme la transferencia.\"},\"fr\":{\"question\":\"Comment envoyer un versement en utilisant QRPay Pro\\u00a0?\",\"answer\":\"Pour envoyer un versement, connectez-vous \\u00e0 votre compte, s\\u00e9lectionnez l\'option \\u00ab Remise de fonds \\u00bb, saisissez les coordonn\\u00e9es du destinataire, choisissez le montant, v\\u00e9rifiez la transaction et confirmez le transfert.\"},\"hi\":{\"question\":\"\\u092e\\u0948\\u0902 QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u0915\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0942\\u0902?\",\"answer\":\"\\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f, \\u0905\\u092a\\u0928\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0932\\u0949\\u0917 \\u0907\\u0928 \\u0915\\u0930\\u0947\\u0902, \'\\u092a\\u094d\\u0930\\u0947\\u0937\\u0923\' \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a \\u091a\\u0941\\u0928\\u0947\\u0902, \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u093e \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902, \\u0930\\u093e\\u0936\\u093f \\u091a\\u0941\\u0928\\u0947\\u0902, \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u0938\\u092e\\u0940\\u0915\\u094d\\u0937\\u093e \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724c9041a665\"},\"6724c90c318e3\":{\"language\":{\"en\":{\"question\":\"Is there a limit on how much I can send through remittance?\",\"answer\":\"Yes, there may be limits on remittance amounts based on your account type and the recipient\'s location. Check the terms in your account settings for specific limits.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u062d\\u062f \\u0644\\u0644\\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0630\\u064a \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0625\\u0631\\u0633\\u0627\\u0644\\u0647 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645\\u060c \\u0642\\u062f \\u062a\\u0643\\u0648\\u0646 \\u0647\\u0646\\u0627\\u0643 \\u062d\\u062f\\u0648\\u062f \\u0644\\u0645\\u0628\\u0627\\u0644\\u063a \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0628\\u0646\\u0627\\u0621\\u064b \\u0639\\u0644\\u0649 \\u0646\\u0648\\u0639 \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0648\\u0645\\u0648\\u0642\\u0639 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645. \\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0627\\u0644\\u0634\\u0631\\u0648\\u0637 \\u0627\\u0644\\u0645\\u0648\\u062c\\u0648\\u062f\\u0629 \\u0641\\u064a \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0644\\u0645\\u0639\\u0631\\u0641\\u0629 \\u0627\\u0644\\u062d\\u062f\\u0648\\u062f \\u0627\\u0644\\u0645\\u062d\\u062f\\u062f\\u0629.\"},\"es\":{\"question\":\"\\u00bfExiste un l\\u00edmite de cu\\u00e1nto puedo enviar mediante remesas?\",\"answer\":\"S\\u00ed, puede haber l\\u00edmites en los montos de las remesas seg\\u00fan su tipo de cuenta y la ubicaci\\u00f3n del destinatario. Consulte los t\\u00e9rminos en la configuraci\\u00f3n de su cuenta para conocer l\\u00edmites espec\\u00edficos.\"},\"fr\":{\"question\":\"Y a-t-il une limite au montant que je peux envoyer par virement de fonds ?\",\"answer\":\"Oui, il peut y avoir des limites sur les montants des versements en fonction de votre type de compte et de l\'emplacement du destinataire. V\\u00e9rifiez les conditions dans les param\\u00e8tres de votre compte pour conna\\u00eetre les limites sp\\u00e9cifiques.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u0907\\u0938 \\u092a\\u0930 \\u0915\\u094b\\u0908 \\u0938\\u0940\\u092e\\u093e \\u0939\\u0948 \\u0915\\u093f \\u092e\\u0948\\u0902 \\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u0915\\u093f\\u0924\\u0928\\u093e \\u092d\\u0947\\u091c \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?\",\"answer\":\"\\u0939\\u093e\\u0902, \\u0906\\u092a\\u0915\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u0915\\u0947 \\u092a\\u094d\\u0930\\u0915\\u093e\\u0930 \\u0914\\u0930 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u0947 \\u0938\\u094d\\u0925\\u093e\\u0928 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u0930\\u093e\\u0936\\u093f \\u092a\\u0930 \\u0938\\u0940\\u092e\\u093e\\u090f\\u0902 \\u0939\\u094b \\u0938\\u0915\\u0924\\u0940 \\u0939\\u0948\\u0902\\u0964 \\u0935\\u093f\\u0936\\u093f\\u0937\\u094d\\u091f \\u0938\\u0940\\u092e\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u0940 \\u0916\\u093e\\u0924\\u093e \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917 \\u092e\\u0947\\u0902 \\u0936\\u0930\\u094d\\u0924\\u094b\\u0902 \\u0915\\u0940 \\u091c\\u093e\\u0901\\u091a \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724c90c318e3\"},\"6724c91468977\":{\"language\":{\"en\":{\"question\":\"How long does it take for the recipient to receive the funds?\",\"answer\":\"Funds are typically transferred instantly, but some transactions may take longer depending on the recipient\'s country and local banking processes.\"},\"ar\":{\"question\":\"\\u0643\\u0645 \\u0645\\u0646 \\u0627\\u0644\\u0648\\u0642\\u062a \\u064a\\u0633\\u062a\\u063a\\u0631\\u0642 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645 \\u0644\\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u061f\",\"answer\":\"\\u064a\\u062a\\u0645 \\u0639\\u0627\\u062f\\u0629\\u064b \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631\\u060c \\u0648\\u0644\\u0643\\u0646 \\u0642\\u062f \\u062a\\u0633\\u062a\\u063a\\u0631\\u0642 \\u0628\\u0639\\u0636 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0648\\u0642\\u062a\\u064b\\u0627 \\u0623\\u0637\\u0648\\u0644 \\u0627\\u0639\\u062a\\u0645\\u0627\\u062f\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u0628\\u0644\\u062f \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645 \\u0648\\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0627\\u0644\\u0645\\u0635\\u0631\\u0641\\u064a\\u0629 \\u0627\\u0644\\u0645\\u062d\\u0644\\u064a\\u0629.\"},\"es\":{\"question\":\"\\u00bfCu\\u00e1nto tiempo tarda el destinatario en recibir los fondos?\",\"answer\":\"Los fondos generalmente se transfieren instant\\u00e1neamente, pero algunas transacciones pueden demorar m\\u00e1s seg\\u00fan el pa\\u00eds del destinatario y los procesos bancarios locales.\"},\"fr\":{\"question\":\"Combien de temps faut-il pour que le b\\u00e9n\\u00e9ficiaire re\\u00e7oive les fonds ?\",\"answer\":\"Les fonds sont g\\u00e9n\\u00e9ralement transf\\u00e9r\\u00e9s instantan\\u00e9ment, mais certaines transactions peuvent prendre plus de temps en fonction du pays du destinataire et des processus bancaires locaux.\"},\"hi\":{\"question\":\"\\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u094b \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u092e\\u0947\\u0902 \\u0915\\u093f\\u0924\\u0928\\u093e \\u0938\\u092e\\u092f \\u0932\\u0917\\u0924\\u093e \\u0939\\u0948?\",\"answer\":\"\\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0906\\u092e \\u0924\\u094c\\u0930 \\u092a\\u0930 \\u0924\\u0941\\u0930\\u0902\\u0924 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u093f\\u0924 \\u0915\\u0940 \\u091c\\u093e\\u0924\\u0940 \\u0939\\u0948, \\u0932\\u0947\\u0915\\u093f\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u0947 \\u0926\\u0947\\u0936 \\u0914\\u0930 \\u0938\\u094d\\u0925\\u093e\\u0928\\u0940\\u092f \\u092c\\u0948\\u0902\\u0915\\u093f\\u0902\\u0917 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0915\\u0941\\u091b \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u092e\\u0947\\u0902 \\u0905\\u0927\\u093f\\u0915 \\u0938\\u092e\\u092f \\u0932\\u0917 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964\"}},\"id\":\"6724c91468977\"},\"6724c91cc135e\":{\"language\":{\"en\":{\"question\":\"Are there any fees associated with sending remittances?\",\"answer\":\"Fees may vary depending on the amount sent and the destination country. Please review the fee structure in your account settings for detailed information.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0623\\u064a \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u062d\\u0648\\u0627\\u0644\\u0627\\u062a\\u061f\",\"answer\":\"\\u0642\\u062f \\u062a\\u062e\\u062a\\u0644\\u0641 \\u0627\\u0644\\u0631\\u0633\\u0648\\u0645 \\u062d\\u0633\\u0628 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0645\\u0631\\u0633\\u0644 \\u0648\\u0628\\u0644\\u062f \\u0627\\u0644\\u0648\\u062c\\u0647\\u0629. \\u064a\\u0631\\u062c\\u0649 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0629 \\u0647\\u064a\\u0643\\u0644 \\u0627\\u0644\\u0631\\u0633\\u0648\\u0645 \\u0641\\u064a \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0645\\u0641\\u0635\\u0644\\u0629.\"},\"es\":{\"question\":\"\\u00bfExisten tarifas asociadas con el env\\u00edo de remesas?\",\"answer\":\"Las tarifas pueden variar seg\\u00fan la cantidad enviada y el pa\\u00eds de destino. Revise la estructura de tarifas en la configuraci\\u00f3n de su cuenta para obtener informaci\\u00f3n detallada.\"},\"fr\":{\"question\":\"Y a-t-il des frais associ\\u00e9s \\u00e0 l\\u2019envoi de fonds ?\",\"answer\":\"Les frais peuvent varier en fonction du montant envoy\\u00e9 et du pays de destination. Veuillez consulter la structure des frais dans les param\\u00e8tres de votre compte pour des informations d\\u00e9taill\\u00e9es.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0938\\u0947 \\u0938\\u0902\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0915\\u094b\\u0908 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0939\\u0948?\",\"answer\":\"\\u092d\\u0947\\u091c\\u0940 \\u0917\\u0908 \\u0930\\u093e\\u0936\\u093f \\u0914\\u0930 \\u0917\\u0902\\u0924\\u0935\\u094d\\u092f \\u0926\\u0947\\u0936 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u092d\\u093f\\u0928\\u094d\\u0928 \\u0939\\u094b \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0935\\u093f\\u0938\\u094d\\u0924\\u0943\\u0924 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u0943\\u092a\\u092f\\u093e \\u0905\\u092a\\u0928\\u0940 \\u0916\\u093e\\u0924\\u093e \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917 \\u092e\\u0947\\u0902 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0938\\u0902\\u0930\\u091a\\u0928\\u093e \\u0915\\u0940 \\u0938\\u092e\\u0940\\u0915\\u094d\\u0937\\u093e \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"id\":\"6724c91cc135e\"}}}', 1, 1, '2024-11-01 18:26:33', '2024-11-07 10:46:10');

