INSERT INTO `frontend_header_section_pages` VALUES (1, 1, 'personal', '{\"images\":{\"section_image\":\"a7d0c116-855c-4dc3-9a85-713b7c2015d9.webp\",\"step_image\":\"a62cff34-351a-4604-8030-aa134e4c35c7.webp\"},\"language\":{\"en\":{\"heading\":\"Receive Money Instantly and Securely with QRPay Pro\",\"sub_heading\":\"Effortless payments are now a reality. With QRPay Pro, receiving money from friends, family, or clients is easy. Your funds are transferred securely into your account with a quick QR code scan. Multi-currency support and global accessibility ensure that you can receive payments from anywhere, anytime, with the assurance of enhanced security for every transaction.\",\"process_step_title\":\"Get Started in 3 Easy Steps\",\"button_name\":\"Start Receiving Now\",\"button_link\":\"user\\/receive-money\",\"step_title\":\"Effortlessly Receive Money in Your QRPay Pro Account\",\"step_sub_title\":\"Here\\u2019s how you can quickly and securely receive payments in just a few steps.\"},\"es\":{\"heading\":\"Reciba dinero de forma instant\\u00e1nea y segura con QRPay Pro\",\"sub_heading\":\"Los pagos sin esfuerzo son ahora una realidad. Con QRPay Pro, recibir dinero de amigos, familiares o clientes es f\\u00e1cil. Sus fondos se transfieren de forma segura a su cuenta con un r\\u00e1pido escaneo del c\\u00f3digo QR. El soporte multidivisa y la accesibilidad global garantizan que pueda recibir pagos desde cualquier lugar y en cualquier momento, con la garant\\u00eda de una seguridad mejorada para cada transacci\\u00f3n.\",\"process_step_title\":\"Comience en 3 sencillos pasos\",\"button_name\":\"Comience a recibir ahora\",\"button_link\":\"user\\/receive-money\",\"step_title\":\"Reciba dinero sin esfuerzo en su cuenta QRPay Pro\",\"step_sub_title\":\"A continuaci\\u00f3n le mostramos c\\u00f3mo puede recibir pagos de forma r\\u00e1pida y segura en solo unos pocos pasos.\"},\"ar\":{\"heading\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631 \\u0648\\u0628\\u0634\\u0643\\u0644 \\u0622\\u0645\\u0646 \\u0645\\u0639 QRPay Pro\",\"sub_heading\":\"\\u0623\\u0635\\u0628\\u062d\\u062a \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0627\\u0644\\u0633\\u0647\\u0644\\u0629 \\u0627\\u0644\\u0622\\u0646 \\u062d\\u0642\\u064a\\u0642\\u0629 \\u0648\\u0627\\u0642\\u0639\\u0629. \\u0645\\u0639 QRPay Pro\\u060c \\u0623\\u0635\\u0628\\u062d \\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u0646 \\u0627\\u0644\\u0623\\u0635\\u062f\\u0642\\u0627\\u0621 \\u0623\\u0648 \\u0627\\u0644\\u0639\\u0627\\u0626\\u0644\\u0629 \\u0623\\u0648 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0623\\u0645\\u0631\\u064b\\u0627 \\u0633\\u0647\\u0644\\u0627\\u064b. \\u064a\\u062a\\u0645 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0628\\u0634\\u0643\\u0644 \\u0622\\u0645\\u0646 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0645\\u0633\\u062d \\u0633\\u0631\\u064a\\u0639 \\u0644\\u0631\\u0645\\u0632 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639\\u0629. \\u064a\\u0636\\u0645\\u0646 \\u062f\\u0639\\u0645 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u062a\\u0639\\u062f\\u062f\\u0629 \\u0648\\u0625\\u0645\\u0643\\u0627\\u0646\\u064a\\u0629 \\u0627\\u0644\\u0648\\u0635\\u0648\\u0644 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645\\u064a\\u0629 \\u0625\\u0645\\u0643\\u0627\\u0646\\u064a\\u0629 \\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0645\\u0646 \\u0623\\u064a \\u0645\\u0643\\u0627\\u0646 \\u0648\\u0641\\u064a \\u0623\\u064a \\u0648\\u0642\\u062a\\u060c \\u0645\\u0639 \\u0636\\u0645\\u0627\\u0646 \\u0627\\u0644\\u0623\\u0645\\u0627\\u0646 \\u0627\\u0644\\u0645\\u0639\\u0632\\u0632 \\u0644\\u0643\\u0644 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0629.\",\"process_step_title\":\"\\u0627\\u0628\\u062f\\u0623 \\u0641\\u064a 3 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0633\\u0647\\u0644\\u0629\",\"button_name\":\"\\u0627\\u0628\\u062f\\u0623 \\u0627\\u0644\\u0627\\u0633\\u062a\\u0644\\u0627\\u0645 \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"user\\/receive-money\",\"step_title\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\",\"step_sub_title\":\"\\u0625\\u0644\\u064a\\u0643 \\u0643\\u064a\\u0641\\u064a\\u0629 \\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0628\\u0633\\u0631\\u0639\\u0629 \\u0648\\u0623\\u0645\\u0627\\u0646 \\u0641\\u064a \\u0628\\u0636\\u0639 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0641\\u0642\\u0637.\"},\"fr\":{\"heading\":\"Recevez de l\'argent instantan\\u00e9ment et en toute s\\u00e9curit\\u00e9 avec QRPay Pro\",\"sub_heading\":\"Les paiements sans effort sont d\\u00e9sormais une r\\u00e9alit\\u00e9. Avec QRPay Pro, recevoir de l\'argent d\'amis, de famille ou de clients est simple. Vos fonds sont transf\\u00e9r\\u00e9s en toute s\\u00e9curit\\u00e9 sur votre compte avec un scan rapide du code QR. La prise en charge multidevises et l\'accessibilit\\u00e9 mondiale garantissent que vous pouvez recevoir des paiements de n\'importe o\\u00f9 et \\u00e0 tout moment, avec l\'assurance d\'une s\\u00e9curit\\u00e9 renforc\\u00e9e pour chaque transaction.\",\"process_step_title\":\"Commencez en 3 \\u00e9tapes faciles\",\"button_name\":\"Commencez \\u00e0 recevoir maintenant\",\"button_link\":\"user\\/receive-money\",\"step_title\":\"Recevez de l\'argent sans effort sur votre compte QRPay Pro\",\"step_sub_title\":\"Voici comment recevoir des paiements rapidement et en toute s\\u00e9curit\\u00e9 en quelques \\u00e9tapes seulement.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0924\\u0941\\u0930\\u0902\\u0924 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0927\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\",\"sub_heading\":\"\\u0938\\u0939\\u091c \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0905\\u092c \\u090f\\u0915 \\u0935\\u093e\\u0938\\u094d\\u0924\\u0935\\u093f\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964 QRPay Pro \\u0915\\u0947 \\u0938\\u093e\\u0925, \\u0926\\u094b\\u0938\\u094d\\u0924\\u094b\\u0902, \\u092a\\u0930\\u093f\\u0935\\u093e\\u0930 \\u092f\\u093e \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915\\u094b\\u0902 \\u0938\\u0947 \\u0927\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0928\\u093e \\u0906\\u0938\\u093e\\u0928 \\u0939\\u0948\\u0964 \\u0924\\u094d\\u0935\\u0930\\u093f\\u0924 \\u0915\\u094d\\u092f\\u0942\\u0906\\u0930 \\u0915\\u094b\\u0921 \\u0938\\u094d\\u0915\\u0948\\u0928 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0906\\u092a\\u0915\\u0940 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0906\\u092a\\u0915\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u093f\\u0924 \\u0915\\u0930 \\u0926\\u0940 \\u091c\\u093e\\u0924\\u0940 \\u0939\\u0948\\u0964 \\u092c\\u0939\\u0941-\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u0928 \\u0914\\u0930 \\u0935\\u0948\\u0936\\u094d\\u0935\\u093f\\u0915 \\u092a\\u0939\\u0941\\u0902\\u091a \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0924\\u0940 \\u0939\\u0948 \\u0915\\u093f \\u0906\\u092a \\u0939\\u0930 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092c\\u0922\\u093c\\u0940 \\u0939\\u0941\\u0908 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0915\\u0947 \\u0906\\u0936\\u094d\\u0935\\u093e\\u0938\\u0928 \\u0915\\u0947 \\u0938\\u093e\\u0925, \\u0915\\u0939\\u0940\\u0902 \\u0938\\u0947 \\u092d\\u0940, \\u0915\\u092d\\u0940 \\u092d\\u0940 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\",\"process_step_title\":\"3 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u0906\\u0930\\u0902\\u092d \\u0915\\u0930\\u0947\\u0902\",\"button_name\":\"\\u0905\\u092d\\u0940 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0928\\u093e \\u092a\\u094d\\u0930\\u093e\\u0930\\u0902\\u092d \\u0915\\u0930\\u0947\\u0902\",\"button_link\":\"user\\/receive-money\",\"step_title\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0927\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\",\"step_sub_title\":\"\\u092f\\u0939\\u093e\\u0902 \\u092c\\u0924\\u093e\\u092f\\u093e \\u0917\\u092f\\u093e \\u0939\\u0948 \\u0915\\u093f \\u0906\\u092a \\u0915\\u0948\\u0938\\u0947 \\u0915\\u0941\\u091b \\u0939\\u0940 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u0924\\u094d\\u0935\\u0930\\u093f\\u0924 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"items\":{\"6722fd0c94fb0\":{\"language\":{\"en\":{\"name\":\"Select the Currency\"},\"ar\":{\"name\":\"\\u062d\\u062f\\u062f \\u0627\\u0644\\u0639\\u0645\\u0644\\u0629\"},\"es\":{\"name\":\"Seleccione la moneda\"},\"fr\":{\"name\":\"S\\u00e9lectionnez la devise\"},\"hi\":{\"name\":\"\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0915\\u093e \\u091a\\u092f\\u0928 \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6722fd0c94fb0\"},\"6722fd16d0a1d\":{\"language\":{\"en\":{\"name\":\"Enter the Amount\"},\"ar\":{\"name\":\"\\u062d\\u062f\\u062f \\u0627\\u0644\\u0639\\u0645\\u0644\\u0629\"},\"es\":{\"name\":\"Seleccione la moneda\"},\"fr\":{\"name\":\"S\\u00e9lectionnez la devise\"},\"hi\":{\"name\":\"\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0915\\u093e \\u091a\\u092f\\u0928 \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6722fd16d0a1d\"},\"6722fd20d6a05\":{\"language\":{\"en\":{\"name\":\"Confirm the Exchange\"},\"ar\":{\"name\":\"\\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0635\\u0631\\u0641\"},\"es\":{\"name\":\"Confirmar el cambio\"},\"fr\":{\"name\":\"Confirmer l\'\\u00e9change\"},\"hi\":{\"name\":\"\\u090f\\u0915\\u094d\\u0938\\u091a\\u0947\\u0902\\u091c \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6722fd20d6a05\"}}}', 1, 1, '2024-10-31 09:43:33', '2024-12-12 18:35:05');
INSERT INTO `frontend_header_section_pages` VALUES (2, 5, 'personal', '{\"images\":{\"section_image\":\"e96aa65d-6669-4457-97d3-1adf9f5cf271.webp\",\"step_image\":\"6fb292b3-dc74-4b20-841a-27686245b69b.webp\"},\"language\":{\"en\":{\"heading\":\"Seamless Currency Exchange at Your Fingertips\",\"sub_heading\":\"With QRPay Pro\\u2019s Exchange Money feature, you can quickly convert your balance into the currency of your choice. Enjoy real-time exchange rates, competitive fees, and an intuitive experience that makes currency conversion fast and simple. QRPay Pro supports a wide range of currencies, so you\\u2019re ready for transactions, whether you\\u2019re at home or abroad.\",\"process_step_title\":\"Get Started with Currency Exchange in 3 Easy Steps\",\"button_name\":\"Start Exchanging Now\",\"button_link\":\"user\\/money-exchange\",\"step_title\":\"Convert Money in Just a Few Taps\",\"step_sub_title\":\"Follow these simple steps to exchange money in your QRPay Pro account with confidence.\"},\"es\":{\"heading\":\"Cambio de divisas fluido a tu alcance\",\"sub_heading\":\"Con la funci\\u00f3n Exchange Money de QRPay Pro, puede convertir r\\u00e1pidamente su saldo a la moneda que elija. Disfrute de tipos de cambio en tiempo real, tarifas competitivas y una experiencia intuitiva que hace que la conversi\\u00f3n de divisas sea r\\u00e1pida y sencilla. QRPay Pro admite una amplia gama de monedas, por lo que est\\u00e1 listo para realizar transacciones, ya sea que est\\u00e9 en casa o en el extranjero.\",\"process_step_title\":\"Comience con el cambio de divisas en 3 sencillos pasos\",\"button_name\":\"Comience a intercambiar ahora\",\"button_link\":\"user\\/money-exchange\",\"step_title\":\"Convierta dinero con solo unos pocos toques\",\"step_sub_title\":\"Siga estos sencillos pasos para cambiar dinero en su cuenta QRPay Pro con confianza.\"},\"ar\":{\"heading\":\"\\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0628\\u0633\\u0644\\u0627\\u0633\\u0629 \\u0641\\u064a \\u0645\\u062a\\u0646\\u0627\\u0648\\u0644 \\u064a\\u062f\\u0643\",\"sub_heading\":\"\\u0645\\u0639 \\u0645\\u064a\\u0632\\u0629 Exchange Money \\u0641\\u064a QRPay Pro\\u060c \\u064a\\u0645\\u0643\\u0646\\u0643 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0631\\u0635\\u064a\\u062f\\u0643 \\u0628\\u0633\\u0631\\u0639\\u0629 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0629 \\u0627\\u0644\\u062a\\u064a \\u062a\\u062e\\u062a\\u0627\\u0631\\u0647\\u0627. \\u0627\\u0633\\u062a\\u0645\\u062a\\u0639 \\u0628\\u0623\\u0633\\u0639\\u0627\\u0631 \\u0627\\u0644\\u0635\\u0631\\u0641 \\u0641\\u064a \\u0627\\u0644\\u0648\\u0642\\u062a \\u0627\\u0644\\u062d\\u0642\\u064a\\u0642\\u064a\\u060c \\u0648\\u0627\\u0644\\u0631\\u0633\\u0648\\u0645 \\u0627\\u0644\\u062a\\u0646\\u0627\\u0641\\u0633\\u064a\\u0629\\u060c \\u0648\\u062a\\u062c\\u0631\\u0628\\u0629 \\u0628\\u062f\\u064a\\u0647\\u064a\\u0629 \\u062a\\u062c\\u0639\\u0644 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0633\\u0631\\u064a\\u0639\\u064b\\u0627 \\u0648\\u0628\\u0633\\u064a\\u0637\\u064b\\u0627. \\u064a\\u062f\\u0639\\u0645 QRPay Pro \\u0645\\u062c\\u0645\\u0648\\u0639\\u0629 \\u0648\\u0627\\u0633\\u0639\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a\\u060c \\u0644\\u0630\\u0627 \\u0641\\u0623\\u0646\\u062a \\u062c\\u0627\\u0647\\u0632 \\u0644\\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u060c \\u0633\\u0648\\u0627\\u0621 \\u0643\\u0646\\u062a \\u0641\\u064a \\u0627\\u0644\\u0645\\u0646\\u0632\\u0644 \\u0623\\u0648 \\u0641\\u064a \\u0627\\u0644\\u062e\\u0627\\u0631\\u062c.\",\"process_step_title\":\"\\u0627\\u0628\\u062f\\u0623 \\u0645\\u0639 \\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0641\\u064a 3 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0633\\u0647\\u0644\\u0629\",\"button_name\":\"\\u0627\\u0628\\u062f\\u0623 \\u0628\\u0627\\u0644\\u062a\\u0628\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"user\\/money-exchange\",\"step_title\":\"\\u0642\\u0645 \\u0628\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0628\\u0636\\u0639 \\u0646\\u0642\\u0631\\u0627\\u062a \\u0641\\u0642\\u0637\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0628\\u0633\\u064a\\u0637\\u0629 \\u0644\\u062a\\u0628\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u0628\\u0643\\u0644 \\u062b\\u0642\\u0629.\"},\"fr\":{\"heading\":\"Cambio de divisas fluido a tu alcance\",\"sub_heading\":\"Avec la fonction Exchange Money de QRPay Pro, vous pouvez rapidement convertir votre solde dans la devise de votre choix. Profitez de taux de change en temps r\\u00e9el, de frais comp\\u00e9titifs et d\'une exp\\u00e9rience intuitive qui rend la conversion de devises rapide et simple. QRPay Pro prend en charge une large gamme de devises, vous \\u00eates donc pr\\u00eat \\u00e0 effectuer des transactions, que vous soyez chez vous ou \\u00e0 l\'\\u00e9tranger.\",\"process_step_title\":\"D\\u00e9marrez avec le change de devises en 3 \\u00e9tapes faciles\",\"button_name\":\"Commencez \\u00e0 \\u00e9changer maintenant\",\"button_link\":\"user\\/money-exchange\",\"step_title\":\"Convertissez de l\'argent en quelques clics\",\"step_sub_title\":\"Suivez ces \\u00e9tapes simples pour \\u00e9changer de l\'argent sur votre compte QRPay Pro en toute confiance.\"},\"hi\":{\"heading\":\"\\u0906\\u092a\\u0915\\u0940 \\u0909\\u0902\\u0917\\u0932\\u093f\\u092f\\u094b\\u0902 \\u092a\\u0930 \\u0928\\u093f\\u0930\\u094d\\u092c\\u093e\\u0927 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f\",\"sub_heading\":\"QRPay Pro \\u0915\\u0947 \\u090f\\u0915\\u094d\\u0938\\u091a\\u0947\\u0902\\u091c \\u092e\\u0928\\u0940 \\u092b\\u0940\\u091a\\u0930 \\u0915\\u0947 \\u0938\\u093e\\u0925, \\u0906\\u092a \\u0905\\u092a\\u0928\\u0947 \\u092c\\u0948\\u0932\\u0947\\u0902\\u0938 \\u0915\\u094b \\u0924\\u0941\\u0930\\u0902\\u0924 \\u0905\\u092a\\u0928\\u0940 \\u092a\\u0938\\u0902\\u0926 \\u0915\\u0940 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u092e\\u0947\\u0902 \\u092c\\u0926\\u0932 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0935\\u093e\\u0938\\u094d\\u0924\\u0935\\u093f\\u0915 \\u0938\\u092e\\u092f \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0926\\u0930\\u094b\\u0902, \\u092a\\u094d\\u0930\\u0924\\u093f\\u0938\\u094d\\u092a\\u0930\\u094d\\u0927\\u0940 \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0914\\u0930 \\u090f\\u0915 \\u0938\\u0939\\u091c \\u0905\\u0928\\u0941\\u092d\\u0935 \\u0915\\u093e \\u0906\\u0928\\u0902\\u0926 \\u0932\\u0947\\u0902 \\u091c\\u094b \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0930\\u0942\\u092a\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u094b \\u0924\\u0947\\u091c\\u093c \\u0914\\u0930 \\u0938\\u0930\\u0932 \\u092c\\u0928\\u093e\\u0924\\u093e \\u0939\\u0948\\u0964 QRPay \\u092a\\u094d\\u0930\\u094b \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u0940 \\u090f\\u0915 \\u0935\\u093f\\u0938\\u094d\\u0924\\u0943\\u0924 \\u0936\\u094d\\u0930\\u0943\\u0902\\u0916\\u0932\\u093e \\u0915\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948, \\u0907\\u0938\\u0932\\u093f\\u090f \\u0906\\u092a \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0924\\u0948\\u092f\\u093e\\u0930 \\u0939\\u0948\\u0902, \\u091a\\u093e\\u0939\\u0947 \\u0906\\u092a \\u0918\\u0930 \\u092a\\u0930 \\u0939\\u094b\\u0902 \\u092f\\u093e \\u0935\\u093f\\u0926\\u0947\\u0936 \\u092e\\u0947\\u0902\\u0964\",\"process_step_title\":\"3 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0936\\u0941\\u0930\\u0942 \\u0915\\u0930\\u0947\\u0902\",\"button_name\":\"\\u0905\\u092d\\u0940 \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u092a\\u094d\\u0930\\u093e\\u0930\\u0902\\u092d \\u0915\\u0930\\u0947\\u0902\",\"button_link\":\"user\\/money-exchange\",\"step_title\":\"\\u092c\\u0938 \\u0915\\u0941\\u091b \\u0939\\u0940 \\u091f\\u0948\\u092a \\u092e\\u0947\\u0902 \\u092a\\u0948\\u0938\\u0947 \\u092c\\u0926\\u0932\\u0947\\u0902\",\"step_sub_title\":\"\\u0906\\u0924\\u094d\\u092e\\u0935\\u093f\\u0936\\u094d\\u0935\\u093e\\u0938 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u093e \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0928 \\u0938\\u0930\\u0932 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"67247a302b5cc\":{\"language\":{\"en\":{\"name\":\"Select the Currency\"},\"ar\":{\"name\":\"\\u062d\\u062f\\u062f \\u0627\\u0644\\u0639\\u0645\\u0644\\u0629\"},\"es\":{\"name\":\"Seleccione la moneda\"},\"fr\":{\"name\":\"Seleccione la moneda\"},\"hi\":{\"name\":\"\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0915\\u093e \\u091a\\u092f\\u0928 \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"67247a302b5cc\"},\"67247a38d7552\":{\"language\":{\"en\":{\"name\":\"Enter the Amount\"},\"ar\":{\"name\":\"\\u0623\\u062f\\u062e\\u0644 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a\"},\"es\":{\"name\":\"Ingrese la cantidad\"},\"fr\":{\"name\":\"Ingrese la cantidad\"},\"hi\":{\"name\":\"\\u0930\\u093e\\u0936\\u093f \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"67247a38d7552\"},\"67247a4055c9d\":{\"language\":{\"en\":{\"name\":\"Confirm the Exchange\"},\"ar\":{\"name\":\"\\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0635\\u0631\\u0641\"},\"es\":{\"name\":\"Confirmar el cambio\"},\"fr\":{\"name\":\"Confirmar el cambio\"},\"hi\":{\"name\":\"\\u090f\\u0915\\u094d\\u0938\\u091a\\u0947\\u0902\\u091c \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"67247a4055c9d\"}}}', 1, 1, '2024-11-01 12:48:33', '2024-12-12 18:35:26');
INSERT INTO `frontend_header_section_pages` VALUES (6, 6, 'personal', '{\"images\":{\"section_image\":\"6582641d-0075-46a5-a5e1-a0b3e771966a.webp\",\"step_image\":\"d150696c-fa00-4d7c-a4f2-7efb3a6b0dfd.webp\"},\"language\":{\"en\":{\"heading\":\"Send Money Instantly to Anyone, Anywhere\",\"sub_heading\":\"With QRPay Pro, sending money is fast, easy, and secure. Transfer funds to friends, family, or businesses by entering their QRPay Pro ID or scanning a QR code. Enjoy seamless transfers with low fees, multi-currency support, and real-time tracking to keep you informed at every step.\",\"process_step_title\":\"Start Sending Money in 3 Simple Steps\",\"button_name\":\"Send Money Now\",\"button_link\":\"user\\/send-money\",\"step_title\":\"How to Send Money with QRPay Pro\",\"step_sub_title\":\"Follow these easy steps to securely send funds from your QRPay Pro account.\"},\"es\":{\"heading\":\"Env\\u00ede dinero al instante a cualquier persona y en cualquier lugar\",\"sub_heading\":\"Con QRPay Pro, enviar dinero es r\\u00e1pido, f\\u00e1cil y seguro. Transfiera fondos a amigos, familiares o empresas ingresando su ID de QRPay Pro o escaneando un c\\u00f3digo QR. Disfrute de transferencias fluidas con tarifas bajas, soporte multidivisa y seguimiento en tiempo real para mantenerlo informado en cada paso.\",\"process_step_title\":\"Comience a enviar dinero en 3 sencillos pasos\",\"button_name\":\"Env\\u00eda dinero ahora\",\"button_link\":\"user\\/send-money\",\"step_title\":\"C\\u00f3mo enviar dinero con QRPay Pro\",\"step_sub_title\":\"Siga estos sencillos pasos para enviar fondos de forma segura desde su cuenta QRPay Pro.\"},\"ar\":{\"heading\":\"Env\\u00ede dinero al instante a cualquier persona y en cualquier lugar\",\"sub_heading\":\"Con QRPay Pro, enviar dinero es r\\u00e1pido, f\\u00e1cil y seguro. Transfiera fondos a amigos, familiares o empresas ingresando su ID de QRPay Pro o escaneando un c\\u00f3digo QR. Disfrute de transferencias fluidas con tarifas bajas, soporte multidivisa y seguimiento en tiempo real para mantenerlo informado en cada paso.\",\"process_step_title\":\"Comience a enviar dinero en 3 sencillos pasos\",\"button_name\":\"Env\\u00eda dinero ahora\",\"button_link\":\"user\\/send-money\",\"step_title\":\"C\\u00f3mo enviar dinero con QRPay Pro\",\"step_sub_title\":\"Siga estos sencillos pasos para enviar fondos de forma segura desde su cuenta QRPay Pro.\"},\"fr\":{\"heading\":\"Env\\u00ede dinero al instante a cualquier persona y en cualquier lugar\",\"sub_heading\":\"Avec QRPay Pro, envoyer de l\'argent est rapide, facile et s\\u00e9curis\\u00e9. Transf\\u00e9rez des fonds \\u00e0 des amis, \\u00e0 la famille ou \\u00e0 des entreprises en saisissant leur identifiant QRPay Pro ou en scannant un code QR. Profitez de transferts fluides avec des frais peu \\u00e9lev\\u00e9s, une prise en charge multidevises et un suivi en temps r\\u00e9el pour vous tenir inform\\u00e9 \\u00e0 chaque \\u00e9tape.\",\"process_step_title\":\"Commencez \\u00e0 envoyer de l\'argent en 3 \\u00e9tapes simples\",\"button_name\":\"Envoyez de l\'argent maintenant\",\"button_link\":\"user\\/send-money\",\"step_title\":\"Comment envoyer de l\'argent avec QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes simples pour envoyer des fonds en toute s\\u00e9curit\\u00e9 depuis votre compte QRPay Pro.\"},\"hi\":{\"heading\":\"\\u0915\\u0939\\u0940\\u0902 \\u092d\\u0940, \\u0915\\u093f\\u0938\\u0940 \\u0915\\u094b \\u092d\\u0940 \\u0924\\u0941\\u0930\\u0902\\u0924 \\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0947\\u0902\",\"sub_heading\":\"QRPay Pro \\u0915\\u0947 \\u0938\\u093e\\u0925, \\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0928\\u093e \\u0924\\u0947\\u091c\\u093c, \\u0906\\u0938\\u093e\\u0928 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0939\\u0948\\u0964 \\u092e\\u093f\\u0924\\u094d\\u0930\\u094b\\u0902, \\u092a\\u0930\\u093f\\u0935\\u093e\\u0930 \\u092f\\u093e \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f\\u094b\\u0902 \\u0915\\u094b \\u0909\\u0928\\u0915\\u0940 QRPay \\u092a\\u094d\\u0930\\u094b \\u0906\\u0908\\u0921\\u0940 \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0915\\u0947 \\u092f\\u093e QR \\u0915\\u094b\\u0921 \\u0938\\u094d\\u0915\\u0948\\u0928 \\u0915\\u0930\\u0915\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902\\u0964 \\u0906\\u092a\\u0915\\u094b \\u0939\\u0930 \\u0915\\u0926\\u092e \\u092a\\u0930 \\u0938\\u0942\\u091a\\u093f\\u0924 \\u0930\\u0916\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u092e \\u0936\\u0941\\u0932\\u094d\\u0915, \\u092c\\u0939\\u0941-\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u0928 \\u0914\\u0930 \\u0935\\u093e\\u0938\\u094d\\u0924\\u0935\\u093f\\u0915 \\u0938\\u092e\\u092f \\u091f\\u094d\\u0930\\u0948\\u0915\\u093f\\u0902\\u0917 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0928\\u093f\\u0930\\u094d\\u092c\\u093e\\u0927 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u093e \\u0906\\u0928\\u0902\\u0926 \\u0932\\u0947\\u0902\\u0964\",\"process_step_title\":\"3 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0928\\u093e \\u0936\\u0941\\u0930\\u0942 \\u0915\\u0930\\u0947\\u0902\",\"button_name\":\"\\u0905\\u092d\\u0940 \\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0947\\u0902\",\"button_link\":\"user\\/send-money\",\"step_title\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0947\\u0902\",\"step_sub_title\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u0938\\u0947 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0928 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"6724961b0da16\":{\"language\":{\"en\":{\"name\":\"Enter Recipient Details\"},\"ar\":{\"name\":null},\"es\":{\"name\":null},\"fr\":{\"name\":null},\"hi\":{\"name\":null}},\"id\":\"6724961b0da16\"},\"672496257e41a\":{\"language\":{\"en\":{\"name\":\"Choose Amount and Currency\"},\"ar\":{\"name\":null},\"es\":{\"name\":null},\"fr\":{\"name\":null},\"hi\":{\"name\":null}},\"id\":\"672496257e41a\"},\"6724962bd01af\":{\"language\":{\"en\":{\"name\":\"Confirm and Send\"},\"ar\":{\"name\":null},\"es\":{\"name\":null},\"fr\":{\"name\":null},\"hi\":{\"name\":null}},\"id\":\"6724962bd01af\"}}}', 1, 1, '2024-11-01 14:35:01', '2024-12-12 18:35:49');
INSERT INTO `frontend_header_section_pages` VALUES (7, 7, 'personal', '{\"images\":{\"section_image\":\"385fb6df-94f4-4752-93f2-aa2431038c76.webp\",\"step_image\":\"19f6152d-1a24-494b-90d4-ef5f047655c5.webp\"},\"language\":{\"en\":{\"heading\":\"Get Paid Instantly with QRPay Pro Payment Links\",\"sub_heading\":\"QRPay Pro\\u2019s Payment Link feature allows you to receive payments effortlessly by creating a shareable link. Whether it\\u2019s for a friend, client, or anyone else, just send the link and let them complete the payment at their convenience. No need to share account details\\u2014just generate, share, and receive funds securely.\",\"process_step_title\":\"Set Up Your Payment Link in 3 Simple Steps\",\"button_name\":\"Create Payment Link\",\"button_link\":\"user\\/payment-link\",\"step_title\":\"How to Use QRPay Pro\\u2019s Payment Link Feature\",\"step_sub_title\":\"Follow these easy steps to generate and share your payment link for fast payments.\"},\"es\":{\"heading\":\"Reciba pagos al instante con enlaces de pago QRPay Pro\",\"sub_heading\":\"La funci\\u00f3n Enlace de pago de QRPay Pro le permite recibir pagos sin esfuerzo mediante la creaci\\u00f3n de un enlace para compartir. Ya sea para un amigo, cliente o cualquier otra persona, simplemente env\\u00ede el enlace y perm\\u00edtale completar el pago a su conveniencia. No es necesario compartir los detalles de la cuenta: simplemente genere, comparta y reciba fondos de forma segura.\",\"process_step_title\":\"Configure su enlace de pago en 3 sencillos pasos\",\"button_name\":\"Crear enlace de pago\",\"button_link\":\"user\\/payment-link\",\"step_title\":\"C\\u00f3mo utilizar la funci\\u00f3n de enlace de pago de QRPay Pro\",\"step_sub_title\":\"Siga estos sencillos pasos para generar y compartir su enlace de pago para pagos r\\u00e1pidos.\"},\"ar\":{\"heading\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0631\\u0648\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 QRPay Pro\",\"sub_heading\":\"\\u062a\\u062a\\u064a\\u062d \\u0644\\u0643 \\u0645\\u064a\\u0632\\u0629 \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0641\\u064a QRPay Pro \\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0639\\u0646 \\u0637\\u0631\\u064a\\u0642 \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u0627\\u0628\\u0637 \\u0642\\u0627\\u0628\\u0644 \\u0644\\u0644\\u0645\\u0634\\u0627\\u0631\\u0643\\u0629. \\u0633\\u0648\\u0627\\u0621 \\u0643\\u0627\\u0646 \\u0630\\u0644\\u0643 \\u0644\\u0635\\u062f\\u064a\\u0642 \\u0623\\u0648 \\u0639\\u0645\\u064a\\u0644 \\u0623\\u0648 \\u0623\\u064a \\u0634\\u062e\\u0635 \\u0622\\u062e\\u0631\\u060c \\u0645\\u0627 \\u0639\\u0644\\u064a\\u0643 \\u0633\\u0648\\u0649 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0631\\u0627\\u0628\\u0637 \\u0648\\u0627\\u0644\\u0633\\u0645\\u0627\\u062d \\u0644\\u0647\\u0645 \\u0628\\u0625\\u0643\\u0645\\u0627\\u0644 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0641\\u064a \\u0627\\u0644\\u0648\\u0642\\u062a \\u0627\\u0644\\u0630\\u064a \\u064a\\u0646\\u0627\\u0633\\u0628\\u0647\\u0645. \\u0644\\u0627 \\u062f\\u0627\\u0639\\u064a \\u0644\\u0645\\u0634\\u0627\\u0631\\u0643\\u0629 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u062d\\u0633\\u0627\\u0628 \\u2014 \\u0645\\u0627 \\u0639\\u0644\\u064a\\u0643 \\u0633\\u0648\\u0649 \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0648\\u0645\\u0634\\u0627\\u0631\\u0643\\u062a\\u0647\\u0627 \\u0648\\u0627\\u0633\\u062a\\u0644\\u0627\\u0645\\u0647\\u0627 \\u0628\\u0634\\u0643\\u0644 \\u0622\\u0645\\u0646.\",\"process_step_title\":\"\\u0642\\u0645 \\u0628\\u0625\\u0639\\u062f\\u0627\\u062f \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u0641\\u064a 3 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0628\\u0633\\u064a\\u0637\\u0629\",\"button_name\":\"\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639\",\"button_link\":\"user\\/payment-link\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0645\\u064a\\u0632\\u0629 \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0641\\u064a QRPay Pro\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0633\\u0647\\u0644\\u0629 \\u0644\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u0648\\u0645\\u0634\\u0627\\u0631\\u0643\\u062a\\u0647 \\u0644\\u0644\\u062f\\u0641\\u0639\\u0627\\u062a \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639\\u0629.\"},\"fr\":{\"heading\":\"Reciba pagos al instante con enlaces de pago QRPay Pro\",\"sub_heading\":\"La fonction Payment Link de QRPay Pro vous permet de recevoir des paiements sans effort en cr\\u00e9ant un lien partageable. Que ce soit pour un ami, un client ou toute autre personne, envoyez simplement le lien et laissez-le effectuer le paiement \\u00e0 sa convenance. Pas besoin de partager les d\\u00e9tails de votre compte\\u00a0: g\\u00e9n\\u00e9rez, partagez et recevez simplement des fonds en toute s\\u00e9curit\\u00e9.\",\"process_step_title\":\"Configurez votre lien de paiement en 3 \\u00e9tapes simples\",\"button_name\":\"Cr\\u00e9er un lien de paiement\",\"button_link\":\"user\\/payment-link\",\"step_title\":\"Comment utiliser la fonctionnalit\\u00e9 de lien de paiement de QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes simples pour g\\u00e9n\\u00e9rer et partager votre lien de paiement pour des paiements rapides.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0924\\u0941\\u0930\\u0902\\u0924 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\",\"sub_heading\":\"QRPay Pro \\u0915\\u0940 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0906\\u092a\\u0915\\u094b \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930\\u0928\\u0947 \\u092f\\u094b\\u0917\\u094d\\u092f \\u0932\\u093f\\u0902\\u0915 \\u092c\\u0928\\u093e\\u0915\\u0930 \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0940 \\u0905\\u0928\\u0941\\u092e\\u0924\\u093f \\u0926\\u0947\\u0924\\u0940 \\u0939\\u0948\\u0964 \\u091a\\u093e\\u0939\\u0947 \\u092f\\u0939 \\u0915\\u093f\\u0938\\u0940 \\u092e\\u093f\\u0924\\u094d\\u0930, \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915 \\u092f\\u093e \\u0915\\u093f\\u0938\\u0940 \\u0905\\u0928\\u094d\\u092f \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0939\\u094b, \\u092c\\u0938 \\u0932\\u093f\\u0902\\u0915 \\u092d\\u0947\\u091c\\u0947\\u0902 \\u0914\\u0930 \\u0909\\u0928\\u094d\\u0939\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0940 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e\\u0928\\u0941\\u0938\\u093e\\u0930 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u092a\\u0942\\u0930\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0926\\u0947\\u0902\\u0964 \\u0916\\u093e\\u0924\\u093e \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0940 \\u0915\\u094b\\u0908 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915\\u0924\\u093e \\u0928\\u0939\\u0940\\u0902 \\u0939\\u0948 - \\u092c\\u0938 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0909\\u0924\\u094d\\u092a\\u0928\\u094d\\u0928 \\u0915\\u0930\\u0947\\u0902, \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\\u0964\",\"process_step_title\":\"3 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0938\\u0947\\u091f \\u0915\\u0930\\u0947\\u0902\",\"button_name\":\"\\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u092c\\u0928\\u093e\\u090f\\u0902\",\"button_link\":\"user\\/payment-link\",\"step_title\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0948\\u0938\\u0947 \\u0915\\u0930\\u0947\\u0902\",\"step_sub_title\":\"\\u0924\\u0947\\u091c\\u093c \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u092c\\u0928\\u093e\\u0928\\u0947 \\u0914\\u0930 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0928 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"672496f92c3b1\":{\"language\":{\"en\":{\"name\":\"Generate a Payment Link\"},\"ar\":{\"name\":\"\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639\"},\"es\":{\"name\":\"Generar un enlace de pago\"},\"fr\":{\"name\":\"Generar un enlace de pago\"},\"hi\":{\"name\":\"\\u090f\\u0915 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u091c\\u0928\\u0930\\u0947\\u091f \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"672496f92c3b1\"},\"672496ffdb248\":{\"language\":{\"en\":{\"name\":\"Share the Link\"},\"ar\":{\"name\":\"\\u0645\\u0634\\u0627\\u0631\\u0643\\u0629 \\u0627\\u0644\\u0631\\u0627\\u0628\\u0637\"},\"es\":{\"name\":\"Comparte el enlace\"},\"fr\":{\"name\":\"Comparte el enlace\"},\"hi\":{\"name\":\"\\u0932\\u093f\\u0902\\u0915 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"672496ffdb248\"},\"67249705758e6\":{\"language\":{\"en\":{\"name\":\"Receive Payment\"},\"ar\":{\"name\":\"\\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u062f\\u0641\\u0639\"},\"es\":{\"name\":\"Recibir pago\"},\"fr\":{\"name\":\"Recibir pago\"},\"hi\":{\"name\":\"\\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"67249705758e6\"}}}', 1, 1, '2024-11-01 14:53:04', '2024-12-12 18:36:21');
INSERT INTO `frontend_header_section_pages` VALUES (8, 8, 'personal', '{\"images\":{\"section_image\":\"33f24ecf-bcd4-44fc-a9ab-14680a6f8922.webp\",\"step_image\":\"bc42cf73-34d2-455d-bb22-9fd74dfcd260.webp\"},\"language\":{\"en\":{\"heading\":\"Effortlessly Request Money with QRPay Pro\",\"sub_heading\":\"With QRPay Pro\\u2019s Request Money feature, you can quickly send payment requests to anyone. Whether it\\u2019s for a shared expense, a loan repayment, or a service fee, simply enter the amount, send the request, and get paid instantly. It\\u2019s a secure and hassle-free way to manage your finances.\",\"process_step_title\":\"Request Money in 3 Simple Steps\",\"button_name\":\"Request Funds Now\",\"button_link\":\"user\\/request-money\",\"step_title\":\"How to Request Money with QRPay Pro\",\"step_sub_title\":\"Follow these simple steps to send a request for payment to anyone using QRPay Pro.\"},\"es\":{\"heading\":\"Solicite dinero sin esfuerzo con QRPay Pro\",\"sub_heading\":\"Con la funci\\u00f3n Solicitar dinero de QRPay Pro, puede enviar r\\u00e1pidamente solicitudes de pago a cualquier persona. Ya sea para un gasto compartido, el pago de un pr\\u00e9stamo o una tarifa de servicio, simplemente ingrese el monto, env\\u00ede la solicitud y reciba el pago al instante. Es una forma segura y sin complicaciones de administrar sus finanzas.\",\"process_step_title\":\"Solicita dinero en 3 sencillos pasos\",\"button_name\":\"Solicitar fondos ahora\",\"button_link\":\"user\\/request-money\",\"step_title\":\"C\\u00f3mo solicitar dinero con QRPay Pro\",\"step_sub_title\":\"Siga estos sencillos pasos para enviar una solicitud de pago a cualquier persona que utilice QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0627\\u0637\\u0644\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\",\"sub_heading\":\"\\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0645\\u064a\\u0632\\u0629 \\u0637\\u0644\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a QRPay Pro\\u060c \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0637\\u0644\\u0628\\u0627\\u062a \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0628\\u0633\\u0631\\u0639\\u0629 \\u0625\\u0644\\u0649 \\u0623\\u064a \\u0634\\u062e\\u0635. \\u0633\\u0648\\u0627\\u0621 \\u0643\\u0627\\u0646 \\u0627\\u0644\\u0623\\u0645\\u0631 \\u064a\\u062a\\u0639\\u0644\\u0642 \\u0628\\u0646\\u0641\\u0642\\u0629 \\u0645\\u0634\\u062a\\u0631\\u0643\\u0629\\u060c \\u0623\\u0648 \\u0633\\u062f\\u0627\\u062f \\u0642\\u0631\\u0636\\u060c \\u0623\\u0648 \\u0631\\u0633\\u0648\\u0645 \\u062e\\u062f\\u0645\\u0629\\u060c \\u0645\\u0627 \\u0639\\u0644\\u064a\\u0643 \\u0633\\u0648\\u0649 \\u0625\\u062f\\u062e\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a \\u0648\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0637\\u0644\\u0628 \\u0648\\u0627\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631. \\u0625\\u0646\\u0647\\u0627 \\u0637\\u0631\\u064a\\u0642\\u0629 \\u0622\\u0645\\u0646\\u0629 \\u0648\\u062e\\u0627\\u0644\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u062a\\u0627\\u0639\\u0628 \\u0644\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643.\",\"process_step_title\":\"\\u0627\\u0637\\u0644\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a 3 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0628\\u0633\\u064a\\u0637\\u0629\",\"button_name\":\"\\u0627\\u0637\\u0644\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"user\\/request-money\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u0637\\u0644\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0628\\u0633\\u064a\\u0637\\u0629 \\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0637\\u0644\\u0628 \\u0644\\u0644\\u062f\\u0641\\u0639 \\u0625\\u0644\\u0649 \\u0623\\u064a \\u0634\\u062e\\u0635 \\u064a\\u0633\\u062a\\u062e\\u062f\\u0645 QRPay Pro.\"},\"fr\":{\"heading\":\"Solicite dinero sin esfuerzo con QRPay Pro\",\"sub_heading\":\"Avec la fonction Request Money de QRPay Pro, vous pouvez envoyer rapidement des demandes de paiement \\u00e0 n\'importe qui. Qu\'il s\'agisse d\'une d\\u00e9pense partag\\u00e9e, d\'un remboursement de pr\\u00eat ou de frais de service, entrez simplement le montant, envoyez la demande et soyez pay\\u00e9 instantan\\u00e9ment. C\\u2019est un moyen s\\u00fbr et sans tracas de g\\u00e9rer vos finances.\",\"process_step_title\":\"Demandez de l\'argent en 3 \\u00e9tapes simples\",\"button_name\":\"Demander des fonds maintenant\",\"button_link\":\"user\\/request-money\",\"step_title\":\"Comment demander de l\'argent avec QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes simples pour envoyer une demande de paiement \\u00e0 toute personne utilisant QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0938\\u0939\\u091c\\u0924\\u093e \\u0938\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u093e \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u0915\\u0930\\u0947\\u0902\",\"sub_heading\":\"QRPay Pro \\u0915\\u0947 \\u0930\\u093f\\u0915\\u094d\\u0935\\u0947\\u0938\\u094d\\u091f \\u092e\\u0928\\u0940 \\u092b\\u0940\\u091a\\u0930 \\u0915\\u0947 \\u0938\\u093e\\u0925, \\u0906\\u092a \\u0915\\u093f\\u0938\\u0940 \\u0915\\u094b \\u092d\\u0940 \\u0924\\u0941\\u0930\\u0902\\u0924 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u092d\\u0947\\u091c \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u091a\\u093e\\u0939\\u0947 \\u0935\\u0939 \\u0938\\u093e\\u091d\\u093e \\u0935\\u094d\\u092f\\u092f \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0939\\u094b, \\u090b\\u0923 \\u092a\\u0941\\u0928\\u0930\\u094d\\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0939\\u094b, \\u092f\\u093e \\u0938\\u0947\\u0935\\u093e \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0939\\u094b, \\u092c\\u0938 \\u0930\\u093e\\u0936\\u093f \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902, \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u092d\\u0947\\u091c\\u0947\\u0902 \\u0914\\u0930 \\u0924\\u0941\\u0930\\u0902\\u0924 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\\u0964 \\u092f\\u0939 \\u0906\\u092a\\u0915\\u0947 \\u0935\\u093f\\u0924\\u094d\\u0924 \\u0915\\u094b \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u093e \\u090f\\u0915 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0914\\u0930 \\u092a\\u0930\\u0947\\u0936\\u093e\\u0928\\u0940 \\u092e\\u0941\\u0915\\u094d\\u0924 \\u0924\\u0930\\u0940\\u0915\\u093e \\u0939\\u0948\\u0964\",\"process_step_title\":\"3 \\u0938\\u0930\\u0932 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u0927\\u0928 \\u0915\\u093e \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u0915\\u0930\\u0947\\u0902\",\"button_name\":\"\\u0905\\u092d\\u0940 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0915\\u093e \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u0915\\u0930\\u0947\\u0902\",\"button_link\":\"user\\/request-money\",\"step_title\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u093e \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u0915\\u0948\\u0938\\u0947 \\u0915\\u0930\\u0947\\u0902\",\"step_sub_title\":\"QRPay Pro \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u0915\\u093f\\u0938\\u0940 \\u092d\\u0940 \\u0935\\u094d\\u092f\\u0915\\u094d\\u0924\\u093f \\u0915\\u094b \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0928 \\u0938\\u0930\\u0932 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"6724985094bee\":{\"language\":{\"en\":{\"name\":\"Enter Request Details\"},\"ar\":{\"name\":\"\\u0623\\u062f\\u062e\\u0644 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0637\\u0644\\u0628\"},\"es\":{\"name\":\"Ingrese los detalles de la solicitud\"},\"fr\":{\"name\":\"Entrez les d\\u00e9tails de la demande\"},\"hi\":{\"name\":\"\\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6724985094bee\"},\"67249857752b8\":{\"language\":{\"en\":{\"name\":\"Send the Request\"},\"ar\":{\"name\":\"\\u0623\\u0631\\u0633\\u0644 \\u0627\\u0644\\u0637\\u0644\\u0628\"},\"es\":{\"name\":\"Enviar la solicitud\"},\"fr\":{\"name\":\"Envoyer la demande\"},\"hi\":{\"name\":\"\\u0905\\u0928\\u0941\\u0930\\u094b\\u0927 \\u092d\\u0947\\u091c\\u0947\\u0902\"}},\"id\":\"67249857752b8\"},\"6724985e429ec\":{\"language\":{\"en\":{\"name\":\"Receive Notification\"},\"ar\":{\"name\":\"\\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0625\\u062e\\u0637\\u0627\\u0631\"},\"es\":{\"name\":\"Recibir notificaci\\u00f3n\"},\"fr\":{\"name\":\"Recevoir une notification\"},\"hi\":{\"name\":\"\\u0905\\u0927\\u093f\\u0938\\u0942\\u091a\\u0928\\u093e \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6724985e429ec\"}}}', 1, 1, '2024-11-01 14:58:48', '2024-12-12 18:36:48');
INSERT INTO `frontend_header_section_pages` VALUES (9, 9, 'personal', '{\"images\":{\"section_image\":\"975939bc-aa8a-401e-886f-35494adc0e4f.webp\",\"step_image\":\"1a249f43-394f-4b85-8c3f-66aae4203f60.webp\"},\"language\":{\"en\":{\"heading\":\"Send Remittances Quickly and Securely with QRPay Pro\",\"sub_heading\":\"QRPay Pro makes international money transfers simple and reliable. Whether you\\u2019re sending money to support family members abroad or paying bills for friends, our remittance service ensures your funds arrive safely and swiftly. With competitive rates and real-time tracking, you can send money confidently, knowing it\\u2019s in good hands.\",\"process_step_title\":\"Remit Funds in 3 Easy Steps\",\"button_name\":\"Start Sending Remittance Now\",\"button_link\":\"user\\/remittance\",\"step_title\":\"How to Use QRPay Pro for Remittances\",\"step_sub_title\":\"Follow these simple steps to send remittance funds anywhere in the world using QRPay Pro.\"},\"es\":{\"heading\":\"Env\\u00ede remesas de forma r\\u00e1pida y segura con QRPay Pro\",\"sub_heading\":\"QRPay Pro hace que las transferencias de dinero internacionales sean simples y confiables. Ya sea que env\\u00ede dinero para mantener a familiares en el extranjero o pague facturas de amigos, nuestro servicio de remesas garantiza que sus fondos lleguen de forma segura y r\\u00e1pida. Con tarifas competitivas y seguimiento en tiempo real, puede enviar dinero con confianza sabiendo que est\\u00e1 en buenas manos.\",\"process_step_title\":\"Enviar fondos en 3 sencillos pasos\",\"button_name\":\"Comience a enviar remesas ahora\",\"button_link\":\"user\\/remittance\",\"step_title\":\"C\\u00f3mo utilizar QRPay Pro para remesas\",\"step_sub_title\":\"Siga estos sencillos pasos para enviar fondos de remesas a cualquier parte del mundo utilizando QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0623\\u0631\\u0633\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0628\\u0633\\u0631\\u0639\\u0629 \\u0648\\u0623\\u0645\\u0627\\u0646 \\u0645\\u0639 QRPay Pro\",\"sub_heading\":\"QRPay Pro \\u064a\\u062c\\u0639\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062f\\u0648\\u0644\\u064a\\u0629 \\u0628\\u0633\\u064a\\u0637\\u0629 \\u0648\\u0645\\u0648\\u062b\\u0648\\u0642\\u0629. \\u0633\\u0648\\u0627\\u0621 \\u0643\\u0646\\u062a \\u062a\\u0631\\u0633\\u0644 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0627\\u064b \\u0644\\u062f\\u0639\\u0645 \\u0623\\u0641\\u0631\\u0627\\u062f \\u0639\\u0627\\u0626\\u0644\\u062a\\u0643 \\u0641\\u064a \\u0627\\u0644\\u062e\\u0627\\u0631\\u062c \\u0623\\u0648 \\u062a\\u062f\\u0641\\u0639 \\u0641\\u0648\\u0627\\u062a\\u064a\\u0631 \\u0644\\u0623\\u0635\\u062f\\u0642\\u0627\\u0626\\u0643\\u060c \\u0641\\u0625\\u0646 \\u062e\\u062f\\u0645\\u0629 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0644\\u062f\\u064a\\u0646\\u0627 \\u062a\\u0636\\u0645\\u0646 \\u0648\\u0635\\u0648\\u0644 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0628\\u0623\\u0645\\u0627\\u0646 \\u0648\\u0633\\u0631\\u0639\\u0629. \\u0628\\u0641\\u0636\\u0644 \\u0627\\u0644\\u0623\\u0633\\u0639\\u0627\\u0631 \\u0627\\u0644\\u062a\\u0646\\u0627\\u0641\\u0633\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062a\\u062a\\u0628\\u0639 \\u0641\\u064a \\u0627\\u0644\\u0648\\u0642\\u062a \\u0627\\u0644\\u0641\\u0639\\u0644\\u064a\\u060c \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u062b\\u0642\\u0629\\u060c \\u0645\\u0639 \\u0627\\u0644\\u0639\\u0644\\u0645 \\u0623\\u0646\\u0647\\u0627 \\u0641\\u064a \\u0623\\u064a\\u062f\\u064d \\u0623\\u0645\\u064a\\u0646\\u0629.\",\"process_step_title\":\"\\u0642\\u0645 \\u0628\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a 3 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0633\\u0647\\u0644\\u0629\",\"button_name\":\"\\u0627\\u0628\\u062f\\u0623 \\u0628\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u062d\\u0648\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"user\\/remittance\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro \\u0644\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0627\\u0644\\u064a\\u0629\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0628\\u0633\\u064a\\u0637\\u0629 \\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0623\\u0645\\u0648\\u0627\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0625\\u0644\\u0649 \\u0623\\u064a \\u0645\\u0643\\u0627\\u0646 \\u0641\\u064a \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro.\"},\"fr\":{\"heading\":\"Env\\u00ede remesas de forma r\\u00e1pida y segura con QRPay Pro\",\"sub_heading\":\"QRPay Pro rend les transferts d\'argent internationaux simples et fiables. Que vous envoyiez de l\'argent pour subvenir aux besoins de membres de votre famille \\u00e0 l\'\\u00e9tranger ou que vous payiez des factures \\u00e0 des amis, notre service de transfert de fonds garantit que vos fonds arrivent rapidement et en toute s\\u00e9curit\\u00e9. Avec des tarifs comp\\u00e9titifs et un suivi en temps r\\u00e9el, vous pouvez envoyer de l\\u2019argent en toute confiance, sachant qu\\u2019il est entre de bonnes mains.\",\"process_step_title\":\"Transf\\u00e9rer des fonds en 3 \\u00e9tapes faciles\",\"button_name\":\"Commencez \\u00e0 envoyer des fonds maintenant\",\"button_link\":\"user\\/remittance\",\"step_title\":\"Comment utiliser QRPay Pro pour les envois de fonds\",\"step_sub_title\":\"Suivez ces \\u00e9tapes simples pour envoyer des fonds partout dans le monde \\u00e0 l\'aide de QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0924\\u094d\\u0935\\u0930\\u093f\\u0924 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u092d\\u0947\\u091c\\u0947\\u0902\",\"sub_heading\":\"QRPay Pro \\u0905\\u0902\\u0924\\u0930\\u094d\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0927\\u0928 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u094b \\u0938\\u0930\\u0932 \\u0914\\u0930 \\u0935\\u093f\\u0936\\u094d\\u0935\\u0938\\u0928\\u0940\\u092f \\u092c\\u0928\\u093e\\u0924\\u093e \\u0939\\u0948\\u0964 \\u091a\\u093e\\u0939\\u0947 \\u0906\\u092a \\u0935\\u093f\\u0926\\u0947\\u0936 \\u092e\\u0947\\u0902 \\u092a\\u0930\\u093f\\u0935\\u093e\\u0930 \\u0915\\u0947 \\u0938\\u0926\\u0938\\u094d\\u092f\\u094b\\u0902 \\u0915\\u0940 \\u0938\\u0939\\u093e\\u092f\\u0924\\u093e \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0927\\u0928 \\u092d\\u0947\\u091c \\u0930\\u0939\\u0947 \\u0939\\u094b\\u0902 \\u092f\\u093e \\u0926\\u094b\\u0938\\u094d\\u0924\\u094b\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092c\\u093f\\u0932 \\u0915\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930 \\u0930\\u0939\\u0947 \\u0939\\u094b\\u0902, \\u0939\\u092e\\u093e\\u0930\\u0940 \\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u0938\\u0947\\u0935\\u093e \\u092f\\u0939 \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0924\\u0940 \\u0939\\u0948 \\u0915\\u093f \\u0906\\u092a\\u0915\\u093e \\u0927\\u0928 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0914\\u0930 \\u0924\\u0947\\u091c\\u0940 \\u0938\\u0947 \\u092a\\u0939\\u0941\\u0902\\u091a\\u0947\\u0964 \\u092a\\u094d\\u0930\\u0924\\u093f\\u0938\\u094d\\u092a\\u0930\\u094d\\u0927\\u0940 \\u0926\\u0930\\u094b\\u0902 \\u0914\\u0930 \\u0935\\u093e\\u0938\\u094d\\u0924\\u0935\\u093f\\u0915 \\u0938\\u092e\\u092f \\u0915\\u0940 \\u091f\\u094d\\u0930\\u0948\\u0915\\u093f\\u0902\\u0917 \\u0915\\u0947 \\u0938\\u093e\\u0925, \\u0906\\u092a \\u0906\\u0924\\u094d\\u092e\\u0935\\u093f\\u0936\\u094d\\u0935\\u093e\\u0938 \\u0938\\u0947 \\u092a\\u0948\\u0938\\u093e \\u092d\\u0947\\u091c \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u092f\\u0939 \\u091c\\u093e\\u0928\\u0924\\u0947 \\u0939\\u0941\\u090f \\u0915\\u093f \\u092f\\u0939 \\u0905\\u091a\\u094d\\u091b\\u0947 \\u0939\\u093e\\u0925\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u0939\\u0948\\u0964\",\"process_step_title\":\"3 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u092d\\u0947\\u091c\\u0947\\u0902\",\"button_name\":\"\\u0905\\u092d\\u0940 \\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u092d\\u0947\\u091c\\u0928\\u093e \\u092a\\u094d\\u0930\\u093e\\u0930\\u0902\\u092d \\u0915\\u0930\\u0947\\u0902\",\"button_link\":\"user\\/remittance\",\"step_title\":\"\\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u0915\\u0947 \\u0932\\u093f\\u090f QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0948\\u0938\\u0947 \\u0915\\u0930\\u0947\\u0902\",\"step_sub_title\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u0926\\u0941\\u0928\\u093f\\u092f\\u093e \\u092e\\u0947\\u0902 \\u0915\\u0939\\u0940\\u0902 \\u092d\\u0940 \\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0928 \\u0938\\u0930\\u0932 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"67249928d6543\":{\"language\":{\"en\":{\"name\":\"Enter Recipient Details\"},\"ar\":{\"name\":\"\\u0623\\u062f\\u062e\\u0644 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645\"},\"es\":{\"name\":\"Ingrese los detalles del destinatario\"},\"fr\":{\"name\":\"Ingrese los detalles del destinatario\"},\"hi\":{\"name\":\"\\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"67249928d6543\"},\"67249930052f4\":{\"language\":{\"en\":{\"name\":\"Choose Transfer Method\"},\"ar\":{\"name\":\"\\u0627\\u062e\\u062a\\u0631 \\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u0646\\u0642\\u0644\"},\"es\":{\"name\":\"Elija el m\\u00e9todo de transferencia\"},\"fr\":{\"name\":\"Elija el m\\u00e9todo de transferencia\"},\"hi\":{\"name\":\"\\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0935\\u093f\\u0927\\u093f \\u091a\\u0941\\u0928\\u0947\\u0902\"}},\"id\":\"67249930052f4\"},\"6724993747058\":{\"language\":{\"en\":{\"name\":\"Confirm and Send\"},\"ar\":{\"name\":\"\\u062a\\u0623\\u0643\\u064a\\u062f \\u0648\\u0625\\u0631\\u0633\\u0627\\u0644\"},\"es\":{\"name\":\"Confirmar y enviar\"},\"fr\":{\"name\":\"Confirmar y enviar\"},\"hi\":{\"name\":\"\\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u092d\\u0947\\u091c\\u0947\\u0902\"}},\"id\":\"6724993747058\"}}}', 1, 1, '2024-11-01 15:02:21', '2024-12-12 18:37:23');
INSERT INTO `frontend_header_section_pages` VALUES (10, 10, 'personal', '{\"images\":{\"section_image\":\"8536606e-b16d-4f8f-8ede-ac0066ea23ec.webp\",\"step_image\":\"55a99f4b-489d-44a7-90d7-e38af5286315.webp\"},\"language\":{\"en\":{\"heading\":\"Easily Add Funds to Your QRPay Pro Account\",\"sub_heading\":\"With QRPay Pro, adding money to your account is fast and straightforward. Whether you\\u2019re funding your wallet for future transactions or ensuring you have a balance ready for bills and purchases, our seamless process makes it simple to add funds anytime, anywhere. Enjoy peace of mind with secure transactions and multiple funding options.\",\"process_step_title\":\"Add Money in 3 Simple Steps\",\"button_name\":\"Add Funds Now\",\"button_link\":\"user\\/add-money\",\"step_title\":\"How to Add Money to Your QRPay Pro Account\",\"step_sub_title\":\"Follow these straightforward steps to deposit funds into your QRPay Pro account effortlessly.\"},\"es\":{\"heading\":\"Agregue fondos f\\u00e1cilmente a su cuenta QRPay Pro\",\"sub_heading\":\"Con QRPay Pro, agregar dinero a su cuenta es r\\u00e1pido y sencillo. Ya sea que est\\u00e9 financiando su billetera para transacciones futuras o asegur\\u00e1ndose de tener un saldo listo para facturas y compras, nuestro proceso fluido simplifica la adici\\u00f3n de fondos en cualquier momento y en cualquier lugar. Disfrute de la tranquilidad con transacciones seguras y m\\u00faltiples opciones de financiaci\\u00f3n.\",\"process_step_title\":\"Agregue dinero en 3 simples pasos\",\"button_name\":\"Agregar fondos ahora\",\"button_link\":\"user\\/add-money\",\"step_title\":\"C\\u00f3mo agregar dinero a su cuenta QRPay Pro\",\"step_sub_title\":\"Siga estos sencillos pasos para depositar fondos en su cuenta QRPay Pro sin esfuerzo.\"},\"ar\":{\"heading\":\"\\u0642\\u0645 \\u0628\\u0625\\u0636\\u0627\\u0641\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\",\"sub_heading\":\"\\u0645\\u0639 QRPay Pro\\u060c \\u062a\\u0639\\u062f \\u0625\\u0636\\u0627\\u0641\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0623\\u0645\\u0631\\u064b\\u0627 \\u0633\\u0631\\u064a\\u0639\\u064b\\u0627 \\u0648\\u0645\\u0628\\u0627\\u0634\\u0631\\u064b\\u0627. \\u0633\\u0648\\u0627\\u0621 \\u0643\\u0646\\u062a \\u062a\\u0642\\u0648\\u0645 \\u0628\\u062a\\u0645\\u0648\\u064a\\u0644 \\u0645\\u062d\\u0641\\u0638\\u062a\\u0643 \\u0644\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0633\\u062a\\u0642\\u0628\\u0644\\u064a\\u0629 \\u0623\\u0648 \\u0627\\u0644\\u062a\\u0623\\u0643\\u062f \\u0645\\u0646 \\u0623\\u0646 \\u0644\\u062f\\u064a\\u0643 \\u0631\\u0635\\u064a\\u062f\\u064b\\u0627 \\u062c\\u0627\\u0647\\u0632\\u064b\\u0627 \\u0644\\u0644\\u0641\\u0648\\u0627\\u062a\\u064a\\u0631 \\u0648\\u0627\\u0644\\u0645\\u0634\\u062a\\u0631\\u064a\\u0627\\u062a\\u060c \\u0641\\u0625\\u0646 \\u0639\\u0645\\u0644\\u064a\\u062a\\u0646\\u0627 \\u0627\\u0644\\u0633\\u0644\\u0633\\u0629 \\u062a\\u062c\\u0639\\u0644 \\u0645\\u0646 \\u0627\\u0644\\u0633\\u0647\\u0644 \\u0625\\u0636\\u0627\\u0641\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a \\u0623\\u064a \\u0648\\u0642\\u062a \\u0648\\u0641\\u064a \\u0623\\u064a \\u0645\\u0643\\u0627\\u0646. \\u0627\\u0633\\u062a\\u0645\\u062a\\u0639 \\u0628\\u0631\\u0627\\u062d\\u0629 \\u0627\\u0644\\u0628\\u0627\\u0644 \\u0645\\u0639 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0622\\u0645\\u0646\\u0629 \\u0648\\u062e\\u064a\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u062a\\u0645\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0645\\u062a\\u0639\\u062f\\u062f\\u0629.\",\"process_step_title\":\"\\u0623\\u0636\\u0641 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a 3 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0628\\u0633\\u064a\\u0637\\u0629\",\"button_name\":\"\\u0623\\u0636\\u0641 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"user\\/add-money\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u0625\\u0636\\u0627\\u0641\\u0629 \\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0644\\u0625\\u064a\\u062f\\u0627\\u0639 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u062f\\u0648\\u0646 \\u0639\\u0646\\u0627\\u0621.\"},\"fr\":{\"heading\":\"Agregue fondos f\\u00e1cilmente a su cuenta QRPay Pro\",\"sub_heading\":\"Avec QRPay Pro, ajouter de l\'argent sur votre compte est rapide et simple. Que vous approvisionniez votre portefeuille pour de futures transactions ou que vous vous assuriez d\'avoir un solde pr\\u00eat pour les factures et les achats, notre processus transparent facilite l\'ajout de fonds \\u00e0 tout moment et en tout lieu. Profitez d\'une tranquillit\\u00e9 d\'esprit gr\\u00e2ce \\u00e0 des transactions s\\u00e9curis\\u00e9es et \\u00e0 de multiples options de financement.\",\"process_step_title\":\"Ajoutez de l\'argent en 3 \\u00e9tapes simples\",\"button_name\":\"Ajouter des fonds maintenant\",\"button_link\":\"user\\/add-money\",\"step_title\":\"Comment ajouter de l\'argent \\u00e0 votre compte QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes simples pour d\\u00e9poser des fonds sur votre compte QRPay Pro sans effort.\"},\"hi\":{\"heading\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u091c\\u094b\\u0921\\u093c\\u0947\\u0902\",\"sub_heading\":\"QRPay Pro \\u0915\\u0947 \\u0938\\u093e\\u0925, \\u0906\\u092a\\u0915\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u092a\\u0948\\u0938\\u0947 \\u091c\\u094b\\u0921\\u093c\\u0928\\u093e \\u0924\\u0947\\u091c\\u093c \\u0914\\u0930 \\u0938\\u0930\\u0932 \\u0939\\u0948\\u0964 \\u091a\\u093e\\u0939\\u0947 \\u0906\\u092a \\u092d\\u0935\\u093f\\u0937\\u094d\\u092f \\u0915\\u0947 \\u0932\\u0947\\u0928-\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u0947 \\u092c\\u091f\\u0941\\u090f \\u092e\\u0947\\u0902 \\u0927\\u0928 \\u0932\\u0917\\u093e \\u0930\\u0939\\u0947 \\u0939\\u094b\\u0902 \\u092f\\u093e \\u092f\\u0939 \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930 \\u0930\\u0939\\u0947 \\u0939\\u094b\\u0902 \\u0915\\u093f \\u0906\\u092a\\u0915\\u0947 \\u092a\\u093e\\u0938 \\u092c\\u093f\\u0932\\u094b\\u0902 \\u0914\\u0930 \\u0916\\u0930\\u0940\\u0926\\u093e\\u0930\\u0940 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0936\\u0947\\u0937 \\u0930\\u093e\\u0936\\u093f \\u0924\\u0948\\u092f\\u093e\\u0930 \\u0939\\u0948, \\u0939\\u092e\\u093e\\u0930\\u0940 \\u0928\\u093f\\u0930\\u094d\\u092c\\u093e\\u0927 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0915\\u093f\\u0938\\u0940 \\u092d\\u0940 \\u0938\\u092e\\u092f, \\u0915\\u0939\\u0940\\u0902 \\u092d\\u0940 \\u0927\\u0928 \\u091c\\u094b\\u0921\\u093c\\u0928\\u093e \\u0906\\u0938\\u093e\\u0928 \\u092c\\u0928\\u093e\\u0924\\u0940 \\u0939\\u0948\\u0964 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0914\\u0930 \\u0915\\u0908 \\u092b\\u0902\\u0921\\u093f\\u0902\\u0917 \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a\\u094b\\u0902 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u092e\\u093e\\u0928\\u0938\\u093f\\u0915 \\u0936\\u093e\\u0902\\u0924\\u093f \\u0915\\u093e \\u0906\\u0928\\u0902\\u0926 \\u0932\\u0947\\u0902\\u0964\",\"process_step_title\":\"3 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u092a\\u0948\\u0938\\u0947 \\u091c\\u094b\\u0921\\u093c\\u0947\\u0902\",\"button_name\":\"\\u0905\\u092d\\u0940 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u091c\\u094b\\u0921\\u093c\\u0947\\u0902\",\"button_link\":\"user\\/add-money\",\"step_title\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u091c\\u094b\\u0921\\u093c\\u0947\\u0902\",\"step_sub_title\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u091c\\u092e\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0928 \\u0938\\u0930\\u0932 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"67249a18b8964\":{\"language\":{\"en\":{\"name\":\"Select Funding Source\"},\"ar\":{\"name\":\"\\u062d\\u062f\\u062f \\u0645\\u0635\\u062f\\u0631 \\u0627\\u0644\\u062a\\u0645\\u0648\\u064a\\u0644\"},\"es\":{\"name\":\"Seleccionar fuente de financiamiento\"},\"fr\":{\"name\":\"Seleccionar fuente de financiamiento\"},\"hi\":{\"name\":\"\\u092b\\u0902\\u0921\\u093f\\u0902\\u0917 \\u0938\\u094d\\u0930\\u094b\\u0924 \\u0915\\u093e \\u091a\\u092f\\u0928 \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"67249a18b8964\"},\"67249a1f07139\":{\"language\":{\"en\":{\"name\":\"Enter Amount\"},\"ar\":{\"name\":\"\\u0623\\u062f\\u062e\\u0644 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a\"},\"es\":{\"name\":\"Ingrese el monto\"},\"fr\":{\"name\":\"Ingrese el monto\"},\"hi\":{\"name\":\"\\u0930\\u093e\\u0936\\u093f \\u0921\\u093e\\u0932\\u0947\\u0902\"}},\"id\":\"67249a1f07139\"},\"67249a248a80d\":{\"language\":{\"en\":{\"name\":\"Confirm the Transaction\"},\"ar\":{\"name\":\"\\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629\"},\"es\":{\"name\":\"Confirmar la transacci\\u00f3n\"},\"fr\":{\"name\":\"Confirmar la transacci\\u00f3n\"},\"hi\":{\"name\":\"\\u0932\\u0947\\u0928-\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"67249a248a80d\"}}}', 1, 1, '2024-11-01 15:06:25', '2024-12-12 18:37:54');
INSERT INTO `frontend_header_section_pages` VALUES (11, 11, 'personal', '{\"images\":{\"section_image\":\"bab98721-83ae-4a7d-b4f8-499a0f828c74.webp\",\"step_image\":\"2167781a-e9eb-449a-a9eb-5e23f1c411f3.webp\"},\"language\":{\"en\":{\"heading\":\"Effortlessly Withdraw Funds from Your QRPay Pro Account\",\"sub_heading\":\"With QRPay Pro, withdrawing your money is quick and secure. Whether you need cash for your daily expenses or want to transfer funds to your bank account, our streamlined withdrawal process makes it simple to access your funds when you need them. Enjoy peace of mind with robust security measures protecting your transactions.\",\"process_step_title\":\"Withdraw Money in 3 Simple Steps\",\"button_name\":\"Withdraw Funds Now\",\"button_link\":\"user\\/withdraw\",\"step_title\":\"How to Withdraw Money from Your QRPay Pro Account\",\"step_sub_title\":\"Follow these easy steps to withdraw funds from your QRPay Pro account seamlessly.\"},\"es\":{\"heading\":\"Retire fondos sin esfuerzo de su cuenta QRPay Pro\",\"sub_heading\":\"Con QRPay Pro, retirar tu dinero es r\\u00e1pido y seguro. Ya sea que necesite efectivo para sus gastos diarios o desee transferir fondos a su cuenta bancaria, nuestro proceso de retiro simplificado simplifica el acceso a sus fondos cuando los necesita. Disfrute de la tranquilidad con s\\u00f3lidas medidas de seguridad que protegen sus transacciones.\",\"process_step_title\":\"Retirar dinero en 3 sencillos pasos\",\"button_name\":\"Retirar fondos ahora\",\"button_link\":\"user\\/withdraw\",\"step_title\":\"C\\u00f3mo retirar dinero de su cuenta QRPay Pro\",\"step_sub_title\":\"Siga estos sencillos pasos para retirar fondos de su cuenta QRPay Pro sin problemas.\"},\"ar\":{\"heading\":\"\\u0642\\u0645 \\u0628\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0645\\u0646 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\",\"sub_heading\":\"\\u0645\\u0639 QRPay Pro\\u060c \\u0623\\u0635\\u0628\\u062d \\u0633\\u062d\\u0628 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0633\\u0631\\u064a\\u0639\\u064b\\u0627 \\u0648\\u0622\\u0645\\u0646\\u064b\\u0627. \\u0633\\u0648\\u0627\\u0621 \\u0643\\u0646\\u062a \\u0628\\u062d\\u0627\\u062c\\u0629 \\u0625\\u0644\\u0649 \\u0623\\u0645\\u0648\\u0627\\u0644 \\u0646\\u0642\\u062f\\u064a\\u0629 \\u0644\\u062a\\u063a\\u0637\\u064a\\u0629 \\u0646\\u0641\\u0642\\u0627\\u062a\\u0643 \\u0627\\u0644\\u064a\\u0648\\u0645\\u064a\\u0629 \\u0623\\u0648 \\u062a\\u0631\\u063a\\u0628 \\u0641\\u064a \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0627\\u0644\\u0645\\u0635\\u0631\\u0641\\u064a\\u060c \\u0641\\u0625\\u0646 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0645\\u0628\\u0633\\u0637\\u0629 \\u0644\\u062f\\u064a\\u0646\\u0627 \\u062a\\u062c\\u0639\\u0644 \\u0645\\u0646 \\u0627\\u0644\\u0633\\u0647\\u0644 \\u0627\\u0644\\u0648\\u0635\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0639\\u0646\\u062f\\u0645\\u0627 \\u062a\\u062d\\u062a\\u0627\\u062c \\u0625\\u0644\\u064a\\u0647\\u0627. \\u0627\\u0633\\u062a\\u0645\\u062a\\u0639 \\u0628\\u0631\\u0627\\u062d\\u0629 \\u0627\\u0644\\u0628\\u0627\\u0644 \\u0645\\u0639 \\u0627\\u0644\\u0625\\u062c\\u0631\\u0627\\u0621\\u0627\\u062a \\u0627\\u0644\\u0623\\u0645\\u0646\\u064a\\u0629 \\u0627\\u0644\\u0642\\u0648\\u064a\\u0629 \\u0627\\u0644\\u062a\\u064a \\u062a\\u062d\\u0645\\u064a \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u0643.\",\"process_step_title\":\"\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a 3 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0628\\u0633\\u064a\\u0637\\u0629\",\"button_name\":\"\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"user\\/withdraw\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u0646 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0633\\u0647\\u0644\\u0629 \\u0644\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u0646 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u0628\\u0633\\u0644\\u0627\\u0633\\u0629.\"},\"fr\":{\"heading\":\"Retire fondos sin esfuerzo de su cuenta QRPay Pro\",\"sub_heading\":\"Avec QRPay Pro, retirer votre argent est rapide et s\\u00e9curis\\u00e9. Que vous ayez besoin d\'argent pour vos d\\u00e9penses quotidiennes ou que vous souhaitiez transf\\u00e9rer des fonds sur votre compte bancaire, notre processus de retrait simplifi\\u00e9 facilite l\'acc\\u00e8s \\u00e0 vos fonds lorsque vous en avez besoin. Profitez d\'une tranquillit\\u00e9 d\'esprit gr\\u00e2ce \\u00e0 des mesures de s\\u00e9curit\\u00e9 robustes prot\\u00e9geant vos transactions.\",\"process_step_title\":\"Retirer de l\'argent en 3 \\u00e9tapes simples\",\"button_name\":\"Retirer des fonds maintenant\",\"button_link\":\"user\\/withdraw\",\"step_title\":\"Comment retirer de l\'argent de votre compte QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes simples pour retirer des fonds de votre compte QRPay Pro en toute transparence.\"},\"hi\":{\"heading\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u0938\\u0947 \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0928\\u093f\\u0915\\u093e\\u0932\\u0947\\u0902\",\"sub_heading\":\"QRPay Pro \\u0915\\u0947 \\u0938\\u093e\\u0925, \\u0905\\u092a\\u0928\\u093e \\u092a\\u0948\\u0938\\u093e \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u093e \\u0924\\u094d\\u0935\\u0930\\u093f\\u0924 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0939\\u0948\\u0964 \\u091a\\u093e\\u0939\\u0947 \\u0906\\u092a\\u0915\\u094b \\u0905\\u092a\\u0928\\u0947 \\u0926\\u0948\\u0928\\u093f\\u0915 \\u0916\\u0930\\u094d\\u091a\\u094b\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0928\\u0915\\u0926\\u0940 \\u0915\\u0940 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915\\u0924\\u093e \\u0939\\u094b \\u092f\\u093e \\u0906\\u092a \\u0905\\u092a\\u0928\\u0947 \\u092c\\u0948\\u0902\\u0915 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u093f\\u0924 \\u0915\\u0930\\u0928\\u093e \\u091a\\u093e\\u0939\\u0924\\u0947 \\u0939\\u094b\\u0902, \\u0939\\u092e\\u093e\\u0930\\u0940 \\u0938\\u0941\\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093f\\u0924 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u091c\\u0930\\u0942\\u0930\\u0924 \\u092a\\u0921\\u093c\\u0928\\u0947 \\u092a\\u0930 \\u0906\\u092a\\u0915\\u0947 \\u0927\\u0928 \\u0924\\u0915 \\u092a\\u0939\\u0941\\u0902\\u091a \\u0915\\u094b \\u0906\\u0938\\u093e\\u0928 \\u092c\\u0928\\u093e\\u0924\\u0940 \\u0939\\u0948\\u0964 \\u0905\\u092a\\u0928\\u0947 \\u0932\\u0947\\u0928-\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092e\\u091c\\u092c\\u0942\\u0924 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0909\\u092a\\u093e\\u092f\\u094b\\u0902 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u092e\\u093e\\u0928\\u0938\\u093f\\u0915 \\u0936\\u093e\\u0902\\u0924\\u093f \\u0915\\u093e \\u0906\\u0928\\u0902\\u0926 \\u0932\\u0947\\u0902\\u0964\",\"process_step_title\":\"3 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0947\\u0902\",\"button_name\":\"\\u0905\\u092d\\u0940 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0928\\u093f\\u0915\\u093e\\u0932\\u0947\\u0902\",\"button_link\":\"user\\/withdraw\",\"step_title\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u0938\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0947\\u0902\",\"step_sub_title\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u0938\\u0947 \\u0928\\u093f\\u0930\\u094d\\u092c\\u093e\\u0927 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0928 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"67249ac22c6bd\":{\"language\":{\"en\":{\"name\":\"Choose Withdrawal Method\"},\"ar\":{\"name\":\"\\u0627\\u062e\\u062a\\u0631 \\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u0633\\u062d\\u0628\"},\"es\":{\"name\":\"Elija el m\\u00e9todo de retiro\"},\"fr\":{\"name\":\"Elija el m\\u00e9todo de retiro\"},\"hi\":{\"name\":\"\\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0935\\u093f\\u0927\\u093f \\u091a\\u0941\\u0928\\u0947\\u0902\"}},\"id\":\"67249ac22c6bd\"},\"67249ac80326e\":{\"language\":{\"en\":{\"name\":\"Enter Amount\"},\"ar\":{\"name\":\"\\u0623\\u062f\\u062e\\u0644 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a\"},\"es\":{\"name\":\"Ingrese el monto\"},\"fr\":{\"name\":\"Ingrese el monto\"},\"hi\":{\"name\":\"\\u0930\\u093e\\u0936\\u093f \\u0921\\u093e\\u0932\\u0947\\u0902\"}},\"id\":\"67249ac80326e\"},\"67249acd4186f\":{\"language\":{\"en\":{\"name\":\"Confirm the Transaction\"},\"ar\":{\"name\":\"\\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629\"},\"es\":{\"name\":\"Confirmar la transacci\\u00f3n\"},\"fr\":{\"name\":\"Confirmar la transacci\\u00f3n\"},\"hi\":{\"name\":\"\\u0932\\u0947\\u0928-\\u0926\\u0947\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"67249acd4186f\"}}}', 1, 1, '2024-11-01 15:09:15', '2024-12-31 12:26:00');
INSERT INTO `frontend_header_section_pages` VALUES (12, 12, 'personal', '{\"images\":{\"section_image\":\"4d37f2ff-4896-4026-9446-9b3ff64e72f7.webp\",\"step_image\":\"90201c5b-2a67-4443-aad2-cf6a19b03edc.webp\"},\"language\":{\"en\":{\"heading\":\"Quick and Convenient Payments to QRPay Pro Merchants\",\"sub_heading\":\"With QRPay Pro, making payments for your purchases has never been easier. As a user, you can effortlessly transfer funds to merchants registered on the QRPay Pro platform. Enjoy the convenience of using your QRPay Pro account for all your transactions while benefiting from robust security measures that protect your financial information.\",\"process_step_title\":\"Make Payments in 3 Simple Steps\",\"button_name\":\"Make a Payment Now\",\"button_link\":\"user\\/make-payment\",\"step_title\":\"How to Make a Payment to QRPay Pro Merchants\",\"step_sub_title\":\"Follow these straightforward steps to complete your payment effortlessly.\"},\"es\":{\"heading\":\"Pagos r\\u00e1pidos y convenientes a comerciantes de QRPay Pro\",\"sub_heading\":\"Con QRPay Pro realizar pagos de tus compras nunca ha sido tan f\\u00e1cil. Como usuario, puede transferir fondos sin esfuerzo a comerciantes registrados en la plataforma QRPay Pro. Disfrute de la comodidad de utilizar su cuenta QRPay Pro para todas sus transacciones mientras se beneficia de s\\u00f3lidas medidas de seguridad que protegen su informaci\\u00f3n financiera.\",\"process_step_title\":\"Realice pagos en 3 sencillos pasos\",\"button_name\":\"Realizar un pago ahora\",\"button_link\":\"user\\/make-payment\",\"step_title\":\"C\\u00f3mo realizar un pago a comerciantes de QRPay Pro\",\"step_sub_title\":\"Siga estos sencillos pasos para completar su pago sin esfuerzo.\"},\"ar\":{\"heading\":\"\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0633\\u0631\\u064a\\u0639\\u0629 \\u0648\\u0645\\u0631\\u064a\\u062d\\u0629 \\u0644\\u062a\\u062c\\u0627\\u0631 QRPay Pro\",\"sub_heading\":\"\\u0645\\u0639 QRPay Pro\\u060c \\u0623\\u0635\\u0628\\u062d \\u0625\\u062c\\u0631\\u0627\\u0621 \\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0645\\u0642\\u0627\\u0628\\u0644 \\u0645\\u0634\\u062a\\u0631\\u064a\\u0627\\u062a\\u0643 \\u0623\\u0633\\u0647\\u0644 \\u0645\\u0646 \\u0623\\u064a \\u0648\\u0642\\u062a \\u0645\\u0636\\u0649. \\u0643\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u060c \\u064a\\u0645\\u0643\\u0646\\u0643 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u062a\\u062c\\u0627\\u0631 \\u0627\\u0644\\u0645\\u0633\\u062c\\u0644\\u064a\\u0646 \\u0639\\u0644\\u0649 \\u0645\\u0646\\u0635\\u0629 QRPay Pro. \\u0627\\u0633\\u062a\\u0645\\u062a\\u0639 \\u0628\\u0631\\u0627\\u062d\\u0629 \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u0644\\u062c\\u0645\\u064a\\u0639 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u0643 \\u0645\\u0639 \\u0627\\u0644\\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0625\\u062c\\u0631\\u0627\\u0621\\u0627\\u062a \\u0627\\u0644\\u0623\\u0645\\u0646\\u064a\\u0629 \\u0627\\u0644\\u0642\\u0648\\u064a\\u0629 \\u0627\\u0644\\u062a\\u064a \\u062a\\u062d\\u0645\\u064a \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a\\u0643 \\u0627\\u0644\\u0645\\u0627\\u0644\\u064a\\u0629.\",\"process_step_title\":\"\\u0642\\u0645 \\u0628\\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u062f\\u0641\\u0639\\u0627\\u062a \\u0641\\u064a 3 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0628\\u0633\\u064a\\u0637\\u0629\",\"button_name\":\"\\u0642\\u0645 \\u0628\\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"user\\/make-payment\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0644\\u062a\\u062c\\u0627\\u0631 QRPay Pro\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0644\\u0625\\u0643\\u0645\\u0627\\u0644 \\u062f\\u0641\\u0639\\u062a\\u0643 \\u062f\\u0648\\u0646 \\u0639\\u0646\\u0627\\u0621.\"},\"fr\":{\"heading\":\"Pagos r\\u00e1pidos y convenientes a comerciantes de QRPay Pro\",\"sub_heading\":\"Avec QRPay Pro, effectuer des paiements pour vos achats n\'a jamais \\u00e9t\\u00e9 aussi simple. En tant qu\'utilisateur, vous pouvez facilement transf\\u00e9rer des fonds aux commer\\u00e7ants enregistr\\u00e9s sur la plateforme QRPay Pro. Profitez de la commodit\\u00e9 d\'utiliser votre compte QRPay Pro pour toutes vos transactions tout en b\\u00e9n\\u00e9ficiant de mesures de s\\u00e9curit\\u00e9 robustes qui prot\\u00e8gent vos informations financi\\u00e8res.\",\"process_step_title\":\"Effectuez des paiements en 3 \\u00e9tapes simples\",\"button_name\":\"Effectuer un paiement maintenant\",\"button_link\":\"user\\/make-payment\",\"step_title\":\"Comment effectuer un paiement aux marchands QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes simples pour effectuer votre paiement sans effort.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u093f\\u092f\\u094b\\u0902 \\u0915\\u094b \\u0924\\u094d\\u0935\\u0930\\u093f\\u0924 \\u0914\\u0930 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e\\u091c\\u0928\\u0915 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928\",\"sub_heading\":\"QRPay Pro \\u0915\\u0947 \\u0938\\u093e\\u0925, \\u0905\\u092a\\u0928\\u0940 \\u0916\\u0930\\u0940\\u0926\\u093e\\u0930\\u0940 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0928\\u093e \\u0907\\u0924\\u0928\\u093e \\u0906\\u0938\\u093e\\u0928 \\u0915\\u092d\\u0940 \\u0928\\u0939\\u0940\\u0902 \\u0930\\u0939\\u093e\\u0964 \\u090f\\u0915 \\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e \\u0915\\u0947 \\u0930\\u0942\\u092a \\u092e\\u0947\\u0902, \\u0906\\u092a QRPay \\u092a\\u094d\\u0930\\u094b \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e \\u092a\\u0930 \\u092a\\u0902\\u091c\\u0940\\u0915\\u0943\\u0924 \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u093f\\u092f\\u094b\\u0902 \\u0915\\u094b \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u093f\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0905\\u092a\\u0928\\u0940 \\u0935\\u093f\\u0924\\u094d\\u0924\\u0940\\u092f \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0915\\u0940 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0935\\u093e\\u0932\\u0947 \\u092e\\u091c\\u092c\\u0942\\u0924 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0909\\u092a\\u093e\\u092f\\u094b\\u0902 \\u0938\\u0947 \\u0932\\u093e\\u092d \\u0909\\u0920\\u093e\\u0924\\u0947 \\u0939\\u0941\\u090f \\u0905\\u092a\\u0928\\u0947 \\u0938\\u092d\\u0940 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0940 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0915\\u093e \\u0906\\u0928\\u0902\\u0926 \\u0932\\u0947\\u0902\\u0964\",\"process_step_title\":\"3 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0947\\u0902\",\"button_name\":\"\\u0905\\u092d\\u0940 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0947\\u0902\",\"button_link\":\"user\\/make-payment\",\"step_title\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u093f\\u092f\\u094b\\u0902 \\u0915\\u094b \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0948\\u0938\\u0947 \\u0915\\u0930\\u0947\\u0902\",\"step_sub_title\":\"\\u0905\\u092a\\u0928\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u092a\\u0942\\u0930\\u093e \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0928 \\u0938\\u0930\\u0932 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"67249bf0b6879\":{\"language\":{\"en\":{\"name\":\"Scan Merchant QRCode\"},\"ar\":{\"name\":\"\\u0645\\u0633\\u062d \\u0631\\u0645\\u0632 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639\\u0629 \\u0644\\u0644\\u062a\\u0627\\u062c\\u0631\"},\"es\":{\"name\":\"Escanear el c\\u00f3digo QR del comerciante\"},\"fr\":{\"name\":\"Escanear el c\\u00f3digo QR del comerciante\"},\"hi\":{\"name\":\"\\u092e\\u0930\\u094d\\u091a\\u0947\\u0902\\u091f QRCode \\u0915\\u094b \\u0938\\u094d\\u0915\\u0948\\u0928 \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"67249bf0b6879\"},\"67249bfb359a1\":{\"language\":{\"en\":{\"name\":\"Enter Amount\"},\"ar\":{\"name\":\"\\u0623\\u062f\\u062e\\u0644 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a\"},\"es\":{\"name\":\"Ingrese el monto\"},\"fr\":{\"name\":\"Ingrese el monto\"},\"hi\":{\"name\":\"\\u0930\\u093e\\u0936\\u093f \\u0921\\u093e\\u0932\\u0947\\u0902\"}},\"id\":\"67249bfb359a1\"},\"67249c0627136\":{\"language\":{\"en\":{\"name\":\"Confirm the Payment\"},\"ar\":{\"name\":\"\\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u062f\\u0641\\u0639\"},\"es\":{\"name\":\"Confirmar el pago\"},\"fr\":{\"name\":\"Confirmar el pago\"},\"hi\":{\"name\":\"\\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f\"}},\"id\":\"67249c0627136\"}}}', 1, 1, '2024-11-01 15:13:59', '2024-12-12 18:38:50');
INSERT INTO `frontend_header_section_pages` VALUES (13, 13, 'personal', '{\"images\":{\"section_image\":\"958e8e32-c3ed-4a09-ab06-44f27c86abce.webp\",\"step_image\":\"a6e95d6a-bcdc-406d-b97c-0c30d42db0a5.webp\"},\"language\":{\"en\":{\"heading\":\"Quick and Secure Withdrawals to QRPay Pro Agents\",\"sub_heading\":\"With QRPay Pro, accessing your funds has never been easier. Users can withdraw money from their QRPay Pro account to trusted QRPay Pro agents. Enjoy peace of mind with every transaction, knowing your funds are secure and the process is hassle-free.\",\"process_step_title\":\"Withdraw Funds in 3 Simple Steps\",\"button_name\":\"Withdraw Money Now\",\"button_link\":\"user\\/money-out\",\"step_title\":\"How to Withdraw Money from Your QRPay Pro Account\",\"step_sub_title\":\"Follow these straightforward steps to securely transfer your funds to a QRPay Pro agent.\"},\"es\":{\"heading\":\"Retiros r\\u00e1pidos y seguros a agentes QRPay Pro\",\"sub_heading\":\"Con QRPay Pro, acceder a sus fondos nunca ha sido tan f\\u00e1cil. Los usuarios pueden retirar dinero de su cuenta QRPay Pro a agentes QRPay Pro confiables. Disfrute de la tranquilidad con cada transacci\\u00f3n, sabiendo que sus fondos est\\u00e1n seguros y el proceso es sencillo.\",\"process_step_title\":\"Retirar fondos en 3 sencillos pasos\",\"button_name\":\"Retirar dinero ahora\",\"button_link\":\"user\\/money-out\",\"step_title\":\"C\\u00f3mo retirar dinero de su cuenta QRPay Pro\",\"step_sub_title\":\"Siga estos sencillos pasos para transferir sus fondos de forma segura a un agente de QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0633\\u062d\\u0628 \\u0633\\u0631\\u064a\\u0639\\u0629 \\u0648\\u0622\\u0645\\u0646\\u0629 \\u0625\\u0644\\u0649 \\u0648\\u0643\\u0644\\u0627\\u0621 QRPay Pro\",\"sub_heading\":\"\\u0645\\u0639 QRPay Pro\\u060c \\u0623\\u0635\\u0628\\u062d \\u0627\\u0644\\u0648\\u0635\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0623\\u0633\\u0647\\u0644 \\u0645\\u0646 \\u0623\\u064a \\u0648\\u0642\\u062a \\u0645\\u0636\\u0649. \\u064a\\u0645\\u0643\\u0646 \\u0644\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u064a\\u0646 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u0646 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0647\\u0645 \\u0625\\u0644\\u0649 \\u0648\\u0643\\u0644\\u0627\\u0621 QRPay Pro \\u0627\\u0644\\u0645\\u0648\\u062b\\u0648\\u0642\\u064a\\u0646. \\u0627\\u0633\\u062a\\u0645\\u062a\\u0639 \\u0628\\u0631\\u0627\\u062d\\u0629 \\u0627\\u0644\\u0628\\u0627\\u0644 \\u0645\\u0639 \\u0643\\u0644 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0629\\u060c \\u0645\\u0639 \\u0627\\u0644\\u0639\\u0644\\u0645 \\u0623\\u0646 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0622\\u0645\\u0646\\u0629 \\u0648\\u0623\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629 \\u062e\\u0627\\u0644\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u062a\\u0627\\u0639\\u0628.\",\"process_step_title\":\"\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a 3 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0628\\u0633\\u064a\\u0637\\u0629\",\"button_name\":\"\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"user\\/money-out\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u0646 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0644\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0628\\u0634\\u0643\\u0644 \\u0622\\u0645\\u0646 \\u0625\\u0644\\u0649 \\u0648\\u0643\\u064a\\u0644 QRPay Pro.\"},\"fr\":{\"heading\":\"Retiros r\\u00e1pidos y seguros a agentes QRPay Pro\",\"sub_heading\":\"Avec QRPay Pro, acc\\u00e9der \\u00e0 vos fonds n\'a jamais \\u00e9t\\u00e9 aussi simple. Les utilisateurs peuvent retirer de l\'argent de leur compte QRPay Pro vers des agents QRPay Pro de confiance. Ayez l\'esprit tranquille \\u00e0 chaque transaction, sachant que vos fonds sont en s\\u00e9curit\\u00e9 et que le processus se d\\u00e9roule sans tracas.\",\"process_step_title\":\"Retirer des fonds en 3 \\u00e9tapes simples\",\"button_name\":\"Retirer de l\'argent maintenant\",\"button_link\":\"user\\/money-out\",\"step_title\":\"Comment retirer de l\'argent de votre compte QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes simples pour transf\\u00e9rer en toute s\\u00e9curit\\u00e9 vos fonds vers un agent QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u090f\\u091c\\u0947\\u0902\\u091f\\u094b\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0924\\u094d\\u0935\\u0930\\u093f\\u0924 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0928\\u093f\\u0915\\u093e\\u0938\\u0940\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925, \\u0906\\u092a\\u0915\\u0947 \\u092b\\u0902\\u0921 \\u0924\\u0915 \\u092a\\u0939\\u0941\\u0902\\u091a \\u0915\\u092d\\u0940 \\u0907\\u0924\\u0928\\u0940 \\u0906\\u0938\\u093e\\u0928 \\u0928\\u0939\\u0940\\u0902 \\u0930\\u0939\\u0940\\u0964 \\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u0938\\u0947 \\u0935\\u093f\\u0936\\u094d\\u0935\\u0938\\u0928\\u0940\\u092f QRPay \\u092a\\u094d\\u0930\\u094b \\u090f\\u091c\\u0947\\u0902\\u091f\\u094b\\u0902 \\u0915\\u094b \\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u0932\\u0947\\u0928-\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u092e\\u093e\\u0928\\u0938\\u093f\\u0915 \\u0936\\u093e\\u0902\\u0924\\u093f \\u0915\\u093e \\u0906\\u0928\\u0902\\u0926 \\u0932\\u0947\\u0902, \\u092f\\u0939 \\u091c\\u093e\\u0928\\u0915\\u0930 \\u0915\\u093f \\u0906\\u092a\\u0915\\u0940 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0939\\u0948 \\u0914\\u0930 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u092a\\u0930\\u0947\\u0936\\u093e\\u0928\\u0940 \\u092e\\u0941\\u0915\\u094d\\u0924 \\u0939\\u0948\\u0964\",\"process_step_title\":\"3 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0928\\u093f\\u0915\\u093e\\u0932\\u0947\\u0902\",\"button_name\":\"\\u0905\\u092d\\u0940 \\u092a\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0947\\u0902\",\"button_link\":\"user\\/money-out\",\"step_title\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u0938\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0947\\u0902\",\"step_sub_title\":\"\\u0905\\u092a\\u0928\\u0947 \\u092b\\u0902\\u0921 \\u0915\\u094b QRPay \\u092a\\u094d\\u0930\\u094b \\u090f\\u091c\\u0947\\u0902\\u091f \\u0915\\u094b \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0928 \\u0938\\u0930\\u0932 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"67249ccf1b85e\":{\"language\":{\"en\":{\"name\":\"Scan QRPay Pro Agent\'s QRCode\"},\"ar\":{\"name\":\"\\u0642\\u0645 \\u0628\\u0645\\u0633\\u062d QRCode \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0648\\u0643\\u064a\\u0644 QRPay Pro\"},\"es\":{\"name\":\"Escanee el c\\u00f3digo QR del agente QRPay Pro\"},\"fr\":{\"name\":\"Escanee el c\\u00f3digo QR del agente QRPay Pro\"},\"hi\":{\"name\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u090f\\u091c\\u0947\\u0902\\u091f \\u0915\\u0947 QRCode \\u0915\\u094b \\u0938\\u094d\\u0915\\u0948\\u0928 \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"67249ccf1b85e\"},\"67249cd59b605\":{\"language\":{\"en\":{\"name\":\"Enter Amount\"},\"ar\":{\"name\":\"\\u0623\\u062f\\u062e\\u0644 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a\"},\"es\":{\"name\":\"Ingrese el monto\"},\"fr\":{\"name\":\"Ingrese el monto\"},\"hi\":{\"name\":\"\\u0930\\u093e\\u0936\\u093f \\u0921\\u093e\\u0932\\u0947\\u0902\"}},\"id\":\"67249cd59b605\"},\"67249cdb11e84\":{\"language\":{\"en\":{\"name\":\"Specify the amount you wish to withdraw from your QRPayPro account.\"},\"ar\":{\"name\":\"\\u062d\\u062f\\u062f \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0630\\u064a \\u062a\\u0631\\u063a\\u0628 \\u0641\\u064a \\u0633\\u062d\\u0628\\u0647 \\u0645\\u0646 \\u062d\\u0633\\u0627\\u0628 QRPayPro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643.\"},\"es\":{\"name\":\"Especifique el monto que desea retirar de su cuenta QRPayPro.\"},\"fr\":{\"name\":\"Especifique el monto que desea retirar de su cuenta QRPayPro.\"},\"hi\":{\"name\":\"\\u0935\\u0939 \\u0930\\u093e\\u0936\\u093f \\u0928\\u093f\\u0930\\u094d\\u0926\\u093f\\u0937\\u094d\\u091f \\u0915\\u0930\\u0947\\u0902 \\u091c\\u093f\\u0938\\u0947 \\u0906\\u092a \\u0905\\u092a\\u0928\\u0947 QRPayPro \\u0916\\u093e\\u0924\\u0947 \\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u093e \\u091a\\u093e\\u0939\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"67249cdb11e84\"},\"67249ce09bf45\":{\"language\":{\"en\":{\"name\":\"Confirm the Withdrawal\"},\"ar\":{\"name\":\"\\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0627\\u0646\\u0633\\u062d\\u0627\\u0628\"},\"es\":{\"name\":\"Confirmar el retiro\"},\"fr\":{\"name\":\"Confirmar el retiro\"},\"hi\":{\"name\":\"\\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"67249ce09bf45\"}}}', 1, 1, '2024-11-01 15:17:59', '2024-12-12 18:39:20');
INSERT INTO `frontend_header_section_pages` VALUES (14, 14, 'personal', '{\"images\":{\"section_image\":\"aa013ae0-d785-4156-9650-8f92ea480df9.webp\",\"step_image\":\"cc5b11d0-c369-4360-87f3-663874a7ee96.webp\"},\"language\":{\"en\":{\"heading\":\"Enjoy Safe Online Shopping with QRPay Pro Virtual Cards\",\"sub_heading\":\"With QRPay Pro\'s virtual card feature, you can make online purchases without revealing your actual credit card details. Generate a virtual card in seconds and use it for all your online transactions with confidence, knowing that your financial information is protected.\",\"process_step_title\":\"Generate Your Virtual Card in 3 Simple Steps\",\"button_name\":\"Create a Virtual Card Now\",\"button_link\":\"user\\/strowallet-virtual-card\",\"step_title\":\"How to Create and Use Your QRPay Pro Virtual Card\",\"step_sub_title\":\"Follow these easy steps to set up your virtual card for secure online payments.\"},\"es\":{\"heading\":\"Disfrute de compras seguras en l\\u00ednea con las tarjetas virtuales QRPay Pro\",\"sub_heading\":\"Con la funci\\u00f3n de tarjeta virtual de QRPay Pro, puede realizar compras en l\\u00ednea sin revelar los datos reales de su tarjeta de cr\\u00e9dito. Genera una tarjeta virtual en segundos y \\u00fasala para todas tus transacciones en l\\u00ednea con confianza, sabiendo que tu informaci\\u00f3n financiera est\\u00e1 protegida.\",\"process_step_title\":\"Genera tu tarjeta virtual en 3 sencillos pasos\",\"button_name\":\"Crea una tarjeta virtual ahora\",\"button_link\":\"user\\/strowallet-virtual-card\",\"step_title\":\"C\\u00f3mo crear y utilizar su tarjeta virtual QRPay Pro\",\"step_sub_title\":\"Siga estos sencillos pasos para configurar su tarjeta virtual para pagos seguros en l\\u00ednea.\"},\"ar\":{\"heading\":\"\\u0627\\u0633\\u062a\\u0645\\u062a\\u0639 \\u0628\\u0627\\u0644\\u062a\\u0633\\u0648\\u0642 \\u0627\\u0644\\u0622\\u0645\\u0646 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0625\\u0646\\u062a\\u0631\\u0646\\u062a \\u0645\\u0639 \\u0628\\u0637\\u0627\\u0642\\u0627\\u062a QRPay Pro \\u0627\\u0644\\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629\",\"sub_heading\":\"\\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0645\\u064a\\u0632\\u0629 \\u0627\\u0644\\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0640 QRPay Pro\\u060c \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0625\\u062c\\u0631\\u0627\\u0621 \\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0634\\u0631\\u0627\\u0621 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0625\\u0646\\u062a\\u0631\\u0646\\u062a \\u062f\\u0648\\u0646 \\u0627\\u0644\\u0643\\u0634\\u0641 \\u0639\\u0646 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0628\\u0637\\u0627\\u0642\\u062a\\u0643 \\u0627\\u0644\\u0627\\u0626\\u062a\\u0645\\u0627\\u0646\\u064a\\u0629 \\u0627\\u0644\\u0641\\u0639\\u0644\\u064a\\u0629. \\u0623\\u0646\\u0634\\u0626 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629 \\u0641\\u064a \\u062b\\u0648\\u0627\\u0646\\u064d \\u0648\\u0627\\u0633\\u062a\\u062e\\u062f\\u0645\\u0647\\u0627 \\u0641\\u064a \\u062c\\u0645\\u064a\\u0639 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u0643 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0625\\u0646\\u062a\\u0631\\u0646\\u062a \\u0628\\u0643\\u0644 \\u062b\\u0642\\u0629\\u060c \\u0645\\u0639 \\u0627\\u0644\\u0639\\u0644\\u0645 \\u0623\\u0646 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a\\u0643 \\u0627\\u0644\\u0645\\u0627\\u0644\\u064a\\u0629 \\u0645\\u062d\\u0645\\u064a\\u0629.\",\"process_step_title\":\"\\u0642\\u0645 \\u0628\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0628\\u0637\\u0627\\u0642\\u062a\\u0643 \\u0627\\u0644\\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629 \\u0641\\u064a 3 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0628\\u0633\\u064a\\u0637\\u0629\",\"button_name\":\"\\u0623\\u0646\\u0634\\u0626 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629 \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"user\\/strowallet-virtual-card\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0648\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0628\\u0637\\u0627\\u0642\\u0629 QRPay Pro \\u0627\\u0644\\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0633\\u0647\\u0644\\u0629 \\u0644\\u0625\\u0639\\u062f\\u0627\\u062f \\u0628\\u0637\\u0627\\u0642\\u062a\\u0643 \\u0627\\u0644\\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629 \\u0644\\u0625\\u062c\\u0631\\u0627\\u0621 \\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u062f\\u0641\\u0639 \\u0622\\u0645\\u0646\\u0629 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0625\\u0646\\u062a\\u0631\\u0646\\u062a.\"},\"fr\":{\"heading\":\"Disfrute de compras seguras en l\\u00ednea con las tarjetas virtuales QRPay Pro\",\"sub_heading\":\"Avec la fonctionnalit\\u00e9 de carte virtuelle de QRPay Pro, vous pouvez effectuer des achats en ligne sans r\\u00e9v\\u00e9ler les d\\u00e9tails r\\u00e9els de votre carte de cr\\u00e9dit. G\\u00e9n\\u00e9rez une carte virtuelle en quelques secondes et utilisez-la pour toutes vos transactions en ligne en toute confiance, sachant que vos informations financi\\u00e8res sont prot\\u00e9g\\u00e9es.\",\"process_step_title\":\"G\\u00e9n\\u00e9rez votre carte virtuelle en 3 \\u00e9tapes simples\",\"button_name\":\"Cr\\u00e9ez une carte virtuelle maintenant\",\"button_link\":\"user\\/strowallet-virtual-card\",\"step_title\":\"Comment cr\\u00e9er et utiliser votre carte virtuelle QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes simples pour configurer votre carte virtuelle pour des paiements en ligne s\\u00e9curis\\u00e9s.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0911\\u0928\\u0932\\u093e\\u0907\\u0928 \\u0936\\u0949\\u092a\\u093f\\u0902\\u0917 \\u0915\\u093e \\u0906\\u0928\\u0902\\u0926 \\u0932\\u0947\\u0902\",\"sub_heading\":\"QRPay Pro \\u0915\\u0940 \\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0915\\u0947 \\u0938\\u093e\\u0925, \\u0906\\u092a \\u0905\\u092a\\u0928\\u0947 \\u0935\\u093e\\u0938\\u094d\\u0924\\u0935\\u093f\\u0915 \\u0915\\u094d\\u0930\\u0947\\u0921\\u093f\\u091f \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0915\\u093e \\u0916\\u0941\\u0932\\u093e\\u0938\\u093e \\u0915\\u093f\\u090f \\u092c\\u093f\\u0928\\u093e \\u0911\\u0928\\u0932\\u093e\\u0907\\u0928 \\u0916\\u0930\\u0940\\u0926\\u093e\\u0930\\u0940 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0915\\u0941\\u091b \\u0939\\u0940 \\u0938\\u0947\\u0915\\u0902\\u0921 \\u092e\\u0947\\u0902 \\u090f\\u0915 \\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u092c\\u0928\\u093e\\u090f\\u0902 \\u0914\\u0930 \\u0906\\u0924\\u094d\\u092e\\u0935\\u093f\\u0936\\u094d\\u0935\\u093e\\u0938 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0905\\u092a\\u0928\\u0947 \\u0938\\u092d\\u0940 \\u0911\\u0928\\u0932\\u093e\\u0907\\u0928 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0938\\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0947\\u0902, \\u092f\\u0939 \\u091c\\u093e\\u0928\\u0924\\u0947 \\u0939\\u0941\\u090f \\u0915\\u093f \\u0906\\u092a\\u0915\\u0940 \\u0935\\u093f\\u0924\\u094d\\u0924\\u0940\\u092f \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0939\\u0948\\u0964\",\"process_ste