ar\":{\"name\":\"\\u0627\\u0636\\u0628\\u0637 \\u062a\\u0641\\u0636\\u064a\\u0644\\u0627\\u062a\\u0643\"},\"es\":{\"name\":\"Establece tus preferencias\"},\"fr\":{\"name\":\"Establece tus preferencias\"},\"hi\":{\"name\":\"\\u0905\\u092a\\u0928\\u0940 \\u092a\\u094d\\u0930\\u093e\\u0925\\u092e\\u093f\\u0915\\u0924\\u093e\\u090f\\u0901 \\u0928\\u093f\\u0930\\u094d\\u0927\\u093e\\u0930\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"67249dc95f68e\"},\"67249dcebbeee\":{\"language\":{\"en\":{\"name\":\"Use Your Card for Online Purchases\"},\"ar\":{\"name\":\"\\u0627\\u0633\\u062a\\u062e\\u062f\\u0645 \\u0628\\u0637\\u0627\\u0642\\u062a\\u0643 \\u0644\\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0627\\u0644\\u0634\\u0631\\u0627\\u0621 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0625\\u0646\\u062a\\u0631\\u0646\\u062a\"},\"es\":{\"name\":\"Utilice su tarjeta para compras en l\\u00ednea\"},\"fr\":{\"name\":\"Utilice su tarjeta para compras en l\\u00ednea\"},\"hi\":{\"name\":\"\\u0911\\u0928\\u0932\\u093e\\u0907\\u0928 \\u0916\\u0930\\u0940\\u0926\\u093e\\u0930\\u0940 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u0947 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"67249dcebbeee\"}}}', 1, 1, '2024-11-01 15:22:02', '2024-12-12 18:39:41');
INSERT INTO `frontend_header_section_pages` VALUES (15, 15, 'personal', '{\"images\":{\"section_image\":\"eadf7d55-b05f-41ac-8b81-6e17f8e509f3.webp\",\"step_image\":\"920a0609-3cd4-447e-87c3-1e31398fd448.webp\"},\"language\":{\"en\":{\"heading\":\"Send Joy with QRPay Pro Gift Cards\",\"sub_heading\":\"QRPay Pro allows you to purchase and send digital gift cards for a variety of services, making gifting easy and thoughtful. Whether it\'s for a birthday, holiday, or just because, our gift cards are the perfect way to show you care. Enjoy a seamless buying experience and share happiness with friends and family.\",\"process_step_title\":\"Buy a Gift Card in 3 Simple Steps\",\"button_name\":\"Get Your Gift Card Now\",\"button_link\":\"user\\/gift-card\",\"step_title\":\"How to Purchase and Send a Gift Card\",\"step_sub_title\":\"Follow these simple steps to easily purchase and send a gift card through QRPay Pro.\"},\"es\":{\"heading\":\"Env\\u00eda alegr\\u00eda con tarjetas de regalo QRPay Pro\",\"sub_heading\":\"QRPay Pro le permite comprar y enviar tarjetas de regalo digitales para una variedad de servicios, lo que hace que regalar sea f\\u00e1cil y reflexivo. Ya sea para un cumplea\\u00f1os, un d\\u00eda festivo o simplemente porque s\\u00ed, nuestras tarjetas de regalo son la manera perfecta de demostrar que te preocupas. Disfrute de una experiencia de compra perfecta y comparta la felicidad con amigos y familiares.\",\"process_step_title\":\"Compra una tarjeta regalo en 3 sencillos pasos\",\"button_name\":\"Obtenga su tarjeta de regalo ahora\",\"button_link\":\"user\\/gift-card\",\"step_title\":\"C\\u00f3mo comprar y enviar una tarjeta de regalo\",\"step_sub_title\":\"Siga estos sencillos pasos para comprar y enviar f\\u00e1cilmente una tarjeta de regalo a trav\\u00e9s de QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0623\\u0631\\u0633\\u0644 \\u0627\\u0644\\u0641\\u0631\\u062d \\u0645\\u0639 \\u0628\\u0637\\u0627\\u0642\\u0627\\u062a \\u0647\\u062f\\u0627\\u064a\\u0627 QRPay Pro\",\"sub_heading\":\"\\u064a\\u062a\\u064a\\u062d \\u0644\\u0643 QRPay Pro \\u0634\\u0631\\u0627\\u0621 \\u0648\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0628\\u0637\\u0627\\u0642\\u0627\\u062a \\u0627\\u0644\\u0647\\u062f\\u0627\\u064a\\u0627 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a\\u0629 \\u0644\\u0645\\u062c\\u0645\\u0648\\u0639\\u0629 \\u0645\\u062a\\u0646\\u0648\\u0639\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u062e\\u062f\\u0645\\u0627\\u062a\\u060c \\u0645\\u0645\\u0627 \\u064a\\u062c\\u0639\\u0644 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u062a\\u0642\\u062f\\u064a\\u0645 \\u0627\\u0644\\u0647\\u062f\\u0627\\u064a\\u0627 \\u0633\\u0647\\u0644\\u0629 \\u0648\\u0645\\u062f\\u0631\\u0648\\u0633\\u0629. \\u0633\\u0648\\u0627\\u0621 \\u0643\\u0627\\u0646 \\u0630\\u0644\\u0643 \\u0644\\u0639\\u064a\\u062f \\u0645\\u064a\\u0644\\u0627\\u062f\\u060c \\u0623\\u0648 \\u0639\\u0637\\u0644\\u0629\\u060c \\u0623\\u0648 \\u0644\\u0645\\u062c\\u0631\\u062f \\u0630\\u0644\\u0643\\u060c \\u0641\\u0625\\u0646 \\u0628\\u0637\\u0627\\u0642\\u0627\\u062a \\u0627\\u0644\\u0647\\u062f\\u0627\\u064a\\u0627 \\u0644\\u062f\\u064a\\u0646\\u0627 \\u0647\\u064a \\u0627\\u0644\\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u0645\\u062b\\u0627\\u0644\\u064a\\u0629 \\u0644\\u0625\\u0638\\u0647\\u0627\\u0631 \\u0627\\u0647\\u062a\\u0645\\u0627\\u0645\\u0643. \\u0627\\u0633\\u062a\\u0645\\u062a\\u0639 \\u0628\\u062a\\u062c\\u0631\\u0628\\u0629 \\u0634\\u0631\\u0627\\u0621 \\u0633\\u0644\\u0633\\u0629 \\u0648\\u0634\\u0627\\u0631\\u0643 \\u0627\\u0644\\u0633\\u0639\\u0627\\u062f\\u0629 \\u0645\\u0639 \\u0627\\u0644\\u0623\\u0635\\u062f\\u0642\\u0627\\u0621 \\u0648\\u0627\\u0644\\u0639\\u0627\\u0626\\u0644\\u0629.\",\"process_step_title\":\"\\u0642\\u0645 \\u0628\\u0634\\u0631\\u0627\\u0621 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0647\\u062f\\u0627\\u064a\\u0627 \\u0641\\u064a 3 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0628\\u0633\\u064a\\u0637\\u0629\",\"button_name\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0647\\u062f\\u0627\\u064a\\u0627 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643 \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"user\\/gift-card\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u0634\\u0631\\u0627\\u0621 \\u0648\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0647\\u062f\\u064a\\u0629\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0628\\u0633\\u064a\\u0637\\u0629 \\u0644\\u0634\\u0631\\u0627\\u0621 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0647\\u062f\\u0627\\u064a\\u0627 \\u0648\\u0625\\u0631\\u0633\\u0627\\u0644\\u0647\\u0627 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 QRPay Pro.\"},\"fr\":{\"heading\":\"Env\\u00eda alegr\\u00eda con tarjetas de regalo QRPay Pro\",\"sub_heading\":\"QRPay Pro vous permet d\'acheter et d\'envoyer des cartes-cadeaux num\\u00e9riques pour une vari\\u00e9t\\u00e9 de services, rendant les cadeaux faciles et r\\u00e9fl\\u00e9chis. Que ce soit pour un anniversaire, des vacances ou tout simplement parce que nos cartes cadeaux sont le moyen id\\u00e9al de montrer votre attention. Profitez d\'une exp\\u00e9rience d\'achat fluide et partagez votre bonheur avec vos amis et votre famille.\",\"process_step_title\":\"Achetez une carte-cadeau en 3 \\u00e9tapes simples\",\"button_name\":\"Obtenez votre carte-cadeau maintenant\",\"button_link\":\"user\\/gift-card\",\"step_title\":\"Comment acheter et envoyer une carte-cadeau\",\"step_sub_title\":\"Suivez ces \\u00e9tapes simples pour acheter et envoyer facilement une carte-cadeau via QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0916\\u0941\\u0936\\u0940 \\u092d\\u0947\\u091c\\u0947\\u0902\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0906\\u092a\\u0915\\u094b \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u0938\\u0947\\u0935\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0921\\u093f\\u091c\\u093f\\u091f\\u0932 \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0916\\u0930\\u0940\\u0926\\u0928\\u0947 \\u0914\\u0930 \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0940 \\u0905\\u0928\\u0941\\u092e\\u0924\\u093f \\u0926\\u0947\\u0924\\u093e \\u0939\\u0948, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0926\\u0947\\u0928\\u093e \\u0906\\u0938\\u093e\\u0928 \\u0914\\u0930 \\u0935\\u093f\\u091a\\u093e\\u0930\\u0936\\u0940\\u0932 \\u0939\\u094b \\u091c\\u093e\\u0924\\u093e \\u0939\\u0948\\u0964 \\u091a\\u093e\\u0939\\u0947 \\u0935\\u0939 \\u091c\\u0928\\u094d\\u092e\\u0926\\u093f\\u0928 \\u0939\\u094b, \\u091b\\u0941\\u091f\\u094d\\u091f\\u0940 \\u0939\\u094b \\u092f\\u093e \\u0938\\u093f\\u0930\\u094d\\u092b \\u0907\\u0938\\u0932\\u093f\\u090f, \\u0939\\u092e\\u093e\\u0930\\u0947 \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0906\\u092a\\u0915\\u0940 \\u092a\\u0930\\u0935\\u093e\\u0939 \\u0926\\u093f\\u0916\\u093e\\u0928\\u0947 \\u0915\\u093e \\u0938\\u0939\\u0940 \\u0924\\u0930\\u0940\\u0915\\u093e \\u0939\\u0948\\u0902\\u0964 \\u090f\\u0915 \\u0938\\u0939\\u091c \\u0916\\u0930\\u0940\\u0926\\u093e\\u0930\\u0940 \\u0905\\u0928\\u0941\\u092d\\u0935 \\u0915\\u093e \\u0906\\u0928\\u0902\\u0926 \\u0932\\u0947\\u0902 \\u0914\\u0930 \\u0926\\u094b\\u0938\\u094d\\u0924\\u094b\\u0902 \\u0914\\u0930 \\u092a\\u0930\\u093f\\u0935\\u093e\\u0930 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0916\\u0941\\u0936\\u093f\\u092f\\u093e\\u0901 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930\\u0947\\u0902\\u0964\",\"process_step_title\":\"3 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0916\\u0930\\u0940\\u0926\\u0947\\u0902\",\"button_name\":\"\\u0905\\u092d\\u0940 \\u0905\\u092a\\u0928\\u093e \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\",\"button_link\":\"user\\/gift-card\",\"step_title\":\"\\u0917\\u093f\\u092b\\u094d\\u091f \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0915\\u0948\\u0938\\u0947 \\u0916\\u0930\\u0940\\u0926\\u0947\\u0902 \\u0914\\u0930 \\u092d\\u0947\\u091c\\u0947\\u0902\",\"step_sub_title\":\"QRPay Pro \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0916\\u0930\\u0940\\u0926\\u0928\\u0947 \\u0914\\u0930 \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0928 \\u0938\\u0930\\u0932 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"67249e922ec29\":{\"language\":{\"en\":{\"name\":\"Choose Your Gift Card\"},\"ar\":{\"name\":\"\\u0627\\u062e\\u062a\\u0631 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0647\\u062f\\u0627\\u064a\\u0627 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643\"},\"es\":{\"name\":\"Elija su tarjeta de regalo\"},\"fr\":{\"name\":\"Choisissez votre carte cadeau\"},\"hi\":{\"name\":\"\\u0905\\u092a\\u0928\\u093e \\u0909\\u092a\\u0939\\u093e\\u0930 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u091a\\u0941\\u0928\\u0947\\u0902\"}},\"id\":\"67249e922ec29\"},\"67249e982d41b\":{\"language\":{\"en\":{\"name\":\"Enter Recipient Details\"},\"ar\":{\"name\":\"\\u0623\\u062f\\u062e\\u0644 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645\"},\"es\":{\"name\":\"Ingrese los detalles del destinatario\"},\"fr\":{\"name\":\"Saisir les d\\u00e9tails du destinataire\"},\"hi\":{\"name\":\"\\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"67249e982d41b\"},\"67249e9da134d\":{\"language\":{\"en\":{\"name\":\"Make Payment and Send\"},\"ar\":{\"name\":\"\\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0648\\u0625\\u0631\\u0633\\u0627\\u0644\"},\"es\":{\"name\":\"Realizar pago y enviar\"},\"fr\":{\"name\":\"Effectuer le paiement et envoyer\"},\"hi\":{\"name\":\"\\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u092d\\u0947\\u091c\\u0947\\u0902\"}},\"id\":\"67249e9da134d\"}}}', 1, 1, '2024-11-01 15:25:17', '2024-12-12 18:43:25');
INSERT INTO `frontend_header_section_pages` VALUES (16, 16, 'personal', '{\"images\":{\"section_image\":\"ed226f28-df2f-43f7-bb02-c7f3061d0b0a.webp\",\"step_image\":\"c4427edf-10ae-41f2-8ec6-0b5de01939c1.webp\"},\"language\":{\"en\":{\"heading\":\"Simplify Your Bill Payments with QRPay Pro\",\"sub_heading\":\"With QRPay Pro\\u2019s Bill Pay feature, managing and paying your utility and service bills has never been easier. Eliminate the hassle of manual payments and enjoy the convenience of paying your bills directly from your QRPay Pro account, all while ensuring your transactions are secure and efficient.\",\"process_step_title\":\"Pay Your Bills in 3 Easy Steps\",\"button_name\":\"Start Paying Bills Now\",\"button_link\":\"user\\/bill-pay\",\"step_title\":\"How to Pay Your Bills Using QRPay Pro\",\"step_sub_title\":\"Follow these simple steps to effortlessly pay your bills through your QRPay Pro account.\"},\"es\":{\"heading\":\"Simplifique sus pagos de facturas con QRPay Pro\",\"sub_heading\":\"Con la funci\\u00f3n Bill Pay de QRPay Pro, administrar y pagar sus facturas de servicios p\\u00fablicos nunca ha sido tan f\\u00e1cil. Elimine la molestia de los pagos manuales y disfrute de la conveniencia de pagar sus facturas directamente desde su cuenta QRPay Pro, mientras garantiza que sus transacciones sean seguras y eficientes.\",\"process_step_title\":\"Pague sus facturas en 3 sencillos pasos\",\"button_name\":\"Comience a pagar facturas ahora\",\"button_link\":\"user\\/bill-pay\",\"step_title\":\"C\\u00f3mo pagar sus facturas con QRPay Pro\",\"step_sub_title\":\"Siga estos sencillos pasos para pagar sus facturas sin esfuerzo a trav\\u00e9s de su cuenta QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0642\\u0645 \\u0628\\u062a\\u0628\\u0633\\u064a\\u0637 \\u062f\\u0641\\u0639\\u0627\\u062a \\u0641\\u0627\\u062a\\u0648\\u0631\\u062a\\u0643 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\",\"sub_heading\":\"\\u0645\\u0639 \\u0645\\u064a\\u0632\\u0629 \\u062f\\u0641\\u0639 \\u0627\\u0644\\u0641\\u0648\\u0627\\u062a\\u064a\\u0631 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0640 QRPay Pro\\u060c \\u0623\\u0635\\u0628\\u062d\\u062a \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0648\\u062f\\u0641\\u0639 \\u0641\\u0648\\u0627\\u062a\\u064a\\u0631 \\u0627\\u0644\\u0645\\u0631\\u0627\\u0641\\u0642 \\u0648\\u0627\\u0644\\u062e\\u062f\\u0645\\u0627\\u062a \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643 \\u0623\\u0633\\u0647\\u0644 \\u0645\\u0646 \\u0623\\u064a \\u0648\\u0642\\u062a \\u0645\\u0636\\u0649. \\u062a\\u062e\\u0644\\u0635 \\u0645\\u0646 \\u0645\\u062a\\u0627\\u0639\\u0628 \\u0627\\u0644\\u062f\\u0641\\u0639\\u0627\\u062a \\u0627\\u0644\\u064a\\u062f\\u0648\\u064a\\u0629 \\u0648\\u0627\\u0633\\u062a\\u0645\\u062a\\u0639 \\u0628\\u0631\\u0627\\u062d\\u0629 \\u062f\\u0641\\u0639 \\u0641\\u0648\\u0627\\u062a\\u064a\\u0631\\u0643 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0645\\u0646 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\\u060c \\u0643\\u0644 \\u0630\\u0644\\u0643 \\u0645\\u0639 \\u0636\\u0645\\u0627\\u0646 \\u0623\\u0646 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u0643 \\u0622\\u0645\\u0646\\u0629 \\u0648\\u0641\\u0639\\u0627\\u0644\\u0629.\",\"process_step_title\":\"\\u0627\\u062f\\u0641\\u0639 \\u0641\\u0648\\u0627\\u062a\\u064a\\u0631\\u0643 \\u0641\\u064a 3 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0633\\u0647\\u0644\\u0629\",\"button_name\":\"\\u0627\\u0628\\u062f\\u0623 \\u0628\\u062f\\u0641\\u0639 \\u0627\\u0644\\u0641\\u0648\\u0627\\u062a\\u064a\\u0631 \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"user\\/bill-pay\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u062f\\u0641\\u0639 \\u0641\\u0648\\u0627\\u062a\\u064a\\u0631\\u0643 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0628\\u0633\\u064a\\u0637\\u0629 \\u0644\\u062f\\u0641\\u0639 \\u0641\\u0648\\u0627\\u062a\\u064a\\u0631\\u0643 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643.\"},\"fr\":{\"heading\":\"Simplifique sus pagos de facturas con QRPay Pro\",\"sub_heading\":\"Avec la fonction Bill Pay de QRPay Pro, g\\u00e9rer et payer vos factures de services publics et de services n\'a jamais \\u00e9t\\u00e9 aussi simple. \\u00c9liminez les tracas des paiements manuels et profitez de la commodit\\u00e9 de payer vos factures directement depuis votre compte QRPay Pro, tout en garantissant que vos transactions sont s\\u00e9curis\\u00e9es et efficaces.\",\"process_step_title\":\"Payez vos factures en 3 \\u00e9tapes faciles\",\"button_name\":\"Commencez \\u00e0 payer vos factures maintenant\",\"button_link\":\"user\\/bill-pay\",\"step_title\":\"Comment payer vos factures avec QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes simples pour payer vos factures sans effort via votre compte QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0905\\u092a\\u0928\\u0947 \\u092c\\u093f\\u0932 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u094b \\u0938\\u0930\\u0932 \\u092c\\u0928\\u093e\\u090f\\u0902\",\"sub_heading\":\"QRPay Pro \\u0915\\u0947 \\u092c\\u093f\\u0932 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0915\\u0947 \\u0938\\u093e\\u0925, \\u0905\\u092a\\u0928\\u0940 \\u0909\\u092a\\u092f\\u094b\\u0917\\u093f\\u0924\\u093e \\u0914\\u0930 \\u0938\\u0947\\u0935\\u093e \\u092c\\u093f\\u0932\\u094b\\u0902 \\u0915\\u093e \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u0928 \\u0914\\u0930 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0928\\u093e \\u0907\\u0924\\u0928\\u093e \\u0906\\u0938\\u093e\\u0928 \\u0915\\u092d\\u0940 \\u0928\\u0939\\u0940\\u0902 \\u0930\\u0939\\u093e\\u0964 \\u092e\\u0948\\u0928\\u094d\\u092f\\u0941\\u0905\\u0932 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0940 \\u092a\\u0930\\u0947\\u0936\\u093e\\u0928\\u0940 \\u0915\\u094b \\u0926\\u0942\\u0930 \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u0905\\u092a\\u0928\\u0947 \\u092c\\u093f\\u0932\\u094b\\u0902 \\u0915\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u0940\\u0927\\u0947 \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u0938\\u0947 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0940 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0915\\u093e \\u0906\\u0928\\u0902\\u0926 \\u0932\\u0947\\u0902, \\u092f\\u0939 \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0941\\u090f \\u0915\\u093f \\u0906\\u092a\\u0915\\u093e \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0914\\u0930 \\u0915\\u0941\\u0936\\u0932 \\u0939\\u0948\\u0964\",\"process_step_title\":\"3 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u092c\\u093f\\u0932\\u094b\\u0902 \\u0915\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0947\\u0902\",\"button_name\":\"\\u0905\\u092d\\u0940 \\u092c\\u093f\\u0932\\u094b\\u0902 \\u0915\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0936\\u0941\\u0930\\u0942 \\u0915\\u0930\\u0947\\u0902\",\"button_link\":\"user\\/bill-pay\",\"step_title\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u0905\\u092a\\u0928\\u0947 \\u092c\\u093f\\u0932\\u094b\\u0902 \\u0915\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0948\\u0938\\u0947 \\u0915\\u0930\\u0947\\u0902\",\"step_sub_title\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u0915\\u0947 \\u092e\\u093e\\u092