INSERT INTO `frontend_header_section_pages` VALUES (17, 17, 'personal', '{\"images\":{\"section_image\":\"6431b748-6918-4b7b-8bdd-43bc09d87835.webp\",\"step_image\":\"6e5c537e-af0f-4258-9b5d-748c9c1178e4.webp\"},\"language\":{\"en\":{\"heading\":\"Recharge Your Mobile Account Effortlessly with QRPay Pro\",\"sub_heading\":\"With QRPay Pro\\u2019s Mobile Top-Up feature, keeping your mobile phone topped up is quick and hassle-free. Whether you need to add credit for yourself or someone else, QRPay Pro allows you to recharge mobile accounts instantly, all while ensuring secure transactions.\",\"process_step_title\":\"Top Up Your Mobile in 3 Simple Steps\",\"button_name\":\"Start Top-Up Now\",\"button_link\":\"user\\/mobile-topup\",\"step_title\":\"How to Recharge Your Mobile Phone with QRPay Pro\",\"step_sub_title\":\"Follow these easy steps to top up your mobile account directly from your QRPay Pro wallet.\"},\"es\":{\"heading\":\"Recargue su cuenta m\\u00f3vil sin esfuerzo con QRPay Pro\",\"sub_heading\":\"Con la funci\\u00f3n de recarga m\\u00f3vil de QRPay Pro, mantener tu tel\\u00e9fono m\\u00f3vil recargado es r\\u00e1pido y sin complicaciones. Ya sea que necesite agregar cr\\u00e9dito para usted o para otra persona, QRPay Pro le permite recargar cuentas m\\u00f3viles al instante, garantizando al mismo tiempo transacciones seguras.\",\"process_step_title\":\"Recarga tu m\\u00f3vil en 3 sencillos pasos\",\"button_name\":\"Comience a recargar ahora\",\"button_link\":\"user\\/mobile-topup\",\"step_title\":\"C\\u00f3mo recargar tu tel\\u00e9fono m\\u00f3vil con QRPay Pro\",\"step_sub_title\":\"Siga estos sencillos pasos para recargar su cuenta m\\u00f3vil directamente desde su billetera QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0642\\u0645 \\u0628\\u0625\\u0639\\u0627\\u062f\\u0629 \\u0634\\u062d\\u0646 \\u062d\\u0633\\u0627\\u0628 \\u0647\\u0627\\u062a\\u0641\\u0643 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0645\\u0639 QRPay Pro\",\"sub_heading\":\"\\u0645\\u0639 \\u0645\\u064a\\u0632\\u0629 \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0641\\u064a QRPay Pro\\u060c \\u0623\\u0635\\u0628\\u062d \\u0627\\u0644\\u062d\\u0641\\u0627\\u0638 \\u0639\\u0644\\u0649 \\u0631\\u0635\\u064a\\u062f \\u0647\\u0627\\u062a\\u0641\\u0643 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0633\\u0631\\u064a\\u0639\\u064b\\u0627 \\u0648\\u062e\\u0627\\u0644\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u062a\\u0627\\u0639\\u0628. \\u0633\\u0648\\u0627\\u0621 \\u0643\\u0646\\u062a \\u0628\\u062d\\u0627\\u062c\\u0629 \\u0625\\u0644\\u0649 \\u0625\\u0636\\u0627\\u0641\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0644\\u0646\\u0641\\u0633\\u0643 \\u0623\\u0648 \\u0644\\u0634\\u062e\\u0635 \\u0622\\u062e\\u0631\\u060c \\u0641\\u0625\\u0646 QRPay Pro \\u064a\\u0633\\u0645\\u062d \\u0644\\u0643 \\u0628\\u0625\\u0639\\u0627\\u062f\\u0629 \\u0634\\u062d\\u0646 \\u062d\\u0633\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631\\u060c \\u0643\\u0644 \\u0630\\u0644\\u0643 \\u0645\\u0639 \\u0636\\u0645\\u0627\\u0646 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0622\\u0645\\u0646\\u0629.\",\"process_step_title\":\"\\u0642\\u0645 \\u0628\\u062a\\u0639\\u0628\\u0626\\u0629 \\u0647\\u0627\\u062a\\u0641\\u0643 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0641\\u064a 3 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0628\\u0633\\u064a\\u0637\\u0629\",\"button_name\":\"\\u0627\\u0628\\u062f\\u0623 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0627\\u0644\\u0631\\u0635\\u064a\\u062f \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"user\\/mobile-topup\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u0625\\u0639\\u0627\\u062f\\u0629 \\u0634\\u062d\\u0646 \\u0647\\u0627\\u062a\\u0641\\u0643 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0633\\u0647\\u0644\\u0629 \\u0644\\u062a\\u0639\\u0628\\u0626\\u0629 \\u062d\\u0633\\u0627\\u0628 \\u0647\\u0627\\u062a\\u0641\\u0643 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0645\\u0646 \\u0645\\u062d\\u0641\\u0638\\u0629 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643.\"},\"fr\":{\"heading\":\"Rechargez votre compte mobile sans effort avec QRPay Pro\",\"sub_heading\":\"Avec la fonction de recharge mobile de QRPay Pro, garder votre t\\u00e9l\\u00e9phone mobile recharg\\u00e9 est rapide et sans tracas. Que vous ayez besoin d\'ajouter du cr\\u00e9dit pour vous-m\\u00eame ou pour quelqu\'un d\'autre, QRPay Pro vous permet de recharger instantan\\u00e9ment vos comptes mobiles, tout en garantissant des transactions s\\u00e9curis\\u00e9es.\",\"process_step_title\":\"Rechargez votre mobile en 3 \\u00e9tapes simples\",\"button_name\":\"Commencez la recharge maintenant\",\"button_link\":\"user\\/mobile-topup\",\"step_title\":\"Comment recharger votre t\\u00e9l\\u00e9phone mobile avec QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes simples pour recharger votre compte mobile directement depuis votre portefeuille QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0905\\u092a\\u0928\\u0947 \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u0916\\u093e\\u0924\\u0947 \\u0915\\u094b \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0930\\u093f\\u091a\\u093e\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902\",\"sub_heading\":\"QRPay Pro \\u0915\\u0940 \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u09