INSERT INTO `frontend_header_section_pages` VALUES (18, 18, 'business', '{\"images\":{\"section_image\":\"24e78c49-c6c0-4d43-9ec9-74ef2f151a31.webp\",\"step_image\":\"5de7d9f1-5ed8-45b0-826d-09a921a35a2d.webp\"},\"language\":{\"en\":{\"heading\":\"Receive Payments Instantly with QRPay Pro\\u2019s QR Code Technology\",\"sub_heading\":\"With QRPay Pro, receiving payments is simple and reliable. Each merchant account comes with a unique, permanent QR Code, allowing you to accept payments anytime without needing to generate new codes. This secure and contactless payment method supports multiple currencies, making global transactions convenient and efficient.\",\"process_step_title\":\"Start Receiving Money in 3 Simple Steps\",\"button_name\":\"Start Receiving Payments\",\"button_link\":\"merchant\\/receive-money\",\"step_title\":\"How to Receive Money with Your QRPay Pro QR Code\",\"step_sub_title\":\"Follow these steps to seamlessly receive payments using your dedicated QR Code.\"},\"es\":{\"heading\":\"Reciba pagos al instante con la tecnolog\\u00eda de c\\u00f3digo QR de QRPay Pro\",\"sub_heading\":\"Con QRPay Pro, recibir pagos es sencillo y confiable. Cada cuenta de comerciante viene con un c\\u00f3digo QR \\u00fanico y permanente, que le permite aceptar pagos en cualquier momento sin necesidad de generar nuevos c\\u00f3digos. Este m\\u00e9todo de pago seguro y sin contacto admite m\\u00faltiples monedas, lo que hace que las transacciones globales sean convenientes y eficientes.\",\"process_step_title\":\"Comience a recibir dinero en 3 sencillos pasos\",\"button_name\":\"Comience a recibir pagos\",\"button_link\":\"merchant\\/receive-money\",\"step_title\":\"C\\u00f3mo recibir dinero con su c\\u00f3digo QR QRPay Pro\",\"step_sub_title\":\"Siga estos pasos para recibir pagos sin problemas utilizando su c\\u00f3digo QR exclusivo.\"},\"ar\":{\"heading\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u062a\\u0642\\u0646\\u064a\\u0629 QR Code \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0640 QRPay Pro\",\"sub_heading\":\"\\u0645\\u0639 QRPay Pro\\u060c \\u0623\\u0635\\u0628\\u062d \\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0623\\u0645\\u0631\\u064b\\u0627 \\u0628\\u0633\\u064a\\u0637\\u064b\\u0627 \\u0648\\u0645\\u0648\\u062b\\u0648\\u0642\\u064b\\u0627. \\u064a\\u0623\\u062a\\u064a \\u0643\\u0644 \\u062d\\u0633\\u0627\\u0628 \\u062a\\u0627\\u062c\\u0631 \\u0645\\u0632\\u0648\\u062f\\u064b\\u0627 \\u0628\\u0631\\u0645\\u0632 QR \\u0641\\u0631\\u064a\\u062f \\u0648\\u062f\\u0627\\u0626\\u0645\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0645\\u062d \\u0644\\u0643 \\u0628\\u0642\\u0628\\u0648\\u0644 \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0641\\u064a \\u0623\\u064a \\u0648\\u0642\\u062a \\u062f\\u0648\\u0646 \\u0627\\u0644\\u062d\\u0627\\u062c\\u0629 \\u0625\\u0644\\u0649 \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u0645\\u0648\\u0632 \\u062c\\u062f\\u064a\\u062f\\u0629. \\u062a\\u062f\\u0639\\u0645 \\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u0622\\u0645\\u0646\\u0629 \\u0648\\u063a\\u064a\\u0631 \\u0627\\u0644\\u062a\\u0644\\u0627\\u0645\\u0633\\u064a\\u0629 \\u0647\\u0630\\u0647 \\u0639\\u0645\\u0644\\u0627\\u062a \\u0645\\u062a\\u0639\\u062f\\u062f\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u062c\\u0639\\u0644 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645\\u064a\\u0629 \\u0645\\u0631\\u064a\\u062d\\u0629 \\u0648\\u0641\\u0639\\u0627\\u0644\\u0629.\",\"process_step_title\":\"\\u0627\\u0628\\u062f\\u0623 \\u0641\\u064a \\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a 3 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0628\\u0633\\u064a\\u0637\\u0629\",\"button_name\":\"\\u0627\\u0644\\u0628\\u062f\\u0621 \\u0641\\u064a \\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a\",\"button_link\":\"merchant\\/receive-money\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0631\\u0645\\u0632 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639\\u0629 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0644\\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0631\\u0645\\u0632 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639\\u0629 \\u0627\\u0644\\u0645\\u062e\\u0635\\u0635 \\u0644\\u062f\\u064a\\u0643.\"},\"fr\":{\"heading\":\"Recevez des paiements instantan\\u00e9ment avec la technologie QR Code de QRPay Pro\",\"sub_heading\":\"Avec QRPay Pro, recevoir des paiements est simple et fiable. Chaque compte marchand est livr\\u00e9 avec un code QR unique et permanent, vous permettant d\'accepter des paiements \\u00e0 tout moment sans avoir besoin de g\\u00e9n\\u00e9rer de nouveaux codes. Cette m\\u00e9thode de paiement s\\u00e9curis\\u00e9e et sans contact prend en charge plusieurs devises, rendant les transactions mondiales pratiques et efficaces.\",\"process_step_title\":\"Commencez \\u00e0 recevoir de l\'argent en 3 \\u00e9tapes simples\",\"button_name\":\"Commencez \\u00e0 recevoir des paiements\",\"button_link\":\"merchant\\/receive-money\",\"step_title\":\"Comment recevoir de l\'argent avec votre code QR QRPay Pro\",\"step_s