INSERT INTO `frontend_header_section_pages` VALUES (19, 19, 'business', '{\"images\":{\"section_image\":\"2c74bddb-a6bc-4941-ae0e-52cf45e854b1.webp\",\"step_image\":\"e9bab8c3-4846-408e-b891-cb574d508028.webp\"},\"language\":{\"en\":{\"heading\":\"Manage Multi-Currency Transactions with QRPay Pro\\u2019s Exchange Money Feature\",\"sub_heading\":\"QRPay Pro enables merchants to easily exchange currencies, ensuring smooth transactions with international customers. Stay updated with real-time exchange rates and enjoy a seamless process when converting funds in your account, allowing you to serve a global customer base efficiently.\",\"process_step_title\":\"Convert Currency in 3 Simple Steps\",\"button_name\":\"Start Exchanging Currency\",\"button_link\":\"merchant\\/money-exchange\",\"step_title\":\"How to Exchange Money in QRPay Pro\",\"step_sub_title\":\"Follow these steps to quickly and securely exchange money between currencies in your QRPay Pro account.\"},\"es\":{\"heading\":\"Administre transacciones en m\\u00faltiples divisas con la funci\\u00f3n Exchange Money de QRPay Pro\",\"sub_heading\":\"QRPay Pro permite a los comerciantes cambiar divisas f\\u00e1cilmente, garantizando transacciones fluidas con clientes internacionales. Mant\\u00e9ngase actualizado con los tipos de cambio en tiempo real y disfrute de un proceso fluido al convertir fondos en su cuenta, lo que le permitir\\u00e1 atender a una base de clientes global de manera eficiente.\",\"process_step_title\":\"Convierta moneda en 3 sencillos pasos\",\"button_name\":\"Comience a cambiar moneda\",\"button_link\":\"merchant\\/money-exchange\",\"step_title\":\"C\\u00f3mo cambiar dinero en QRPay Pro\",\"step_sub_title\":\"Siga estos pasos para cambiar dinero de forma r\\u00e1pida y segura entre monedas en su cuenta QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0642\\u0645 \\u0628\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0645\\u062a\\u0639\\u062f\\u062f\\u0629 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0645\\u064a\\u0632\\u0629 \\u0635\\u0631\\u0641 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a QRPay Pro\",\"sub_heading\":\"\\u064a\\u062a\\u064a\\u062d QRPay Pro \\u0644\\u0644\\u062a\\u062c\\u0627\\u0631 \\u0625\\u0645\\u0643\\u0627\\u0646\\u064a\\u0629 \\u062a\\u0628\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0636\\u0645\\u0646 \\u0633\\u0644\\u0627\\u0633\\u0629 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0645\\u0639 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0627\\u0644\\u062f\\u0648\\u0644\\u064a\\u064a\\u0646. \\u0627\\u0628\\u0642 \\u0639\\u0644\\u0649 \\u0627\\u0637\\u0644\\u0627\\u0639 \\u062f\\u0627\\u0626\\u0645 \\u0628\\u0623\\u0633\\u0639\\u0627\\u0631 \\u0627\\u0644\\u0635\\u0631\\u0641 \\u0641\\u064a \\u0627\\u0644\\u0648\\u0642\\u062a \\u0627\\u0644\\u0641\\u0639\\u0644\\u064a \\u0648\\u0627\\u0633\\u062a\\u0645\\u062a\\u0639 \\u0628\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0633\\u0644\\u0633\\u0629 \\u0639\\u0646\\u062f \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628\\u0643\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0645\\u062d \\u0644\\u0643 \\u0628\\u062e\\u062f\\u0645\\u0629 \\u0642\\u0627\\u0639\\u062f\\u0629 \\u0639\\u0645\\u0644\\u0627\\u0621 \\u0639\\u0627\\u0644\\u0645\\u064a\\u0629 \\u0628\\u0643\\u0641\\u0627\\u0621\\u0629.\",\"process_step_title\":\"\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0629 \\u0641\\u064a 3 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0628\\u0633\\u064a\\u0637\\u0629\",\"button_name\":\"\\u0627\\u0644\\u0628\\u062f\\u0621 \\u0641\\u064a \\u062a\\u0628\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a\",\"button_link\":\"merchant\\/money-exchange\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u0635\\u0631\\u0641 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a QRPay Pro\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0644\\u062a\\u0628\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0633\\u0631\\u0639\\u0629 \\u0648\\u0623\\u0645\\u0627\\u0646 \\u0628\\u064a\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643.\"},\"fr\":{\"heading\":\"G\\u00e9rez les transactions multidevises avec la fonction Exchange Money de QRPay Pro\",\"sub_heading\":\"QRPay Pro permet aux commer\\u00e7ants d\'\\u00e9changer facilement des devises, garantissant ainsi des transactions fluides avec les clients internationaux. Restez inform\\u00e9 des taux de change en temps r\\u00e9el et profitez d\'un processus transparent lors de la conversion des fonds sur votre compte, vous permettant ainsi de servir efficacement une client\\u00e8le mondiale.\",\"process_step_title\":\"Convertir des devises en 3 \\u00e9tapes simples\",\"button_name\":\"Commencer \\u00e0 \\u00e9changer des devises\",\"button_link\":\"merchant\\/money-exchange\",\"step_title\":\"Comment \\u00e9changer de l\'argent dans QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes pour \\u00e9changer de l\'argent rapidement et en toute s\\u00e9curit\\u00e9 entre les devises de votre compte QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u090f\\u0915\\u094d\\u0938\\u091a\\u0947\\u0902\\u091c \\u092e\\u0928\\u0940 \\u092b\\u0940\\u091a\\u0930 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u092c\\u0939\\u0941-\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u093f\\u092f\\u094b\\u0902 \\u0915\\u094b \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u093e \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u092e\\u0947\\u0902 \\u0938\\u0915\\u094d\\u0937\\u092e \\u092c\\u0928\\u093e\\u0924\\u093e \\u0939\\u0948, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0905\\u0902\\u0924\\u0930\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915\\u094b\\u0902 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0938\\u0939\\u091c \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0939\\u094b\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0935\\u093e\\u0938\\u094d\\u0924\\u0935\\u093f\\u0915 \\u0938\\u092e\\u092f \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0926\\u0930\\u094b\\u0902 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0905\\u092a\\u0921\\u0947\\u091f \\u0930\\u0939\\u0947\\u0902 \\u0914\\u0930 \\u0905\\u092a\\u0928\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u092a\\u0930\\u093f\\u0935\\u0930\\u094d\\u0924\\u093f\\u0924 \\u0915\\u0930\\u0924\\u0947 \\u0938\\u092e\\u092f \\u090f\\u0915 \\u0938\\u0939\\u091c \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0915\\u093e \\u0906\\u0928\\u0902\\u0926 \\u0932\\u0947\\u0902, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0906\\u092a \\u0935\\u0948\\u0936\\u094d\\u0935\\u093f\\u0915 \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915 \\u0906\\u0927\\u093e\\u0930 \\u0915\\u094b \\u0915\\u0941\\u0936\\u0932\\u0924\\u093e\\u092a\\u0942\\u0930\\u094d\\u0935\\u0915 \\u0938\\u0947\\u0935\\u093e \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0947\\u0902\\u0917\\u0947\\u0964\",\"process_step_title\":\"3 \\u0938\\u0930\\u0932 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u092a\\u0930\\u093f\\u0935\\u0930\\u094d\\u0924\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902\",\"button_name\":\"\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0915\\u093e \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u092a\\u094d\\u0930\\u093e\\u0930\\u0902\\u092d \\u0915\\u0930\\u0947\\u0902\",\"button_link\":\"merchant\\/money-exchange\",\"step_title\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092e\\u0947\\u0902 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u093e \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0948\\u0938\\u0947 \\u0915\\u0930\\u0947\\u0902\",\"step_sub_title\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u092c\\u0940\\u091a \\u0924\\u094d\\u0935\\u0930\\u093f\\u0924 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u093e \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"6724b7a6800f7\":{\"language\":{\"en\":{\"name\":\"Select the Currency to Exchange\"},\"ar\":{\"name\":\"\\u062d\\u062f\\u062f \\u0627\\u0644\\u0639\\u0645\\u0644\\u0629 \\u0627\\u0644\\u0645\\u0631\\u0627\\u062f \\u0635\\u0631\\u0641\\u0647\\u0627\"},\"es\":{\"name\":\"Seleccione la moneda a cambiar\"},\"fr\":{\"name\":\"S\\u00e9lectionnez la devise \\u00e0 \\u00e9changer\"},\"hi\":{\"name\":\"\\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0915\\u093e \\u091a\\u092f\\u0928 \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6724b7a6800f7\"},\"6724b7ac97533\":{\"language\":{\"en\":{\"name\":\"Choose Your Target Currency\"},\"ar\":{\"name\":\"\\u0627\\u062e\\u062a\\u0631 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0647\\u062f\\u0641\\u0629\"},\"es\":{\"name\":\"Elija su moneda objetivo\"},\"fr\":{\"name\":\"Choisissez votre devise cible\"},\"hi\":{\"name\":\"\\u0905\\u092a\\u0928\\u0940 \\u0932\\u0915\\u094d\\u0937\\u093f\\u0924 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u091a\\u0941\\u0928\\u0947\\u0902\"}},\"id\":\"6724b7ac97533\"},\"6724b7b383f24\":{\"language\":{\"en\":{\"name\":\"Confirm and Exchange\"},\"ar\":{\"name\":\"\\u062a\\u0623\\u0643\\u064a\\u062f \\u0648\\u062a\\u0628\\u0627\\u062f\\u0644\"},\"es\":{\"name\":\"Confirmar e intercambiar\"},\"fr\":{\"name\":\"Confirmer et \\u00e9changer\"},\"hi\":{\"name\":\"\\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6724b7b383f24\"}}}', 1, 1, '2024-11-01 17:12:28', '2024-12-12 18:17:34');
INSERT INTO `frontend_header_section_pages` VALUES (20, 20, 'business', '{\"images\":{\"section_image\":\"b7479304-2e1b-489d-95b4-c5f207baeee3.webp\",\"step_image\":\"efbff342-f9fd-4366-a740-fbb2099639e1.webp\"},\"language\":{\"en\":{\"heading\":\"Collect Payments Easily with QRPay Pro Payment Links\",\"sub_heading\":\"QRPay Pro enables merchants to create and share unique payment links, making it convenient for customers to pay online. Whether you\\u2019re sending invoices or offering remote payment options, the QRPay Pro payment link feature simplifies the payment process and offers enhanced security for your transactions.\",\"process_step_title\":\"Accept Payments in 3 Easy Steps\",\"button_name\":\"Create Payment Link\",\"button_link\":\"merchant\\/payment-link\",\"step_title\":\"How to Use Payment Links in QRPay Pro\",\"step_sub_title\":\"Generate and share payment links in minutes to streamline payment collection for your business.\"},\"es\":{\"heading\":\"Cobre pagos f\\u00e1cilmente con los enlaces de pago QRPay Pro\",\"sub_heading\":\"QRPay Pro permite a los comerciantes crear y compartir enlaces de pago \\u00fanicos, lo que hace que sea conveniente para los clientes pagar en l\\u00ednea. Ya sea que env\\u00ede facturas u ofrezca opciones de pago remoto, la funci\\u00f3n de enlace de pago QRPay Pro simplifica el proceso de pago y ofrece mayor seguridad para sus transacciones.\",\"process_step_title\":\"Acepte pagos en 3 sencillos pasos\",\"button_name\":\"Crear enlace de pago\",\"button_link\":\"merchant\\/payment-link\",\"step_title\":\"C\\u00f3mo utilizar enlaces de pago en QRPay Pro\",\"step_sub_title\":\"Genere y comparta enlaces de pago en minutos para agilizar el cobro de pagos para su empresa.\"},\"ar\":{\"heading\":\"Collect Payments Easily with QRPay Pro Payment Links\",\"sub_heading\":\"\\u064a\\u062a\\u064a\\u062d QRPay Pro \\u0644\\u0644\\u062a\\u062c\\u0627\\u0631 \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u0648\\u0627\\u0628\\u0637 \\u062f\\u0641\\u0639 \\u0641\\u0631\\u064a\\u062f\\u0629 \\u0648\\u0645\\u0634\\u0627\\u0631\\u0643\\u062a\\u0647\\u0627\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0647\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0625\\u0646\\u062a\\u0631\\u0646\\u062a. \\u0633\\u0648\\u0627\\u0621 \\u0643\\u0646\\u062a \\u062a\\u0631\\u0633\\u0644 \\u0627\\u0644\\u0641\\u0648\\u0627\\u062a\\u064a\\u0631 \\u0623\\u0648 \\u062a\\u0642\\u062f\\u0645 \\u062e\\u064a\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0639\\u0646 \\u0628\\u0639\\u062f\\u060c \\u0641\\u0625\\u0646 \\u0645\\u064a\\u0632\\u0629 \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 QRPay Pro \\u062a\\u0639\\u0645\\u0644 \\u0639\\u0644\\u0649 \\u062a\\u0628\\u0633\\u064a\\u0637 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0648\\u062a\\u0648\\u0641\\u0631 \\u0623\\u0645\\u0627\\u0646\\u064b\\u0627 \\u0645\\u062d\\u0633\\u0646\\u064b\\u0627 \\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u0643.\",\"process_step_title\":\"\\u0627\\u0642\\u0628\\u0644 \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0641\\u064a 3 \\u062e\\u0637\\u0648\\u0627\\u062a \\u0633\\u0647\\u0644\\u0629\",\"button_name\":\"\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639\",\"button_link\":\"merchant\\/payment-link\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0631\\u0648\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0641\\u064a QRPay Pro\",\"step_sub_title\":\"\\u0642\\u0645 \\u0628\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u0648\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0648\\u0645\\u0634\\u0627\\u0631\\u0643\\u062a\\u0647\\u0627 \\u0641\\u064a \\u062f\\u0642\\u0627\\u0626\\u0642 \\u0644\\u062a\\u0628\\u0633\\u064a\\u0637 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u062a\\u062d\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0644\\u0634\\u0631\\u0643\\u062a\\u0643.\"},\"fr\":{\"heading\":\"Collectez facilement des paiements avec les liens de paiement QRPay Pro\",\"sub_heading\":\"QRPay Pro permet aux commer\\u00e7ants de cr\\u00e9er et de partager des liens de paiement uniques, ce qui permet aux clients de payer en ligne facilement. Que vous envoyiez des factures ou proposiez des options de paiement \\u00e0 distance, la fonction de lien de paiement QRPay Pro simplifie le processus de paiement et offre une s\\u00e9curit\\u00e9 renforc\\u00e9e pour vos transactions.\",\"process_step_title\":\"Acceptez les paiements en 3 \\u00e9tapes faciles\",\"button_name\":\"Cr\\u00e9er un lien de paiement\",\"button_link\":\"merchant\\/payment-link\",\"step_title\":\"Comment utiliser les liens de paiement dans QRPay Pro\",\"step_sub_title\":\"G\\u00e9n\\u00e9rez et partagez des liens de paiement en quelques minutes pour rationaliser la collecte des paiements pour votre entreprise.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u090f\\u0915\\u0924\\u094d\\u0930 \\u0915\\u0930\\u0947\\u0902\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u093f\\u092f\\u094b\\u0902 \\u0915\\u094b \\u0905\\u0926\\u094d\\u0935\\u093f\\u0924\\u0940\\u092f \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u092c\\u0928\\u093e\\u0928\\u0947 \\u0914\\u0930 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930\\u0928\\u0947 \\u092e\\u0947\\u0902 \\u0938\\u0915\\u094d\\u0937\\u092e \\u092c\\u0928\\u093e\\u0924\\u093e \\u0939\\u0948, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915\\u094b\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0911\\u0928\\u0932\\u093e\\u0907\\u0928 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0928\\u093e \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e\\u091c\\u0928\\u0915 \\u0939\\u094b \\u091c\\u093e\\u0924\\u093e \\u0939\\u0948\\u0964 \\u091a\\u093e\\u0939\\u0947 \\u0906\\u092a \\u091a\\u093e\\u0932\\u093e\\u0928 \\u092d\\u0947\\u091c \\u0930\\u0939\\u0947 \\u0939\\u094b\\u0902 \\u092f\\u093e \\u0926\\u0942\\u0930\\u0938\\u094d\\u0925 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a \\u092a\\u0947\\u0936 \\u0915\\u0930 \\u0930\\u0939\\u0947 \\u0939\\u094b\\u0902, QRPay \\u092a\\u094d\\u0930\\u094b \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0915\\u094b \\u0938\\u0930\\u0932 \\u092c\\u0928\\u093e\\u0924\\u0940 \\u0939\\u0948 \\u0914\\u0930 \\u0906\\u092a\\u0915\\u0947 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092c\\u0922\\u093c\\u0940 \\u0939\\u0941\\u0908 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930\\u0924\\u0940 \\u0939\\u0948\\u0964\",\"process_step_title\":\"3 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u094d\\u0935\\u0940\\u0915\\u093e\\u0930 \\u0915\\u0930\\u0947\\u0902\",\"button_name\":\"\\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u092c\\u0928\\u093e\\u090f\\u0902\",\"button_link\":\"merchant\\/payment-link\",\"step_title\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u092e\\u0947\\u0902 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0948\\u0938\\u0947 \\u0915\\u0930\\u0947\\u0902\",\"step_sub_title\":\"\\u0905\\u092a\\u0928\\u0947 \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u0902\\u0917\\u094d\\u0930\\u0939 \\u0915\\u094b \\u0938\\u0941\\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092e\\u093f\\u0928\\u091f\\u094b\\u0902 \\u092e\\u0947\\u0902 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u092c\\u0928\\u093e\\u090f\\u0902 \\u0914\\u0930 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"6724b8c540a68\":{\"language\":{\"en\":{\"name\":\"Generate a Payment Link\"},\"ar\":{\"name\":\"\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u0627\\u0628\\u0637 \\u0627\\u0644\\u062f\\u0641\\u0639\"},\"es\":{\"name\":\"Generar un enlace de pago\"},\"fr\":{\"name\":\"G\\u00e9n\\u00e9rer un lien de paiement\"},\"hi\":{\"name\":\"\\u090f\\u0915 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0932\\u093f\\u0902\\u0915 \\u091c\\u0928\\u0930\\u0947\\u091f \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6724b8c540a68\"},\"6724b8cb81a6f\":{\"language\":{\"en\":{\"name\":\"Share the Link with Customers\"},\"ar\":{\"name\":\"\\u0645\\u0634\\u0627\\u0631\\u0643\\u0629 \\u0627\\u0644\\u0631\\u0627\\u0628\\u0637 \\u0645\\u0639 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621\"},\"es\":{\"name\":\"Comparta el enlace con los clientes\"},\"fr\":{\"name\":\"Partagez le lien avec les clients\"},\"hi\":{\"name\":\"\\u0917\\u094d\\u0930\\u093e\\u0939\\u0915\\u094b\\u0902 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0932\\u093f\\u0902\\u0915 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6724b8cb81a6f\"},\"6724b8d4454dc\":{\"language\":{\"en\":{\"name\":\"Receive Instant Payment Notifications\"},\"ar\":{\"name\":\"\\u062a\\u0644\\u0642\\u064a \\u0625\\u0634\\u0639\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u0641\\u0648\\u0631\\u064a\"},\"es\":{\"name\":\"Reciba notificaciones de pago instant\\u00e1neas\"},\"fr\":{\"name\":\"Recevez des notifications de paiement instantan\\u00e9es\"},\"hi\":{\"name\":\"\\u0924\\u094d\\u0935\\u0930\\u093f\\u0924 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u0942\\u091a\\u0928\\u093e\\u090f\\u0902 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6724b8d4454dc\"}}}', 1, 1, '2024-11-01 17:17:18', '2024-12-12 18:18:35');
INSERT INTO `frontend_header_section_pages` VALUES (21, 21, 'business', '{\"images\":{\"section_image\":\"6cad9e7b-6878-42c6-956e-6c4ab24bf1fe.webp\",\"step_image\":\"dd5aa5d2-8cd3-47f6-a5b8-e93d2c1b621c.webp\"},\"language\":{\"en\":{\"heading\":\"Access Your Funds Easily with QRPay Pro\",\"sub_heading\":\"QRPay Pro makes it simple for merchants to withdraw funds from their accounts. Transfer your balance directly to your bank or preferred digital wallet, enjoying quick and secure access to your earnings.\",\"process_step_title\":\"Three Simple Steps to Withdraw Your Funds\",\"button_name\":\"Withdraw Now\",\"button_link\":\"merchant\\/withdraw\",\"step_title\":\"How to Withdraw Money from Your QRPay Pro Account\",\"step_sub_title\":\"Follow these easy steps to move your QRPay Pro funds to your bank or digital wallet.\"},\"es\":{\"heading\":\"Acceda a sus fondos f\\u00e1cilmente con QRPay Pro\",\"sub_heading\":\"QRPay Pro simplifica a los comerciantes el retiro de fondos de sus cuentas. Transfiera su saldo directamente a su banco o billetera digital preferida, disfrutando de un acceso r\\u00e1pido y seguro a sus ganancias.\",\"process_step_title\":\"Tres sencillos pasos para retirar sus fondos\",\"button_name\":\"Retirar ahora\",\"button_link\":\"merchant\\/withdraw\",\"step_title\":\"C\\u00f3mo retirar dinero de su cuenta QRPay Pro\",\"step_sub_title\":\"Siga estos sencillos pasos para transferir sus fondos de QRPay Pro a su banco o billetera digital.\"},\"ar\":{\"heading\":\"\\u064a\\u0645\\u0643\\u0646\\u0643 \\u0627\\u0644\\u0648\\u0635\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\",\"sub_heading\":\"QRPay Pro \\u064a\\u062c\\u0639\\u0644 \\u0645\\u0646 \\u0627\\u0644\\u0633\\u0647\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u062c\\u0627\\u0631 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u0646 \\u062d\\u0633\\u0627\\u0628\\u0627\\u062a\\u0647\\u0645. \\u0642\\u0645 \\u0628\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0631\\u0635\\u064a\\u062f\\u0643 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0628\\u0646\\u0643 \\u0627\\u0644\\u0630\\u064a \\u062a\\u062a\\u0639\\u0627\\u0645\\u0644 \\u0645\\u0639\\u0647 \\u0623\\u0648 \\u0627\\u0644\\u0645\\u062d\\u0641\\u0638\\u0629 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0641\\u0636\\u0644\\u0629 \\u0644\\u062f\\u064a\\u0643\\u060c \\u0644\\u062a\\u0633\\u062a\\u0645\\u062a\\u0639 \\u0628\\u0625\\u0645\\u0643\\u0627\\u0646\\u064a\\u0629 \\u0627\\u0644\\u0648\\u0635\\u0648\\u0644 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639 \\u0648\\u0627\\u0644\\u0622\\u0645\\u0646 \\u0625\\u0644\\u0649 \\u0623\\u0631\\u0628\\u0627\\u062d\\u0643.\",\"process_step_title\":\"\\u062b\\u0644\\u0627\\u062b \\u062e\\u0637\\u0648\\u0627\\u062a \\u0628\\u0633\\u064a\\u0637\\u0629 \\u0644\\u0633\\u062d\\u0628 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643\",\"button_name\":\"\\u0627\\u0646\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"merchant\\/withdraw\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0645\\u0646 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0633\\u0647\\u0644\\u0629 \\u0644\\u0646\\u0642\\u0644 \\u0623\\u0645\\u0648\\u0627\\u0644 QRPay Pro \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0628\\u0646\\u0643 \\u0627\\u0644\\u0630\\u064a \\u062a\\u062a\\u0639\\u0627\\u0645\\u0644 \\u0645\\u0639\\u0647 \\u0623\\u0648 \\u0645\\u062d\\u0641\\u0638\\u062a\\u0643 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a\\u0629.\"},\"fr\":{\"heading\":\"Acc\\u00e9dez facilement \\u00e0 vos fonds avec QRPay Pro\",\"sub_heading\":\"QRPay Pro permet aux commer\\u00e7ants de retirer facilement des fonds de leurs comptes. Transf\\u00e9rez votre solde directement vers votre banque ou votre portefeuille num\\u00e9rique pr\\u00e9f\\u00e9r\\u00e9, b\\u00e9n\\u00e9ficiant d\'un acc\\u00e8s rapide et s\\u00e9curis\\u00e9 \\u00e0 vos gains.\",\"process_step_title\":\"Trois \\u00e9tapes simples pour retirer vos fonds\",\"button_name\":\"Retirer maintenant\",\"button_link\":\"merchant\\/withdraw\",\"step_title\":\"Comment retirer de l\'argent de votre compte QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes simples pour transf\\u00e9rer vos fonds QRPay Pro vers votre banque ou votre portefeuille num\\u00e9rique.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0905\\u092a\\u0928\\u0947 \\u092b\\u0902\\u0921 \\u0924\\u0915 \\u092a\\u0939\\u0941\\u0902\\u091a\\u0947\\u0902\",\"sub_heading\":\"QRPay Pro \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u093f\\u092f\\u094b\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u0947 \\u0916\\u093e\\u0924\\u094b\\u0902 \\u0938\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u093e \\u0906\\u0938\\u093e\\u0928 \\u092c\\u0928\\u093e\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0905\\u092a\\u0928\\u0940 \\u0915\\u092e\\u093e\\u0908 \\u0924\\u0915 \\u0924\\u094d\\u0935\\u0930\\u093f\\u0924 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u092a\\u0939\\u0941\\u0902\\u091a \\u0915\\u093e \\u0906\\u0928\\u0902\\u0926 \\u0932\\u0947\\u0924\\u0947 \\u0939\\u0941\\u090f, \\u0905\\u092a\\u0928\\u093e \\u0936\\u0947\\u0937 \\u0938\\u0940\\u0927\\u0947 \\u0905\\u092a\\u0928\\u0947 \\u092c\\u0948\\u0902\\u0915 \\u092f\\u093e \\u092a\\u0938\\u0902\\u0926\\u0940\\u0926\\u093e \\u0921\\u093f\\u091c\\u093f\\u091f\\u0932 \\u0935\\u0949\\u0932\\u0947\\u091f \\u092e\\u0947\\u0902 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902\\u0964\",\"process_step_title\":\"\\u0905\\u092a\\u0928\\u0940 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u0947 \\u0915\\u0947 \\u0924\\u0940\\u0928 \\u0938\\u0930\\u0932 \\u091a\\u0930\\u0923\",\"button_name\":\"\\u0905\\u092d\\u0940 \\u0935\\u093e\\u092a\\u0938 \\u0932\\u0947\\u0902\",\"button_link\":\"merchant\\/withdraw\",\"step_title\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u0938\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0947\\u0902\",\"step_sub_title\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u092b\\u0902\\u0921 \\u0915\\u094b \\u0905\\u092a\\u0928\\u0947 \\u092c\\u0948\\u0902\\u0915 \\u092f\\u093e \\u0921\\u093f\\u091c\\u093f\\u091f\\u0932 \\u0935\\u0949\\u0932\\u0947\\u091f \\u092e\\u0947\\u0902 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0928 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"6724b9c2ec46d\":{\"language\":{\"en\":{\"name\":\"Select Withdraw Option\"},\"ar\":{\"name\":\"\\u062d\\u062f\\u062f \\u062e\\u064a\\u0627\\u0631 \\u0627\\u0644\\u0633\\u062d\\u0628\"},\"es\":{\"name\":\"Seleccione la opci\\u00f3n de retiro\"},\"fr\":{\"name\":\"S\\u00e9lectionnez l\'option de retrait\"},\"hi\":{\"name\":\"\\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a \\u091a\\u0941\\u0928\\u0947\\u0902\"}},\"id\":\"6724b9c2ec46d\"},\"6724b9c9dbf68\":{\"language\":{\"en\":{\"name\":\"Choose Withdrawal Method\"},\"ar\":{\"name\":\"\\u0627\\u062e\\u062a\\u0631 \\u0637\\u0631\\u064a\\u0642\\u0629 \\u0627\\u0644\\u0633\\u062d\\u0628\"},\"es\":{\"name\":\"Elija el m\\u00e9todo de retiro\"},\"fr\":{\"name\":\"Choisissez la m\\u00e9thode de retrait\"},\"hi\":{\"name\":\"\\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0935\\u093f\\u0927\\u093f \\u091a\\u0941\\u0928\\u0947\\u0902\"}},\"id\":\"6724b9c9dbf68\"},\"6724b9d034749\":{\"language\":{\"en\":{\"name\":\"Confirm Withdrawal\"},\"ar\":{\"name\":\"\\u062a\\u0623\\u0643\\u064a\\u062f \\u0627\\u0644\\u0633\\u062d\\u0628\"},\"es\":{\"name\":\"Confirmar retiro\"},\"fr\":{\"name\":\"Confirmer le retrait\"},\"hi\":{\"name\":\"\\u0928\\u093f\\u0915\\u093e\\u0938\\u0940 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6724b9d034749\"}}}', 1, 1, '2024-11-01 17:21:29', '2024-12-31 12:26:35');
INSERT INTO `frontend_header_section_pages` VALUES (22, 22, 'business', '{\"images\":{\"section_image\":\"d1a4b4c0-3c07-4e4a-93be-7770903d9b1e.webp\",\"step_image\":\"ec81ccf2-fa4d-4378-a7b2-0ce22869282c.webp\"},\"language\":{\"en\":{\"heading\":\"Configure Your Payment Gateway for Secure Transactions\",\"sub_heading\":\"With QRPay Pro, merchants can easily set up and manage their payment gateway settings. Customize payment options to create a secure, frictionless experience for your customers, supported by QRPay Pro\'s robust security and compliance standards.\",\"process_step_title\":\"Three Simple Steps to Set Up Your Payment Gateway\",\"button_name\":\"Configure Now\",\"button_link\":\"merchant\\/gateway-setting\",\"step_title\":\"How to Set Up and Manage Your QRPay Pro Gateway\",\"step_sub_title\":\"Follow these steps to integrate QRPay Pro\\u2019s secure payment gateway into your platform.\"},\"es\":{\"heading\":\"Configure su pasarela de pago para transacciones seguras\",\"sub_heading\":\"Con QRPay Pro, los comerciantes pueden configurar y administrar f\\u00e1cilmente la configuraci\\u00f3n de su pasarela de pago. Personalice las opciones de pago para crear una experiencia segura y sin fricciones para sus clientes, respaldada por los s\\u00f3lidos est\\u00e1ndares de seguridad y cumplimiento de QRPay Pro.\",\"process_step_title\":\"Tres sencillos pasos para configurar su pasarela de pago\",\"button_name\":\"Configurar ahora\",\"button_link\":\"merchant\\/gateway-setting\",\"step_title\":\"C\\u00f3mo configurar y administrar su puerta de enlace QRPay Pro\",\"step_sub_title\":\"Siga estos pasos para integrar la pasarela de pago seguro de QRPay Pro en su plataforma.\"},\"ar\":{\"heading\":\"\\u0642\\u0645 \\u0628\\u062a\\u0643\\u0648\\u064a\\u0646 \\u0628\\u0648\\u0627\\u0628\\u0629 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643 \\u0644\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0622\\u0645\\u0646\\u0629\",\"sub_heading\":\"\\u0645\\u0639 QRPay Pro\\u060c \\u064a\\u0645\\u0643\\u0646 \\u0644\\u0644\\u062a\\u062c\\u0627\\u0631 \\u0625\\u0639\\u062f\\u0627\\u062f \\u0648\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u0628\\u0648\\u0627\\u0628\\u0629 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0647\\u0645 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629. \\u0642\\u0645 \\u0628\\u062a\\u062e\\u0635\\u064a\\u0635 \\u062e\\u064a\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0644\\u0625\\u0646\\u0634\\u0627\\u0621 \\u062a\\u062c\\u0631\\u0628\\u0629 \\u0622\\u0645\\u0646\\u0629 \\u0648\\u062e\\u0627\\u0644\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0627\\u062d\\u062a\\u0643\\u0627\\u0643 \\u0644\\u0639\\u0645\\u0644\\u0627\\u0626\\u0643\\u060c \\u0645\\u062f\\u0639\\u0648\\u0645\\u0629 \\u0628\\u0645\\u0639\\u0627\\u064a\\u064a\\u0631 \\u0627\\u0644\\u0623\\u0645\\u0627\\u0646 \\u0648\\u0627\\u0644\\u0627\\u0645\\u062a\\u062b\\u0627\\u0644 \\u0627\\u0644\\u0642\\u0648\\u064a\\u0629 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0640 QRPay Pro.\",\"process_step_title\":\"\\u0642\\u0645 \\u0628\\u062a\\u0643\\u0648\\u064a\\u0646 \\u0628\\u0648\\u0627\\u0628\\u0629 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643 \\u0644\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0622\\u0645\\u0646\\u0629\",\"button_name\":\"\\u062a\\u0643\\u0648\\u064a\\u0646 \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"merchant\\/gateway-setting\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u0625\\u0639\\u062f\\u0627\\u062f \\u0648\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0628\\u0648\\u0627\\u0628\\u0629 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0644\\u062f\\u0645\\u062c \\u0628\\u0648\\u0627\\u0628\\u0629 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u0622\\u0645\\u0646\\u0629 \\u0644\\u0640 QRPay Pro \\u0641\\u064a \\u0627\\u0644\\u0646\\u0638\\u0627\\u0645 \\u0627\\u0644\\u0623\\u0633\\u0627\\u0633\\u064a \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643.\"},\"fr\":{\"heading\":\"Configurez votre passerelle de paiement pour des transactions s\\u00e9curis\\u00e9es\",\"sub_heading\":\"Avec QRPay Pro, les commer\\u00e7ants peuvent facilement configurer et g\\u00e9rer les param\\u00e8tres de leur passerelle de paiement. Personnalisez les options de paiement pour cr\\u00e9er une exp\\u00e9rience s\\u00e9curis\\u00e9e et fluide pour vos clients, soutenue par les normes robustes de s\\u00e9curit\\u00e9 et de conformit\\u00e9 de QRPay Pro.\",\"process_step_title\":\"Trois \\u00e9tapes simples pour configurer votre passerelle de paiement\",\"button_name\":\"Configurer maintenant\",\"button_link\":\"merchant\\/gateway-setting\",\"step_title\":\"Comment configurer et g\\u00e9rer votre passerelle QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes pour int\\u00e9grer la passerelle de paiement s\\u00e9curis\\u00e9e de QRPay Pro dans votre plateforme.\"},\"hi\":{\"heading\":\"\\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0917\\u0947\\u091f\\u0935\\u0947 \\u0915\\u0949\\u0928\\u094d\\u092b\\u093c\\u093f\\u0917\\u0930 \\u0915\\u0930\\u0947\\u0902\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925, \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u0940 \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0905\\u092a\\u0928\\u0940 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0917\\u0947\\u091f\\u0935\\u0947 \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917\\u094d\\u0938 \\u0938\\u0947\\u091f \\u0914\\u0930 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u092e\\u091c\\u092c\\u0942\\u0924 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0914\\u0930 \\u0905\\u0928\\u0941\\u092a\\u093e\\u0932\\u0928 \\u092e\\u093e\\u0928\\u0915\\u094b\\u0902 \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u093f\\u0924, \\u0905\\u092a\\u0928\\u0947 \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915\\u094b\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u090f\\u0915 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924, \\u0918\\u0930\\u094d\\u0937\\u0923 \\u0930\\u0939\\u093f\\u0924 \\u0905\\u0928\\u0941\\u092d\\u0935 \\u092c\\u0928\\u093e\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a\\u094b\\u0902 \\u0915\\u094b \\u0905\\u0928\\u0941\\u0915\\u0942\\u0932\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902\\u0964\",\"process_step_title\":\"\\u0905\\u092a\\u0928\\u093e \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0917\\u0947\\u091f\\u0935\\u0947 \\u0938\\u0947\\u091f \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0924\\u0940\\u0928 \\u0938\\u0930\\u0932 \\u091a\\u0930\\u0923\",\"button_name\":\"\\u0905\\u092d\\u0940 \\u0915\\u0949\\u0928\\u094d\\u092b\\u093c\\u093f\\u0917\\u0930 \\u0915\\u0930\\u0947\\u0902\",\"button_link\":\"merchant\\/gateway-setting\",\"step_title\":\"\\u0905\\u092a\\u0928\\u093e QRPay \\u092a\\u094d\\u0930\\u094b \\u0917\\u0947\\u091f\\u0935\\u0947 \\u0915\\u0948\\u0938\\u0947 \\u0938\\u0947\\u091f \\u0905\\u092a \\u0914\\u0930 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902\",\"step_sub_title\":\"QRPay Pro \\u0915\\u0947 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0917\\u0947\\u091f\\u0935\\u0947 \\u0915\\u094b \\u0905\\u092a\\u0928\\u0947 \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e \\u092e\\u0947\\u0902 \\u090f\\u0915\\u0940\\u0915\\u0943\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"6724ba7aadd13\":{\"language\":{\"en\":{\"name\":\"Access Gateway Settings\"},\"ar\":{\"name\":\"\\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u0628\\u0648\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0648\\u0635\\u0648\\u0644\"},\"es\":{\"name\":\"Configuraci\\u00f3n de la puerta de enlace de acceso\"},\"fr\":{\"name\":\"Param\\u00e8tres de la passerelle d\'acc\\u00e8s\"},\"hi\":{\"name\":\"\\u0917\\u0947\\u091f\\u0935\\u0947 \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917\\u094d\\u0938 \\u0924\\u0915 \\u092a\\u0939\\u0941\\u0902\\u091a\\u0947\\u0902\"}},\"id\":\"6724ba7aadd13\"},\"6724ba7fea0b5\":{\"language\":{\"en\":{\"name\":\"Customize Your Settings\"},\"ar\":{\"name\":\"\\u062a\\u062e\\u0635\\u064a\\u0635 \\u0627\\u0644\\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643\"},\"es\":{\"name\":\"Personaliza tu configuraci\\u00f3n\"},\"fr\":{\"name\":\"Personnalisez vos param\\u00e8tres\"},\"hi\":{\"name\":\"\\u0905\\u092a\\u0928\\u0940 \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917\\u094d\\u0938 \\u0905\\u0928\\u0941\\u0915\\u0942\\u0932\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6724ba7fea0b5\"},\"6724ba862ef69\":{\"language\":{\"en\":{\"name\":\"Save and Go Live\"},\"ar\":{\"name\":\"\\u0627\\u062d\\u0641\\u0638 \\u0648\\u0627\\u0628\\u062f\\u0623 \\u0627\\u0644\\u0628\\u062b \\u0627\\u0644\\u0645\\u0628\\u0627\\u0634\\u0631\"},\"es\":{\"name\":\"Guardar y publicar\"},\"fr\":{\"name\":\"Enregistrez et lancez le direct\"},\"hi\":{\"name\":\"\\u0938\\u0939\\u0947\\u091c\\u0947\\u0902 \\u0914\\u0930 \\u0932\\u093e\\u0907\\u0935 \\u0939\\u094b \\u091c\\u093e\\u090f\\u0902\"}},\"id\":\"6724ba862ef69\"}}}', 1, 1, '2024-11-01 17:24:34', '2024-12-12 18:21:18');
INSERT INTO `frontend_header_section_pages` VALUES (23, 23, 'business', '{\"images\":{\"section_image\":\"4a7413d5-0f24-4eec-ae2b-7ef2d9b7f72c.webp\",\"step_image\":\"749747f3-d508-4f6b-9e6c-75db53ccf9ce.webp\"},\"language\":{\"en\":{\"heading\":\"Seamlessly Connect Your Platform with Secure API Keys\",\"sub_heading\":\"With QRPay Pro, creating and managing API keys is simple and secure. Use API keys to integrate QRPay Pro\\u2019s payment features directly into your platform, allowing you to provide smooth, efficient, and secure payment solutions.\",\"process_step_title\":\"Steps to Generate and Use API Keys with QRPay Pro\",\"button_name\":\"Generate API Key\",\"button_link\":\"merchant\\/developer\\/api\",\"step_title\":\"How to Manage Your QRPay Pro API Key\",\"step_sub_title\":\"Follow these steps to create and configure your API keys for secure integration\"},\"es\":{\"heading\":\"Conecte su plataforma sin problemas con claves API seguras\",\"sub_heading\":\"Con QRPay Pro, crear y administrar claves API es simple y seguro. Utilice claves API para integrar las funciones de pago de QRPay Pro directamente en su plataforma, lo que le permitir\\u00e1 brindar soluciones de pago fluidas, eficientes y seguras.\",\"process_step_title\":\"Pasos para generar y utilizar claves API con QRPay Pro\",\"button_name\":\"Generar clave API\",\"button_link\":\"merchant\\/developer\\/api\",\"step_title\":\"C\\u00f3mo administrar su clave API QRPay Pro\",\"step_sub_title\":\"Siga estos pasos para crear y configurar sus claves API para una integraci\\u00f3n segura\"},\"ar\":{\"heading\":\"\\u0642\\u0645 \\u0628\\u062a\\u0648\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0646\\u0638\\u0627\\u0645 \\u0627\\u0644\\u0623\\u0633\\u0627\\u0633\\u064a \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u0628\\u0633\\u0644\\u0627\\u0633\\u0629 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0645\\u0641\\u0627\\u062a\\u064a\\u062d API \\u0627\\u0644\\u0622\\u0645\\u0646\\u0629\",\"sub_heading\":\"\\u0645\\u0639 QRPay Pro\\u060c \\u064a\\u0639\\u062f \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0645\\u0641\\u0627\\u062a\\u064a\\u062d API \\u0648\\u0625\\u062f\\u0627\\u0631\\u062a\\u0647\\u0627 \\u0623\\u0645\\u0631\\u064b\\u0627 \\u0628\\u0633\\u064a\\u0637\\u064b\\u0627 \\u0648\\u0622\\u0645\\u0646\\u064b\\u0627. \\u0627\\u0633\\u062a\\u062e\\u062f\\u0645 \\u0645\\u0641\\u0627\\u062a\\u064a\\u062d API \\u0644\\u062f\\u0645\\u062c \\u0645\\u064a\\u0632\\u0627\\u062a \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0640 QRPay Pro \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0646\\u0638\\u0627\\u0645 \\u0627\\u0644\\u0623\\u0633\\u0627\\u0633\\u064a \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0645\\u062d \\u0644\\u0643 \\u0628\\u062a\\u0648\\u0641\\u064a\\u0631 \\u062d\\u0644\\u0648\\u0644 \\u062f\\u0641\\u0639 \\u0633\\u0644\\u0633\\u0629 \\u0648\\u0641\\u0639\\u0627\\u0644\\u0629 \\u0648\\u0622\\u0645\\u0646\\u0629.\",\"process_step_title\":\"\\u062e\\u0637\\u0648\\u0627\\u062a \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0648\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0645\\u0641\\u0627\\u062a\\u064a\\u062d API \\u0645\\u0639 QRPay Pro\",\"button_name\":\"\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0645\\u0641\\u062a\\u0627\\u062d API\",\"button_link\":\"merchant\\/developer\\/api\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0645\\u0641\\u062a\\u0627\\u062d QRPay Pro API \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0644\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0648\\u062a\\u0643\\u0648\\u064a\\u0646 \\u0645\\u0641\\u0627\\u062a\\u064a\\u062d API \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643 \\u0644\\u0644\\u062a\\u0643\\u0627\\u0645\\u0644 \\u0627\\u0644\\u0622\\u0645\\u0646\"},\"fr\":{\"heading\":\"Connectez facilement votre plateforme avec des cl\\u00e9s API s\\u00e9curis\\u00e9es\",\"sub_heading\":\"Avec QRPay Pro, la cr\\u00e9ation et la gestion des cl\\u00e9s API sont simples et s\\u00e9curis\\u00e9es. Utilisez les cl\\u00e9s API pour int\\u00e9grer les fonctionnalit\\u00e9s de paiement de QRPay Pro directement dans votre plateforme, vous permettant ainsi de fournir des solutions de paiement fluides, efficaces et s\\u00e9curis\\u00e9es.\",\"process_step_title\":\"\\u00c9tapes pour g\\u00e9n\\u00e9rer et utiliser des cl\\u00e9s API avec QRPay Pro\",\"button_name\":\"G\\u00e9n\\u00e9rer une cl\\u00e9 API\",\"button_link\":\"merchant\\/developer\\/api\",\"step_title\":\"Comment g\\u00e9rer votre cl\\u00e9 API QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes pour cr\\u00e9er et configurer vos cl\\u00e9s API pour une int\\u00e9gration s\\u00e9curis\\u00e9e\"},\"hi\":{\"heading\":\"\\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u090f\\u092a\\u0940\\u0906\\u0908 \\u0915\\u0941\\u0902\\u091c\\u093f\\u092f\\u094b\\u0902 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0905\\u092a\\u0928\\u0947 \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e \\u0915\\u094b \\u0928\\u093f\\u0930\\u094d\\u092c\\u093e\\u0927 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0915\\u0928\\u0947\\u0915\\u094d\\u091f \\u0915\\u0930\\u0947\\u0902\",\"sub_heading\":\"QRPay Pro \\u0915\\u0947 \\u0938\\u093e\\u0925, API \\u0915\\u0941\\u0902\\u091c\\u0940 \\u092c\\u0928\\u093e\\u0928\\u093e \\u0914\\u0930 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0915\\u0930\\u0928\\u093e \\u0938\\u0930\\u0932 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0939\\u0948\\u0964 QRPay Pro \\u0915\\u0940 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e\\u0913\\u0902 \\u0915\\u094b \\u0938\\u0940\\u0927\\u0947 \\u0905\\u092a\\u0928\\u0947 \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e \\u092e\\u0947\\u0902 \\u090f\\u0915\\u0940\\u0915\\u0943\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f API \\u0915\\u0941\\u0902\\u091c\\u093f\\u092f\\u094b\\u0902 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0947\\u0902, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0906\\u092a \\u0938\\u0939\\u091c, \\u0915\\u0941\\u0936\\u0932 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u092e\\u093e\\u0927\\u093e\\u0928 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0947\\u0902\\u0917\\u0947\\u0964\",\"process_step_title\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u090f\\u092a\\u0940\\u0906\\u0908 \\u0915\\u0941\\u0902\\u091c\\u0940 \\u092c\\u0928\\u093e\\u0928\\u0947 \\u0914\\u0930 \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u091a\\u0930\\u0923\",\"button_name\":\"\\u090f\\u092a\\u0940\\u0906\\u0908 \\u0915\\u0941\\u0902\\u091c\\u0940 \\u091c\\u0928\\u0930\\u0947\\u091f \\u0915\\u0930\\u0947\\u0902\",\"button_link\":\"merchant\\/developer\\/api\",\"step_title\":\"\\u0905\\u092a\\u0928\\u0940 QRPay \\u092a\\u094d\\u0930\\u094b \\u090f\\u092a\\u0940\\u0906\\u0908 \\u0915\\u0941\\u0902\\u091c\\u0940 \\u0915\\u0948\\u0938\\u0947 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902\",\"step_sub_title\":\"\\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u090f\\u0915\\u0940\\u0915\\u0930\\u0923 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u0940 \\u090f\\u092a\\u0940\\u0906\\u0908 \\u0915\\u0941\\u0902\\u091c\\u093f\\u092f\\u093e\\u0901 \\u092c\\u0928\\u093e\\u0928\\u0947 \\u0914\\u0930 \\u0915\\u0949\\u0928\\u094d\\u092b\\u093c\\u093f\\u0917\\u0930 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0928 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\"}},\"items\":{\"6724bb43acef5\":{\"language\":{\"en\":{\"name\":\"Navigate to API Key Settings\"},\"ar\":{\"name\":\"\\u0627\\u0646\\u062a\\u0642\\u0644 \\u0625\\u0644\\u0649 \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u0645\\u0641\\u062a\\u0627\\u062d API\"},\"es\":{\"name\":\"Navegue a Configuraci\\u00f3n de clave API\"},\"fr\":{\"name\":\"Acc\\u00e9dez aux param\\u00e8tres de la cl\\u00e9 API\"},\"hi\":{\"name\":\"\\u090f\\u092a\\u0940\\u0906\\u0908 \\u0915\\u0941\\u0902\\u091c\\u0940 \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917\\u094d\\u0938 \\u092a\\u0930 \\u0928\\u0947\\u0935\\u093f\\u0917\\u0947\\u091f \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6724bb43acef5\"},\"6724bb49eb177\":{\"language\":{\"en\":{\"name\":\"Generate a New Key\"},\"ar\":{\"name\":\"\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0645\\u0641\\u062a\\u0627\\u062d \\u062c\\u062f\\u064a\\u062f\"},\"es\":{\"name\":\"Generar una nueva clave\"},\"fr\":{\"name\":\"G\\u00e9n\\u00e9rer une nouvelle cl\\u00e9\"},\"hi\":{\"name\":\"\\u090f\\u0915 \\u0928\\u0908 \\u0915\\u0941\\u0902\\u091c\\u0940 \\u0909\\u0924\\u094d\\u092a\\u0928\\u094d\\u0928 \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6724bb49eb177\"},\"6724bb4f864ed\":{\"language\":{\"en\":{\"name\":\"Configure Permissions and Save\"},\"ar\":{\"name\":\"\\u062a\\u0643\\u0648\\u064a\\u0646 \\u0627\\u0644\\u0623\\u0630\\u0648\\u0646\\u0627\\u062a \\u0648\\u062d\\u0641\\u0638\\u0647\\u0627\"},\"es\":{\"name\":\"Configurar permisos y guardar\"},\"fr\":{\"name\":\"Configurer les autorisations et enregistrer\"},\"hi\":{\"name\":\"\\u0905\\u0928\\u0941\\u092e\\u0924\\u093f\\u092f\\u093e\\u0901 \\u0915\\u0949\\u0928\\u094d\\u092b\\u093c\\u093f\\u0917\\u0930 \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u0938\\u0939\\u0947\\u091c\\u0947\\u0902\"}},\"id\":\"6724bb4f864ed\"}}}', 1, 1, '2024-11-01 17:27:44', '2024-12-12 18:21:52');
INSERT INTO `frontend_header_section_pages` VALUES (24, 24, 'enterprise', '{\"images\":{\"section_image\":\"f28f4df8-6d2b-40ba-875a-5611d1fb409b.webp\",\"step_image\":\"436cb13b-8967-4460-ae1e-1ceb485c0a4d.webp\"},\"language\":{\"en\":{\"heading\":\"Receive Money Easily and Securely with QRPay Pro\",\"sub_heading\":\"QRPay Pro makes it simple for agents to receive funds, whether it\\u2019s from customers or other agents. With fast and secure transfers, QRPay Pro ensures that every transaction is processed with top-tier security and convenience, enabling multi-currency support to accept payments from various regions.\",\"process_step_title\":\"Steps to Receive Money Instantly with QRPay Pro\",\"button_name\":\"Start Receiving Money\",\"button_link\":\"agent\\/receive-money\",\"step_title\":\"How to Receive Funds in Your QRPay Pro Account\",\"step_sub_title\":\"Follow these simple steps to receive funds quickly and securely to your QRPay Pro account.\"},\"es\":{\"heading\":\"Reciba dinero de forma f\\u00e1cil y segura con QRPay Pro\",\"sub_heading\":\"QRPay Pro facilita que los agentes reciban fondos, ya sean de clientes u otros agentes. Con transferencias r\\u00e1pidas y seguras, QRPay Pro garantiza que cada transacci\\u00f3n se procese con seguridad y conveniencia de primer nivel, lo que permite soporte multidivisa para aceptar pagos de varias regiones.\",\"process_step_title\":\"Pasos para recibir dinero al instante con QRPay Pro\",\"button_name\":\"Comience a recibir dinero\",\"button_link\":\"agent\\/receive-money\",\"step_title\":\"C\\u00f3mo recibir fondos en su cuenta QRPay Pro\",\"step_sub_title\":\"Siga estos sencillos pasos para recibir fondos de forma r\\u00e1pida y segura en su cuenta QRPay Pro.\"},\"ar\":{\"heading\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0648\\u0623\\u0645\\u0627\\u0646 \\u0645\\u0639 QRPay Pro\",\"sub_heading\":\"\\u064a\\u0633\\u0647\\u0651\\u0644 QRPay Pro \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0648\\u0643\\u0644\\u0627\\u0621 \\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u060c \\u0633\\u0648\\u0627\\u0621 \\u0643\\u0627\\u0646\\u062a \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0623\\u0648 \\u0627\\u0644\\u0648\\u0643\\u0644\\u0627\\u0621 \\u0627\\u0644\\u0622\\u062e\\u0631\\u064a\\u0646. \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639\\u0629 \\u0648\\u0627\\u0644\\u0622\\u0645\\u0646\\u0629\\u060c \\u064a\\u0636\\u0645\\u0646 QRPay Pro \\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0643\\u0644 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0629 \\u0628\\u0623\\u0645\\u0627\\u0646 \\u0648\\u0631\\u0627\\u062d\\u0629 \\u0639\\u0644\\u0649 \\u0623\\u0639\\u0644\\u0649 \\u0645\\u0633\\u062a\\u0648\\u0649\\u060c \\u0645\\u0645\\u0627 \\u064a\\u062a\\u064a\\u062d \\u062f\\u0639\\u0645 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u062a\\u0639\\u062f\\u062f\\u0629 \\u0644\\u0642\\u0628\\u0648\\u0644 \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0645\\u0646 \\u0645\\u0646\\u0627\\u0637\\u0642 \\u0645\\u062e\\u062a\\u0644\\u0641\\u0629.\",\"process_step_title\":\"\\u062e\\u0637\\u0648\\u0627\\u062a \\u0644\\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631 \\u0645\\u0639 QRPay Pro\",\"button_name\":\"\\u0627\\u0644\\u0628\\u062f\\u0621 \\u0641\\u064a \\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\",\"button_link\":\"agent\\/receive-money\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0628\\u0633\\u064a\\u0637\\u0629 \\u0644\\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0633\\u0631\\u0639\\u0629 \\u0648\\u0623\\u0645\\u0627\\u0646 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643.\"},\"fr\":{\"heading\":\"Recevez de l\'argent facilement et en toute s\\u00e9curit\\u00e9 avec QRPay Pro\",\"sub_heading\":\"QRPay Pro permet aux agents de recevoir facilement des fonds, qu\'ils proviennent de clients ou d\'autres agents. Avec des transferts rapides et s\\u00e9curis\\u00e9s, QRPay Pro garantit que chaque transaction est trait\\u00e9e avec une s\\u00e9curit\\u00e9 et une commodit\\u00e9 de haut niveau, permettant une prise en charge multidevises pour accepter les paiements de diff\\u00e9rentes r\\u00e9gions.\",\"process_step_title\":\"\\u00c9tapes pour recevoir de l\'argent instantan\\u00e9ment avec QRPay Pro\",\"button_name\":\"Commencez \\u00e0 recevoir de l\'argent\",\"button_link\":\"agent\\/receive-money\",\"step_title\":\"Comment recevoir des fonds sur votre compte QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes simples pour recevoir des fonds rapidement et en toute s\\u00e9curit\\u00e9 sur votre compte QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0927\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\",\"sub_heading\":\"QRPay Pro \\u090f\\u091c\\u0947\\u0902\\u091f\\u094b\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0927\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0928\\u093e \\u0906\\u0938\\u093e\\u0928 \\u092c\\u0928\\u093e\\u0924\\u093e \\u0939\\u0948, \\u091a\\u093e\\u0939\\u0947 \\u0935\\u0939 \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915\\u094b\\u0902 \\u0938\\u0947 \\u0939\\u094b \\u092f\\u093e \\u0905\\u0928\\u094d\\u092f \\u090f\\u091c\\u0947\\u0902\\u091f\\u094b\\u0902 \\u0938\\u0947\\u0964 \\u0924\\u0947\\u091c \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u0923 \\u0915\\u0947 \\u0938\\u093e\\u0925, QRPay \\u092a\\u094d\\u0930\\u094b \\u092f\\u0939 \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948 \\u0915\\u093f \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u094b \\u0936\\u0940\\u0930\\u094d\\u0937 \\u0938\\u094d\\u0924\\u0930\\u0940\\u092f \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0914\\u0930 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0938\\u0902\\u0938\\u093e\\u0927\\u093f\\u0924 \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e\\u0924\\u093e \\u0939\\u0948, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0935\\u093f\\u092d\\u093f\\u0928\\u094d\\u0928 \\u0915\\u094d\\u0937\\u0947\\u0924\\u094d\\u0930\\u094b\\u0902 \\u0938\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u094d\\u0935\\u0940\\u0915\\u093e\\u0930 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092c\\u0939\\u0941-\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u0928 \\u0938\\u0915\\u094d\\u0937\\u092e \\u0939\\u094b\\u0924\\u093e \\u0939\\u0948\\u0964\",\"process_step_title\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0924\\u0941\\u0930\\u0902\\u0924 \\u0927\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u091a\\u0930\\u0923\",\"button_name\":\"\\u0927\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0928\\u093e \\u092a\\u094d\\u0930\\u093e\\u0930\\u0902\\u092d \\u0915\\u0930\\u0947\\u0902\",\"button_link\":\"agent\\/receive-money\",\"step_title\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0915\\u0948\\u0938\\u0947 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\",\"step_sub_title\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0936\\u0940\\u0918\\u094d\\u0930 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0928 \\u0938\\u0930\\u0932 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"6724bda066b3a\":{\"language\":{\"en\":{\"name\":\"Share Your QR Code or Account ID\"},\"ar\":{\"name\":\"\\u0645\\u0634\\u0627\\u0631\\u0643\\u0629 \\u0631\\u0645\\u0632 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639\\u0629 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u0623\\u0648 \\u0645\\u0639\\u0631\\u0641 \\u0627\\u0644\\u062d\\u0633\\u0627\\u0628\"},\"es\":{\"name\":\"Comparta su c\\u00f3digo QR o ID de cuenta\"},\"fr\":{\"name\":\"Partagez votre code QR ou votre identifiant de compte\"},\"hi\":{\"name\":\"\\u0905\\u092a\\u0928\\u093e \\u0915\\u094d\\u092f\\u0942\\u0906\\u0930 \\u0915\\u094b\\u0921 \\u092f\\u093e \\u0916\\u093e\\u0924\\u093e \\u0906\\u0908\\u0921\\u0940 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6724bda066b3a\"},\"6724bda707a61\":{\"language\":{\"en\":{\"name\":\"Confirm the Transfer Details\"},\"ar\":{\"name\":\"\\u0642\\u0645 \\u0628\\u0