INSERT INTO `frontend_header_section_pages` VALUES (25, 25, 'enterprise', '{\"images\":{\"section_image\":\"81c24481-93c9-4b8c-a39d-348bde89156e.webp\",\"step_image\":\"4c92b1ac-d191-460d-abcf-f0f02a871bbc.webp\"},\"language\":{\"en\":{\"heading\":\"Seamless Currency Exchange with QRPay Pro\",\"sub_heading\":\"QRPay Pro enables agents to exchange currencies in real-time, making it easier to handle international transactions. With competitive exchange rates and a straightforward process, agents can support clients and customers without the hassle of external currency exchanges.\",\"process_step_title\":\"Steps to Exchange Money Instantly with QRPay Pro\",\"button_name\":\"Start Exchanging Money\",\"button_link\":\"agent\\/money-exchange\",\"step_title\":\"How to Exchange Currencies in Your QRPay Pro Account\",\"step_sub_title\":\"Follow these quick steps to securely exchange funds in different currencies directly within QRPay Pro.\"},\"es\":{\"heading\":\"Cambio de divisas sin problemas con QRPay Pro\",\"sub_heading\":\"QRPay Pro permite a los agentes cambiar divisas en tiempo real, lo que facilita el manejo de transacciones internacionales. Con tipos de cambio competitivos y un proceso sencillo, los agentes pueden ayudar a clientes y clientes sin la molestia de los cambios de moneda externos.\",\"process_step_title\":\"Pasos para cambiar dinero al instante con QRPay Pro\",\"button_name\":\"Comience a intercambiar dinero\",\"button_link\":\"agent\\/money-exchange\",\"step_title\":\"C\\u00f3mo cambiar monedas en su cuenta QRPay Pro\",\"step_sub_title\":\"Siga estos r\\u00e1pidos pasos para intercambiar fondos de forma segura en diferentes monedas directamente dentro de QRPay Pro.\"},\"ar\":{\"heading\":\"\\u062a\\u0628\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0628\\u0633\\u0644\\u0627\\u0633\\u0629 \\u0645\\u0639 QRPay Pro\",\"sub_heading\":\"\\u064a\\u0645\\u0643\\u0651\\u0646 QRPay Pro \\u0627\\u0644\\u0648\\u0643\\u0644\\u0627\\u0621 \\u0645\\u0646 \\u062a\\u0628\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0641\\u064a \\u0627\\u0644\\u0648\\u0642\\u062a \\u0627\\u0644\\u0641\\u0639\\u0644\\u064a\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0647\\u0644 \\u0627\\u0644\\u062a\\u0639\\u0627\\u0645\\u0644 \\u0645\\u0639 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u062f\\u0648\\u0644\\u064a\\u0629. \\u0628\\u0641\\u0636\\u0644 \\u0623\\u0633\\u0639\\u0627\\u0631 \\u0627\\u0644\\u0635\\u0631\\u0641 \\u0627\\u0644\\u062a\\u0646\\u0627\\u0641\\u0633\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0628\\u0627\\u0634\\u0631\\u0629\\u060c \\u064a\\u0645\\u0643\\u0646 \\u0644\\u0644\\u0648\\u0643\\u0644\\u0627\\u0621 \\u062f\\u0639\\u0645 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0648\\u0627\\u0644\\u0632\\u0628\\u0627\\u0626\\u0646 \\u062f\\u0648\\u0646 \\u0645\\u062a\\u0627\\u0639\\u0628 \\u0635\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u062e\\u0627\\u0631\\u062c\\u064a\\u0629.\",\"process_step_title\":\"\\u062e\\u0637\\u0648\\u0627\\u062a \\u0644\\u062a\\u0628\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631 \\u0645\\u0639 QRPay Pro\",\"button_name\":\"\\u0627\\u0644\\u0628\\u062f\\u0621 \\u0641\\u064a \\u062a\\u0628\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\",\"button_link\":\"agent\\/money-exchange\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u062a\\u0628\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639\\u0629 \\u0644\\u062a\\u0628\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0634\\u0643\\u0644 \\u0622\\u0645\\u0646 \\u0628\\u0639\\u0645\\u0644\\u0627\\u062a \\u0645\\u062e\\u062a\\u0644\\u0641\\u0629 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629\\u064b \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 QRPay Pro.\"},\"fr\":{\"heading\":\"\\u00c9change de devises transparent avec QRPay Pro\",\"sub_heading\":\"QRPay Pro permet aux agents d\'\\u00e9changer des devises en temps r\\u00e9el, facilitant ainsi la gestion des transactions internationales. Avec des taux de change comp\\u00e9titifs et un processus simple, les agents peuvent assister les clients sans les tracas des \\u00e9changes de devises externes.\",\"process_step_title\":\"\\u00c9tapes pour \\u00e9changer de l\'argent instantan\\u00e9ment avec QRPay Pro\",\"button_name\":\"Commencez \\u00e0 \\u00e9changer de l\'argent\",\"button_link\":\"agent\\/money-exchange\",\"step_title\":\"Comment \\u00e9changer des devises dans votre compte QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes rapides pour \\u00e9changer en toute s\\u00e9curit\\u00e9 des fonds dans diff\\u00e9rentes devises directement dans QRPay Pro.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0928\\u093f\\u0930\\u094d\\u092c\\u093e\\u0927 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u090f\\u091c\\u0947\\u0902\\u091f\\u094b\\u0902 \\u0915\\u094b \\u0935\\u093e\\u0938\\u094d\\u0924\\u0935\\u093f\\u0915 \\u0938\\u092e\\u092f \\u092e\\u0947\\u0902 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u093e \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u092e\\u0947\\u0902 \\u0938\\u0915\\u094d\\u0937\\u092e \\u092c\\u0928\\u093e\\u0924\\u093e \\u0939\\u0948, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0905\\u0902\\u0924\\u0930\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u094b \\u0938\\u0902\\u092d\\u093e\\u0932\\u0928\\u093e \\u0906\\u0938\\u093e\\u0928 \\u0939\\u094b \\u091c\\u093e\\u0924\\u093e \\u0939\\u0948\\u0964 \\u092a\\u094d\\u0930\\u0924\\u093f\\u0938\\u094d\\u092a\\u0930\\u094d\\u0927\\u0940 \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0926\\u0930\\u094b\\u0902 \\u0914\\u0930 \\u090f\\u0915 \\u0938\\u0940\\u0927\\u0940 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0915\\u0947 \\u0938\\u093e\\u0925, \\u090f\\u091c\\u0947\\u0902\\u091f \\u092c\\u093e\\u0939\\u0930\\u0940 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0915\\u0940 \\u092a\\u0930\\u0947\\u0936\\u093e\\u0928\\u0940 \\u0915\\u0947 \\u092c\\u093f\\u0928\\u093e \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915\\u094b\\u0902 \\u0914\\u0930 \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915\\u094b\\u0902 \\u0915\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u0928 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\",\"process_step_title\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0924\\u0941\\u0930\\u0902\\u0924 \\u092a\\u0948\\u0938\\u0947 \\u090f\\u0915\\u094d\\u0938\\u091a\\u0947\\u0902\\u091c \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u091a\\u0930\\u0923\",\"button_name\":\"\\u092a\\u0948\\u0938\\u0947 \\u0915\\u093e \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0936\\u0941\\u0930\\u0942 \\u0915\\u0930\\u0947\\u0902\",\"button_link\":\"agent\\/money-exchange\",\"step_title\":\"\\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0913\\u0902 \\u0915\\u093e \\u0906\\u0926\\u093e\\u0928-\\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0948\\u0938\\u0947 \\u0915\\u0930\\u0947\\u0902\",\"step_sub_title\":\"\\u0938\\u0940\\u09