INSERT INTO `frontend_header_section_pages` VALUES (31, 31, 'enterprise', '{\"images\":{\"section_image\":\"dd394b87-6030-40b2-b451-442a41c94244.webp\",\"step_image\":\"14bd55c6-ddf2-4309-9df6-4beef0513723.webp\"},\"language\":{\"en\":{\"heading\":\"Quick and Convenient Mobile Top-Ups with QRPay Pro\",\"sub_heading\":\"QRPay Pro enables agents to easily top up mobile accounts for users, ensuring they stay connected without interruption.\",\"process_step_title\":\"Simple Steps to Top-Up Mobile Accounts\",\"button_name\":\"Start Mobile Top-Up Now\",\"button_link\":\"agent\\/mobile-topup\",\"step_title\":\"How to Top-Up Mobile Phones Using QRPay Pro\",\"step_sub_title\":\"How to Top-Up Mobile Phones Using QRPay Pro\"},\"es\":{\"heading\":\"Recargas m\\u00f3viles r\\u00e1pidas y c\\u00f3modas con QRPay Pro\",\"sub_heading\":\"QRPay Pro permite a los agentes recargar f\\u00e1cilmente las cuentas m\\u00f3viles de los usuarios, garantizando que permanezcan conectados sin interrupciones.\",\"process_step_title\":\"Pasos sencillos para recargar cuentas m\\u00f3viles\",\"button_name\":\"Iniciar recarga m\\u00f3vil ahora\",\"button_link\":\"agent\\/mobile-topup\",\"step_title\":\"C\\u00f3mo recargar tel\\u00e9fonos m\\u00f3viles usando QRPay Pro\",\"step_sub_title\":\"C\\u00f3mo recargar tel\\u00e9fonos m\\u00f3viles usando QRPay Pro\"},\"ar\":{\"heading\":\"Quick and Convenient Mobile Top-Ups with QRPay Pro\",\"sub_heading\":\"\\u064a\\u062a\\u064a\\u062d QRPay Pro \\u0644\\u0644\\u0648\\u0643\\u0644\\u0627\\u0621 \\u0625\\u0645\\u0643\\u0627\\u0646\\u064a\\u0629 \\u062a\\u0639\\u0628\\u0626\\u0629 \\u062d\\u0633\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0644\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u064a\\u0646 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0636\\u0645\\u0646 \\u0628\\u0642\\u0627\\u0626\\u0647\\u0645 \\u0639\\u0644\\u0649 \\u0627\\u062a\\u0635\\u0627\\u0644 \\u062f\\u0648\\u0646 \\u0627\\u0646\\u0642\\u0637\\u0627\\u0639.\",\"process_step_title\":\"\\u062e\\u0637\\u0648\\u0627\\u062a \\u0628\\u0633\\u064a\\u0637\\u0629 \\u0644\\u0625\\u0639\\u0627\\u062f\\u0629 \\u062a\\u0639\\u0628\\u0626\\u0629 \\u062d\\u0633\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644\",\"button_name\":\"\\u0627\\u0628\\u062f\\u0623 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"agent\\/mobile-topup\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0627\\u0644\\u0647\\u0648\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644\\u0629 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\",\"step_sub_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u062a\\u0639\\u0628\\u0626\\u0629 \\u0631\\u0635\\u064a\\u062f \\u0627\\u0644\\u0647\\u0648\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644\\u0629 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\"},\"fr\":{\"heading\":\"Recharges mobiles rapides et pratiques avec QRPay Pro\",\"sub_heading\":\"QRPay Pro permet aux agents de recharger facilement les comptes mobiles des utilisateurs, garantissant ainsi qu\'ils restent connect\\u00e9s sans interruption.\",\"process_step_title\":\"\\u00c9tapes simples pour recharger les comptes mobiles\",\"button_name\":\"Commencez la recharge mobile maintenant\",\"button_link\":\"agent\\/mobile-topup\",\"step_title\":\"Comment recharger des t\\u00e9l\\u00e9phones mobiles \\u00e0 l\'aide de QRPay Pro\",\"step_sub_title\":\"Comment recharger des t\\u00e9l\\u00e9phones mobiles \\u00e0 l\'aide de QRPay Pro\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u