INSERT INTO `frontend_header_section_pages` VALUES (32, 32, 'enterprise', '{\"images\":{\"section_image\":\"c4ee9177-b2ac-4374-aead-2990abf37daa.webp\",\"step_image\":\"ee4c38f2-50eb-4d40-8aac-6f8248ea5b3b.webp\"},\"language\":{\"en\":{\"heading\":\"Fast and Secure Remittance Services with QRPay Pro\",\"sub_heading\":\"QRPay Pro allows agents to send money internationally, ensuring funds reach users quickly and securely.\",\"process_step_title\":\"Easy Steps to Send Remittances\",\"button_name\":\"Start Send Remittance Now\",\"button_link\":\"agent\\/remittance\",\"step_title\":\"How to Remit Funds Using QRPay Pro\",\"step_sub_title\":\"Follow these straightforward steps to send money to users quickly and reliably.\"},\"es\":{\"heading\":\"Servicios de remesas r\\u00e1pidos y seguros con QRPay Pro\",\"sub_heading\":\"QRPay Pro permite a los agentes enviar dinero internacionalmente, garantizando que los fondos lleguen a los usuarios de forma r\\u00e1pida y segura.\",\"process_step_title\":\"Pasos sencillos para enviar remesas\",\"button_name\":\"Comience a enviar remesas ahora\",\"button_link\":\"agent\\/remittance\",\"step_title\":\"C\\u00f3mo enviar fondos usando QRPay Pro\",\"step_sub_title\":\"Siga estos sencillos pasos para enviar dinero a los usuarios de forma r\\u00e1pida y confiable.\"},\"ar\":{\"heading\":\"\\u062e\\u062f\\u0645\\u0627\\u062a \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0633\\u0631\\u064a\\u0639\\u0629 \\u0648\\u0622\\u0645\\u0646\\u0629 \\u0645\\u0639 QRPay Pro\",\"sub_heading\":\"\\u064a\\u062a\\u064a\\u062d QRPay Pro \\u0644\\u0644\\u0648\\u0643\\u0644\\u0627\\u0621 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u062f\\u0648\\u0644\\u064a\\u064b\\u0627\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0636\\u0645\\u0646 \\u0648\\u0635\\u0648\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u064a\\u0646 \\u0628\\u0633\\u0631\\u0639\\u0629 \\u0648\\u0623\\u0645\\u0627\\u0646.\",\"process_step_title\":\"\\u062e\\u0637\\u0648\\u0627\\u062a \\u0633\\u0647\\u0644\\u0629 \\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u062d\\u0648\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0627\\u0644\\u064a\\u0629\",\"button_name\":\"\\u0627\\u0628\\u062f\\u0623 \\u0628\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"agent\\/remittance\",\"step_title\":\"\\u0643\\u064a\\u0641\\u064a\\u0629 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 QRPay Pro\",\"step_sub_title\":\"\\u0627\\u062a\\u0628\\u0639 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u064a\\u0646 \\u0628\\u0633\\u0631\\u0639\\u0629 \\u0648\\u0628\\u0634\\u0643\\u0644 \\u0645\\u0648\\u062b\\u0648\\u0642.\"},\"fr\":{\"heading\":\"Services de transfert de fonds rapides et s\\u00e9curis\\u00e9s avec QRPay Pro\",\"sub_heading\":\"QRPay Pro permet aux agents d\'envoyer de l\'argent \\u00e0 l\'international, garantissant ainsi que les fonds parviennent aux utilisateurs rapidement et en toute s\\u00e9curit\\u00e9.\",\"process_step_title\":\"\\u00c9tapes faciles pour envoyer des fonds\",\"button_name\":\"Commencez \\u00e0 envoyer des fonds maintenant\",\"button_link\":\"agent\\/remittance\",\"step_title\":\"Comment transf\\u00e9rer des fonds \\u00e0 l\'aide de QRPay Pro\",\"step_sub_title\":\"Suivez ces \\u00e9tapes simples pour envoyer de l\\u2019argent aux utilisateurs de mani\\u00e8re rapide et fiable.\"},\"hi\":{\"heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0924\\u0947\\u091c\\u093c \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u0938\\u0947\\u0935\\u093e\\u090f\\u0901\",\"sub_heading\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u090f\\u091c\\u0947\\u0902\\u091f\\u094b\\u0902 \\u0915\\u094b \\u0905\\u0902\\u0924\\u0930\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0938\\u094d\\u0924\\u0930 \\u092a\\u0930 \\u092a\\u0948\\u0938\\u093e \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0940 \\u0905\\u0928\\u0941\\u092e\\u0924\\u093f \\u0926\\u0947\\u0924\\u093e \\u0939\\u0948, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u092f\\u0939 \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0939\\u094b\\u0924\\u093e \\u0939\\u0948 \\u0915\\u093f \\u0927\\u0928 \\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e\\u0913\\u0902 \\u0924\\u0915 \\u091c\\u0932\\u094d\\u0926\\u0940 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u092a\\u0939\\u0941\\u0902\\u091a\\u0947\\u0964\",\"process_step_title\":\"\\u0927\\u0928 \\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u0906\\u0938\\u093e\\u0928 \\u091a\\u0930\\u0923\",\"button_name\":\"\\u0905\\u092d\\u0940 \\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u092d\\u0947\\u091c\\u0928\\u093e \\u092a\\u094d\\u0930\\u093e\\u0930\\u0902\\u092d \\u0915\\u0930\\u0947\\u0902\",\"button_link\":\"agent\\/remittance\",\"step_title\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u0915\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0947\\u0902\",\"step_sub_title\":\"\\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e\\u0913\\u0902 \\u0915\\u094b \\u0936\\u0940\\u0918\\u094d\\u0930\\u0924\\u093e \\u0914\\u0930 \\u0935\\u093f\\u0936\\u094d\\u0935\\u0938\\u0928\\u0940\\u092f \\u0930\\u0942\\u092a \\u0938\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0907\\u0928 \\u0938\\u0930\\u0932 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0947\\u0902\\u0964\"}},\"items\":{\"6724c8cb3013b\":{\"language\":{\"en\":{\"name\":\"Log In to Your Account\"},\"ar\":{\"name\":\"\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0643\"},\"es\":{\"name\":\"Inicie sesi\\u00f3n en su cuenta\"},\"fr\":{\"name\":\"Connectez-vous \\u00e0 votre compte\"},\"hi\":{\"name\":\"\\u0905\\u092a\\u0928\\u0947 \\u0905\\u0915\\u093e\\u0909\\u0902\\u091f \\u092e\\u0947\\u0902 \\u0932\\u0949\\u0917 \\u0907\\u0928 \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6724c8cb3013b\"},\"6724c8d013fd0\":{\"language\":{\"en\":{\"name\":\"Select the Remittance Option\"},\"ar\":{\"name\":\"\\u062d\\u062f\\u062f \\u062e\\u064a\\u0627\\u0631 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\"},\"es\":{\"name\":\"Seleccione la opci\\u00f3n de remesa\"},\"fr\":{\"name\":\"S\\u00e9lectionnez l\'option de versement\"},\"hi\":{\"name\":\"\\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a \\u091a\\u0941\\u0928\\u0947\\u0902\"}},\"id\":\"6724c8d013fd0\"},\"6724c8d4c78e5\":{\"language\":{\"en\":{\"name\":\"Enter Recipient Details\"},\"ar\":{\"name\":\"\\u0623\\u062f\\u062e\\u0644 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645\"},\"es\":{\"name\":\"Ingrese los detalles del destinatario\"},\"fr\":{\"name\":\"Saisir les d\\u00e9tails du destinataire\"},\"hi\":{\"name\":\"\\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924\\u0915\\u0930\\u094d\\u0924\\u093e \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0926\\u0930\\u094d\\u091c \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6724c8d4c78e5\"},\"6724c8da7b20e\":{\"language\":{\"en\":{\"name\":\"Choose the Amount to Send\"},\"ar\":{\"name\":\"\\u0627\\u062e\\u062a\\u0631 \\u0627\\u0644\\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0645\\u0631\\u0627\\u062f \\u0625\\u0631\\u0633\\u0627\\u0644\\u0647\"},\"es\":{\"name\":\"Elija la cantidad a enviar\"},\"fr\":{\"name\":\"Choisissez le montant \\u00e0 envoyer\"},\"hi\":{\"name\":\"\\u092d\\u0947\\u091c\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0930\\u093e\\u0936\\u093f \\u091a\\u0941\\u0928\\u0947\\u0902\"}},\"id\":\"6724c8da7b20e\"},\"6724c8e103e92\":{\"language\":{\"en\":{\"name\":\"Review Transaction Details\"},\"ar\":{\"name\":\"\\u0645\\u0631\\u0627\\u062c\\u0639\\u0629 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0629\"},\"es\":{\"name\":\"Revisar los detalles de la transacci\\u00f3n\"},\"fr\":{\"name\":\"V\\u00e9rifier les d\\u00e9tails de la transaction\"},\"hi\":{\"name\":\"\\u0932\\u0947\\u0928-\\u0926\\u0947\\u0928 \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0915\\u0940 \\u0938\\u092e\\u0940\\u0915\\u094d\\u0937\\u093e \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6724c8e103e92\"},\"6724c8e6b507a\":{\"language\":{\"en\":{\"name\":\"Confirm and Complete the Remittance\"},\"ar\":{\"name\":\"\\u062a\\u0623\\u0643\\u064a\\u062f \\u0648\\u0625\\u0643\\u0645\\u0627\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\"},\"es\":{\"name\":\"Confirmar y completar la remesa\"},\"fr\":{\"name\":\"Confirmer et compl\\u00e9ter le versement\"},\"hi\":{\"name\":\"\\u092a\\u094d\\u0930\\u0947\\u0937\\u0923 \\u0915\\u0940 \\u092a\\u0941\\u0937\\u094d\\u091f\\u093f \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u092a\\u0942\\u0930\\u093e \\u0915\\u0930\\u0947\\u0902\"}},\"id\":\"6724c8e6b507a\"}}}', 1, 1, '2024-11-01 18:25:39', '2024-12-12 18:31:35');

-- ----------------------------
-- Table structure for frontend_header_sections
-- ----------------------------
DROP TABLE IF EXISTS `frontend_header_sections`;
CREATE TABLE `frontend_header_sections`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` enum('personal','business','enterprise','company') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `icon` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `title` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `sub_title` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `last_edit_by` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp(0) NULL DEFAULT NULL,
  `updated_at` timestamp(0) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `frontend_header_sections_slug_unique`(`slug`) USING BTREE,
  INDEX `frontend_header_sections_last_edit_by_foreign`(`last_edit_by`) USING BTREE,
  CONSTRAINT `frontend_header_sections_last_edit_by_foreign` FOREIGN KEY (`last_edit_by`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

