INSERT INTO `frontend_header_sections` VALUES (1, 'personal', NULL, '{\"language\":{\"en\":{\"icon\":\"fas fa-receipt\"},\"ar\":{\"icon\":\"fas fa-receipt\"},\"es\":{\"icon\":\"fas fa-receipt\"},\"fr\":{\"icon\":\"fas fa-receipt\"},\"hi\":{\"icon\":\"fas fa-receipt\"}}}', '{\"language\":{\"en\":{\"title\":\"Receive Money\"},\"ar\":{\"title\":\"\\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0645\\u0627\\u0644\"},\"es\":{\"title\":\"Recibir dinero\"},\"fr\":{\"title\":\"Recevoir de l\'argent\"},\"hi\":{\"title\":\"\\u0927\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\"}}}', '{\"language\":{\"en\":{\"sub_title\":\"Securely receive funds directly into your QRPay Pro account\\u2014fast, flexible, and hassle-free.\"},\"ar\":{\"sub_title\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0634\\u0643\\u0644 \\u0622\\u0645\\u0646 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 - \\u0633\\u0631\\u064a\\u0639 \\u0648\\u0645\\u0631\\u0646 \\u0648\\u062e\\u0627\\u0644\\u064a \\u0645\\u0646 \\u0627\\u0644\\u0645\\u062a\\u0627\\u0639\\u0628.\"},\"es\":{\"sub_title\":\"Reciba fondos de forma segura directamente en su cuenta QRPay Pro: r\\u00e1pido, flexible y sin complicaciones.\"},\"fr\":{\"sub_title\":\"Recevez des fonds en toute s\\u00e9curit\\u00e9 directement sur votre compte QRPay Pro : rapide, flexible et sans tracas.\"},\"hi\":{\"sub_title\":\"\\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0938\\u0940\\u0927\\u0947 \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902 - \\u0924\\u0947\\u091c\\u093c, \\u0932\\u091a\\u0940\\u0932\\u093e \\u0914\\u0930 \\u092a\\u0930\\u0947\\u0936\\u093e\\u0928\\u0940 \\u092e\\u0941\\u0915\\u094d\\u0924\\u0964\"}}}', 1, 1, '2024-10-31 08:58:04', '2024-11-06 18:59:29');
INSERT INTO `frontend_header_sections` VALUES (2, 'company', 'about', '{\"language\":{\"en\":{\"icon\":\"fas fa-plus-circle\"},\"es\":{\"icon\":\"fas fa-plus-circle\"},\"ar\":{\"icon\":\"fas fa-plus-circle\"},\"fr\":{\"icon\":\"fas fa-plus-circle\"},\"hi\":{\"icon\":\"fas fa-plus-circle\"}}}', '{\"language\":{\"en\":{\"title\":\"About Us\"},\"es\":{\"title\":\"Sobre nosotros\"},\"ar\":{\"title\":\"\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0639\\u0646\\u0627\"},\"fr\":{\"title\":\"\\u00c0 propos de nous\"},\"hi\":{\"title\":\"\\u0939\\u092e\\u093e\\u0930\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902\"}}}', '{\"language\":{\"en\":{\"sub_title\":\"Discover our mission to simplify payments with cutting-edge technology.\"},\"es\":{\"sub_title\":\"Descubra nuestra misi\\u00f3n de simplificar los pagos con tecnolog\\u00eda de punta.\"},\"ar\":{\"sub_title\":\"\\u0627\\u0643\\u062a\\u0634\\u0641 \\u0645\\u0647\\u0645\\u062a\\u0646\\u0627 \\u0644\\u062a\\u0628\\u0633\\u064a\\u0637 \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0627\\u0644\\u062a\\u0643\\u0646\\u0648\\u0644\\u0648\\u062c\\u064a\\u0627 \\u0627\\u0644\\u0645\\u062a\\u0637\\u0648\\u0631\\u0629.\"},\"fr\":{\"sub_title\":\"D\\u00e9couvrez notre mission de simplifier les paiements gr\\u00e2ce \\u00e0 une technologie de pointe.\"},\"hi\":{\"sub_title\":\"\\u0905\\u0924\\u094d\\u092f\\u093e\\u0927\\u0941\\u0928\\u093f\\u0915 \\u092a\\u094d\\u0930\\u094c\\u0926\\u094d\\u092f\\u094b\\u0917\\u093f\\u0915\\u0940 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u094b \\u0938\\u0930\\u0932 \\u092c\\u0928\\u093e\\u0928\\u0947 \\u0915\\u0947 \\u0939\\u092e\\u093e\\u0930\\u0947 \\u092e\\u093f\\u0936\\u0928 \\u0915\\u0940 \\u0916\\u094b\\u091c \\u0915\\u0930\\u0947\\u0902\\u0964\"}}}', 1, 1, '2024-10-31 13:09:52', '2024-12-12 19:06:17');
INSERT INTO `frontend_header_sections` VALUES (3, 'company', 'service', '{\"language\":{\"en\":{\"icon\":\"fas fa-paper-plane\"},\"es\":{\"icon\":null},\"ar\":{\"icon\":\"fas fa-paper-plane\"},\"fr\":{\"icon\":\"fas fa-paper-plane\"},\"hi\":{\"icon\":\"fas fa-paper-plane\"}}}', '{\"language\":{\"en\":{\"title\":\"Service Details\"},\"es\":{\"title\":\"Detalles del servicio\"},\"ar\":{\"title\":\"\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u062e\\u062f\\u0645\\u0629\"},\"fr\":{\"title\":\"D\\u00e9tails des services\"},\"hi\":{\"title\":\"\\u0938\\u0947\\u0935\\u093e \\u0935\\u093f\\u0935\\u0930\\u0923\"}}}', '{\"language\":{\"en\":{\"sub_title\":\"View comprehensive information about QRPay  Pro\'s services, including features, fees, and supported payment options.\"},\"es\":{\"sub_title\":\"Vea informaci\\u00f3n completa sobre los servicios de QRPay Pro, incluidas funciones, tarifas y opciones de pago admitidas.\"},\"ar\":{\"sub_title\":\"\\u0639\\u0631\\u0636 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0634\\u0627\\u0645\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u062e\\u062f\\u0645\\u0627\\u062a QRPay Pro\\u060c \\u0628\\u0645\\u0627 \\u0641\\u064a \\u0630\\u0644\\u0643 \\u0627\\u0644\\u0645\\u064a\\u0632\\u0627\\u062a \\u0648\\u0627\\u0644\\u0631\\u0633\\u0648\\u0645 \\u0648\\u062e\\u064a\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u0645\\u062f\\u0639\\u0648\\u0645\\u0629.\"},\"fr\":{\"sub_title\":\"Consultez des informations compl\\u00e8tes sur les services de QRPay Pro, y compris les fonctionnalit\\u00e9s, les frais et les options de paiement prises en charge.\"},\"hi\":{\"sub_title\":\"\\u0938\\u0941\\u0935\\u093f\\u0927\\u093e\\u0913\\u0902, \\u0936\\u0941\\u0932\\u094d\\u0915 \\u0914\\u0930 \\u0938\\u092e\\u0930\\u094d\\u0925\\u093f\\u0924 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a\\u094b\\u0902 \\u0938\\u0939\\u093f\\u0924 QRPay Pro \\u0915\\u0940 \\u0938\\u0947\