INSERT INTO `frontend_header_sections` VALUES (18, 'business', NULL, '{\"language\":{\"en\":{\"icon\":\"fas fa-receipt\"},\"ar\":{\"icon\":\"fas fa-receipt\"},\"es\":{\"icon\":\"fas fa-receipt\"},\"fr\":{\"icon\":\"fas fa-receipt\"},\"hi\":{\"icon\":\"fas fa-receipt\"}}}', '{\"language\":{\"en\":{\"title\":\"Receive Money\"},\"ar\":{\"title\":\"\\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0645\\u0627\\u0644\"},\"es\":{\"title\":\"Recibir dinero\"},\"fr\":{\"title\":\"Recevoir de l\'argent\"},\"hi\":{\"title\":\"\\u0927\\u0928 \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0947\\u0902\"}}}', '{\"language\":{\"en\":{\"sub_title\":\"Accept payments seamlessly with QRPay Pro\\u2019s permanent QR Code feature.\"},\"ar\":{\"sub_title\":\"\\u0627\\u0642\\u0628\\u0644 \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0628\\u0633\\u0644\\u0627\\u0633\\u0629 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0645\\u064a\\u0632\\u0629 \\u0631\\u0645\\u0632 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639\\u0629 \\u0627\\u0644\\u062f\\u0627\\u0626\\u0645 \\u0641\\u064a QRPay Pro.\"},\"es\":{\"sub_title\":\"Acepte pagos sin problemas con la funci\\u00f3n de c\\u00f3digo QR permanente de QRPay Pro.\"},\"fr\":{\"sub_title\":\"Acceptez les paiements en toute transparence gr\\u00e2ce \\u00e0 la fonctionnalit\\u00e9 QR Code permanente de QRPay Pro.\"},\"hi\":{\"sub_title\":\"QRPay Pro \\u0915\\u0940 \\u0938\\u094d\\u0925\\u093e\\u092f\\u0940 QR \\u0915\\u094b\\u0921 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0928\\u093f\\u0930\\u094d\\u092c\\u093e\\u0927 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u094d\\u0935\\u0940\\u0915\\u093e\\u0930 \\u0915\\u0930\\u0947\\u0902\\u0964\"}}}', 1, 1, '2024-10-31 16:44:11', '2024-11-06 17:15:56');
INSERT INTO `frontend_header_sections` VALUES (19, 'business', NULL, '{\"language\":{\"en\":{\"icon\":\"fas fa-exchange-alt\"},\"ar\":{\"icon\":\"fas fa-exchange-alt\"},\"es\":{\"icon\":\"fas fa-exchange-alt\"},\"fr\":{\"icon\":\"fas fa-exchange-alt\"},\"hi\":{\"icon\":\"fas fa-exchange-alt\"}}}', '{\"language\":{\"en\":{\"title\":\"Exchange Money\"},\"ar\":{\"title\":\"\\u0635\\u0631\\u0641 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\"},\"es\":{\"title\":\"Cambiar dinero\"},\"fr\":{\"title\":\"\\u00c9changer de l\'argent\"},\"hi\":{\"title\":\"\\u0935\\u093f\\u0926\\u0947\\u0936\\u0940 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\"}}}', '{\"language\":{\"en\":{\"sub_title\":\"Easily convert currencies within your QRPay Pro account for seamless global transactions.\"},\"ar\":{\"sub_title\":\"\\u0642\\u0645 \\u0628\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u062f\\u0627\\u062e\\u0644 \\u062d\\u0633\\u0627\\u0628 QRPay Pro \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u0644\\u0625\\u062c\\u0631\\u0627\\u0621 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0639\\u0627\\u0644\\u0645\\u064a\\u0629 \\u0633\\u0644\\u0633\\u0629.\"},\"es\":{\"sub_title\":\"Convierta f\\u00e1cilmente monedas dentro de su cuenta QRPay Pro para realizar transacciones globales sin problemas.\"},\"fr\":{\"sub_title\":\"Convertissez facilement les devises au sein de votre compte QRPay Pro pour des transactions mondiales transparentes.\"},\"hi\":{\"sub_title\":\"\\u0928\\u093f\\u0930\\u094d\\u092c\\u093e\\u0927 \\u0935\\u0948\\u0936\\u094d\\u0935\\u093f\\u0915 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0905\\u092a\\u0928\\u0947 QRPay \\u092a\\u094d\\u0930\\u094b \\u0916\\u093e\\u0924\\u0947 \\u092e\\u0947\\u0902 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u090f\\u0902 \\u092a\\u0930\\u093f\\u0935\\u0930\\u0