INSERT INTO `frontend_header_sections` VALUES (22, 'business', NULL, '{\"language\":{\"en\":{\"icon\":\"fas fa-tools\"},\"ar\":{\"icon\":\"fas fa-tools\"},\"es\":{\"icon\":\"fas fa-tools\"},\"fr\":{\"icon\":\"fas fa-tools\"},\"hi\":{\"icon\":\"fas fa-tools\"}}}', '{\"language\":{\"en\":{\"title\":\"Gateway Setting\"},\"ar\":{\"title\":\"\\u0625\\u0639\\u062f\\u0627\\u062f \\u0627\\u0644\\u0628\\u0648\\u0627\\u0628\\u0629\"},\"es\":{\"title\":\"Configuraci\\u00f3n de puerta de enlace\"},\"fr\":{\"title\":\"Param\\u00e8tre de passerelle\"},\"hi\":{\"title\":\"\\u0917\\u0947\\u091f\\u0935\\u0947 \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917\"}}}', '{\"language\":{\"en\":{\"sub_title\":\"Seamlessly integrate and customize your payment gateway with QRPay Pro for a streamlined checkout experience.\"},\"ar\":{\"sub_title\":\"\\u0642\\u0645 \\u0628\\u062f\\u0645\\u062c \\u0648\\u062a\\u062e\\u0635\\u064a\\u0635 \\u0628\\u0648\\u0627\\u0628\\u0629 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643 \\u0628\\u0633\\u0644\\u0627\\u0633\\u0629 \\u0645\\u0639 QRPay Pro \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u062a\\u062c\\u0631\\u0628\\u0629 \\u062f\\u0641\\u0639 \\u0645\\u0628\\u0633\\u0637\\u0629.\"},\"es\":{\"sub_title\":\"Integre y personalice perfectamente su pasarela de pago con QRPay Pro para una experiencia de pago optimizada.\"},\"fr\":{\"sub_title\":\"Int\\u00e9grez et personnalisez en toute transparence votre passerelle de paiement avec QRPay Pro pour une exp\\u00e9rience de paiement simplifi\\u00e9e.\"},\"hi\":{\"sub_title\":\"\\u0938\\u0941\\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093f\\u0924 \\u091a\\u0947\\u0915\\u0906\\u0909\\u091f \\u0905\\u0928\\u0941\\u092d\\u0935 \\u0915\\u0947 \\u0932\\u093f\\u090f QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0905\\u092a\\u0928\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0917\\u0947\\u091f\\u0935\\u0947 \\u0915\\u094b \\u0938\\u0939\\u091c\\u0924\\u093e \\u0938\\u0947 \\u090f\\u0915\\u0940\\u0915\\u0943\\u0924 \\u0914\\u0930 \\u0905\\u0928\\u0941\\u0915\\u0942\\u0932\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902\\u0964\"}}}', 1, 1, '2024-10-31 16:48:10', '2024-11-06 17:55:36');
INSERT INTO `frontend_header_sections` VALUES (23, 'business', NULL, '{\"language\":{\"en\":{\"icon\":\"fas fa-tools\"},\"ar\":{\"icon\":\"fas fa-tools\"},\"es\":{\"icon\":\"fas fa-tools\"},\"fr\":{\"icon\":\"fas fa-tools\"},\"hi\":{\"icon\":\"fas fa-tools\"}}}', '{\"language\":{\"en\":{\"title\":\"API Key\"},\"ar\":{\"title\":\"\\u0645\\u0641\\u062a\\u0627\\u062d \\u0648\\u0627\\u062c\\u0647\\u0629 \\u0628\\u0631\\u0645\\u062c\\u0629 \\u0627\\u0644\\u062a\\u0637\\u0628\\u064a\\u0642\\u0627\\u062a\"},\"es\":{\"title\":\"Clave API\"},\"fr\":{\"title\":\"Cl\\u00e9 API\"},\"hi\":{\"title\":\"\\u090f\\u092a\\u0940\\u0906\\u0908 \\u0915\\u0941\\u0902\\u091c\\u0940\"}}}', '{\"language\":{\"en\":{\"sub_title\":\"Generate and control API keys to securely integrate QRPay Pro\\u2019s payment features into your system.\"},\"ar\":{\"sub_title\":\"\\u0642\\u0645 \\u0628\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0645\\u0641\\u0627\\u062a\\u064a\\u062d API \\u0648\\u0627\\u0644\\u062a\\u062d\\u0643\\u0645 \\u0641\\u064a\\u0647\\u0627 \\u0644\\u062f\\u0645\\u062c \\u0645\\u064a\\u0632\\u0627\\u062a \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0640 QRPay Pro \\u0628\\u0634\\u0643\\u0644 \\u0622\\u0645\\u0646 \\u0641\\u064a \\u0646\\u0638\\u0627\\u0645\\u0643.\"},\"es\":{\"sub_title\":\"Genere y controle claves API para integrar de forma segura las funciones de pago de QRPay Pro en su sistema.\"},\"fr\":{\"sub_title\":\"G\\u00e9n\\u00e9rez et contr\\u00f4lez des cl\\u00e9s API pour int\\u00e9grer en toute s\\u00e9curit\\u00e9 les fonctionnalit\\u00e9s de paiement de QRPay Pro dans votre syst\\u00e8me.\"},\"hi\":{\"sub_title\":\"QRPay \\u092a\\u094d\\u0930\\u094b \\u0915\\u0940 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e\\u0913\\u0902 \\u0915\\u094b \\u0905\\u092a\\u0928\\u0947 \\u0938\\u093f\\u0938\\u094d\\u091f\\u092e \\u092e\\u0947\\u0902 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u093