\\u0940 \\u0915\\u0940 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0915\\u0948\\u0938\\u0947 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902?<\\/p><p>\\u0938\\u092d\\u0940 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0940 \\u0917\\u0908 \\u0938\\u0902\\u0935\\u0947\\u0926\\u0928\\u0936\\u0940\\u0932\\/\\u0915\\u094d\\u0930\\u0947\\u0921\\u093f\\u091f \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 Stripe \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u092d\\u0947\\u091c\\u0940 \\u091c\\u093e\\u0924\\u0940 \\u0939\\u0948\\u0964<\\/p><p>\\u0915\\u093f\\u0938\\u0940 \\u0932\\u0947\\u0928-\\u0926\\u0947\\u0928 \\u0915\\u0947 \\u092c\\u093e\\u0926, \\u0906\\u092a\\u0915\\u0940 \\u0928\\u093f\\u091c\\u0940 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 (\\u0915\\u094d\\u0930\\u0947\\u0921\\u093f\\u091f \\u0915\\u093e\\u0930\\u094d\\u0921, \\u0938\\u093e\\u092e\\u093e\\u091c\\u093f\\u0915 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0928\\u0902\\u092c\\u0930, \\u0935\\u093f\\u0924\\u094d\\u0924\\u0940\\u092f \\u0935\\u093f\\u0935\\u0930\\u0923, \\u0907\\u0924\\u094d\\u092f\\u093e\\u0926\\u093f) \\u0939\\u092e\\u093e\\u0930\\u0947 \\u0915\\u0930\\u094d\\u092e\\u091a\\u093e\\u0930\\u093f\\u092f\\u094b\\u0902 \\u0915\\u0947 \\u092a\\u093e\\u0938 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0928\\u0939\\u0940\\u0902 \\u0930\\u0939\\u0947\\u0917\\u0940\\u0964<\\/p><p>\\u0915\\u094d\\u092f\\u093e \\u0939\\u092e \\u092c\\u093e\\u0939\\u0930\\u0940 \\u092a\\u0915\\u094d\\u0937\\u094b\\u0902 \\u0915\\u094b \\u0915\\u094b\\u0908 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0926\\u0947\\u0924\\u0947 \\u0939\\u0948\\u0902?<\\/p><p>\\u0939\\u092e \\u0935\\u094d\\u092f\\u0915\\u094d\\u0924\\u093f\\u0917\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u092a\\u0939\\u091a\\u093e\\u0928 \\u092f\\u094b\\u0917\\u094d\\u092f \\u0921\\u0947\\u091f\\u093e \\u0915\\u094b \\u092c\\u0947\\u091a\\u0924\\u0947, \\u090f