 \\u0915\\u0930\\u0924\\u0947 \\u092f\\u093e \\u0915\\u093f\\u0938\\u0940 \\u092d\\u0940 \\u092e\\u093e\\u092e\\u0932\\u0947 \\u092e\\u0947\\u0902 \\u092c\\u093e\\u0939\\u0930\\u0940 \\u0938\\u092e\\u0942\\u0939\\u094b\\u0902 \\u0915\\u094b \\u0928\\u0939\\u0940\\u0902 \\u0926\\u0947\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0907\\u0938\\u092e\\u0947\\u0902 \\u092d\\u0930\\u094b\\u0938\\u0947\\u092e\\u0902\\u0926 \\u092c\\u093e\\u0939\\u0930\\u0940 \\u0932\\u094b\\u0917 \\u0936\\u093e\\u092e\\u093f\\u0932 \\u0928\\u0939\\u0940\\u0902 \\u0939\\u0948\\u0902 \\u091c\\u094b \\u0939\\u092e\\u093e\\u0930\\u0940 \\u0938\\u093e\\u0907\\u091f \\u0915\\u094b \\u091a\\u0932\\u093e\\u0928\\u0947, \\u0939\\u092e\\u093e\\u0930\\u0947 \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0915\\u093e \\u0928\\u0947\\u0924\\u0943\\u0924\\u094d\\u0935 \\u0915\\u0930\\u0928\\u0947 \\u092f\\u093e \\u0906\\u092a\\u0915\\u094b \\u0938\\u092e\\u093e\\u092f\\u094b\\u091c\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u092e\\u0947\\u0902 \\u0939\\u092e\\u093e\\u0930\\u0940 \\u0938\\u0939\\u093e\\u092f\\u0924\\u093e \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0915\\u094d\\u092f\\u094b\\u0902\\u0915\\u093f \\u0935\\u0947 \\u0938\\u092e\\u0942\\u0939 \\u0907\\u0938 \\u0921\\u0947\\u091f\\u093e \\u0915\\u094b \\u0928\\u093f\\u091c\\u0940 \\u0930\\u0916\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0938\\u0939\\u092e\\u0924\\u093f \\u0926\\u0947\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0939\\u092e \\u0906\\u092a\\u0915\\u093e \\u0921\\u0947\\u091f\\u093e \\u0924\\u092c \\u092d\\u0940 \\u0921\\u093f\\u0932\\u0940\\u0935\\u0930 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902 \\u091c\\u092c \\u0939\\u092e \\u092e\\u093e\\u0928\\u0924\\u0947 \\u0939\\u0948\\u0902 \\u0915\\u093f \\u0921\\u093f\\u0938\\u094d\\u091a\\u093e\\u0930\\u094d\\u091c \\u0915\\u093e\\u0928\\u0942\\u0928 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0928\\u0947, \\u0939\\u092e\\u093e\\u0930\\u0940 \\u0938\\u093e\\u0907\\u091f \\u0930\\u0923\\u0928\\u0940\\u0924\\u093f\\u092f\\u094b\\u0902 \\u0915\\u094b \\u0932\\u093e\\u0917\\u0942 \\u0915\\u0930\\u0928\\u0947, \\u092f\\u093e \\u0905\\u092a\\u0928\\u0947 \\u092f\\u093e \\u0926\\u0942\\u0938\\u0930\\u094b\\u0902 \\u0915\\u0947 \\u0905\\u0927\\u093f\\u0915\\u093e\\u0930\\u094b\\u0902, \\u0938\\u0902\\u092a\\u0924\\u094d\\u0924\\u093f \\u092f\\u093e \\u0915\\u0932\\u094d\\u092f\\u093e\\u0923 \\u0915\\u094b \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0909\\u092a\\u092f\\u0941\\u0915\\u094d\\u0924 \\u0939\\u0948\\u0964<\\/p><p>\\u092c\\u091a\\u094d\\u091a\\u094b\\u0902 \\u0915\\u0940 \\u0911\\u0928\\u0932\\u093e\\u0907\\u0928 \\u0917\\u094b\\u092a\\u0928\\u0940\\u092f\\u0924\\u093e \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0905\\u0927\\u093f\\u0928\\u093f\\u092f\\u092e \\u0915\\u093e \\u0905\\u0928\\u0941\\u092a\\u093e\\u0932\\u0928<\\/p><p>\\u0939\\u092e COPPA (\\u092c\\u091a\\u094d\\u091a\\u094b\\u0902 \\u0915\\u0940 \\u0911\\u0928\\u0932\\u093e\\u0907\\u0928 \\u0917\\u094b\\u092a\\u0928\\u0940\\u092f\\u0924\\u093e \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0905\\u0927\\u093f\\u0928\\u093f\\u092f\\u092e) \\u0915\\u0940 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915\\u0924\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0905\\u0928\\u0941\\u0930\\u0942\\u092a \\u0939\\u0948\\u0902, \\u0939\\u092e 13 \\u0935\\u0930\\u094d\\u0937 \\u0938\\u0947 \\u0915\\u092e \\u0909\\u092e\\u094d\\u0930 \\u0915\\u0947 \\u0915\\u093f\\u0938\\u0940 \\u092d\\u0940 \\u0935\\u094d\\u092f\\u0915\\u094d\\u0924\\u093f \\u0938\\u0947 \\u0915\\u094b\\u0908 \\u092d\\u0940 \\u0921\\u0947\\u091f\\u093e \\u090f\\u0915\\u0924\\u094d\\u0930 \\u0928\\u0939\\u0940\\u0902 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0939\\u092e\\u093e\\u0930\\u0940 \\u0938\\u093e\\u0907\\u091f, \\u0906\\u0907\\u091f\\u092e \\u0914\\u0930 \\u092a\\u094d\\u0930\\u0936\\u093e\\u0938\\u0928 \\u092a\\u0942\\u0930\\u0940 \\u0924\\u0930\\u0939 \\u0938\\u0947 \\u0909\\u0928 \\u0935\\u094d\\u092f\\u0915\\u094d\\u0924\\u093f\\u092f\\u094b\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0938\\u092e\\u0928\\u094d\\u0935\\u093f\\u0924 \\u0939\\u0948\\u0902 \\u091c\\u094b \\u0915\\u092e \\u0938\\u0947 \\u0915\\u092e 13 \\u0935\\u0930\\u094d\\u0937 \\u092f\\u093e \\u0909\\u0938\\u0938\\u0947 \\u0905\\u0927\\u093f\\u0915 \\u0909\\u092e\\u094d\\u0930 \\u0915\\u0947 \\u0939\\u0948\\u0902\\u0964<\\/p><p>\\u0939\\u092e\\u093e\\u0930\\u0940 \\u0917\\u094b\\u092a\\u0928\\u0940\\u092f\\u0924\\u093e \\u0928\\u0940\\u0924\\u093f \\u092e\\u0947\\u0902 \\u092a\\u0930\\u093f\\u0935\\u0930\\u094d\\u0924\\u0928<\\/p><p>\\u092f\\u0926\\u093f \\u0939\\u092e \\u0905\\u092a\\u0928\\u0940 \\u0917\\u094b\\u092a\\u0928\\u0940\\u092f\\u0924\\u093e \\u0928\\u0940\\u0924\\u093f \\u0915\\u094b \\u092c\\u0926\\u0932\\u0928\\u0947 \\u0915\\u093e \\u0928\\u093f\\u0930\\u094d\\u0923\\u092f \\u0932\\u0947\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0924\\u094b \\u0939\\u092e \\u0909\\u0928 \\u092a\\u0930\\u093f\\u0935\\u0930\\u094d\\u0924\\u0928\\u094b\\u0902 \\u0915\\u094b \\u0907\\u0938 \\u092a\\u0943\\u0937\\u094d\\u0920 \\u092a\\u0930 \\u092a\\u094b\\u0938\\u094d\\u091f \\u0915\\u0930\\u0947\\u0902\\u0917\\u0947\\u0964<\\/p><p>\\u0939\\u092e \\u0906\\u092a\\u0915\\u0940 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0915\\u092c \\u0924\\u0915 \\u0930\\u0916\\u0924\\u0947 \\u0939\\u0948\\u0902?<\\/p><p>\\u091c\\u092c \\u0906\\u092a \\u0939\\u092e\\u093e\\u0930\\u0940 \\u0938\\u093e\\u0907\\u091f \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092a\\u0902\\u091c\\u0940\\u0915\\u0930\\u0923 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0924\\u094b \\u0939\\u092e \\u0906\\u092a\\u0915\\u0947 \\u092c\\u093e\\u0930\\u0947 \\u092e\\u0947\\u0902 \\u0906\\u092a\\u0915\\u0947 \\u092a\\u093e\\u0938 \\u092e\\u094c\\u091c\\u0942\\u0926 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0915\\u094b \\u0924\\u092c \\u0924\\u0915 \\u091a\\u0915\\u094d\\u0930\\u093f\\u0924 \\u0914\\u0930 \\u0930\\u0916\\u0924\\u0947 \\u0939\\u0948\\u0902 \\u091c\\u092c \\u0924\\u0915 \\u0906\\u092a \\u0930\\u093f\\u0915\\u0949\\u0930\\u094d\\u0921 \\u0915\\u094b \\u092e\\u093f\\u091f\\u093e \\u0928\\u0939\\u0940\\u0902 \\u0926\\u0947\\u0924\\u0947 \\u092f\\u093e \\u0916\\u0941\\u0926 \\u0915\\u094b \\u0935\\u093e\\u092a\\u0938 \\u0928\\u0939\\u0940\\u0902 \\u0932\\u0947 \\u0932\\u0947\\u0924\\u0947 (\\u0915\\u093e\\u0928\\u0942\\u0928\\u094b\\u0902 \\u0914\\u0930 \\u0926\\u093f\\u0936\\u093e\\u0928\\u093f\\u0930\\u094d\\u0926\\u0947\\u0936\\u094b\\u0902 \\u0915\\u0947 \\u0905\\u0927\\u0940\\u0928)\\u0964<\\/p>\"}}}', 1, 1, '2023-06-12 12:19:42', '2024-11-13 13:45:39');
INSERT INTO `setup_pages` VALUES (16, 'useful-links', 'refund-policy', '{\"language\":{\"en\":{\"title\":\"Refund Policy\"},\"es\":{\"title\":\"Politica de reembolso\"},\"ar\":{\"title\":\"\\u0633\\u064a\\u0627\\u0633\\u0629 \\u0627\\u0644\\u0627\\u0633\\u062a\\u0631\\u062c\\u0627\\u0639\"},\"fr\":{\"title\":\"Politica de reembolso\"},\"hi\":{\"title\":\"\\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0935\\u093e\\u092a\\u0938\\u0940 \\u0915\\u0940 \\u0928\\u0940\\u0924\\u093f\"}}}', NULL, '{\"language\":{\"en\":{\"details\":\"<h3 style=\\\"margin-left:0px;\\\"><strong>What information do we collect?<\\/strong><\\/h3><p style=\\\"margin-left:0px;\\\">We gather data from you when you register on our site, submit a request, buy any services, react to an overview, or round out a structure. At the point when requesting any assistance or enrolling on our site, as suitable, you might be approached to enter your: name, email address, or telephone number. You may, nonetheless, visit our site anonymously.<\\/p><h3 style=\\\"margin-left:0px;\\\"><strong>How do we protect your information?<\\/strong><\\/h3><p style=\\\"margin-left:0px;\\\">All provided delicate\\/credit data is sent through Stripe.<br>After an exchange, your private data (credit cards, social security numbers, financials, and so on) won be put away on our workers.<\\/p><h3 style=\\\"margin-left:0px;\\\"><strong>Do we disclose any information to outside parties?<\\/strong><\\/h3><p style=\\\"margin-left:0px;\\\">We don sell, exchange, or in any case move to outside gatherings by and by recognizable data. This does exclude confided in outsiders who help us in working our site, leading our business, or adjusting you, since those gatherings consent to keep this data private. We may likewise deliver your data when we accept discharge is suitable to follow the law, implement our site strategies, or ensure our own or others rights, property, or wellbeing.<\\/p><h3 style=\\\"margin-left:0px;\\\"><strong>Childrens Online Privacy Protection Act Compliance<\\/strong><\\/h3><p style=\\\"margin-left:0px;\\\">We are consistent with the prerequisites of COPPA (Childrens Online Privacy Protection Act), we don gather any data from anybody under 13 years old. Our site, items, and administrations are completely coordinated to individuals who are in any event 13 years of age or more established.<\\/p><h3 style=\\\"margin-left:0px;\\\"><strong>Changes to our Privacy Policy<\\/strong><\\/h3><p style=\\\"margin-left:0px;\\\">If we decide to change our privacy policy, we will post those changes on this page.<\\/p><h3 style=\\\"margin-left:0px;\\\"><strong>How long we retain your information?<\\/strong><\\/h3><p style=\\\"margin-left:0px;\\\">At the point when you register for our site, we cycle and keep your information we have about you however long you don not erase the record or withdraw yourself (subject to laws and guidelines).<\\/p>\"},\"es\":{\"details\":\"<p>\\u00bfQu\\u00e9 informaci\\u00f3n recopilamos?<\\/p><p>Recopilamos datos suyos cuando se registra en nuestro sitio, env\\u00eda una solicitud, compra alg\\u00fan servicio, reacciona a una descripci\\u00f3n general o completa una estructura. En el momento de solicitar asistencia o registrarse en nuestro sitio, seg\\u00fan corresponda, es posible que se le solicite que ingrese su: nombre, direcci\\u00f3n de correo electr\\u00f3nico o n\\u00famero de tel\\u00e9fono. No obstante, puede visitar nuestro sitio de forma an\\u00f3nima.<\\/p><p>\\u00bfC\\u00f3mo protegemos tu informaci\\u00f3n?<\\/p><p>Todos los datos delicados\\/cr\\u00e9ditos proporcionados se env\\u00edan a trav\\u00e9s de Stripe.<br>Despu\\u00e9s de un intercambio, sus datos privados (tarjetas de cr\\u00e9dito, n\\u00fameros de seguro social, finanzas, etc.) pasar\\u00e1n a nuestros trabajadores.<\\/p><p>\\u00bfRevelamos alguna informaci\\u00f3n a terceros?<\\/p><p>No vendemos, intercambiamos ni, en ning\\u00fan caso, nos trasladamos a reuniones externas mediante datos reconocibles. Esto excluye a personas externas de confianza que nos ayudan a trabajar en nuestro sitio, dirigir nuestro negocio o ajustarlo, ya que esas reuniones consienten en mantener estos datos privados. Asimismo, podremos entregar sus datos cuando aceptemos que la descarga es adecuada para cumplir con la ley, implementar las estrategias de nuestro sitio o garantizar nuestros derechos, propiedad o bienestar o los de otros.<\\/p><p>Cumplimiento de la Ley de Protecci\\u00f3n de la Privacidad Infantil en L\\u00ednea<\\/p><p>Somos consistentes con los requisitos previos de COPPA (Ley de Protecci\\u00f3n de la Privacidad Infantil en L\\u00ednea), no recopilamos datos de ninguna persona menor de 13 a\\u00f1os. Nuestro sitio, art\\u00edculos y servicios est\\u00e1n completamente adaptados a personas mayores de 13 a\\u00f1os o m\\u00e1s.<\\/p><p>Cambios en nuestra Pol\\u00edtica de Privacidad<\\/p><p>Si decidimos cambiar nuestra pol\\u00edtica de privacidad, publicaremos esos cambios en esta p\\u00e1gina.<\\/p><p>\\u00bfCu\\u00e1nto tiempo conservamos su informaci\\u00f3n?<\\/p><p>En el momento en que se registra en nuestro sitio, realizamos un ciclo y mantenemos la informaci\\u00f3n que tenemos sobre usted durante el tiempo que usted no borre el registro ni se retire (sujeto a leyes y pautas).<\\/p>\"},\"ar\":{\"details\":\"<p>\\u0645\\u0627 \\u0647\\u064a \\u0627\\u0644\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u0646\\u0642\\u0648\\u0645 \\u0628\\u062c\\u0645\\u0639\\u0647\\u0627\\u061f<\\/p><p>\\u0646\\u0642\\u0648\\u0645 \\u0628\\u062c\\u0645\\u0639 \\u0627\\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0645\\u0646\\u0643 \\u0639\\u0646\\u062f\\u0645\\u0627 \\u062a\\u0642\\u0648\\u0645 \\u0628\\u0627\\u0644\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0639\\u0644\\u0649 \\u0645\\u0648\\u0642\\u0639\\u0646\\u0627 \\u060c \\u0623\\u0648 \\u062a\\u0642\\u062f\\u064a\\u0645 \\u0637\\u0644\\u0628 \\u060c \\u0623\\u0648 \\u0634\\u0631\\u0627\\u0621 \\u0623\\u064a \\u062e\\u062f\\u0645\\u0627\\u062a \\u060c \\u0623\\u0648 \\u0627\\u0644\\u0631\\u062f \\u0639\\u0644\\u0649 \\u0646\\u0638\\u0631\\u0629 \\u0639\\u0627\\u0645\\u0629 \\u060c \\u0623\\u0648 \\u0625\\u0646\\u0647\\u0627\\u0621 \\u0647\\u064a\\u0643\\u0644. \\u0639\\u0646\\u062f \\u0637\\u0644\\u0628 \\u0623\\u064a \\u0645\\u0633\\u0627\\u0639\\u062f\\u0629 \\u0623\\u0648 \\u0627\\u0644\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0639\\u0644\\u0649 \\u0645\\u0648\\u0642\\u0639\\u0646\\u0627 \\u060c \\u062d\\u0633\\u0628 \\u0627\\u0644\\u0627\\u0642\\u062a\\u0636\\u0627\\u0621 \\u060c \\u0642\\u062f \\u064a\\u062a\\u0645 \\u0627\\u0644\\u0627\\u062a\\u0635\\u0627\\u0644 \\u0628\\u0643 \\u0644\\u0625\\u062f\\u062e\\u0627\\u0644: \\u0627\\u0633\\u0645\\u0643 \\u0623\\u0648 \\u0639\\u0646\\u0648\\u0627\\u0646 \\u0628\\u0631\\u064a\\u062f\\u0643 \\u0627\\u0644\\u0625\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a \\u0623\\u0648 \\u0631\\u0642\\u0645 \\u0647\\u0627\\u062a\\u0641\\u0643. \\u0648\\u0645\\u0639 \\u0630\\u0644\\u0643 \\u060c \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0632\\u064a\\u0627\\u0631\\u0629 \\u0645\\u0648\\u0642\\u0639\\u0646\\u0627 \\u062f\\u0648\\u0646 \\u0627\\u0644\\u0643\\u0634\\u0641 \\u0639\\u0646 \\u0647\\u0648\\u064a\\u062a\\u0643.<\\/p><p>\\u0643\\u064a\\u0641 \\u0646\\u062d\\u0645\\u064a \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a\\u0643\\u061f<\\/p><p>\\u064a\\u062a\\u0645 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0627\\u0644\\u062f\\u0642\\u064a\\u0642\\u0629 \\/ \\u0627\\u0644\\u0627\\u0626\\u062a\\u0645\\u0627\\u0646\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0642\\u062f\\u0645\\u0629 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 Stripe.<br>\\u0628\\u0639\\u062f \\u0627\\u0644\\u062a\\u0628\\u0627\\u062f\\u0644 \\u060c \\u0633\\u064a\\u062a\\u0645 \\u0648\\u0636\\u0639 \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a\\u0643 \\u0627\\u0644\\u062e