INSERT INTO `site_sections` VALUES (1, 'site_cookie', '{\"status\":true,\"link\":\"page\\/privacy-policy\",\"desc\":\"We may use cookies or any other tracking technologies when you visit our website, including any other media form, mobile website, or mobile application related or connected to help customize the Site and improve your experience.\"}', 1, NULL, '2023-02-20 05:21:32', '2024-03-27 10:04:52');
INSERT INTO `site_sections` VALUES (2, 'banner-section', '{\"images\":{\"banner_image\":\"12469fc0-480c-438e-ab96-687bbb65048a.webp\"},\"language\":{\"en\":{\"title\":\"A Machine-Readable Code\",\"heading\":\"Transfer Money With The QRCode In A Second\",\"sub_heading\":\"Our innovative payment solution allows you to transfer money quickly and securely using QR codes. With just a simple scan, you can send or receive funds in a matter of seconds, eliminating the need for manual entry or tedious account details.\"},\"es\":{\"title\":\"Un c\\u00f3digo legible por m\\u00e1quina\",\"heading\":\"Transfiere dinero con el QRCode en un segundo\",\"sub_heading\":\"Nuestra innovadora soluci\\u00f3n de pago le permite transferir dinero de forma r\\u00e1pida y segura mediante c\\u00f3digos QR. Con solo un simple escaneo, puede enviar o recibir fondos en cuesti\\u00f3n de segundos, eliminando la necesidad de ingresar manualmente o los tediosos detalles de la cuenta.\"},\"ar\":{\"title\":\"\\u0631\\u0645\\u0632 \\u064a\\u0645\\u0643\\u0646 \\u0642\\u0631\\u0627\\u0621\\u062a\\u0647 \\u0622\\u0644\\u064a\\u064b\\u0627\",\"heading\":\"\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0631\\u0645\\u0632 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639\\u0629 \\u0641\\u064a \\u062b\\u0627\\u0646\\u064a\\u0629\",\"sub_heading\":\"\\u064a\\u062a\\u064a\\u062d \\u0644\\u0643 \\u062d\\u0644 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u0645\\u0628\\u062a\\u0643\\u0631 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0646\\u0627 \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0633\\u0631\\u0639\\u0629 \\u0648\\u0623\\u0645\\u0627\\u0646 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0631\\u0645\\u0648\\u0632 QR. \\u0628\\u0645\\u062c\\u0631\\u062f \\u0645\\u0633\\u062d \\u0628\\u0633\\u064a\\u0637 \\u060c \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0623\\u0648 \\u062a\\u0644\\u0642\\u064a\\u0647\\u0627 \\u0641\\u064a \\u063a\\u0636\\u0648\\u0646 \\u062b\\u0648\\u0627\\u0646\\u064d \\u060c \\u0645\\u0645\\u0627 \\u064a\\u0644\\u063a\\u064a \\u0627\\u0644\\u062d\\u0627\\u062c\\u0629 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0625\\u062f\\u062e\\u0627\\u0644 \\u0627\\u0644\\u064a\\u062f\\u0648\\u064a \\u0623\\u0648 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u062d\\u0633\\u0627\\u0628 \\u0627\\u0644\\u0645\\u0645\\u0644\\u0629.\"},\"fr\":{\"title\":\"Un code lisible par machine\",\"heading\":\"Transf\\u00e9rez de l\'argent avec le QRCode en une seconde.\",\"sub_heading\":\"Notre solution de paiement innovante vous permet de transf\\u00e9rer de l\'argent rapidement et en toute s\\u00e9curit\\u00e9 \\u00e0 l\'aide de codes QR. Avec un simple scan, vous pouvez envoyer ou recevoir des fonds en quelques secondes, \\u00e9liminant ainsi le besoin de saisie manuelle ou de d\\u00e9tails de compte fastidieux.\"},\"hi\":{\"title\":\"\\u092e\\u0936\\u0940\\u0928-\\u092a\\u0920\\u0928\\u0940\\u092f \\u0915\\u094b\\u0921\",\"heading\":\"\\u090f\\u0915 \\u0938\\u0947\\u0915\\u0902\\u0921 \\u092e\\u0947\\u0902 \\u0915\\u094d\\u092f\\u0942\\u0906\\u0930 \\u0915\\u094b\\u0921 \\u0938\\u0947 \\u092a\\u0948\\u0938\\u0947 \\u091f\\u094d\\u0930\\u093e\\u0902\\u0938\\u092b\\u0930 \\u0915\\u0930\\u0947\\u0902\",\"sub_heading\":\"\\u0939\\u092e\\u093e\\u0930\\u093e \\u0905\\u092d\\u093f\\u0928\\u0935 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u092e\\u093e\\u0927\\u093e\\u0928 \\u0906\\u092a\\u0915\\u094b QR \\u0915\\u094b\\u0921 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u0924\\u0947\\u091c\\u093c\\u0940 \\u0938\\u0947 \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0927\\u0928 \\u0939\\u0938\\u094d\\u0924\\u093e\\u0902\\u0924\\u0930\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0940 \\u0905\\u0928\\u0941\\u092e\\u0924\\u093f \\u0926\\u0947\\u0924\\u093e \\u0939\\u0948\\u0964 \\u092c\\u0938 \\u090f\\u0915 \\u0938\\u093e\\u0927\\u093e\\u0930\\u0923 \\u0938\\u094d\\u0915\\u0948\\u0928 \\u0915\\u0947 \\u0938\\u093e\\u0925, \\u0906\\u092a \\u0915\\u0941\\u091b \\u0939\\u0940 \\u0938\\u0947\\u0915\\u0902\\u0921 \\u092e\\u0947\\u0902 \\u0927\\u0928\\u0930\\u093e\\u0936\\u093f \\u092d\\u0947\\u091c \\u092f\\u093e \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u092e\\u0948\\u0928\\u094d\\u092f\\u0941\\u0905\\u0932 \\u092a\\u094d\\u0930\\u0935\\u093f\\u0937\\u094d\\u091f\\u093f \\u092f\\u093e \\u0925\\u0915\\u093e\\u090a \\u0916\\u093e\\u0924\\u093e \\u0935\\u093f\\u0935\\u0930\\u0923 \\u0915\\u0940 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915\\u0924\\u093e \\u0938\\u092e\\u093e\\u092a\\u094d\\u0924 \\u0939\\u094b \\u091c\\u093e\\u0924\\u0940 \\u0939\\u0948\\u0964\"}}}', 1, NULL, '2023-02-25 06:01:05', '2024-11-12 18:10:01');
INSERT INTO `site_sections` VALUES (3, 'banner-floting', '{\"language\":{\"en\":{\"title\":\"Our Key Features\",\"sub_title\":\"Transfer money seamlessly and instantly using QR codes, enabling swift and hassle-free transactions. Make secure payments with confidence, thanks to our advanced security system that safeguards your financial information. Conveniently top up your mobile device for uninterrupted connectivity. Store and manage your funds securely in a mobile wallet, providing easy access and control over your finances. Enjoy the flexibility of a virtual card, empowering you to make online purchases effortlessly. Experience efficient remittance services for swift and reliable money transfers. Simplify your financial transactions and embrace the convenience of our comprehensive suite of features.\",\"button_name\":\"Contact Us\",\"button_link\":\"contact\"},\"es\":{\"title\":\"Nuestras caracter\\u00edsticas clave\",\"sub_title\":\"Transfiere dinero sin problemas y al instante usando c\\u00f3digos QR, lo que permite transacciones r\\u00e1pidas y sin complicaciones. Realiza pagos seguros con confianza, gracias a nuestro avanzado sistema de seguridad que resguarda tu informaci\\u00f3n financiera. Recargue convenientemente su dispositivo m\\u00f3vil para una conectividad ininterrumpida. Almacene y administre sus fondos de forma segura en una billetera m\\u00f3vil, lo que brinda f\\u00e1cil acceso y control sobre sus finanzas. Disfrute de la flexibilidad de una tarjeta virtual, que le permite realizar compras en l\\u00ednea sin esfuerzo. Experimente servicios de remesas eficientes para transferencias de dinero r\\u00e1pidas y confiables. Simplifique sus transacciones financieras y disfrute de la comodidad de nuestro completo conjunto de funciones.\",\"button_name\":\"Contacta con nosotras\",\"button_link\":\"contact\"},\"ar\":{\"title\":\"\\u0627\\u0644\\u0645\\u064a\\u0632\\u0627\\u062a \\u0627\\u0644\\u0631\\u0626\\u064a\\u0633\\u064a\\u0629 \\u0644\\u062f\\u064a\\u0646\\u0627\",\"sub_title\":\"\\u0642\\u0645 \\u0628\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0628\\u0633\\u0644\\u0627\\u0633\\u0629 \\u0648\\u0628\\u0634\\u0643\\u0644 \\u0641\\u0648\\u0631\\u064a \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0631\\u0645\\u0648\\u0632 QR \\u060c \\u0645\\u0645\\u0627 \\u064a\\u062a\\u064a\\u062d \\u0625\\u062c\\u0631\\u0627\\u0621 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0633\\u0631\\u064a\\u0639\\u0629 \\u0648\\u062e\\u0627\\u0644\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u062a\\u0627\\u0639\\u0628. \\u0642\\u0645 \\u0628\\u0625\\u062c\\u0631\\u0627\\u0621 \\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0622\\u0645\\u0646\\u0629 \\u0628\\u0643\\u0644 \\u062b\\u0642\\u0629 \\u060c \\u0628\\u0641\\u0636\\u0644 \\u0646\\u0638\\u0627\\u0645 \\u0627\\u0644\\u0623\\u0645\\u0627\\u0646 \\u0627\\u0644\\u0645\\u062a\\u0642\\u062f\\u0645 \\u0644\\u062f\\u064a\\u0646\\u0627 \\u0627\\u0644\\u0630\\u064a \\u064a\\u062d\\u0645\\u064a \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a\\u0643 \\u0627\\u0644\\u0645\\u0627\\u0644\\u064a\\u0629. \\u0642\\u0645 \\u0628\\u062a\\u0639\\u0628\\u0626\\u0629 \\u062c\\u0647\\u0627\\u0632\\u0643 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u062a\\u0635\\u0627\\u0644 \\u063a\\u064a\\u0631 \\u0645\\u0646\\u0642\\u0637\\u0639. \\u0642\\u0645 \\u0628\\u062a\\u062e\\u0632\\u064a\\u0646 \\u0648\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0628\\u0623\\u0645\\u0627\\u0646 \\u0641\\u064a \\u0645\\u062d\\u0641\\u0638\\u0629 \\u0645\\u062d\\u0645\\u0648\\u0644\\u0629 \\u060c \\u0645\\u0645\\u0627 \\u064a\\u0648\\u0641\\u0631 \\u0633\\u0647\\u0648\\u0644\\u0629 \\u0627\\u0644\\u0648\\u0635\\u0648\\u0644 \\u0648\\u0627\\u0644\\u062a\\u062d\\u0643\\u0645 \\u0641\\u064a \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643. \\u062a\\u0645\\u062a\\u0639 \\u0628\\u0645\\u0631\\u0648\\u0646\\u0629 \\u0627\\u0644\\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629 \\u060c \\u0645\\u0645\\u0627 \\u064a\\u0645\\u0643\\u0651\\u0646\\u0643 \\u0645\\u0646 \\u0625\\u062c\\u0631\\u0627\\u0621 \\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0634\\u0631\\u0627\\u0621 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0625\\u0646\\u062a\\u0631\\u0646\\u062a \\u062f\\u0648\\u0646 \\u0639\\u0646\\u0627\\u0621. \\u062c\\u0631\\u0628 \\u062e\\u062f\\u0645\\u0627\\u062a \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0627\\u0644\\u0641\\u0639\\u0627\\u0644\\u0629 \\u0644\\u0625\\u062c\\u0631\\u0627\\u0621 \\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0645\\u0627\\u0644\\u064a\\u0629 \\u0633\\u0631\\u064a\\u0639\\u0629 \\u0648\\u0645\\u0648\\u062b\\u0648\\u0642\\u0629. \\u0642\\u0645 \\u0628\\u062a\\u0628\\u0633\\u064a\\u0637 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u0643 \\u0627\\u0644\\u0645\\u0627\\u0644\\u064a\\u0629 \\u0648\\u0627\\u062d\\u062a\\u0636\\u0646 \\u0627\\u0644\\u0631\\u0627\\u062d\\u0629 \\u0627\\u0644\\u062a\\u064a \\u062a\\u0648\\u0641\\u0631\\u0647\\u0627 \\u0645\\u062c\\u0645\\u0648\\u0639\\u0629 \\u0627\\u0644\\u0645\\u064a\\u0632\\u0627\\u062a \\u0627\\u0644\\u0634\\u0627\\u0645\\u0644\\u0629 \\u0644\\u062f\\u064a\\u0646\\u0627.\",\"button_name\":\"\\u0627\\u062a\\u0635\\u0644 \\u0628\\u0646\\u0627\",\"button_link\":\"contact\"},\"fr\":{\"title\":\"Nos principales fonctionnalit\\u00e9s\",\"sub_title\":\"Transf\\u00e9rez de l\'argent de mani\\u00e8re transparente et instantan\\u00e9e \\u00e0 l\'aide de codes QR, permettant des transactions rapides et sans tracas. Effectuez des paiements s\\u00e9curis\\u00e9s en toute confiance, gr\\u00e2ce \\u00e0 notre syst\\u00e8me de s\\u00e9curit\\u00e9 avanc\\u00e9 qui prot\\u00e8ge vos informations financi\\u00e8res. Rechargez facilement votre appareil mobile pour une connectivit\\u00e9 ininterrompue. Stockez et g\\u00e9rez vos fonds en toute s\\u00e9curit\\u00e9 dans un portefeuille mobile, offrant un acc\\u00e8s et un contr\\u00f4le faciles sur vos finances. Profitez de la flexibilit\\u00e9 d\'une carte virtuelle, vous permettant d\'effectuer des achats en ligne sans effort. B\\u00e9n\\u00e9ficiez de services de transfert de fonds efficaces pour des transferts d\'argent rapides et fiables. Simplifiez vos transactions financi\\u00e8res et profitez de la commodit\\u00e9 de notre suite compl\\u00e8te de fonctionnalit\\u00e9s.\",\"button_name\":\"Contactez-nous\",\"button_link\":\"contact\"},\"hi\":{\"title\":\"\\u0939\\u092e\\u093e\\u0930\\u0940 \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0935\\u093f\\u0936\\u0947\\u0937\\u0924\\u093e\\u090f\\u0902\",\"sub_title\":\"QR \\u0915\\u094b\\u0921 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 \\u0938\\u0939\\u091c\\u0924\\u093e \\u0938\\u0947 \\u0914\\u0930 \\u0924\\u0941\\u0930\\u0902\\u0924 \\u092a\\u0948\\u0938\\u0947 \\u091f\\u094d\\u0930\\u093e\\u0902\\u0938\\u092b\\u0930 \\u0915\\u0930\\u0947\\u0902, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0924\\u0947\\u091c\\u093c \\u0914\\u0930 \\u092a\\u0930\\u0947\\u0936\\u093e\\u0928\\u0940 \\u092e\\u0941\\u0915\\u094d\\u0924 \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0938\\u0902\\u092d\\u0935 \\u0939\\u094b \\u0938\\u0915\\u0947\\u0964 \\u0939\\u092e\\u093e\\u0930\\u0940 \\u0909\\u0928\\u094d\\u0928\\u0924 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u092a\\u094d\\u0930\\u0923\\u093e\\u0932\\u0940 \\u0915\\u0940 \\u092c\\u0926\\u094c\\u0932\\u0924 \\u0906\\u0924\\u094d\\u092e\\u0935\\u093f\\u0936\\u094d\\u0935\\u093e\\u0938 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0930\\u0947\\u0902 \\u091c\\u094b \\u0906\\u092a\\u0915\\u0940 \\u0935\\u093f\\u0924\\u094d\\u0924\\u0940\\u092f \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0915\\u0940 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0915\\u0930\\u0924\\u0940 \\u0939\\u0948\\u0964 \\u0928\\u093f\\u0930\\u094d\\u092c\\u093e\\u0927 \\u0915\\u0928\\u0947\\u0915\\u094d\\u091f\\u093f\\u0935\\u093f\\u091f\\u0940 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u0947 \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u0921\\u093f\\u0935\\u093e\\u0907\\u0938 \\u0915\\u094b \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e\\u091c\\u0928\\u0915 \\u0924\\u0930\\u0940\\u0915\\u0947 \\u0938\\u0947 \\u091f\\u0949\\u092a \\u0905\\u092a \\u0915\\u0930\\u0947\\u0902\\u0964 \\u0905\\u092a\\u0928\\u0947 \\u092b\\u0902\\u0921 \\u0915\\u094b \\u092e\\u094b\\u092c\\u093e\\u0907\\u0932 \\u0935\\u0949\\u0932\\u0947\\u091f \\u092e\\u0947\\u0902 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0938\\u094d\\u091f\\u094b\\u0930 \\u0914\\u0930 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0906\\u092a\\u0915\\u0947 \\u0935\\u093f\\u0924\\u094d\\u0924 \\u092a\\u0930 \\u0906\\u0938\\u093e\\u0928 \\u092a\\u0939\\u0941\\u0901\\u091a \\u0914\\u0930 \\u0928\\u093f\\u092f\\u0902\\u0924\\u094d\\u0930\\u0923 \\u0939\\u094b\\u0964 \\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0915\\u0940 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0915\\u093e \\u0906\\u0928\\u0902\\u0926 \\u0932\\u0947\\u0902, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0906\\u092a \\u0906\\u0938\\u093e\\u0928\\u0940 \\u0938\\u0947 \\u0911\\u0928\\u0932\\u093e\\u0907\\u0928 \\u0916\\u0930\\u0940\\u0926\\u093e\\u0930\\u0940 \\u0915\\u0930 \\u092a\\u093e\\u090f\\u0901\\u0917\\u0947\\u0964 \\u0924\\u0947\\u091c\\u093c \\u0914\\u0930 \\u0935\\u093f\\u0936\\u094d\\u0935\\u0938\\u0928\\u0940\\u092f \\u092e\\u0928\\u0940 \\u091f\\u094d\\u0930\\u093e\\u0902\