INSERT INTO `site_sections` VALUES (13, 'auth-section', '{\"language\":{\"en\":{\"login_text\":\"Our secure login process ensures the confidentiality of your information. Log in today and stay connected to your finances, anytime and anywhere.\",\"register_text\":\"Become a part of our community by registering for an account today. Enjoy a range of benefits and features tailored to meet your needs. Our registration page makes it easy to create your account, providing a seamless and user-friendly experience.\",\"forget_text\":\"Take control of your account by resetting your password. Our password recovery page guides you through the necessary steps to securely reset your password.\"},\"es\":{\"login_text\":\"Nuestro proceso de inicio de sesi\\u00f3n seguro garantiza la confidencialidad de su informaci\\u00f3n. Inicie sesi\\u00f3n hoy y mant\\u00e9ngase conectado con sus finanzas, en cualquier momento y en cualquier lugar.\",\"register_text\":\"Convi\\u00e9rtase en parte de nuestra comunidad registr\\u00e1ndose para obtener una cuenta hoy. Disfrute de una variedad de beneficios y caracter\\u00edsticas dise\\u00f1adas para satisfacer sus necesidades. Nuestra p\\u00e1gina de registro facilita la creaci\\u00f3n de su cuenta, proporcionando una experiencia fluida y f\\u00e1cil de usar.\",\"forget_text\":\"Convi\\u00e9rtase en parte de nuestra comunidad registr\\u00e1ndose para obtener una cuenta hoy. Disfrute de una variedad de beneficios y caracter\\u00edsticas dise\\u00f1adas para satisfacer sus necesidades. Nuestra p\\u00e1gina de registro facilita la creaci\\u00f3n de su cuenta, proporcionando una experiencia fluida y f\\u00e1cil de usar.\"},\"ar\":{\"login_text\":\"\\u062a\\u0636\\u0645\\u0646 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 \\u0627\\u0644\\u0622\\u0645\\u0646\\u0629 \\u0644\\u062f\\u064a\\u0646\\u0627 \\u0633\\u0631\\u064a\\u0629 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a\\u0643. \\u0633\\u062c\\u0651\\u0644 \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 \\u0627\\u0644\\u064a\\u0648\\u0645 \\u0648\\u0627\\u0628\\u0642 \\u0639\\u0644\\u0649 \\u0627\\u062a\\u0635\\u0627\\u0644 \\u0628\\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0641\\u064a \\u0623\\u064a \\u0648\\u0642\\u062a \\u0648\\u0641\\u064a \\u0623\\u064a \\u0645\\u0643\\u0627\\u0646.\",\"register_text\":\"\\u0643\\u0646 \\u062c\\u0632\\u0621\\u064b\\u0627 \\u0645\\u0646 \\u0645\\u062c\\u062a\\u0645\\u0639\\u0646\\u0627 \\u0628\\u0627\\u0644\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628 \\u0627\\u0644\\u064a\\u0648\\u0645. \\u0627\\u0633\\u062a\\u0645\\u062a\\u0639 \\u0628\\u0645\\u062c\\u0645\\u0648\\u0639\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0632\\u0627\\u064a\\u0627 \\u0648\\u0627\\u0644\\u0645\\u064a\\u0632\\u0627\\u062a \\u0627\\u0644\\u0645\\u0635\\u0645\\u0645\\u0629 \\u062e\\u0635\\u064a\\u0635\\u064b\\u0627 \\u0644\\u062a\\u0644\\u0628\\u064a\\u0629 \\u0627\\u062d\\u062a\\u064a\\u0627\\u062c\\u0627\\u062a\\u0643. \\u062a\\u0633\\u0647\\u0644 \\u0635\\u0641\\u062d\\u0629 \\u0627\\u0644\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0646\\u0627 \\u0625\\u0646\\u0634\\u0627\\u0621 \\u062d\\u0633\\u0627\\u0628\\u0643 \\u060c \\u0645\\u0645\\u0627 \\u064a\\u0648\\u0641\\u0631 \\u062a\\u062c\\u0631\\u0628\\u0629 \\u0633\\u0644\\u0633\\u0629 \\u0648\\u0633\\u0647\\u0644\\u0629 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645.\",\"forget_text\":\"\\u062a\\u062d\\u0643\\u0645 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0639\\u0646 \\u0637\\u0631\\u064a\\u0642 \\u0625\\u0639\\u0627\\u062f\\u0629 \\u062a\\u0639\\u064a\\u064a\\u0646 \\u0643\\u0644\\u0645\\u0629 \\u0627\\u0644\\u0645\\u0631\\u0648\\u0631 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643. \\u062a\\u0631\\u0634\\u062f\\u0643 \\u0635\\u0641\\u062d\\u0629 \\u0627\\u0633\\u062a\\u0639\\u0627\\u062f\\u0629 \\u0643\\u0644\\u0645\\u0629 \\u0627\\u0644\\u0645\\u0631\\u0648\\u0631 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0646\\u0627 \\u062e\\u0644\\u0627\\u0644 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0627\\u062a \\u0627\\u0644\\u0636\\u0631\\u0648\\u0631\\u064a\\u0629 \\u0644\\u0625\\u0639\\u0627\\u062f\\u0629 \\u062a\\u0639\\u064a\\u064a\\u0646 \\u0643\\u0644\\u0645\\u0629 \\u0627\\u0644\\u0645\\u0631\\u0648\\u0631 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643 \\u0628\\u0634\\u0643\\u0644 \\u0622\\u0645\\u0646.\"},\"fr\":{\"login_text\":\"Notre processus de connexion s\\u00e9curis\\u00e9 garantit la confidentialit\\u00e9 de vos informations. Connectez-vous aujourd\'hui et restez connect\\u00e9 \\u00e0 vos finances, \\u00e0 tout moment et en tout lieu.\",\"register_text\":\"Devenez membre de notre communaut\\u00e9 en cr\\u00e9ant un compte d\\u00e8s aujourd\'hui. B\\u00e9n\\u00e9ficiez d\\u2019une gamme d\\u2019avantages et de fonctionnalit\\u00e9s adapt\\u00e9s \\u00e0 vos besoins. Notre page d\'inscription facilite la cr\\u00e9ation de votre compte, offrant une exp\\u00e9rience transparente et conviviale.\",\"forget_text\":\"Prenez le contr\\u00f4le de votre compte en r\\u00e9initialisant votre mot de passe. Notre page de r\\u00e9cup\\u00e9ration de mot de passe vous guide \\u00e0 travers les \\u00e9tapes n\\u00e9cessaires pour r\\u00e9initialiser votre mot de passe en toute s\\u00e9curit\\u00e9.\"},\"hi\":{\"login_text\":\"\\u0939\\u092e\\u093e\\u0930\\u0940 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0932\\u0949\\u0917\\u093f\\u0928 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0906\\u092a\\u0915\\u0940 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0915\\u0940 \\u0917\\u094b\\u092a\\u0928\\u0940\\u092f\\u0924\\u093e \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0924\\u0940 \\u0939\\u0948\\u0964 \\u0906\\u091c \\u0939\\u0940 \\u0932\\u0949\\u0917 \\u0907\\u0928 \\u0915\\u0930\\u0947\\u0902 \\u0914\\u0930 \\u0915\\u092d\\u0940 \\u092d\\u0940 \\u0914\\u0930 \\u0915\\u0939\\u0940\\u0902 \\u092d\\u0940 \\u0905\\u092a\\u0928\\u0947 \\u0935\\u093f\\u0924\\u094d\\u0924 \\u0938\\u0947 \\u091c\\u0941\\u0921\\u093c\\u0947 \\u0930\\u0939\\u0947\\u0902\\u0964\",\"register_text\":\"\\u0906\\u091c \\u0939\\u0940 \\u090f\\u0915 \\u0916\\u093e\\u0924\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092a\\u0902\\u091c\\u0940\\u0915\\u0930\\u0923 \\u0915\\u0930\\u0915\\u0947 \\u0939\\u092e\\u093e\\u0930\\u0947 \\u0938\\u092e\\u0941\\u0926\\u093e\\u092f \\u0915\\u093e \\u0939\\u093f\\u0938\\u094d\\u0938\\u093e \\u092c\\u0928\\u0947\\u0902\\u0964 \\u0905\\u092a\\u0928\\u0940 \\u091c\\u093c\\u0930\\u0942\\u0930\\u0924\\u094b\\u0902 \\u0915\\u0947 \\u0939\\u093f\\u0938\\u093e\\u092c \\u0938\\u0947 \\u0924\\u0948\\u092f\\u093e\\u0930 \\u0915\\u093f\\u090f \\u0917\\u090f \\u0915\\u0908 \\u0924\\u0930\\u0939 \\u0915\\u0947 \\u0932\\u093e\\u092d\\u094b\\u0902 \\u0914\\u0930 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e\\u0913\\u0902 \\u0915\\u093e \\u0906\\u0928\\u0902\\u0926 \\u0932\\u0947\\u0902\\u0964 \\u0939\\u092e\\u093e\\u0930\\u093e \\u092a\\u0902\\u091c\\u0940\\u0915\\u0930\\u0923 \\u092a\\u0943\\u0937\\u094d\\u0920 \\u0906\\u092a\\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u093e \\u0916\\u093e\\u0924\\u093e \\u092c\\u0928\\u093e\\u0928\\u093e \\u0906\\u0938\\u093e\\u0928 \\u092c\\u0928\\u093e\\u0924\\u093e \\u0939\\u0948, \\u091c\\u094b \\u090f\\u0915 \\u0938\\u0939\\u091c \\u0914\\u0930 \\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e-\\u0905\\u0928\\u0941\\u0915\\u0942\\u0932 \\u0905\\u0928\\u0941\\u092d\\u0935 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948\\u0964\",\"forget_text\":\"\\u0905\\u092a\\u0928\\u093e \\u092a\\u093e\\u0938\\u0935\\u0930\\u094d\\u0921 \\u0930\\u0940\\u0938\\u0947\\u091f \\u0915\\u0930\\u0915\\u0947 \\u0905\\u092a\\u0928\\u0947 \\u0916\\u093e\\u0924\\u0947 \\u092a\\u0930 \\u0928\\u093f\\u092f\\u0902\\u0924\\u094d\\u0930\\u0923 \\u0930\\u0916\\u0947\\u0902\\u0964 \\u0939\\u092e\\u093e\\u0930\\u093e \\u092a\\u093e\\u0938\\u0935\\u0930\\u094d\\u0921 \\u0930\\u093f\\u0915\\u0935\\u0930\\u0940 \\u092a\\u0947\\u091c \\u0906\\u092a\\u0915\\u094b \\u0905\\u092a\\u0928\\u093e \\u092a\\u093e\\u0938\\u0935\\u0930\\u094d\\u0921 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0930\\u0940\\u0938\\u0947\\u091f \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915 \\u091a\\u0930\\u0923\\u094b\\u0902 \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u092e\\u093e\\u0930\\u094d\\u0917\\u0926\\u0930\\u094d\\u0936\\u0928 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948\\u0964\"}}}', 1, NULL, '2023-06-13 10:44:19', '2024-11-12 18:04:51');
INSERT INTO `site_sections` VALUES (14, 'security-section', '{\"language\":{\"en\":{\"heading\":\"Security\",\"sub_heading\":\"5 Ways to Security System\",\"details\":\"We provide some awesome features that helpful.\"},\"es\":{\"heading\":\"Seguridad\",\"sub_heading\":\"5 formas de sistema de seguridad\",\"details\":\"Proporcionamos algunas caracter\\u00edsticas incre\\u00edbles que son \\u00fatiles.\"},\"ar\":{\"heading\":\"\\u062d\\u0645\\u0627\\u064a\\u0629\",\"sub_heading\":\"5 \\u0637\\u0631\\u0642 \\u0644\\u0646\\u0638\\u0627\\u0645 \\u0627\\u0644\\u0623\\u0645\\u0646\",\"details\":\"\\u0646\\u062d\\u0646 \\u0646\\u0642\\u062f\\u0645 \\u0628\\u0639\\u0636 \\u0627\\u0644\\u0645\\u064a\\u0632\\u0627\\u062a \\u0627\\u0644\\u0631\\u0627\\u0626\\u0639\\u0629 \\u0627\\u0644\\u062a\\u064a \\u0645\\u0641\\u064a\\u062f\\u0629.\"},\"fr\":{\"heading\":\"S\\u00e9curit\\u00e9\",\"sub_heading\":\"5 fa\\u00e7ons d\'acc\\u00e9der au syst\\u00e8me de s\\u00e9curit\\u00e9\",\"details\":\"Nous fournissons des fonctionnalit\\u00e9s impressionnantes et utiles.\"},\"hi\":{\"heading\":\"\\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e\",\"sub_heading\":\"\\u0938\\u093f\\u0938\\u094d\\u091f\\u092e \\u0915\\u094b \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 5 \\u0924\\u0930\\u0940\\u0915\\u0947\",\"details\":\"\\u0939\\u092e \\u0915\\u0941\\u091b \\u0905\\u0926\\u094d\\u092d\\u0941\\u0924 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e\\u090f\\u0901 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902 \\u091c\\u094b \\u0909\\u092a\\u092f\\u094b\\u0917\\u0940 \\u0939\\u0948\\u0902\\u0964\"}},\"items\":{\"648801275ab10\":{\"language\":{\"en\":{\"title\":\"SMS or Email Verification\",\"icon\":\"las la-unlock-alt\",\"sub_title\":\"Both email and SMS make for more secure authentication, but there are pros and cons to everything.\"},\"es\":{\"title\":\"Verificaci\\u00f3n por SMS o correo electr\\u00f3nico\",\"icon\":\"las la-unlock-alt\",\"sub_title\":\"Tanto el correo electr\\u00f3nico como los SMS hacen que la autenticaci\\u00f3n sea m\\u00e1s segura, pero todo tiene ventajas y desventajas.\"},\"ar\":{\"title\":\"\\u0627\\u0644\\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0627\\u0644\\u0631\\u0633\\u0627\\u0626\\u0644 \\u0627\\u0644\\u0642\\u0635\\u064a\\u0631\\u0629 \\u0623\\u0648 \\u0627\\u0644\\u0628\\u0631\\u064a\\u062f \\u0627\\u0644\\u0625\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a\",\"icon\":\"las la-unlock-alt\",\"sub_title\":\"\\u064a\\u0639\\u0645\\u0644 \\u0643\\u0644 \\u0645\\u0646 \\u0627\\u0644\\u0628\\u0631\\u064a\\u062f \\u0627\\u0644\\u0625\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a \\u0648\\u0627\\u0644\\u0631\\u0633\\u0627\\u0626\\u0644 \\u0627\\u0644\\u0642\\u0635\\u064a\\u0631\\u0629 \\u0639\\u0644\\u0649 \\u062a\\u0648\\u0641\\u064a\\u0631 \\u0645\\u0635\\u0627\\u062f\\u0642\\u0629 \\u0623\\u0643\\u062b\\u0631 \\u0623\\u0645\\u0627\\u0646\\u064b\\u0627 \\u060c \\u0648\\u0644\\u0643\\u0646 \\u0647\\u0646\\u0627\\u0643 \\u0645\\u0632\\u0627\\u064a\\u0627 \\u0648\\u0639\\u064a\\u0648\\u0628 \\u0644\\u0643\\u0644 \\u0634\\u064a\\u0621.\"},\"fr\":{\"title\":\"V\\u00e9rification par SMS ou par e-mail\",\"icon\":\"las la-unlock-alt\",\"sub_title\":\"Les e-mails et les SMS permettent une authentification plus s\\u00e9curis\\u00e9e, mais il y a des avantages et des inconv\\u00e9nients \\u00e0 tout.\"},\"hi\":{\"title\":\"\\u090f\\u0938\\u090f\\u092e\\u090f\\u0938 \\u092f\\u093e \\u0908\\u092e\\u0947\\u0932 \\u0938\\u0924\\u094d\\u092f\\u093e\\u092a\\u0928\",\"icon\":\"las la-unlock-alt\",\"sub_title\":\"\\u0908\\u092e\\u0947\\u0932 \\u0914\\u0930 \\u090f\\u0938\\u090f\\u092e\\u090f\\u0938 \\u0926\\u094b\\u0928\\u094b\\u0902 \\u0939\\u0940 \\u092a\\u094d\\u0930\\u092e\\u093e\\u0923\\u0940\\u0915\\u0930\\u0923 \\u0915\\u094b \\u0905\\u0927\\u093f\\u0915 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u092c\\u0928\\u093e\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0932\\u0947\\u0915\\u093f\\u0928 \\u0939\\u0930 \\u091a\\u0940\\u091c \\u0915\\u0947 \\u0905\\u092a\\u0928\\u0947 \\u092b\\u093e\\u092f\\u0926\\u0947 \\u0914\\u0930 \\u0928\\u0941\\u0915\\u0938\\u093e\\u0928 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"648801275ab10\"},\"648801a84f245\":{\"language\":{\"en\":{\"title\":\"KYC Solution\",\"icon\":\"las la-certificate\",\"sub_title\":\"Protect sensitive information with our GDPR compliant tech - no server connection needed.\"},\"es\":{\"title\":\"Soluci\\u00f3n KYC\",\"icon\":\"las la-certificate\",\"sub_title\":\"Proteja la informaci\\u00f3n confidencial con nuestra tecnolog\\u00eda compatible con GDPR: no se necesita conexi\\u00f3n al servidor.\"},\"ar\":{\"title\":\"\\u062d\\u0644 KYC\",\"icon\":\"las la-certificate\",\"sub_title\":\"\\u062d\\u0645\\u0627\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0627\\u0644\\u062d\\u0633\\u0627\\u0633\\u0629 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u062a\\u0642\\u0646\\u064a\\u062a\\u0646\\u0627 \\u0627\\u0644\\u0645\\u062a\\u0648\\u0627\\u0641\\u0642\\u0629 \\u0645\\u0639 \\u0627\\u0644\\u0644\\u0627\\u0626\\u062d\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0645\\u0629 \\u0644\\u062d\\u0645\\u0627\\u064a\\u0629 \\u0627\\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a - \\u0644\\u0627 \\u062d\\u0627\\u062c\\u0629 \\u0644\\u0644\\u0627\\u062a\\u0635\\u0627\\u0644 \\u0628\\u0627\\u0644\\u062e\\u0627\\u062f\\u0645.\"},\"fr\":{\"title\":\"Solution KYC\",\"icon\":\"las la-certificate\",\"sub_title\":\"Prot\\u00e9gez les informations sensibles gr\\u00e2ce \\u00e0 notre technologie conforme au RGPD - aucune connexion au serveur n\'est n\\u00e9cessaire.\"},\"hi\":{\"title\":\"\\u0915\\u0947\\u0935\\u093e\\u0908\\u0938\\u0940 \\u0938\\u092e\\u093e\\u0927\\u093e\\u0928\",\"icon\":\"las la-certificate\",\"sub_title\":\"\\u0939\\u092e\\u093e\\u0930\\u0940 GDPR \\u0905\\u0928\\u0941\\u092a\\u093e\\u0932\\u0915 \\u0924\\u0915\\u0928\\u0940\\u0915 \\u0938\\u0947 \\u0938\\u0902\\u0935\\u0947\\u0926\\u0928\\u0936\\u0940\\u0932 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0930\\u0916\\u0947\\u0902 - \\u0915\\u093f\\u0938\\u0940 \\u0938\\u0930\\u094d\\u0935\\u0930 \\u0915\\u0928\\u0947\\u0915\\u094d\\u0936\\u0928 \\u0915\\u0940 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915\\u0924\\u093e \\u0928\\u0939\\u0940\\u0902\\u0964\"}},\"id\":\"648801a84f245\"},\"648802233d890\":{\"language\":{\"en\":{\"title\":\"Two Factor Authentication\",\"icon\":\"las la-fingerprint\",\"sub_title\":\"2FA is an extra layer of protection used to ensure the security of online accounts beyond just a username and password.\"},\"es\":{\"title\":\"Autenticaci\\u00f3n de dos factores\",\"icon\":\"las la-fingerprint\",\"sub_title\":\"2FA es una capa adicional de protecci\\u00f3n utilizada para garantizar la seguridad de las cuentas en l\\u00ednea m\\u00e1s all\\u00e1 de un simple nombre de usuario y contrase\\u00f1a.\"},\"ar\":{\"title\":\"\\u062d\\u0645\\u0627\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0627\\u0644\\u062d\\u0633\\u0627\\u0633\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0644\\u0627\\u0626\\u062d\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0645\\u0629 \\u0644\\u0644\\u0628\\u0646\\u0648\\u062f \\u0648\\u0627\\u0644\\u0645\\u062a\\u0648\\u0641\\u0631\\u0629 \\u0628\\u0627\\u0644\\u062e\\u0627\\u0631\\u062c.\",\"icon\":\"las la-fingerprint\",\"sub_title\":\"2FA  \\u0647\\u064a \\u0637\\u0628\\u0642\\u0629 \\u0625\\u0636\\u0627\\u0641\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u062d\\u0645\\u0627\\u064a\\u0629 \\u062a\\u064f\\u0633\\u062a\\u062e\\u062f\\u0645 \\u0644\\u0636\\u0645\\u0627\\u0646 \\u0623\\u0645\\u0627\\u0646 \\u0627\\u0644\\u062d\\u0633\\u0627\\u0628\\u0627\\u062a \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0625\\u0646\\u062a\\u0631\\u0646\\u062a \\u0628\\u0645\\u0627 \\u064a\\u062a\\u062c\\u0627\\u0648\\u0632 \\u0645\\u062c\\u0631\\u062f \\u0627\\u0633\\u0645 \\u0645\\u0633\\u062a\\u062e\\u062f\\u0645 \\u0648\\u0643\\u0644\\u0645\\u0629 \\u0645\\u0631\\u0648\\u0631.\"},\"fr\":{\"title\":\"Authentification \\u00e0 deux facteurs\",\"icon\":\"las la-fingerprint\",\"sub_title\":\"2FA est une couche de protection suppl\\u00e9mentaire utilis\\u00e9e pour garantir la s\\u00e9curit\\u00e9 des comptes en ligne au-del\\u00e0 d\\u2019un simple nom d\\u2019utilisateur et mot de passe.\"},\"hi\":{\"title\":\"\\u0926\\u094b \\u0915\\u093e\\u0930\\u0915 \\u092a\\u094d\\u0930\\u092e\\u093e\\u0923\\u0940\\u0915\\u0930\\u0923\",\"icon\":\"las la-fingerprint\",\"sub_title\":\"2FA \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0915\\u0940 \\u090f\\u0915 \\u0905\\u0924\\u093f\\u0930\\u093f\\u0915\\u094d\\u0924 \\u092a\\u0930\\u0924 \\u0939\\u0948 \\u091c\\u093f\\u0938\\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e \\u0928\\u093e\\u092e \\u0914\\u0930 \\u092a\\u093e\\u0938\\u0935\\u0930\\u094d\\u0921 \\u0938\\u0947 \\u092a\\u0930\\u0947 \\u0911\\u0928\\u0932\\u093e\\u0907\\u0928 \\u0916\\u093e\\u0924\\u094b\\u0902 \\u0915\\u0940 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0938\\u0941\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e\\u0924\\u093e \\u0939\\u0948\\u0964\"}},\"id\":\"648802233d890\"},\"648802c7e3538\":{\"language\":{\"en\":{\"title\":\"End-to-End Encryption\",\"icon\":\"las la-shield-alt\",\"sub_title\":\"End-to-end encryption is a system of communication where only the users communicating can read the messages.\"},\"es\":{\"title\":\"Encriptado de fin a fin\",\"icon\":\"las la-shield-alt\",\"sub_title\":\"El cifrado de extremo a extremo es un sistema de comunicaci\\u00f3n en el que solo los usuarios que se comunican pueden leer los mensajes.\"},\"ar\":{\"title\":\"\\u0627\\u0644\\u062a\\u0634\\u0641\\u064a\\u0631 \\u0627\\u0644\\u062a\\u0627\\u0645 \\u0628\\u064a\\u0646 \\u0627\\u0644\\u0623\\u0637\\u0631\\u0627\\u0641\",\"icon\":\"las la-shield-alt\",\"sub_title\":\"\\u0627\\u0644\\u062a\\u0634\\u0641\\u064a\\u0631 \\u0645\\u0646 \\u0637\\u0631\\u0641 \\u0625\\u0644\\u0649 \\u0637\\u0631\\u0641 \\u0647\\u0648 \\u0646\\u0638\\u0627\\u0645 \\u0627\\u062a\\u0635\\u0627\\u0644 \\u062d\\u064a\\u062b \\u064a\\u0645\\u0643\\u0646 \\u0644\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u064a\\u0646 \\u0627\\u0644\\u0645\\u062a\\u0635\\u0644\\u064a\\u0646 \\u0641\\u0642\\u0637 \\u0642\\u0631\\u0627\\u0621\\u0629 \\u0627\\u0644\\u0631\\u0633\\u0627\\u0626\\u0644.\"},\"fr\":{\"title\":\"Chiffrement de bout en bout\",\"icon\":\"las la-shield-alt\",\"sub_title\":\"Le chiffrement de bout en bout est un syst\\u00e8me de communication dans lequel seuls les utilisateurs qui communiquent peuvent lire les messages.\"},\"hi\":{\"title\":\"\\u090f\\u0902\\u0921-\\u091f\\u0942-\\u090f\\u0902\\u0921 \\u090f\\u0928\\u094d\\u0915\\u094d\\u0930\\u093f\\u092a\\u094d\\u0936\\u0928\",\"icon\":\"las la-shield-alt\",\"sub_title\":\"\\u090f\\u0902\\u0921-\\u091f\\u0942-\\u090f\\u0902\\u0921 \\u090f\\u0928\\u094d\\u0915\\u094d\\u0930\\u093f\\u092a\\u094d\\u0936\\u0928 \\u0938\\u0902\\u091a\\u093e\\u0930 \\u0915\\u0940 \\u090f\\u0915 \\u092a\\u094d\\u0930\\u0923\\u093e\\u0932\\u0940 \\u0939\\u0948, \\u091c\\u093f\\u0938\\u092e\\u0947\\u0902 \\u0915\\u0947\\u0935\\u0932 \\u0938\\u0902\\u091a\\u093e\\u0930 \\u0915\\u0930\\u0928\\u0947 \\u0935\\u093e\\u0932\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e \\u0939\\u0940 \\u0938\\u0902\\u0926\\u0947\\u0936 \\u092a\\u0922\\u093c \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964\"}},\"id\":\"648802c7e3538\"},\"64880c5e02d5c\":{\"language\":{\"en\":{\"title\":\"Behavior Tracking\",\"icon\":\"las la-street-view\",\"sub_title\":\"It is a technique companies and advertisers use to create targeted advertisements and campaigns.\"},\"es\":{\"title\":\"Seguimiento del comportamiento\",\"icon\":\"las la-street-view\",\"sub_title\":\"Es una t\\u00e9cnica que utilizan las empresas y los anunciantes para crear anuncios y campa\\u00f1as dirigidas\"},\"ar\":{\"title\":\"\\u062a\\u062a\\u0628\\u0639 \\u0627\\u0644\\u0633\\u0644\\u0648\\u0643\",\"icon\":\"las la-street-view\",\"sub_title\":\"\\u0625\\u0646\\u0647\\u0627 \\u062a\\u0642\\u0646\\u064a\\u0629 \\u062a\\u0633\\u062a\\u062e\\u062f\\u0645\\u0647\\u0627 \\u0627\\u0644\\u0634\\u0631\\u0643\\u0627\\u062a \\u0648\\u0627\\u0644\\u0645\\u0639\\u0644\\u0646\\u0648\\u0646 \\u0644\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0625\\u0639\\u0644\\u0627\\u0646\\u0627\\u062a \\u0648\\u062d\\u0645\\u0644\\u0627\\u062a \\u0645\\u0633\\u062a\\u0647\\u062f\\u0641\\u0629.\"},\"fr\":{\"title\":\"Suivi du comportement\",\"icon\":\"las la-street-view\",\"sub_title\":\"Il s\'agit d\'une technique utilis\\u00e9e par les entreprises et les annonceurs pour cr\\u00e9er des publicit\\u00e9s et des campagnes cibl\\u00e9es.\"},\"hi\":{\"title\":\"\\u0935\\u094d\\u092f\\u0935\\u0939\\u093e\\u0930 \\u091f\\u094d\\u0930\\u0948\\u0915\\u093f\\u0902\\u0917\",\"icon\":\"las la-street-view\",\"sub_title\":\"\\u092f\\u0939 \\u090f\\u0915 \\u0924\\u0915\\u0928\\u0940\\u0915 \\u0939\\u0948 \\u091c\\u093f\\u0938\\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0902\\u092a\\u0928\\u093f\\u092f\\u093e\\u0902 \\u0914\\u0930 \\u0935\\u093f\\u091c\\u094d\\u091e\\u093e\\u092a\\u0928\\u0926\\u093e\\u0924\\u093e \\u0932\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0935\\u093f\\u091c\\u094d\\u091e\\u093e\\u092a\\u0928 \\u0914\\u0930 \\u0905\\u092d\\u093f\\u092f\\u093e\\u0928 \\u092c\\u0928\\u093e\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"}},\"id\":\"64880c5e02d5c\"}}}', 1, NULL, '2023-06-13 11:29:55', '2024-11-12 18:21:28');
INSERT INTO `site_sections` VALUES (15, 'overview-section', '{\"images\":{\"map_image\":\"3edd39be-cb6c-49c5-9e31-6067ce61a942.webp\"},\"language\":{\"en\":{\"title\":\"Overview\",\"heading\":\"In 2024, a financial institution generated $6.8 billion in income.\",\"sub_heading\":\"Have you ever finally just given in to the temptation and read your horoscope in the newspaper?\",\"botton_text\":\"Financial institutions play a vital role as they serve as a platform for exchange money.\",\"button_name\":\"Send Money Now\",\"button_link\":\"user\\/send-money\"},\"es\":{\"title\":\"Descripci\\u00f3n general\",\"heading\":\"En 2024, una instituci\\u00f3n financiera gener\\u00f3 $6.800 millones en ingreso\",\"sub_heading\":\"\\u00bfAlguna vez has cedido finalmente a la tentaci\\u00f3n y has le\\u00eddo tu hor\\u00f3scopo en el peri\\u00f3dico?\",\"botton_text\":\"Las instituciones financieras juegan un papel vital ya que sirven como plataforma para el intercambio de dinero.\",\"button_name\":\"Env\\u00eda dinero ahora\",\"button_link\":\"user\\/send-money\"},\"ar\":{\"title\":\"\\u0645\\u0644\\u062e\\u0635\",\"heading\":\"\\u0641\\u064a \\u0639\\u0627\\u0645 2024\\u060c \\u062d\\u0642\\u0642\\u062a \\u0645\\u0624\\u0633\\u0633\\u0629 \\u0645\\u0627\\u0644\\u064a\\u0629 \\u062f\\u062e\\u0644\\u0627\\u064b \\u0628\\u0642\\u064a\\u0645\\u0629 6.8 \\u0645\\u0644\\u064a\\u0627\\u0631 \\u062f\\u0648\\u0644\\u0627\\u0631.\",\"sub_heading\":\"\\u0647\\u0644 \\u0633\\u0628\\u0642 \\u0644\\u0643 \\u0623\\u0646 \\u0627\\u0633\\u062a\\u0633\\u0644\\u0645\\u062a \\u0623\\u062e\\u064a\\u0631\\u064b\\u0627 \\u0644\\u0644\\u0625\\u063a\\u0631\\u0627\\u0621 \\u0648\\u0642\\u0631\\u0623\\u062a \\u0628\\u0631\\u062c\\u0643 \\u0641\\u064a \\u0627\\u0644\\u0635\\u062d\\u064a\\u0641\\u0629\\u061f\",\"botton_text\":\"\\u062a\\u0644\\u0639\\u0628 \\u0627\\u0644\\u0645\\u0624\\u0633\\u0633\\u0627\\u062a \\u0627\\u0644\\u0645\\u0627\\u0644\\u064a\\u0629 \\u062f\\u0648\\u0631\\u064b\\u0627 \\u062d\\u064a\\u0648\\u064a\\u064b\\u0627 \\u0644\\u0623\\u0646\\u0647\\u0627 \\u062a\\u0639\\u0645\\u0644 \\u0643\\u0645\\u0646\\u0635\\u0629 \\u0644\\u062a\\u0628\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644.\",\"button_name\":\"\\u0623\\u0631\\u0633\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644 \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"user\\/send-money\"},\"fr\":{\"title\":\"Aper\\u00e7u\",\"heading\":\"En 2024, une institution financi\\u00e8re a g\\u00e9n\\u00e9r\\u00e9 6,8 milliards de dollars de revenus.\",\"sub_heading\":\"Avez-vous d\\u00e9j\\u00e0 finalement c\\u00e9d\\u00e9 \\u00e0 la tentation et lu votre horoscope dans le journal ?\",\"botton_text\":\"Les institutions financi\\u00e8res jouent un r\\u00f4le essentiel car elles servent de plateforme d\\u2019\\u00e9change d\\u2019argent.\",\"button_name\":\"Envoyez de l\'argent maintenant\",\"button_link\":\"user\\/send-money\"},\"hi\":{\"title\":\"\\u0905\\u0935\\u0932\\u094b\\u0915\\u0928\",\"heading\":\"2024 \\u092e\\u0947\\u0902, \\u090f\\u0915 \\u0935\\u093f\\u0924\\u094d\\u0924\\u0940\\u092f \\u0938\\u0902\\u0938\\u094d\\u0925\\u093e\\u0928 \\u0928\\u0947 6.8 \\u092c\\u093f\\u0932\\u093f\\u092f\\u0928 \\u0921\\u0949\\u0932\\u0930 \\u0915\\u0940 \\u0906\\u092f \\u0905\\u0930\\u094d\\u091c\\u093f\\u0924 \\u0915\\u0940\\u0964\",\"sub_heading\":\"\\u0915\\u094d\\u092f\\u093e \\u0906\\u092a\\u0928\\u0947 \\u0915\\u092d\\u0940 \\u092a\\u094d\\u0930\\u0932\\u094b\\u092d\\u0928 \\u092e\\u0947\\u0902 \\u0906\\u0915\\u0930 \\u0905\\u0916\\u092c\\u093e\\u0930 \\u092e\\u0947\\u0902 \\u0905\\u092a\\u0928\\u0940 \\u0915\\u0941\\u0902\\u0921\\u0932\\u0940 \\u092a\\u0922\\u093c\\u0940 \\u0939\\u0948?\",\"botton_text\":\"\\u0935\\u093f\\u0924\\u094d\\u0924\\u0940\\u092f \\u0938\\u0902\\u0938\\u094d\\u0925\\u093e\\u090f\\u0902 \\u092e\\u0939\\u0924\\u094d\\u0935\\u092a\\u0942\\u0930\\u094d\\u0923 \\u092d\\u0942\\u092e\\u093f\\u0915\\u093e \\u0928\\u093f\\u092d\\u093e\\u0924\\u0940 \\u0939\\u0948\\u0902 \\u0915\\u094d\\u092f\\u094b\\u0902\\u0915\\u093f \\u0935\\u0947 \\u092e\\u0941\\u0926\\u094d\\u0930\\u093e \\u0935\\u093f\\u0928\\u093f\\u092e\\u092f \\u0915\\u0947 \\u0932\\u093f\\u090f \\u090f\\u0915 \\u092e\\u0902\\u091a \\u0915\\u0947 \\u0930\\u0942\\u092a \\u092e\\u0947\\u0902 \\u0915\\u093e\\u0930\\u094d\\u092f \\u0915\\u0930\\u0924\\u0940 \\u0939\\u0948\\u0902\\u0964\",\"button_name\":\"\\u0905\\u092d\\u0940 \\u092a\\u0948\\u0938\\u0947 \\u092d\\u0947\\u091c\\u0947\\u0902\",\"button_link\":\"user\\/send-money\"}}}', 1, NULL, '2023-06-13 12:43:31', '2024-11-12 18:23:33');
INSERT INTO `site_sections` VALUES (16, 'why-choose-us-section', '{\"language\":{\"en\":{\"heading\":\"WHY CHOOSE US\",\"sub_heading\":\"Finances Through Secure Banking Practices\",\"details\":\"Essential for protecting your money and personal information. Here are some tips to help you maintain financial security.\"},\"es\":{\"heading\":\"POR QU\\u00c9 ELEGIRNOS\",\"sub_heading\":\"Finanzas a trav\\u00e9s de pr\\u00e1cticas bancarias seguras\",\"details\":\"Esencial para proteger su dinero e informaci\\u00f3n personal. Aqu\\u00ed hay algunos consejos para ayudarlo a mantener la seguridad financiera.\"},\"ar\":{\"heading\":\"\\u0644\\u0645\\u0627\\u0630\\u0627 \\u0623\\u062e\\u062a\\u0631\\u062a\\u0646\\u0627\",\"sub_heading\":\"\\u0627\\u0644\\u062a\\u0645\\u0648\\u064a\\u0644 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0645\\u0627\\u0631\\u0633\\u0627\\u062a \\u0627\\u0644\\u0645\\u0635\\u0631\\u0641\\u064a\\u0629 \\u0627\\u0644\\u0622\\u0645\\u0646\\u0629\",\"details\":\"\\u0636\\u0631\\u0648\\u0631\\u064a \\u0644\\u062d\\u0645\\u0627\\u064a\\u0629 \\u0623\\u0645\\u0648\\u0627\\u0644\\u0643 \\u0648\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a\\u0643 \\u0627\\u0644\\u0634\\u062e\\u0635\\u064a\\u0629. \\u0641\\u064a\\u0645\\u0627 \\u064a\\u0644\\u064a \\u0628\\u0639\\u0636 \\u0627\\u0644\\u0646\\u0635\\u0627\\u0626\\u062d \\u0644\\u0645\\u0633\\u0627\\u0639\\u062f\\u062a\\u0643 \\u0641\\u064a \\u0627\\u0644\\u062d\\u0641\\u0627\\u0638 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0623\\u0645\\u0646 \\u0627\\u0644\\u0645\\u0627\\u0644\\u064a.\"},\"fr\":{\"heading\":\"POURQUOI NOUS CHOISIR\",\"sub_heading\":\"Finances gr\\u00e2ce \\u00e0 des pratiques bancaires s\\u00e9curis\\u00e9es\",\"details\":\"Indispensable pour prot\\u00e9ger votre argent et vos informations personnelles. Voici quelques conseils pour vous aider \\u00e0 maintenir votre s\\u00e9curit\\u00e9 financi\\u00e8re.\"},\"hi\":{\"heading\":\"\\u0939\\u092e\\u0947\\u0902 \\u0915\\u094