-- ----------------------------
-- Table structure for transactions
-- ----------------------------
DROP TABLE IF EXISTS `transactions`;
CREATE TABLE `transactions`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `admin_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `user_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `user_wallet_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `merchant_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `merchant_wallet_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `agent_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `agent_wallet_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `sandbox_wallet_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `payment_gateway_currency_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `payment_link_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `type` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `trx_id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Transaction ID',
  `request_amount` decimal(28, 8) NOT NULL,
  `payable` decimal(28, 8) NOT NULL,
  `available_balance` decimal(28, 8) NOT NULL,
  `remark` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `details` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `reject_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0: Default, 1: Success, 2: Pending, 3: Hold, 4: Rejected',
  `attribute` enum('SEND','RECEIVED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp(0) NULL DEFAULT NULL,
  `updated_at` timestamp(0) NULL DEFAULT NULL,
  `callback_ref` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `transactions_admin_id_foreign`(`admin_id`) USING BTREE,
  INDEX `transactions_user_id_foreign`(`user_id`) USING BTREE,
  INDEX `transactions_user_wallet_id_foreign`(`user_wallet_id`) USING BTREE,
  INDEX `transactions_merchant_id_foreign`(`merchant_id`) USING BTREE,
  INDEX `transactions_merchant_wallet_id_foreign`(`merchant_wallet_id`) USING BTREE,
  INDEX `transactions_payment_gateway_currency_id_foreign`(`payment_gateway_currency_id`) USING BTREE,
  INDEX `transactions_payment_link_id_foreign`(`payment_link_id`) USING BTREE,
  INDEX `transactions_agent_id_foreign`(`agent_id`) USING BTREE,
